INSERT INTO `en33_pages` (`id`, `name`, `title`, `meta_desc`, `meta_key`, `contents`, `published`, `lang_id`, `lang`, `icon`, `layout`, `url`) VALUES
(355, 'Volunteer Abroad in Jordan', 'Volunteer job in Jordan', 'Volunteer job in Jordan', 'Volunteer job in Jordan', '&lt;p style=&quot;text-align: left;&quot;&gt;&lt;span class=&quot;h3 h5&quot;&gt;Jordan is one of the most fascinating nations in the Middle East. From biblical sites, castles, ancient citadels to ruined Roman cities, you will easily find something in Jordan that fascinates you. Jordan is the home of Petra, an ancient Nabataean lost city, comparable to Machu Picchu as well as Angkor Wat and Amman, its capital and a modern, culturally diverse Arab city. There are many opportunities for individuals who wish to discover a different aspect of the nation by volunteering.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;h3&gt;Job Brief:&lt;/h3&gt;\r\n&lt;p&gt;We are seeking a qualified person who speaks and writes Italian and Spanish to work  in our travel agency in Petra.&lt;/p&gt;\r\n&lt;p&gt;You will primarily be responsible to our clients emails and to analyze all of them and to answer them in less than one hour.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;h3&gt;Responsibilities:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;Run, maintain, reconcile, review, combine, analyze and data entry in the required languages in our website. &lt;/span&gt;&lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;Identify and resolve all the emails.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;Qualifications:&lt;/span&gt;&lt;/span&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;Having work experience as an accountant.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;Bachelor&#039;s degree plus two years of applicable experience, or combination of education and relevant work experience.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;Proficiency in basic business applications, such as Microsoft Office; &lt;/span&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;user knowledge of Excel.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;Basic knowledge of accounting systems and the internet; &lt;/span&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;computer literacy.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;Understanding of and ability to apply accounting skills and concepts.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;Ability to draft professional e-mails, memos, business letters, and reports, and to clearly and effectively communicate information to internal audiences and client groups.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;Ability to learn project management skills and to participate as part of a project team.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;Benefits:&lt;/span&gt;&lt;/span&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;Paid vacation =&amp;gt; Yes&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;Sick leave =&amp;gt; Yes &lt;/span&gt;&lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;Health benefits include medical and dental =&amp;gt; No &lt;/span&gt;&lt;/span&gt;&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;To Apply:&lt;/span&gt;&lt;/span&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;Submit resume detailing your experience.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;Submit a cover letter explaining why you would be a great fit.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;Send your full CV to our email at&lt;strong&gt; &lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;strong&gt;&lt;a href=&quot;mailto:khaled@pvt.jo&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;khaled@pvt.jo&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;/strong&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;vertical-align: inherit;&quot;&gt; or by Whatsapp at &lt;strong&gt;+96277 77 67 938.&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt; &lt;/p&gt;', 1, 355, 'en', '', 'one col', 'volunteer-abroad-in-jordan'),
(356, 'Jobs in Jordan', 'Jobs in Jordan', 'Jobs in Jordan', 'Jobs in Jordan', '&lt;p style=&quot;text-align: center;&quot;&gt; &lt;/p&gt;\r\n&lt;h3&gt;Job Brief:&lt;/h3&gt;\r\n&lt;p&gt;We are seeking a qualified person who speaks and writes Italian and Spanish to work  in &lt;strong&gt;&lt;a href=&quot;http://www.pvt.jo&quot;&gt;our travel agency in Petra.&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;You will primarily be responsible to our clients emails and to analyze all of them and to answer them in less than one hour.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;h3&gt;Responsabilities: &lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Run, maintain, reconcile, review, combine, analyze and data entry in the required languages in our website.&lt;/li&gt;\r\n&lt;li&gt;Identify and resolve all the emails.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;Qualifications:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Having work experience as an accountant.&lt;/li&gt;\r\n&lt;li&gt;Bachelor&#039;s degree plus two years of applicable experience, or combination of education and relevant work experience.&lt;/li&gt;\r\n&lt;li&gt;Proficiency in basic business applications, such as Microsoft Office; user knowledge of Excel.&lt;/li&gt;\r\n&lt;li&gt;Basic knowledge of accounting systems and the internet; computer literacy.&lt;/li&gt;\r\n&lt;li&gt;Understanding of and ability to apply accounting skills and concepts.&lt;/li&gt;\r\n&lt;li&gt;Ability to draft professional e-mails, memos, business letters, and reports, and to clearly and effectively communicate information to internal audiences and client groups.&lt;/li&gt;\r\n&lt;li&gt;Ability to learn project management skills and to participate as part of a project team.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;Benefits:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Paid vacation=&amp;gt; Yes&lt;/li&gt;\r\n&lt;li&gt;Sick leave =&amp;gt; Yes &lt;/li&gt;\r\n&lt;li&gt;Health benefits to include medical and dental = &amp;gt; No &lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;To Apply:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Submit resume detailing your experience.&lt;/li&gt;\r\n&lt;li&gt;Submit a cover letter explaining why you would be a great fit.&lt;/li&gt;\r\n&lt;li&gt;Send your full CV to our email at &lt;strong&gt;&lt;a href=&quot;mailto:khaled@pvt.jo&quot;&gt;khaled@pvt.jo&lt;/a&gt;&lt;/strong&gt; or by Whatsapp at &lt;strong&gt;+96277 77 67 938.&lt;/strong&gt;&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt; &lt;/p&gt;', 1, 356, 'en', '', 'one col', 'jobs-in-jordan'),
(357, 'Trabajos en Jordania', 'Trabajos en Jordania', 'Trabajos en Jordania', 'Trabajos en Jordania', '&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;h3&gt;Resumen del trabajo:&lt;/h3&gt;\r\n&lt;p&gt;<br>Estamos buscando una persona calificada que habla y escribe italiano y español para trabajar en &lt;a href=&quot;http://www.pvt.jo&quot;&gt;nuestra agencia de viajes en Petra&lt;/a&gt;.&lt;/p&gt;\r\n&lt;p&gt;Usted será responsable ante los correos electrónicos de nuestros clientes y analizará todos ellos y responderá en menos de una hora.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;Responsabilidades:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Ejecutar, mantener, reconciliar, revisar, combinar, analizar e introducción de datos en los idiomas requeridos en nuestro sitio web.&lt;/li&gt;\r\n&lt;li&gt;Identificar y resolver todos los correos electrónicos.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;Calificaciones:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Tener experiencia laboral como contador.&lt;/li&gt;\r\n&lt;li&gt;Licenciatura más dos años de experiencia aplicable, o combinación de educación y experiencia de trabajo relevante.&lt;/li&gt;\r\n&lt;li&gt;Competencia en aplicaciones empresariales básicas, como Microsoft Office; Conocimiento del usuario de Excel.&lt;/li&gt;\r\n&lt;li&gt;Conocimientos básicos de sistemas contables e internet; alfabetización informática.&lt;/li&gt;\r\n&lt;li&gt;Comprensión y capacidad de aplicar habilidades y conceptos de contabilidad.&lt;/li&gt;\r\n&lt;li&gt;Capacidad para redactar correos electrónicos profesionales, memorandos, cartas comerciales e informes, y para comunicar de manera clara y eficaz la información a audiencias internas y grupos de clientes.&lt;/li&gt;\r\n&lt;li&gt;Capacidad para aprender habilidades de gestión de proyectos y para participar como parte de un equipo de proyecto.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;<br>Beneficios:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Vacaciones pagadas =&amp;gt; Sí&lt;/li&gt;\r\n&lt;li&gt;Licencia por enfermedad =&amp;gt; Sí&lt;/li&gt;\r\n&lt;li&gt;Beneficios de salud para incluir medicina y dental =&amp;gt; No&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;<br>Aplicar:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Envíe un curriculum vitae detallando su experiencia.&lt;/li&gt;\r\n&lt;li&gt;Envíe una carta de presentación explicando por qué sería un gran candidato.&lt;/li&gt;\r\n&lt;li&gt;Envíe su CV completo a nuestro correo electrónico &lt;strong&gt;&lt;a href=&quot;mailto:khaled@pvt.jo&quot;&gt;khaled@pvt.jo&lt;/a&gt;&lt;/strong&gt; O por Whatsapp al &lt;strong&gt;+96277 77 67 938.&lt;/strong&gt;&lt;/li&gt;\r\n&lt;/ul&gt;', 1, 356, 'es', '', 'one col', 'trabajos-en-jordania'),
(358, 'Trabajo de voluntariado en Jordania', 'Trabajo de voluntariado  en Jordania', 'Trabajo de voluntario/a en Jordania', 'Trabajo de voluntario/a en Jordania', '&lt;p&gt;Jordania es una de las naciones más fascinantes de Oriente Medio. Desde lugares bíblicos, castillos, antiguas ciudadelas hasta ciudades romanas en ruinas, encontrarás algo en Jordania que te fascine. Jordania es el hogar de Petra, una antigua ciudad perdida nabatea, comparable a Machu Picchu o Angkor Wat y Amman, su capital, es una ciudad árabe moderna y culturalmente diversa. Hay muchas oportunidades para las personas que desean descubrir un aspecto diferente de la Nación mediante el voluntariado.&lt;/p&gt;\r\n&lt;h3&gt; <br>&lt;strong&gt;Resumen del trabajo:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;<br>Estamos buscando una persona calificada que habla y escribe italiano y español para trabajar en nuestra agencia de viajes en Petra.&lt;/p&gt;\r\n&lt;p&gt;Será responsable ante los correos electrónicos de nuestros clientes, analizará todos ellos y responderá en menos de una hora.&lt;/p&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Responsabilidades:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Ejecutar, mantener, reconciliar, revisar, combinar, analizar e introducción de datos en los idiomas requeridos en nuestro sitio web.&lt;/li&gt;\r\n&lt;li&gt;Identificar y resolver todos los correos electrónicos.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;h3&gt;&lt;strong&gt;Calificaciones:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Tener experiencia laboral como contador.&lt;/li&gt;\r\n&lt;li&gt;Licenciatura más dos años de experiencia aplicable, o combinación de educación y experiencia de trabajo relevante.Competencia en aplicaciones empresariales básicas, como Microsoft Office; Conocimiento del usuario de Excel.&lt;/li&gt;\r\n&lt;li&gt;Conocimientos básicos de sistemas contables e internet; alfabetización informática.&lt;/li&gt;\r\n&lt;li&gt;Comprensión y capacidad de aplicar habilidades y conceptos de contabilidad.&lt;/li&gt;\r\n&lt;li&gt;Capacidad para redactar correos electrónicos profesionales, memorandos, cartas comerciales e informes, y para comunicar de manera clara y eficaz la información a audiencias internas y grupos de clientes.&lt;/li&gt;\r\n&lt;li&gt;Capacidad para aprender habilidades de gestión de proyectos y para formar parte de un equipo de proyecto.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Beneficios:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Vacaciones pagadas =&amp;gt; Sí&lt;/li&gt;\r\n&lt;li&gt;Licencia por enfermedad =&amp;gt; Sí&lt;/li&gt;\r\n&lt;li&gt;Beneficios de salud para incluir medicina y dental =&amp;gt; No&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Aplicar:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Envíe un curriculum vitae detallando su experiencia.&lt;/li&gt;\r\n&lt;li&gt;Envíe una carta de presentación explicando por qué sería un gran cantidato.&lt;/li&gt;\r\n&lt;li&gt;Envíe su CV completo a nuestro correo electrónico &lt;a href=&quot;mailto:khaled@pvt.jo&quot;&gt;khaled@pvt.jo&lt;/a&gt; o por Whatsapp al &lt;strong&gt;+96277 77 67 938.&lt;/strong&gt;&lt;/li&gt;\r\n&lt;/ul&gt;', 1, 355, 'es', '', 'one col', 'trabajo-de-voluntariado-en-jordania'),
(359, 'Términos y Condiciones', 'Términos y Condiciones', 'PV travel términos y condiciones', 'PV travel términos y condiciones', '&lt;p&gt;&lt;span style=&quot;font-size: 18pt;&quot;&gt;&lt;strong&gt;Términos y Condiciones&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;<br> &lt;strong&gt;PV TRAVELS. AVISOS, TERMINOS Y CONDICIONES&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;<br>Somos PV Travels. Y esperamos la oportunidad de actuar como su agente de reservas para sus necesidades de viaje. Estos términos y condiciones (el &quot;Acuerdo&quot;) describen lo que legalmente tiene derecho a esperar de nosotros cuando compre servicios relacionados con viajes a través de nosotros, además de sus obligaciones como cliente. Los términos &quot;nosotros&quot; y &quot;nuestro&quot; se refieren a PV Travels. El término &quot;usted&quot; se refiere al cliente que visita nuestro sitio web, hace una reserva a través de nosotros o de otro modo utilizando nuestros servicios&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;ol&gt;\r\n&lt;li&gt;&lt;strong&gt;Nuestro acuerdo con usted&lt;/strong&gt;<br>&lt;strong&gt;Productos y Proveedores&lt;/strong&gt;<br>Vendemos una variedad de productos relacionados con viajes de diferentes proveedores y proveedores de servicios (&quot;Proveedores&quot;). Cada Proveedor tiene sus propios términos y condiciones que son aplicables a sus arreglos particulares además de nuestros términos y condiciones generales, y debe asegurarse de entenderlos. Ciertos softwares y contenidos que se encuentran en nuestro sitio web son de propiedad o licenciados por nosotros o nuestros Proveedores, cuyo uso puede estar sujeto a otras condiciones. Nuestro sitio web, que se menciona en todo este Acuerdo, se puede encontrar en &lt;a href=&quot;http://www.pvt.jo&quot;&gt;www.pvt.jo.&lt;/a&gt;<br>PV TRAVELS actúa como intermediario o &quot;agente de reserva&quot; para productos y servicios que no son suministrados directamente por nosotros (por ejemplo, transporte aéreo y terrestre, alojamiento en hotel, comidas, cruceros, etc.). No somos co-vendedores de tales productos y servicios. Usted celebrará un contrato separado con dichos proveedores en relación con dichos productos y servicios.<br>Todas las boletos de aerolíneas están sujetos a aumentos de precios suplementarios que se pueden imponer después de la fecha de compra. Los aumentos de precios posteriores a la compra pueden ser aplicados debido a los costos adicionales impuestos por un proveedor o gobierno. Podrá cobrarle sumas adicionales por PV TRAVELS para compensar las comisiones, recargos por combustible, impuestos y fluctuaciones en los mercados de divisas o cualquier combinación de los mismos. La aceptación de estos términos y condiciones por medio de la presente le autoriza a cualquier aumento de precio posterior a la compra y autoriza a PV TRAVELS a cargar mi tarjeta de crédito por dichos importes adicionales.<br>Depósitos y Pago<br>Los depósitos de usted no son reembolsables. El pago de un depósito nos permite mantener una reserva con usted, pero no garantiza el precio. El precio sólo se puede garantizar una vez que recibimos el pago completo y otros documentos de viaje han sido emitidos, con sujeción a los términos y condiciones del proveedor. Le informaremos de la fecha en que se requiere el pago completo. Tras la provisión de su información de pago, nos está autorizando a realizar los arreglos de pago con los Proveedores correspondientes.<br>Nos reservamos el derecho de rechazar cheques personales como método de pago. Después del pago completo, las condiciones del contrato con su Proveedor pueden permitirles aumentar el costo de sus arreglos. Si actuamos como su Agente de Reserva, le pasaremos cualquier aumento a medida que seamos conscientes de dicho aumento. Si hemos arreglado un paquete, los cambios en los costos de transporte, incluyendo el costo del combustible, los impuestos, las tarifas y los tipos de cambio, significan que el precio de sus arreglos de viaje puede cambiar después de haber pagado por completo.<br>Documentación<br>Nuestra práctica general es enviar documentos a nuestros clientes electrónicamente siempre que sea posible. Nos reservamos el derecho de cobrar una cuota de administración si usted solicita que dichos documentos se envíen como una copia impresa.<br>Cancelaciones y Cambios<br>Su contrato con sus proveedores puede permitirles cancelar o modificar reservas. Si somos su Agente de reservas, nos aseguraremos de que usted sea notificado con prontitud de cualquier cambio significativo una vez que nos enteramos de dicho cambio si hay tiempo antes de su salida, pero no asumimos ninguna responsabilidad por los cambios o los costos incurridos que puedan resultar. Sujeto a los términos y condiciones del Proveedor, usted tendrá la opción de aceptar el cambio de arreglos, aceptar una oferta de arreglos de viaje alternativos si uno es puesto a su disposición por el Proveedor, o cancelar sus arreglos reservados y recibir cualquier reembolso aplicable. No garantizamos que se apliquen reembolsos.<br>Si ha reservado un vuelo y nos avisa de un cambio significativo en el horario de su aerolínea antes de salir de su país, nos pondremos en contacto con usted por correo electrónico para informarle de ello. Asegúrese de que ha proporcionado su dirección de correo electrónico de contacto y que revisa periódicamente los mensajes antes de salir. No tenemos ningún control sobre los cambios en el horario de la aerolínea y no asumimos ninguna responsabilidad por los costos que puedan surgir como resultado de dichos cambios.<br>Después de haber dejado el país, es su responsabilidad verificar con la aerolínea que cualquier vuelo que haya confirmado esté funcionando según lo reservado. Le recomendamos encarecidamente que se ponga en contacto con su aerolínea al menos 72 horas antes de la salida programada de cada vuelo para hacerlo. Tenga en cuenta que para algunas líneas aéreas es obligatorio confirmar con ellos su intención de volar.&lt;/li&gt;\r\n&lt;/ol&gt;\r\n&lt;p&gt;&lt;strong&gt;2. Su Acuerdo Con Nosotros&lt;/strong&gt;<br>&lt;strong&gt;Su aceptación de estos términos y condiciones&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;<br>Al reservar su acuerdo con nosotros o usar nuestro sitio web, usted acepta estar sujeto a los términos de este Acuerdo, incluyendo las Partes 1 a 3 de este Contrato y cualquier otro término y condiciones adicionales de cualquier Proveedor que sean aplicables a su reserva, O el uso de cualquier contenido del sitio web. Usted acepta en nombre de usted y de los que usted representa para cumplir con todos los términos y condiciones, incluyendo el pago de todas las cantidades a su vencimiento. Usted acepta que cualquier violación de cualquiera de estos términos y condiciones puede resultar en:<br>(A) la cancelación de su reserva o compra.<br>(B) su confiscación de cualquier dinero pagado por su reserva o compra.<br>(C) se le niega el acceso al producto o servicio relacionado con el viaje correspondiente.<br>(D) nuestro derecho a cargar en su cuenta los costos incurridos como resultado de dicha violación.<br>Usted declara y garantiza que:<br>(A) usted es de edad suficiente para utilizar nuestros servicios y sitio web y puede crear obligaciones legales vinculantes en relación con su uso.<br>(B) usted está legalmente autorizado para actuar en nombre de aquellos a quienes representa y acepta estos términos y condiciones en su nombre.<br>(C) la información proporcionada por usted o miembros de su grupo es verdadera y correcta. Usted es responsable de informar a estas otras personas de todos los términos y condiciones aplicables a sus arreglos de viaje. Usted entiende que usted es financieramente responsable de cualquier uso de nuestros servicios o sitio web por usted y aquellos que utilizan su nombre o cuenta.<br>Si cambia su reserva<br>Si un cambio solicitado por usted a sus arreglos de viaje es permitido y posible, nuestros honorarios de servicio estándar se aplicarán además de cualquier cargo adicional del Proveedor. Póngase en contacto con su agente de reservas para consultar los cambios o consulte la sección &quot;Ayuda de viaje&quot; de www.pvt.jo para obtener detalles sobre cómo solicitar cambios. Tenga en cuenta que todos los cambios de reserva están sujetos a disponibilidad y los términos y condiciones del producto comprado.<br>Los cambios en los detalles del nombre no están permitidos por muchas aerolíneas y otros proveedores. Si bien nos esforzaremos en hacer tal cambio si es necesario, tenga en cuenta que la mayoría de las aerolíneas y los proveedores tratan un cambio de nombre como una cancelación, a la que se aplicarán condiciones y cargos estándar.<br>Los vuelos deben ser tomados en la secuencia que aparecen en su boleto o confirmación eticket. Si usted planea no tomar un vuelo como reservado, comuníquese con la aerolínea con la mayor antelación posible para discutir sus opciones. Si no se registra a tiempo para una reserva confirmada, la aerolínea puede registrarlo como un &quot;no show&quot;, lo que podría resultar en cargos adicionales y / o cancelar su itinerario completo y / o dejar sin efecto su billete.<br>Si cancela su reserva<br>Si cancela sus arreglos, puede tener derecho a un reembolso parcial. Además de los términos y condiciones de cancelación de su (s) Proveedor (es), nuestros honorarios estándar se aplicarán según se indique en su recibo o confirmación de la reserva. Necesitamos recibir de usted su vale original antes de que cualquier reembolso aplicable pueda ser considerado. Si decide cancelar los acuerdos antes de la fecha de vencimiento del saldo, los depósitos pagados no son reembolsables.<br>Los reembolsos sólo se le pagarán una vez que hayamos recibido los fondos del proveedor (s). En general, los billetes de avión no se pueden reembolsar si se utilizan parcialmente. No somos responsables de que un Proveedor no haya pagado un reembolso.<br>Si el motivo de su cancelación está cubierto bajo los términos de su póliza de seguro de viaje, es posible que pueda recuperar sus cargos de cancelación a través de su aseguradora.<br>Aviso importante con respecto a las reservas aéreas<br>Si llega a un billete de avión o pasajero de pasajeros con su billete confirmado y descubre que la aerolínea no muestra ninguna reserva para usted - no salga del mostrador. Revise su boleto. Si el cuadro de estado muestra &quot;Aceptar&quot; para el vuelo en cuestión, las pólizas de la aerolínea normalmente requieren que le acomoden en ese vuelo, o si no es posible, deben encontrarle un vuelo sustituto o pagarle la compensación de embarque denegado. Si es necesario pida hablar con un supervisor.&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;Si tiene una queja&lt;/strong&gt;<br>Si usted tiene un problema durante sus vacaciones, por favor informe al Proveedor relevante (por ejemplo, su hotel) inmediatamente. En caso de que sean incapaces de resolver el asunto, por favor, póngase en contacto con nosotros a través de nuestro sitio web contacto correo electrónico www.pvt.jo. Si no nos contacta oportunamente, no se le permitirá la oportunidad de investigar su queja e intentar rectificar cualquier error mientras esté ausente, y esto puede afectar sus derechos bajo este Acuerdo.<br>Documentos de viaje y destinos<br>Es su responsabilidad asegurarse de que todos los detalles de sus documentos de viaje son correctos y de traer a nuestra atención cualquier error o discrepancia de inmediato. Sus documentos de viaje son valiosos y deben ser salvaguardados como si fueran dinero en efectivo. No siempre es posible sustituir los documentos de viaje en caso de pérdida, robo, daño, etc.<br><br>&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Documentos de viaje y destinos&lt;/strong&gt;<br>Es su responsabilidad asegurarse de que todos los detalles de sus documentos de viaje son correctos y de traer a nuestra atención cualquier error o discrepancia de inmediato. Sus documentos de viaje son valiosos y deben ser salvaguardados como si fueran dinero en efectivo. No siempre es posible sustituir los documentos de viaje en caso de pérdida, robo, daño, etc.<br>Antes de reservar viajes internacionales, le recomendamos que revise las prohibiciones, advertencias y advertencias de su gobierno aplicables a sus destinos. Al ofrecer viajes a cualquier destino en particular, no representamos que el viaje en dicho destino sea seguro o sin riesgo.<br>Usted acepta además que en relación con sus actividades, no permitirá el uso de nuestros servicios o sitio web por cualquier persona que resida o se encuentre en un país para el que dicho uso está prohibido bajo las regulaciones de su país.<br>Requisitos de Pasaporte, Visas e Inmigración<br>Es su responsabilidad completar el pasaporte, visa y otros requisitos de inmigración aplicables a su itinerario. Usted debe confirmar esto con las embajadas y / o consulados relevantes. No aceptamos ninguna responsabilidad en el caso de que usted no pueda viajar debido a no cumplir con tales requisitos.<br>También se le requiere tener un International Student I.D. válido y International Youth I.D. O un Maestro Internacional I.D. Tarjeta si está viajando con un boleto especial para estudiantes / jóvenes / maestros. Es su responsabilidad verificar esto con nuestro experto en viajes que le está ayudando.&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;Seguro&lt;/strong&gt;<br>Seguro de viaje es una parte vital de sus arreglos. Le recomendamos encarecidamente que haya contratado un seguro adecuado para la duración de su viaje. Seguro de viaje es un elemento obligatorio de algunos arreglos de viaje. Podemos ser capaces de organizar un seguro de viaje que se le proporcionará, le proporcionará una cotización, y responder a cualquier pregunta que pueda tener en relación con el seguro.<br>&lt;strong&gt;Divulgación de Materiales Peligrosos&lt;/strong&gt;<br>La ley federal prohíbe el transporte de materiales peligrosos a bordo de las aeronaves en su equipaje o en su persona. Una violación puede resultar en cinco años de prisión y penas de $ 250,000 o más (49 U.S.C. 5124). Los materiales peligrosos incluyen explosivos, gases comprimidos, líquidos y sólidos inflamables, oxidantes, venenos, corrosivos y materiales radiactivos. Ejemplos: pinturas, fluidos ligeros, fuegos artificiales, gases lacrimógenos, botellas de oxígeno y radiofármacos.&lt;/p&gt;\r\n&lt;p&gt;Hay excepciones especiales para pequeñas cantidades (hasta 70 onzas en total) de artículos medicinales y de aseo transportados en su equipaje y ciertos materiales para fumar que se llevan en su persona. Para más información, revise la información que se encuentra en la página web de TSA sobre artículos prohibidos en &lt;a href=&quot;http://www.tsa.gov/traveler-information/prohibited-items&quot;&gt;http://www.tsa.gov/traveler-information/prohibited-items.&lt;/a&gt;<br>Uso de nuestros Servicios y Sitio Web<br>Usted acepta que solo utilizará nuestro sitio web o servicios para hacer reservas o compras legítimas y no hará reservas o reservas especulativas, falsas o fraudulentas en previsión de la demanda. Solo usará nuestro sitio web y servicios de acuerdo con la ley aplicable.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Indemnización&lt;/strong&gt;<br>Usted acepta indemnizarnos a nosotros ya nuestros afiliados y cualquiera de nuestros Proveedores, así como a los oficiales, directores, empleados y agentes de dichas partes de y contra cualquier reclamo, causa de acción, demandas, pérdidas, daños u otros costos Legales y contables) por usted o por terceros como resultado de<br>(A) su incumplimiento de este Acuerdo.<br>(B) su violación de cualquier ley o derechos de cualquier tercero.<br>(C) el uso de nuestro sitio web.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Política de privacidad&lt;/strong&gt;<br>Usted acepta nuestro procesamiento y el intercambio de información personal sobre usted y otros miembros de su grupo que nos ha proporcionado de acuerdo con los términos y para los propósitos establecidos en nuestra política de privacidad. Usted declara que ha leído y acepta los términos de nuestra política de privacidad, que puede encontrar en nuestro sitio web.&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;3. Términos adicionales&lt;/strong&gt;<br>&lt;strong&gt;Garantías, renuncias y limitación de responsabilidad&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;<br>PARA EVITAR DUDA, LAS REFERENCIAS AQUÍ A &quot;NOSOTROS&quot; Y &quot;NUESTRO&quot; TAMBIÉN SE REFIEREN A NUESTRAS AFILIADAS. LA INFORMACIÓN, EL SOFTWARE, LOS PRODUCTOS Y SERVICIOS PROPORCIONADOS POR NOSOTROS O NUESTROS PROVEEDORES O PUBLICADOS EN NUESTRO SITIO WEB PUEDEN INCLUIR INEXACTITUDES O ERRORES, INCLUYENDO ERRORES DE PRECIOS. NO GARANTIZAMOS LA EXACTITUD DE, Y RENUNCIAMOS A TODA RESPONSABILIDAD POR CUALQUIER ERROR O OTRAS INEXACTITUDES RELACIONADAS CON TAL INFORMACIÓN QUE APARECE EN NUESTRO SITIO WEB. RESERVAMOS EXPRESAMENTE EL DERECHO A CORREGIR NINGÚN ERROR DE PRECIOS EN NUESTRO SITIO WEB Y / O EN LAS RESERVAS PENDIENTES EFECTUADAS BAJO UN PRECIO INCORRECTO. EN TAL CASO, SI ESTÁN DISPONIBLES, LE OFRECEMOS LA OPORTUNIDAD DE MANTENER SU RESERVA PENDIENTE A PRECIO CORRECTO O NOSOTROS CANCELAREMOS SU RESERVA SIN PENALIDAD.<br>CUALQUIER CLASIFICACIÓN PARA PROVEEDORES ESTÁ DESTINADA SÓLO COMO DIRECTRICES GENERALES, Y NO GARANTIZAMOS LA EXACTITUD DE LAS CLASIFICACIONES. NO HACEMOS GARANTÍAS SOBRE LA DISPONIBILIDAD DE PRODUCTOS Y SERVICIOS ESPECÍFICOS. NO HACEMOS REPRESENTACIONES SOBRE LA CONVENIENCIA DE LA INFORMACIÓN, SOFTWARE, PRODUCTOS Y SERVICIOS PROPORCIONADOS POR NOSOTROS O CONTENIDOS EN NUESTRO SITIO WEB PARA CUALQUIER FIN. LA INCLUSIÓN O OFRECIMIENTO DE CUALQUIER PRODUCTO O SERVICIO POR NOSOTROS NO CONSTITUYE NUESTRO ENDOSO O RECOMENDACIÓN DE DICHOS PRODUCTOS O SERVICIOS. TODA ESTA INFORMACIÓN, SOFTWARE, PRODUCTOS Y SERVICIOS SE PROPORCIONAN &quot;TAL CUAL&quot; SIN GARANTÍA DE NINGÚN TIPO. RENUNCIAMOS A TODAS LAS GARANTÍAS DE QUE NUESTRO SITIO WEB, SUS SERVIDORES O CUALQUIER EMAIL ENVIADO DE NOSOTROS O NUESTROS PROVEEDORES ESTÉN LIBRES DE VIRUS O DE OTROS COMPONENTES DAÑINOS. POR LA PRESENTE renuncian a todas las garantías y condiciones con respecto a esta información, SOFTWARE, PRODUCTOS Y SERVICIOS, INCLUYENDO TODAS LAS GARANTÍAS Y CONDICIONES DE COMERCIALIZACIÓN, IDONEIDAD PARA UN PROPÓSITO PARTICULAR, TÍTULO Y NO INFRACCIÓN. LAS EXENCIONES DE GARANTÍA PUEDEN VARIAR DE ESTADO EN ESTADO.<br>LOS TRANSPORTADORES, HOTELES Y OTROS PROVEEDORES QUE OFRECEN VIAJES O OTROS SERVICIOS EN ESTE SITIO WEB SON CONTRATISTAS INDEPENDIENTES Y NO AGENTES O EMPLEADOS DEL GOBIERNO. NO SOMOS responsable de los actos, errores, omisiones, representaciones, garantías, INCUMPLIMIENTOS O negligencia de cualquier DICHOS PROVEEDORES O DE CUALQUIER lesiones personales, muerte, daños materiales u otros daños O GASTOS POR. No tenemos responsabilidad Y no hará reembolso en caso de cualquier retraso, cancelación, overbooking, huelga, fuerza mayor u otras causas fuera de nuestro control y no tenemos ninguna responsabilidad de cualquier gasto adicional, OMISIONES, RETRASOS, CAMBIOS DE RUTA O ACTOS DE CUALQUIER GOBIERNO O AUTORIDAD.<br>EN NINGÚN CASO SEREMOS RESPONSABLES POR DAÑOS DIRECTOS, INDIRECTOS, MORALES, ACCIDENTALES, ESPECIALES O CONSECUENCIA DE, O CONECTADOS CON, SU ACCESO A, VISUALIZACIÓN O USO DE ESTE SITIO WEB O LOS SERVICIOS O DE LA RETRASO O incapacidad de acceder, mostrar o usar NUESTRO SITIO WEB SEA basa en una teoría de negligencia, contrato, agravio, responsabilidad estricta, o no, y incluso si hemos sido advertidos de la posibilidad de tales daños.<br>IF, pesar de la limitación Arriba, nosotros encontrado responsable por cualquier pérdida o daño que surja de O CONECTADOS DE CUALQUIER de las ocurrencias descrito arriba, entonces nuestra voluntad RESPONSABILIDAD en ningún caso superior, EN CONJUNTO, LA MAYOR ( A) LAS CUOTAS DE SERVICIO QUE USTED PAGÓ A US EN RELACIÓN CON TAL TRANSACCIÓN (S) EN ESTE SITIO WEB, O (B) CIENTOS DÓLARES (US $ 100.00) O EL EQUIVALENTE EN MONEDA LOCAL.<br>LA LIMITACIÓN DE RESPONSABILIDAD REFLEJA LA ASIGNACIÓN DE RIESGOS ENTRE LAS PARTES. LAS LIMITACIONES ESPECIFICADAS EN ESTA SECCIÓN SOBREVIVIRÁN Y SE APLICARÁN AUNQUE CUALQUIER RECURSO LIMITADO ESPECIFICADO EN ESTOS TÉRMINOS SE ENCUENTRA QUE HA FALLADO SU PROPÓSITO ESENCIAL.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;General&lt;/strong&gt;<br>Estamos actuando como un contratista independiente y no existe ninguna joint venture, asociación o relación laboral entre usted y nosotros o nuestros Proveedores como resultado de este Acuerdo o su uso de nuestro sitio web.<br>Nos reservamos el derecho en cualquier momento de modificar este Acuerdo sin previo aviso. Por favor, consulte nuestro sitio web en www.pvt.jo de vez en cuando para revisar la versión más reciente del Acuerdo. Su acceso continuo o uso de nuestro sitio web o servicios significa su aceptación de las modificaciones al Acuerdo. Usted no puede ceder sus derechos u obligaciones bajo este Acuerdo a terceros. Podemos rescindir este Acuerdo en cualquier momento por cualquier razón, y tal terminación no afectará ningún derecho al alivio al cual tenemos derecho legal o en equidad.<br>Este Acuerdo se regirá por las leyes del Estado de Jordania sin tener en cuenta sus conflictos de principios legales. Si alguna disposición de este Acuerdo se considera inválida, ilegal o inaplicable, la aplicabilidad de las disposiciones restantes no será en modo alguno afectada o perjudicada.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;hr /&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Reservas Tours Condiciones:&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Lea atentamente las siguientes condiciones de reserva:<br>PV Travels se reserva el derecho de negar la participación a cualquier persona que esté incapacitada, mal preparada o en cualquier forma en detrimento de la seguridad del grupo. La participación de cualquier persona en cualquier programa está continuamente sujeto a la discreción del instructor (s) y / o guías.&lt;/p&gt;\r\n&lt;p&gt;PV viajes no se hace responsable de las acciones de las personas y / o empresas que suministran bienes y / o servicios como parte de los paquetes o de los costes adicionales que puedan derivarse del programa de complicación o prolongación por cualquier motivo.&lt;/p&gt;\r\n&lt;p&gt;Cualquier problema médico o relacionado con la salud o condiciones que puedan afectar su participación en cualquier curso o programa debe ser aclarado por su médico antes de tomar el tour,&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;Procedimiento de reserva de excursiones:&lt;/strong&gt;<br>Por favor, rellene nuestro formulario de regastration de reserva con el fin de creet una cuenta en nuestro sitio web y para comprobar su statas reserva, en la reserva, el pago o depósito apropiado es necesario más la siguiente información de usted:&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;A:&lt;/strong&gt; Nombre y dirección postal, teléfono y números de fax.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;B:&lt;/strong&gt; El programa y las fechas que desea reservar e información de contacto para emergencias.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;C:&lt;/strong&gt; Lista con pasaporte completo Detalles de los clientes o personas que participan en el tour propuesto.&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;Pago&lt;/strong&gt;<br>Los precios indicados son en dólares estadounidenses. No incluyen seguro de viaje. Todos los precios están sujetos a cambios antes del comienzo del tour. Si desea tener un recibo impreso, por favor, solicite uno.<br>No confirmaremos ninguna reserva hasta que se reciba su pago&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;Cancelación y devolución de la reserva Tour&lt;/strong&gt;:<br>PV Travels se reserva el derecho de modificar o retirar en parte o cancelar las instalaciones proporcionadas bajo cualquier paquete sin previo aviso. Todos los paquetes pueden ser prorrateados según la tarifa de la tarifa indicada en el momento de la reserva y sujetos a disponibilidad. Las tarifas están sujetas a cambios sin previo aviso debido al repentino aumento de los impuestos gubernamentales y el costo del combustible.&lt;/p&gt;\r\n&lt;p&gt;Nos reservamos el derecho de cancelar un tour debido a la baja inscripción o condiciones climáticas severas, (NOTA: PV Travels se reserva el derecho de cambiar, alterar o cancelar cualquier parte de su itinerario el conjunto o el servicio en cualquier momento después de la reserva debido al clima, condiciones u otras razones sin penalización).&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Politica de reembolso.&lt;/strong&gt;<br>No hay reembolso para estancias cortas y un-aprovecho instalaciones como excursiones de un día.<br>En caso de cancelar su reserva por cualquier motivo, se aplicarán las siguientes penalidades, las siguientes tarifas se aplicarán a todas las reservas confirmadas a PV Travels:&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;A:&lt;/strong&gt; Si la cancelación ocurre 45 días o más antes del comienzo del programa, reembolso completo a usted con la mínima deducción en el reembolso  en concepto de libro de texto o materiales&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;B:&lt;/strong&gt; 50% gastos de cancelación Cuando la cancelación se produce entre 44 y 25 días antes del inicio del programa,&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;C:&lt;/strong&gt; 100% o la tarifa del paquete completo si la cancelación ocurre entre los últimos 24 días antes del inicio del programa.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;D:&lt;/strong&gt; Los depósitos no reembolsables no forman parte de la política de cancelación y deben ser notificados por escrito y se debe conservar el comprobante de reconocimiento.<br> <br>&lt;strong&gt;Para más información contacte con nosotros en: &lt;a href=&quot;mailto:info@pvt.jo&quot;&gt;info@pvt.jo&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;', 1, 340, 'es', '', 'one col', 'términos-y-condiciones'),
(360, 'Política de privacidad de PV Travels', 'Política de privacidad de PV Travels', 'Política de privacidad de PV Travels', 'Política de privacidad de PV Travels', '&lt;p&gt;<br>En &lt;a href=&quot;http://www.pvt.jo&quot;&gt;PV Travels&lt;/a&gt;, una de nuestras principales prioridades es la privacidad de nuestros visitantes. Este documento de Política de Privacidad contiene tipos de información que se recopila y registra en www.pvt.jo y cómo lo usamos.&lt;/p&gt;\r\n&lt;p&gt;Si tiene preguntas adicionales o necesita más información sobre nuestra Política de privacidad, no dude en ponerse en contacto con nosotros a través de correo electrónico en &lt;a href=&quot;mailto:info@pvt.jo&quot;&gt;info@pvt.jo&lt;/a&gt;.&lt;/p&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Archivos de registro&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;<br>&lt;a href=&quot;http://www.pvt.jo&quot;&gt;Www.pvt.jo&lt;/a&gt; sigue un procedimiento estándar de uso de archivos de registro. Estos archivos registran a los visitantes cuando visitan sitios web. Todas las empresas de hosting hacen esto y una parte de la analítica de los servicios de hosting. La información recogida por los archivos de registro incluye direcciones de protocolo de Internet (IP), tipo de navegador, proveedor de servicios de Internet (ISP), fecha y hora, páginas de referencia / salida y posiblemente el número de clics. Estos no están vinculados a ninguna información que sea personalmente identificable. El propósito de la información es analizar las tendencias, administrar el sitio, rastrear el movimiento de los usuarios en el sitio web y recopilar información demográfica.&lt;/p&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Cookies y Web Beacons&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;<br>Como cualquier otro sitio web, www.pvt.jo utiliza &#039;cookies&#039;. Estas cookies se utilizan para almacenar información, incluyendo las preferencias de los visitantes, y las páginas del sitio web al que el visitante accedió o visitó. La información se utiliza para optimizar la experiencia de los usuarios mediante la personalización de nuestro contenido de página web basado en el tipo de navegador de los visitantes y / u otra información.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;Cookie de DoubleClick DART&lt;/h3&gt;\r\n&lt;p&gt;<br>Google es uno de los proveedores de terceros en nuestro sitio. También utiliza cookies, conocidas como cookies DART, para publicar anuncios a nuestros visitantes del sitio según su visita a www.website.com y otros sitios en Internet. Sin embargo, los visitantes pueden optar por rechazar el uso de las cookies de DART visitando la Política de privacidad de la red de contenido y anuncios de Google en la siguiente URL: &lt;a href=&quot;http://www.google.com/privacy_ads.html&quot;&gt;http://www.google.com/privacy_ads.html&lt;/a&gt;.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;h3&gt;&lt;strong&gt;Nuestros socios publicitarios&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;<br>Algunos de los anunciantes de nuestro sitio pueden usar cookies y web beacons. Nuestros socios publicitarios incluyen:&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Google&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;Cada uno de nuestros socios publicitarios tiene su propia Política de privacidad para su sitio web. &lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;Políticas de privacidad&lt;/h3&gt;\r\n&lt;p&gt;<br>Puede consultar esta lista para encontrar la Política de privacidad de cada uno de los socios publicitarios de www.pvt.jo.<br>Los servidores de anuncios de terceros o las redes publicitarias utilizan tecnologías como cookies, JavaScript o Web Beacons que se utilizan en sus respectivos anuncios y enlaces que aparecen en www.pvt.jo, que se envían directamente al navegador de los usuarios. Reciben automáticamente su dirección IP cuando esto ocurre. Estas tecnologías se utilizan para medir la eficacia de sus campañas publicitarias y / o para personalizar el contenido publicitario que se ve en los sitios web que visita.<br>Tenga en cuenta que www.pvt.jo no tiene acceso ni control sobre estas cookies que son utilizadas por los anunciantes de terceros.&lt;/p&gt;\r\n&lt;h3&gt;<br>Políticas de privacidad de terceros&lt;/h3&gt;\r\n&lt;p&gt;<br>La Política de privacidad de www.pvt.jo no se aplica a otros anunciantes o sitios web. Por lo tanto, le aconsejamos que consulte las respectivas Políticas de privacidad de estos servidores de anuncios de terceros para obtener información más detallada. Puede incluir sus prácticas e instrucciones sobre cómo optar por no participar en determinadas opciones. Puede encontrar una lista completa de estas Políticas de privacidad y sus vínculos aquí: Política de privacidad Enlaces.<br>Puede optar por deshabilitar las cookies a través de sus opciones de navegador individuales. Para conocer información más detallada acerca de la gestión de cookies con navegadores web específicos, se puede encontrar en los respectivos sitios web de los navegadores. ¿Qué son las cookies?&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;Información de menores de edad&lt;/h3&gt;\r\n&lt;p&gt;<br>Otra parte de nuestra prioridad es agregar protección a los niños mientras usamos Internet. Animamos a los padres y tutores a observar, participar y / o supervisar y guiar su actividad en línea.<br>Www.pvt.jo no recoge a sabiendas ninguna Información Personal Identificable de niños menores de 13 años. Si usted piensa que su hijo ha proporcionado este tipo de información en nuestro sitio web, le recomendamos encarecidamente que nos contacte inmediatamente y haremos lo mejor posible Esfuerzos para eliminar rápidamente esa información de nuestros registros.&lt;/p&gt;\r\n&lt;h3&gt;<br>Política de privacidad en línea solamente&lt;/h3&gt;\r\n&lt;p&gt;<br>Esta política de privacidad se aplica sólo a nuestras actividades en línea y es válida para los visitantes de nuestro sitio web con respecto a la información que compartieron y / o recopilaron en www.pvt.jo. Esta política no es aplicable a ninguna información recopilada fuera de línea oa través de canales distintos a este sitio web.&lt;/p&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Consentimiento&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;<br>Al utilizar nuestro sitio web, por el presente usted da su consentimiento a nuestra Política de Privacidad y acepta sus Términos y Condiciones.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;Actualizado&lt;/h3&gt;\r\n&lt;p&gt;<br>Esta Política de Privacidad se actualizó por última vez el 20 de mayo de 2016. Si hay alguna actualización, enmienda o cambios en nuestra Política de Privacidad, éstos se publicarán en esta página.&lt;/p&gt;', 1, 337, 'es', '', 'one col', 'política-de-privacidad-de-pv-travels'),
(361, 'Actividades de Trabajo en Equipo', 'Actividades de Trabajo en Equipo', 'Actividades de Trabajo en Equipo', 'Actividades de Trabajo en Equipo', '&lt;p&gt;Organizar un evento o incentivo para su equipo de trabajo o bien como se conoce en ingles team building requiere mucha imaginación, creatividad, pero también depende de su presupuesto. Estos eventos para su equipo de trabajo puede tener lugar durante varios días o bien en un solo día, también puede ser integrado en un seminario o en un foro internacional. En estos eventos de trabajo o team building, los empleados participan en divertidas actividades deportivas o culturales. Es un evento unificador para crear una armonía de grupo y espíritu de equipo que permita a los participantes acercarse entre sí, mejorar y fortalecer los valores de la empresa entre los empleados.&lt;/p&gt;\r\n&lt;p&gt;<br>Los eventos para su equipo de trabajo pueden ser muchos y variados y se adaptarán a sus deseos, sus metas, su presupuesto y su deseo de querer realmente soldar y crear una dinámica de grupo.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;      &lt;span style=&quot;text-decoration: underline;&quot;&gt;Las categorías son diversas y podemos ir muy lejos en la imaginación y el diseño:&lt;/span&gt;&lt;/p&gt;\r\n&lt;ul style=&quot;list-style-type: disc;&quot;&gt;\r\n&lt;li&gt; Actividades extremas: Conducir 4x4, salto de parapente, escalada, buggy, rafting, tirolesa, ciclismo de montaña...&lt;/li&gt;\r\n&lt;li&gt; Actividades divertidas: caza del tesoro, juegos deportivos, rompecabezas...&lt;/li&gt;\r\n&lt;li&gt; Actividades creativas: juegos de rol o imitaciones, introducción a la cocina local, fabricación de joyas locales, diseño de botellas de arena jordanas...&lt;/li&gt;\r\n&lt;li&gt; Actividades culturales: concurso sobre sitios visitados, degustaciones a ojos cerrados de platos locales...&lt;/li&gt;\r\n&lt;li&gt; Las actividades de relajación: talasoterapia y spa, buceo &lt;span&gt;o &lt;/span&gt;natación, barranquismo (&lt;span&gt;canyoning).&lt;/span&gt;..&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;Las posibilidades siguen siendo numerosas e inimaginables y sobre todo personalizables de acuerdo a sus deseos y expectativas.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;strong&gt;&lt;a href=&quot;mailto:info@pvt.jo&quot;&gt;Pídanos todo&lt;/a&gt; lo que usted necesita y nosotros se lo proporcionaremos.&lt;/strong&gt;&lt;/p&gt;', 1, 333, 'es', '', 'one col', 'actividades-de-trabajo-en-equipo');
INSERT INTO `en33_pages` (`id`, `name`, `title`, `meta_desc`, `meta_key`, `contents`, `published`, `lang_id`, `lang`, `icon`, `layout`, `url`) VALUES
(362, 'Viaje de Negocios', 'Viaje de Negocios', 'Viaje de Negocios', 'Viaje de Negocios', '&lt;h2&gt;&lt;span style=&quot;font-size: 18pt;&quot;&gt;&lt;strong&gt;Viajes para Comunidades y Negocios&lt;/strong&gt;&lt;/span&gt;&lt;/h2&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;Tenemos una sólida experiencia en la organización de viajes para Consejos de Empresa y Comunidades. Ya hemos realizado varios viajes para el personal Francés, Belga y Alemán más importante. Podemos construir programas a pedido para grupos a precios reducidos.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;Proponemos una amplia gama de viajes y tenemos una gran variedad de instalaciones de alojamiento, todo estándar. Tenemos un equipo dinámico y creativo que puede ayudarlo y guiarlo en su búsqueda del mejor producto.&lt;/p&gt;\r\n&lt;p&gt;<br> &lt;strong&gt;No espere más y &lt;a href=&quot;mailto:info@pvt.jo&quot;&gt;contáctenos ahora&lt;/a&gt; para las vacaciones de sus empleados y le ofrecemos los mejores precios para complacerlo.&lt;/strong&gt;&lt;/p&gt;', 1, 330, 'es', '', 'one col', 'viaje-de-negocios'),
(363, 'Consejos para Viajeros', 'Consejos para Viajeros', 'Consejos para Viajeros', 'Consejos para Viajeros', '&lt;h3&gt;&lt;strong&gt;Antes de que te Vayas&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Investigue información básica sobre su destino.&lt;/li&gt;\r\n&lt;li&gt;Deje una copia de su itinerario con un familiar o amigo de confianza.&lt;/li&gt;\r\n&lt;li&gt;Si usted está conduciendo, asegúrese de que su vehículo está en buen estado de funcionamiento.&lt;/li&gt;\r\n&lt;li&gt;Obtenga copias de los mapas de su destino para localizar rutas, atracciones y servicios esenciales.&lt;/li&gt;\r\n&lt;li&gt;Considere la posibilidad de unirse a AAA u otro club de viajes para asistencia en carretera u otra asistencia de viaje.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt; <br>&lt;strong&gt;Consejos para viajes Internacionales&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;¿Sabía que necesita un pasaporte vigente y válido si viaja a cualquier lugar fuera de los Estados Unidos, incluyendo Canadá y México? Si no tiene un pasaporte válido, visite Departamento de Estado de los Estados Unidos para solicitar o renovar su pasaporte.&lt;/li&gt;\r\n&lt;li&gt;Además de un pasaporte, también puede necesitar una visa para visitar algunos países. Consulte con el sitio Web del Departamento de Estado de los Estados Unidos o con el sitio Web de su país anfitrión o con los sitios de turismo o asuntos exteriores de su país anfitrión.&lt;/li&gt;\r\n&lt;li&gt;¿Planea conducir en otro país? Compruebe si su licencia de conducir es válida en el extranjero. También puede necesitar un permiso de conducir internacional o una traducción de su licencia de conducir de los Estados Unidos. Visite el sitio &lt;a href=&quot;http://www.aaa.com/vacation/idpf.html&quot; title=&quot;Permiso Internacional de Conducir&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;web de IDA de AAA&lt;/a&gt; para aplicar.&lt;/li&gt;\r\n&lt;li&gt;Encuentre la dirección y el número de teléfono del consulado o embajada de los Estados Unidos.&lt;/li&gt;\r\n&lt;li&gt;Investigue información básica sobre el país o los países que planea visitar para ayudarle a familiarizarse con las leyes y costumbres locales. Su biblioteca o agente de viajes son recursos valiosos aquí. También, consulte con el Departamento de Estado de los Estados Unidos para ver si hay advertencias o advertencias para consideraciones especiales para el país o los países que usted planea visitar.&lt;/li&gt;\r\n&lt;li&gt;Familiarícese con algunas palabras y frases básicas en el idioma del país o países que planea visitar.&lt;/li&gt;\r\n&lt;li&gt;Regístrese en el &lt;a href=&quot;https://travelregistration.state.gov/&quot; title=&quot;Registrese en el Departamento de Estado de los Estados Unidos&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Departamento de Estado de los Estados Unidos&lt;/a&gt; para facilitarle al gobierno de los Estados Unidos ayudarle en una emergencia en el extranjero.&lt;/li&gt;\r\n&lt;li&gt;Haga fotocopias de su pasaporte, billetes de avión, visa, lleve un juego de copias en un lugar seguro y deje otro juego de copias en casa con un familiar o amigo de confianza.&lt;/li&gt;\r\n&lt;li&gt;Su seguro de salud y accidente puede no ser válido fuera de los Estados Unidos. Consulte con su proveedor de seguros para ver si necesita seguro adicional de salud / accidente de viaje.&lt;/li&gt;\r\n&lt;li&gt;Algunos países tienen restricciones sobre cosas que pueden traer consigo o llevar a casa con usted.&lt;/li&gt;\r\n&lt;li&gt;Puede haber restricciones para traer ciertas cosas a los Estados Unidos con usted. Consulte con la Aduana de los Estados Unidos y la Protección Fronteriza para obtener más detalles.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt; <br>&lt;strong&gt;Embalaje&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Viaje liviano.&lt;/li&gt;\r\n&lt;li&gt;Si necesita algún medicamento recetado, traiga lo suficiente para que dure la duración de su viaje. Además, si usa gafas, traiga un par extra.&lt;/li&gt;\r\n&lt;li&gt;Mantenga los medicamentos en sus recipientes originales. También puede necesitar una carta de su médico explicando por qué necesita ciertos medicamentos.&lt;/li&gt;\r\n&lt;li&gt;No empaque ni traiga artículos prohibidos, tales como armas, objetos afilados o sustancias peligrosas.&lt;/li&gt;\r\n&lt;li&gt;No traer un montón de efectivo o tarjetas de crédito. En su lugar, traer cheques de viajero, una o dos tarjetas de crédito, y sólo una pequeña cantidad de dinero en efectivo.&lt;/li&gt;\r\n&lt;li&gt;No empacar o traer objetos de valor, como un jot de joyas.&lt;/li&gt;\r\n&lt;li&gt;Asegúrese de que su equipaje esté etiquetado con su nombre y número de teléfono, pero use una etiqueta de equipaje. También puede considerar el uso de su dirección de trabajo y número de teléfono en sus etiquetas de equipaje.&lt;/li&gt;\r\n&lt;li&gt;Recuerde las reglas de lo que puede llevar a cabo y lo que necesita ser comprobado al volar. Visite el sitio web de la &lt;a href=&quot;https://www.tsa.gov/travel&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot; title=&quot;Administración de Seguridad del Transporte&quot;&gt;Administración de Seguridad del Transporte&lt;/a&gt; para obtener más información sobre estas reglas.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt; <br>&lt;strong&gt;En el Aeropuerto y en el Aire&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;No deje su equipaje desatendido.&lt;/li&gt;\r\n&lt;li&gt;No deje que nadie más que los miembros del personal del aeropuerto manejar su equipaje.&lt;/li&gt;\r\n&lt;li&gt;No acepte paquetes de desconocidos.&lt;/li&gt;\r\n&lt;li&gt;Reportar cualquier actividad sospechosa.&lt;/li&gt;\r\n&lt;li&gt;Una vez en el avion siga todas las reglas e instrucciones de seguridad.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt; <br>&lt;strong&gt;En el Camino&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;&lt;span style=&quot;font-size: 14px; text-decoration-line: inherit;&quot;&gt;Use su cinturón de seguridad.&lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;No beba y conduzca, y no viaje con alguien que haya estado bebiendo.&lt;/li&gt;\r\n&lt;li&gt;Asegúrese de que sus hijos estén en asientos de seguridad para niños aprobados.&lt;/li&gt;\r\n&lt;li&gt;No conduzca si se siente somnoliento.&lt;/li&gt;\r\n&lt;li&gt;No use teléfonos celulares u otros dispositivos electrónicos mientras conduce.&lt;/li&gt;\r\n&lt;li&gt;No haga excursiones solo, y no recoja excursionistas.&lt;/li&gt;\r\n&lt;li&gt;Tenga en cuenta las condiciones del camino y sus alrededores.&lt;/li&gt;\r\n&lt;li&gt;Estacione en áreas bien iluminadas y bien viajadas.&lt;/li&gt;\r\n&lt;li&gt;Mantenga las puertas del coche cerradas.&lt;/li&gt;\r\n&lt;li&gt;No coloque su equipaje u otros objetos de valor en un lugar donde los criminales puedan verlos fácilmente.&lt;/li&gt;\r\n&lt;li&gt;Si usted está teniendo problemas con el auto, sólo acepte la ayuda de la policía u otro personal autorizado.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt; <br>&lt;strong&gt;En tu Hotel&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Encuentra las salidas de incendios más cercanas, alarma contra incendios, extintor / manguera a su habitación.&lt;/li&gt;\r\n&lt;li&gt;Mantenga la puerta de su habitación cerrada en todo momento.&lt;/li&gt;\r\n&lt;li&gt;Pídale a los visitantes que se reúnan en el vestíbulo u otros espacios públicos de su hotel.&lt;/li&gt;\r\n&lt;li&gt;Utilice la caja fuerte del hotel para guardar objetos de valor.&lt;/li&gt;\r\n&lt;li&gt;No entre en un ascensor solo con desconocidos sospechosos.&lt;/li&gt;\r\n&lt;li&gt;Pregunte al personal del hotel sobre las políticas de seguridad si no está seguro&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;&lt;strong&gt;Otras recomendaciones&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Presta atención a tus alrededores. &lt;/li&gt;\r\n&lt;li&gt;No tome más efectivo, cheques de viajero o tarjetas de crédito de lo que necesita.&lt;/li&gt;\r\n&lt;li&gt;No aceptes viajes de extraños.&lt;/li&gt;\r\n&lt;li&gt;Evite grandes multitudes, manifestaciones o confrontaciones públicas.&lt;/li&gt;\r\n&lt;li&gt;Mantener un perfil bajo.&lt;/li&gt;\r\n&lt;li&gt;No tome demasiado alcohol para estar atento a cualquier eventualidad.&lt;/li&gt;\r\n&lt;li&gt;Permanecer en lugares bien iluminados y transitados.&lt;/li&gt;\r\n&lt;li&gt;No muestre su efectivo u otros objetos de valor.&lt;/li&gt;\r\n&lt;li&gt;No hable de sus planes de viaje con extraños.&lt;/li&gt;\r\n&lt;li&gt;Encuentre la ubicación de la estación de policía, el hospital y otros lugares seguros más cercanos.&lt;/li&gt;\r\n&lt;li&gt;Informe cualquier actividad sospechosa a la policía.&lt;/li&gt;\r\n&lt;li&gt;Si te roban, no te resistas.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/p&gt;', 1, 322, 'es', '', 'one col', 'consejos-para-viajeros'),
(364, 'Sobre nosotros', 'Sobre nosotros', 'Sobre nosotros', 'Sobre nosotros', '&lt;p&gt;&lt;strong&gt;PV Travels&lt;/strong&gt; es un Tour Operador Árabe y es el primer servicio de viajes verdaderamente Oriente Medio creado para satisfacer las necesidades del viajero de hoy. Si usted es un eco-trekker, buscador espiritual, o profesional de negocios, con nuestra vasta experiencia podemos atender a todas sus necesidades individuales, independientemente de su religión.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Actuamos como profesionales diseñadores de vacaciones. Gestionamos todos los aspectos de su viaje, desde rutas personalizadas y alojamiento, hasta guías turísticos y actividades.&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;PV Travels&lt;/strong&gt; se especializa en proporcionar una amplia gama de servicios en tierra a los &lt;a href=&quot;es/&quot;&gt;turistas en el Medio Oriente&lt;/a&gt;.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;La atención a los detalles en la ejecución de itinerarios de viaje ha alentado a muchos mayoristas y operadores de viajes internacionales a confiar a&lt;strong&gt; PV Travels&lt;/strong&gt; el servicio a sus clientes.&lt;/p&gt;\r\n&lt;p&gt;<br>   &lt;span style=&quot;text-decoration: underline;&quot;&gt;Los servicios de&lt;strong&gt; PV Travels&lt;/strong&gt; incluyen:&lt;/span&gt;&lt;/p&gt;\r\n&lt;ul style=&quot;list-style-type: disc;&quot;&gt;\r\n&lt;li&gt;Ofrecer tours clásicos, trekking y programas de aventura&lt;/li&gt;\r\n&lt;li&gt;Servicios de destino&lt;/li&gt;\r\n&lt;li&gt;Viaje de placer&lt;/li&gt;\r\n&lt;li&gt;FAM viajes&lt;/li&gt;\r\n&lt;li&gt;Viajes en equipo&lt;/li&gt;\r\n&lt;li&gt;Viajes en grupo&lt;/li&gt;\r\n&lt;li&gt;Viajes corporativos&lt;/li&gt;\r\n&lt;li&gt;Viajes de incentivo&lt;/li&gt;\r\n&lt;li&gt;Servicios de viajes American Express&lt;/li&gt;\r\n&lt;li&gt;Reunión, eventos y conferencias&lt;/li&gt;\r\n&lt;li&gt;Servicios de Producción&lt;/li&gt;\r\n&lt;li&gt;Logística&lt;/li&gt;\r\n&lt;li&gt;Transporte terrestre en vehículos de varias categorías&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;&lt;strong&gt;Para obtener más informaciónes sobre PV Travels, envíe un correo electrónico a &lt;a href=&quot;mailto:info@pvt.jo&quot;&gt;info@pvt.jo&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;', 1, 321, 'es', '', 'one col', 'sobre-nosotros'),
(365, 'Offres d&#039;emploi en Jordanie', 'Offres d&#039;emploi en Jordanie', 'Offres d&#039;emploi en Jordanie', 'Offres d&#039;emploi en Jordanie', '&lt;h3&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;h3&gt;&lt;strong&gt;Job Brief:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;<br>Nous recherchons une personne qualifiée qui parle et écrit l&#039;italien et l&#039;espagnol pour travailler dans &lt;a href=&quot;http://www.pvt.jo&quot;&gt;&lt;strong&gt;notre agence de voyages à Petra.&lt;/strong&gt;&lt;/a&gt;&lt;/p&gt;\r\n&lt;p&gt;Vous serez principalement responsable des courriels de nos clients, de leur analyse et de leur réponse en moins d’une heure.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;&lt;strong&gt;Responsabilités:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Exécutez, maintenez, rapprochez, passez en revue, combinez, analysez et entrez les données dans les langues requises sur notre site Web.&lt;/li&gt;\r\n&lt;li&gt;Identifiez et résolvez tous les emails.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Qualifications:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Avoir une expérience de travail en tant que comptable.&lt;/li&gt;\r\n&lt;li&gt;Baccalauréat, plus de deux années d&#039;expérience pertinente, ou combinaison de formation et d&#039;expérience de travail pertinente.&lt;/li&gt;\r\n&lt;li&gt;Maîtrise des applications professionnelles de base, telles que Microsoft Office; connaissance de l&#039;utilisateur d&#039;Excel.&lt;/li&gt;\r\n&lt;li&gt;Connaissance de base des systèmes de comptabilité et d&#039;Internet; connaissances informatiques.&lt;/li&gt;\r\n&lt;li&gt;Compréhension et capacité d&#039;appliquer les compétences et les concepts comptables.&lt;/li&gt;\r\n&lt;li&gt;Capacité à rédiger des courriels professionnels, des notes de service, des lettres commerciales et des rapports, et à communiquer des informations claires et efficaces aux audiences internes et aux groupes de clients.&lt;/li&gt;\r\n&lt;li&gt;Capacité à acquérir des compétences en gestion de projet et à participer à une équipe de projet.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;<br>Avantages:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Vacances payées =&amp;gt; Oui&lt;/li&gt;\r\n&lt;li&gt;Congé de maladie =&amp;gt; Oui&lt;/li&gt;\r\n&lt;li&gt;Avantages pour la santé à inclure médicaux et dentaires =&amp;gt; Non&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Appliquer:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Soumettez votre CV en détaillant votre expérience.&lt;/li&gt;\r\n&lt;li&gt;Soumettez une lettre d&#039;accompagnement expliquant pourquoi vous conviendrait parfaitement.&lt;/li&gt;\r\n&lt;li&gt;Envoyez votre CV complet à notre email à &lt;a href=&quot;mailto:khaled@pvt.jo&quot;&gt;&lt;strong&gt;khaled@pvt.jo&lt;/strong&gt;&lt;/a&gt; ou par Whatsapp au &lt;strong&gt;+96277 77 67 938&lt;/strong&gt;&lt;/li&gt;\r\n&lt;/ul&gt;', 1, 356, 'fr', 'fa-search', 'one col', 'offres-demploi-en-jordanie'),
(366, 'Our Team', 'PV Travels Team', 'PV Travels Team', 'PV Travels Team', '&lt;div class=&quot;full-width pad&quot;&gt; &lt;/div&gt;\r\n&lt;div class=&quot;body-wrap grey&quot; style=&quot;grey-bottom: 7px dashed #FFFFFF; border-top: 7px dashed #FFFFFF;&quot;&gt;\r\n&lt;div class=&quot;wrap d-pad-t d-pad-b&quot;&gt;\r\n&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-6 pad&quot;&gt;\r\n&lt;h3 class=&quot;section-title-center&quot;&gt;Our Tour Guides&lt;/h3&gt;\r\n&lt;div class=&quot;&quot; style=&quot;overflow-y: auto; height: 350px;&quot;&gt;\r\n&lt;div class=&quot;row bordered-b&quot;&gt;\r\n&lt;div class=&quot;sd-3 h-pad d-pad-t align-center&quot;&gt;&lt;img class=&quot;circle&quot; src=&quot;uploads/uploads/Guide/G05.jpg&quot; alt=&quot;&quot; height=&quot;75&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;sd-9 h-pad d-pad-t&quot;&gt;&lt;strong&gt;Mazen Kayyali&lt;/strong&gt;<br> English tour guide\r\n&lt;div class=&quot;pad-t align-right&quot; style=&quot;font-size: 18px;&quot;&gt;&lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-facebook-rect &quot;&gt; &lt;/em&gt;&lt;/a&gt; &lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-linkedin-rect &quot;&gt; &lt;/em&gt;&lt;/a&gt; &lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-twitter &quot;&gt; &lt;/em&gt;&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;row bordered-b&quot;&gt;\r\n&lt;div class=&quot;sd-3 h-pad d-pad-t align-center&quot;&gt;&lt;img class=&quot;circle&quot; src=&quot;uploads/filemanager/Guide/Parastoo.jpg&quot; height=&quot;75&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;sd-9 h-pad d-pad-t&quot;&gt;&lt;strong&gt;Parastoo Ironn&lt;/strong&gt;<br>French &amp;amp; English tour guide\r\n&lt;div class=&quot;pad-t align-right&quot; style=&quot;font-size: 18px;&quot;&gt;&lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-facebook-rect &quot;&gt; &lt;/em&gt;&lt;/a&gt; &lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-linkedin-rect &quot;&gt; &lt;/em&gt;&lt;/a&gt; &lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-twitter &quot;&gt; &lt;/em&gt;&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;row bordered-b&quot;&gt;\r\n&lt;div class=&quot;sd-3 h-pad d-pad-t align-center&quot;&gt;&lt;img class=&quot;circle&quot; src=&quot;uploads/filemanager/Guide/G06.jpg&quot; height=&quot;75&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;sd-9 h-pad d-pad-t&quot;&gt;&lt;strong&gt;Basel Farahat<br>&lt;/strong&gt;French tour guide\r\n&lt;div class=&quot;pad-t align-right&quot; style=&quot;font-size: 18px;&quot;&gt;&lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-facebook-rect &quot;&gt; &lt;/em&gt;&lt;/a&gt; &lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-linkedin-rect &quot;&gt; &lt;/em&gt;&lt;/a&gt; &lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-twitter &quot;&gt; &lt;/em&gt;&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;row bordered-b&quot;&gt;\r\n&lt;div class=&quot;sd-3 h-pad d-pad-t align-center&quot;&gt;&lt;img class=&quot;circle&quot; src=&quot;uploads/filemanager/Guide/G03.jpg&quot; height=&quot;75&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;sd-9 h-pad d-pad-t&quot;&gt;&lt;strong&gt;Abdel Hakim Bilbeissi&lt;/strong&gt;<br>\r\n&lt;div class=&quot;row&quot; data-truncate=&quot;2&quot;&gt;French tour guide &lt;/div&gt;\r\n&lt;div class=&quot;pad-t align-right&quot; style=&quot;font-size: 18px;&quot;&gt;&lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-facebook-rect &quot;&gt; &lt;/em&gt;&lt;/a&gt; &lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-linkedin-rect &quot;&gt; &lt;/em&gt;&lt;/a&gt; &lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-twitter &quot;&gt; &lt;/em&gt;&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;row bordered-b&quot;&gt;\r\n&lt;div class=&quot;sd-3 h-pad d-pad-t align-center&quot;&gt;&lt;img class=&quot;circle&quot; src=&quot;uploads/filemanager/Guide/G02.jpg&quot; height=&quot;75&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;sd-9 h-pad d-pad-t&quot;&gt;&lt;strong&gt;Rashed Alhusban&lt;/strong&gt;<br>\r\n&lt;div class=&quot;row&quot; data-truncate=&quot;2&quot;&gt;French tour guide &lt;/div&gt;\r\n&lt;div class=&quot;pad-t align-right&quot; style=&quot;font-size: 18px;&quot;&gt;&lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-facebook-rect &quot;&gt; &lt;/em&gt;&lt;/a&gt; &lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-linkedin-rect &quot;&gt; &lt;/em&gt;&lt;/a&gt; &lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-twitter &quot;&gt; &lt;/em&gt;&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-6 pad&quot;&gt;\r\n&lt;h3 class=&quot;section-title-center&quot;&gt;Our Team&lt;/h3&gt;\r\n&lt;div class=&quot;&quot; style=&quot;overflow-y: auto; height: 350px;&quot;&gt;\r\n&lt;div class=&quot;row bordered-b&quot;&gt;\r\n&lt;div class=&quot;sd-3 h-pad d-pad-t align-center&quot;&gt;&lt;img class=&quot;circle&quot; src=&quot;uploads/filemanager/k1.jpg&quot; width=&quot;90&quot; height=&quot;90&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;sd-9 h-pad d-pad-t&quot;&gt;&lt;strong&gt;Khaled Nawafleh&lt;/strong&gt;<br>\r\n&lt;div class=&quot;row&quot; data-truncate=&quot;2&quot;&gt;General Manager of PV Travels Groups&lt;/div&gt;\r\n&lt;div class=&quot;pad-t align-right&quot; style=&quot;font-size: 18px;&quot;&gt;&lt;em class=&quot;ic-facebook-rect &quot;&gt; &lt;/em&gt; &lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-linkedin-rect &quot;&gt; &lt;/em&gt;&lt;/a&gt; &lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-twitter &quot;&gt; &lt;/em&gt;&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;row bordered-b&quot;&gt;\r\n&lt;div class=&quot;sd-3 h-pad d-pad-t align-center&quot;&gt;&lt;img class=&quot;circle&quot; src=&quot;uploads/filemanager/m.jpg&quot; width=&quot;90&quot; height=&quot;90&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;sd-9 h-pad d-pad-t&quot;&gt;&lt;strong&gt;Mahmourd Nawafleh&lt;/strong&gt;<br>\r\n&lt;div class=&quot;row&quot; data-truncate=&quot;2&quot;&gt;Operations Manager in PV Travels Groups&lt;/div&gt;\r\n&lt;div class=&quot;pad-t align-right&quot; style=&quot;font-size: 18px;&quot;&gt;&lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-facebook-rect &quot;&gt; &lt;/em&gt;&lt;/a&gt; &lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-linkedin-rect &quot;&gt; &lt;/em&gt;&lt;/a&gt; &lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-twitter &quot;&gt; &lt;/em&gt;&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;row bordered-b&quot;&gt;\r\n&lt;div class=&quot;sd-3 h-pad d-pad-t align-center&quot;&gt;&lt;img class=&quot;circle&quot; src=&quot;uploads/filemanager/f1.jpg&quot; width=&quot;90&quot; height=&quot;90&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;sd-9 h-pad d-pad-t&quot;&gt;&lt;strong&gt;Fatima Ammar&lt;/strong&gt;\r\n&lt;div class=&quot;row&quot; data-truncate=&quot;2&quot;&gt;\r\n&lt;div class=&quot;row&quot; data-truncate=&quot;2&quot;&gt;Sales department for Italian &amp;amp; Spanish in PV Travels Groups&lt;/div&gt;\r\n&lt;div class=&quot;row&quot; data-truncate=&quot;2&quot;&gt; &lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;pad-t align-right&quot; style=&quot;font-size: 18px;&quot;&gt;&lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-facebook-rect &quot;&gt; &lt;/em&gt;&lt;/a&gt; &lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-linkedin-rect &quot;&gt; &lt;/em&gt;&lt;/a&gt; &lt;a href=&quot;#&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;em class=&quot;ic-twitter &quot;&gt; &lt;/em&gt;&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 366, 'en', '', 'one col', 'our-team'),
(368, 'Tour in Giordania', 'Trova i migliori tours in Giordania', 'Tour in Giordania', 'Vacanze in Giordania,Viaggio in Giordania', '&lt;p&gt;Trova I Migliori Tour e Offerte Di Viaggio In Giordania&lt;/p&gt;', 1, 346, 'it', '', 'tours_in_jordan', 'viaggi-in-giordania'),
(369, 'Tours en Jordania', 'Los mejores sitios en Jordania', 'Viaje en Jordania', 'Vacaciones en Jordania', '&lt;p&gt;Encuentra Los Mejores Tours y Ofertas de Viajes en Jordania&lt;/p&gt;', 1, 346, 'es', '', 'tours_in_jordan', 'tours-en-jordania'),
(370, 'Tours in Oman', 'Trova i migliori tours in Oman', 'Tours in Oman', 'Vacanze,Viaggio in Oman', '&lt;p&gt;Trova Le Migliori Offerte di Viaggio e Offerte di Viaggio in Oman&lt;/p&gt;', 1, 347, 'it', '', 'tours_in_oman', 'viaggi-in-oman'),
(371, 'Tours en Oman', 'Tours en Oman', 'Tours en Oman', 'Vacaciones en Oman', '&lt;p&gt;Encuentra Los Mejores Tours y Ofertas de Viajes en Omán&lt;/p&gt;', 1, 347, 'es', '', 'tours_in_oman', 'tours-en-oman'),
(372, 'Tours in Iran', 'Trova i migliori tours in Iran', 'Tours in Iran', 'Vacanze,Viaggio in Iran', '&lt;p&gt;Le migliori tappe in Iran&lt;/p&gt;', 1, 348, 'it', '', 'tours_in_iran', 'viaggi-in-iran-'),
(373, 'Tours en Iran', 'Tours en Iran', 'Tours en Iran', 'Vacaciones en Iran', '&lt;p&gt;Descubre lo mejor de Iran  &lt;/p&gt;', 1, 348, 'es', '', 'tours_in_iran', 'viajes-en-iran-'),
(374, 'Attività di Team Building', 'Attività di Team Building', 'Siamo a disposizione di offrirvi tutto ciò che riguarda il lavoro di squadra.', 'Lavoro di squadra,viaggi', '&lt;p&gt;Organizzare un evento o un incentivo per il tuo team o come è noto nel team building inglese richiede molta immaginazione, creatività, ma dipende anche dal tuo budget. Questi eventi per il tuo team possono svolgersi per diversi giorni o in un solo giorno e possono anche essere integrati in un seminario o in un forum internazionale. In questi eventi di lavoro o di team building, i dipendenti partecipano a divertenti attività sportive o culturali. È un evento unificante per creare un&#039;armonia di spirito di gruppo e di gruppo che consente ai partecipanti di avvicinarsi, migliorare e rafforzare i valori dell&#039;azienda tra i dipendenti.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;Gli eventi per il tuo team possono essere molti e vari e si adatteranno ai tuoi desideri, ai tuoi obiettivi, al tuo budget e al tuo desiderio di voler davvero saldare e creare una dinamica di gruppo.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;       &lt;span style=&quot;text-decoration: underline;&quot;&gt;Le categorie sono diverse e possiamo andare lontano nell&#039;immaginazione e nel design:&lt;/span&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Attività estreme: 4x4 Guidare,, salto parapendio, arrampicata, buggy, rafting, fodera con zip, mountain bike. Attività divertenti: caccia al tesoro,&lt;/li&gt;\r\n&lt;li&gt;giochi sportivi, giochi di puzzle...&lt;/li&gt;\r\n&lt;li&gt;Attività creative: gioco di ruolo, introduzione alla cucina locale, produzione di gioielli locali, progettazione di bottiglie di sabbia giordane...&lt;/li&gt;\r\n&lt;li&gt;Attività culturali: il quiz sui siti visitati, gli occhi chiusi degustazioni di piatti locali...&lt;/li&gt;\r\n&lt;li&gt;Le attività di relax: thalasso e spa, immersioni e snorkeling, canyoning, nuoto...&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;Le possibilità rimangono numerose e inimmaginabili e soprattutto personalizzabili secondo i vostri desideri e aspettative.<br>  &lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;mailto:info@pvt.jo&quot;&gt;Chiedici tutto&lt;/a&gt; ciò di cui hai bisogno e te lo forniremo.&lt;/strong&gt;&lt;/p&gt;', 1, 333, 'it', '', 'one col', 'lavoro-di-squadra'),
(375, 'Viaggi d&#039;Affari', 'Viaggi d&#039;Affari', 'Viaggi d&#039;Affari', 'Viaggi,imprese.', '&lt;h2&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size: 18pt;&quot;&gt;Viaggi per le Comunità e le Imprese&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/h2&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;Abbiamo una solida esperienza nell&#039;organizzazione di viaggi per consigli e comunità. Abbiamo già fatto diversi viaggi per il più importante personale francese, belga e tedesco. Siamo in grado di costruire programmi su richiesta per gruppi a prezzi ridotti.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;Proponiamo una vasta gamma di viaggi e disponiamo di una vasta gamma di strutture ricettive, tutte standard. Abbiamo un team dinamico e creativo che può aiutarti e guidarti nella tua ricerca del miglior prodotto.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Non aspettare oltre e &lt;a href=&quot;mailto:info@pvt.jo&quot;&gt;contattaci&lt;/a&gt; subito per le vacanze dei tuoi dipendenti e ti offriamo i migliori prezzi per farti piacere.&lt;/strong&gt;&lt;/p&gt;', 1, 330, 'it', '', 'one col', '-comunità-e-imprese'),
(376, 'Chi siamo', 'Chi siamo', 'Chi siamo,dettagli sulla nostra agenzia.', 'Chi siamo', '&lt;p&gt;&lt;strong&gt;PV Travels&lt;/strong&gt; è un Tour Operator arabo ed è il primo vero servizio di viaggio in Medio Oriente creato per rispondere alle esigenze del viaggiatore di oggi. Se sei un eco trekker, cercatore spirituale o professionista, con la nostra vasta esperienza possiamo soddisfare tutte le vostre esigenze individuali indipendentemente dalla vostra religione.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Noi agiamo come i tuoi esperti designer di vacanza esperti. Gestiamo tutti gli aspetti del tuo viaggio, da percorsi e sistemazioni personalizzati, a guide e attività turistiche.&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;PV Travels&lt;/strong&gt; è specializzata nella fornitura di un&#039;ampia gamma di servizi terrestri ai turisti del Medio Oriente.&lt;/p&gt;\r\n&lt;p&gt;<br>L&#039;attenzione ai dettagli nell&#039;eseguire itinerari turistici ha incoraggiato molti grossisti e operatori internazionali di tour affidando a &lt;strong&gt;PV Travels&lt;/strong&gt; di servire i propri clienti.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;      &lt;span style=&quot;text-decoration: underline;&quot;&gt;I servizi &lt;strong&gt;PV Travels&lt;/strong&gt; includono:&lt;/span&gt;&lt;/p&gt;\r\n&lt;ul style=&quot;list-style-type: disc;&quot;&gt;\r\n&lt;li&gt;Fornire escursioni classiche, trekking e programmi di avventura.&lt;/li&gt;\r\n&lt;li&gt;Servizi di destinazione.&lt;/li&gt;\r\n&lt;li&gt;Viaggio di piacere.&lt;/li&gt;\r\n&lt;li&gt;Viaggi FAM.&lt;/li&gt;\r\n&lt;li&gt;Viaggi di squadra.&lt;/li&gt;\r\n&lt;li&gt;Viaggi di gruppo.&lt;/li&gt;\r\n&lt;li&gt;Viaggi aziendali.&lt;/li&gt;\r\n&lt;li&gt;Incentive Travel.&lt;/li&gt;\r\n&lt;li&gt;Servizi di viaggio American Express.&lt;/li&gt;\r\n&lt;li&gt;Incontro, eventi e conferenze.&lt;/li&gt;\r\n&lt;li&gt;Servizi di Produzione.&lt;/li&gt;\r\n&lt;li&gt;Logistica.&lt;/li&gt;\r\n&lt;li&gt;Trasporto terrestre in veicoli multi-categoria.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;Per saperne di più su PV Travels, ti preghiamo di inviare una mail a &lt;a href=&quot;mailto:info@pvt.jo&quot;&gt;info@pvt.jo&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;', 1, 321, 'it', '', 'one col', 'chi-siamo');
INSERT INTO `en33_pages` (`id`, `name`, `title`, `meta_desc`, `meta_key`, `contents`, `published`, `lang_id`, `lang`, `icon`, `layout`, `url`) VALUES
(377, 'Termini e condizioni', 'Termini e condizioni', 'Termini e condizioni', 'Termini e condizioni', '&lt;p&gt;&lt;span style=&quot;font-size: 18pt;&quot;&gt;&lt;strong&gt;Termini &amp;amp; Condizioni&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;VIAGGI FV. AVVISI, TERMINI E CONDIZIONI&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;<br>Siamo &lt;strong&gt;PV TRAVELS ,&lt;/strong&gt; e non vediamo l&#039;ora di poter agire come agente di prenotazione per le vostre esigenze di viaggio. Questi termini e condizioni (l&#039;&quot;Accordo&quot;) descrivono ciò che ha legittimamente diritto di aspettarvi da noi quando acquisti servizi di viaggio attraverso noi , oltre ai vostri obblighi di cliente. I termini &quot;noi&quot;, &quot;noi&quot; e &quot;nostri&quot; si riferiscono a &lt;strong&gt;PV TRAVELS&lt;/strong&gt;. Il termine &quot;tu&quot; si riferisce al cliente che visita il nostro sito web, prenotando una prenotazione attraverso di noi o usando i nostri servizi&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;1. Il nostro accordo con te&lt;/strong&gt;<br>  Prodotti e Fornitori<br>Vendiamo una varietà di prodotti correlati al viaggio da diversi fornitori e fornitori di servizi (&quot;Fornitori&quot;). Ogni Fornitore ha i propri termini e condizioni che sono applicabili ai tuoi particolari accordi in aggiunta ai nostri termini e condizioni generali e devi assicurarti di capirli. Alcuni software e contenuti presenti sul nostro sito web sono di proprietà o concessi in licenza da noi o dai nostri fornitori, il cui utilizzo potrebbe essere soggetto a ulteriori condizioni. Il nostro sito web, che viene indicato nel presente Contratto, è disponibile all&#039;indirizzo www.pvt.jo.<br>&lt;strong&gt;PV TRAVELS&lt;/strong&gt; agisce come intermediario o &quot;agente di prenotazione&quot; per prodotti e servizi non forniti direttamente da noi (ad esempio trasporto aereo e trasporto su terra, sistemazioni alberghiere, pasti, crociere, ecc.). Non siamo un co-vendor di tali prodotti e servizi. Sarai stipulato un contratto separato con tali Fornitori in relazione a tali prodotti e servizi.<br>Tutti i biglietti aerei sono soggetti ad aumenti di prezzo aggiuntivi che possono essere imposti dopo la data di acquisto. Gli aumenti di prezzo post-acquisto possono essere applicati a causa di costi aggiuntivi imposti da un fornitore o da un governo. Potete essere addebitati importi supplementari da parte di &lt;strong&gt;PV TRAVELS p&lt;/strong&gt;er compensare aumenti di tasse, sovraccarico di carburante, tasse e fluttuazioni dei mercati dei cambi o di qualsiasi loro combinazione. L&#039;accettazione di questi termini e condizioni consente di accettare gli aumenti di prezzo post-acquisto e di autorizzare &lt;strong&gt;PV TRAVELS&lt;/strong&gt; di addebitare la mia carta di credito per tali importi aggiuntivi.<br>&lt;strong&gt;Depositi e pagamento&lt;/strong&gt;<br>  Eventuali depositi da voi sono non rimborsabili. Il pagamento di un deposito ci consente di effettuare una prenotazione per te ma non garantisce il prezzo. Il prezzo può essere garantito solo una volta ricevuto il pagamento completo e altri documenti di viaggio sono stati rilasciati, a condizione che vengano rispettati i termini e le condizioni del Fornitore. Vi informiamo della data in cui è richiesto il pagamento completo. Al momento della fornitura delle informazioni sui tuoi pagamenti, ti autorizzi di effettuare le modalità di pagamento con i corrispondenti Fornitori.<br>  Ci riserviamo il diritto di rifiutare i controlli personali come metodo di pagamento. Dopo il pagamento completo, le condizioni del contratto con il vostro fornitore possono consentire loro di aumentare il costo dei vostri accordi. Se agiamo come Agente di Prenotazione, ti concederemo un aumento di questo tipo a quanto sappiamo di tale aumento. Se abbiamo organizzato un pacchetto, le modifiche dei costi di trasporto, compresi il costo del carburante, le tasse, le tasse e i tassi di cambio, consentono di modificare il prezzo del tuo viaggio dopo aver pagato integralmente.<br>&lt;strong&gt;Documentazione&lt;/strong&gt;<br>La nostra pratica generale è quella di inviare documenti ai nostri clienti elettronicamente quando possibile. Ci riserviamo il diritto di addebitare una tassa di amministrazione se si richiede che tali documenti siano inviati come copia cartacea.<br>Annullamenti e modifiche<br>Il contratto con i fornitori può consentire loro di annullare o modificare le prenotazioni. Se siamo il tuo agente di prenotazione, ti assicuriamo di essere tempestivamente informati di eventuali cambiamenti significativi una volta che siamo a conoscenza di tale modifica se c&#039;è tempo prima della partenza, ma non accettiamo alcuna responsabilità per eventuali variazioni o costi sostenuti. Con riserva dei termini e delle condizioni del Fornitore, potrai scegliere di accettare la modifica degli accordi, accettando un&#039;offerta di accordi di viaggio alternativi se uno è reso disponibile dal Fornitore, o annullando le tue prenotazioni e ricevendo eventuali restituzioni applicabili. Non garantiamo che rimborsi verranno applicati.<br>Se hai prenotato un volo e sei stato avvisato di un cambiamento significativo della programmazione della tua compagnia aerea prima di lasciare il tuo paese, ti contatteremo via e-mail per consigliarvi. Assicurati di averci dato il tuo indirizzo di posta elettronica di contatto e di controllare regolarmente i messaggi prima di partire. Non abbiamo alcun controllo sulle modifiche di orario della linea aerea e non accettiamo alcuna responsabilità per i costi che possono derivare a causa di tali modifiche.<br>Dopo aver lasciato il tuo paese, è la tua responsabilità di controllare con la compagnia aerea che i voli in continuazione che hai confermato funzionano come prenotati. Vi raccomandiamo vivamente di contattare la propria compagnia aerea almeno 72 ore prima della partenza programmata di ogni volo per farlo. Si prega di notare che per alcune compagnie aeree è obbligatorio confermare con loro l&#039;intenzione di volare.&lt;/p&gt;\r\n&lt;p&gt;2.&lt;strong&gt; Il tuo accordo con noi&lt;/strong&gt;<br>Con la prenotazione dell&#039;ordine con noi o usando il nostro sito web, accetti di essere vincolato ai termini del presente Contratto, compresi i Parti 1-3 del presente Contratto e eventuali ulteriori condizioni e condizioni di ogni Fornitore applicabili alla Sua prenotazione, modalità di viaggio o l&#039;utilizzo di qualsiasi contenuto del sito web. L&#039;utente accetta per conto di te stesso e di quelli che lei rappresenta per rispettare tutti questi termini e condizioni, incluso il pagamento di tutte le somme dovute. L&#039;utente accetta che qualsiasi violazione di tali termini e condizioni può comportare:<br>(a) la cancellazione della prenotazione o dell&#039;acquisto.<br>(b) la tua perdita di qualsiasi moneta pagata per la tua prenotazione o l&#039;acquisto.<br>(c) è negato l&#039;accesso al prodotto o servizio legati al viaggio.<br>(d) il nostro diritto di addebitare il tuo conto per qualsiasi costo che abbiamo a causa di tale violazione.<br>Lei rappresenta e garantisce che:<br>(a) un&#039;età sufficiente per utilizzare i nostri servizi e il nostro sito web e può creare obblighi legali vincolanti in relazione al tuo utilizzo.<br>(b) siete legalmente autorizzati ad agire per conto di coloro che rappresenti e accettate questi termini e condizioni per loro conto.<br>(c) le informazioni fornite da voi o dai membri del tuo gruppo sono vere e corrette. Lei è responsabile per informare tali altre persone di tutti i termini e le condizioni applicabili alle loro disposizioni di viaggio. Capi che sei finanziariamente responsabile di qualsiasi utilizzo dei nostri servizi o sito web da voi e da quelli che usano il tuo nome o il tuo account.<br>&lt;strong&gt;Se cambia la tua prenotazione&lt;/strong&gt;<br>Nel caso in cui sia consentita e possibile una modifica richiesta dai Vostri accordi di viaggio, le nostre spese di servizio standard saranno applicate in aggiunta a eventuali spese aggiuntive per i fornitori. Vi preghiamo di contattare il nostro agente di prenotazione per richiedere informazioni sulle modifiche o rivedere la sezione &quot;Aiuto di viaggio&quot; di www.pvt.jo per ulteriori dettagli su come richiedere le modifiche. Si prega di notare che tutte le modifiche della prenotazione sono soggette a disponibilità e ai termini e condizioni del prodotto acquistato.<br>Le modifiche ai dettagli dei nomi non sono consentite da molte compagnie aeree e da altri Fornitori. Mentre cercheremo di apportare un tale cambiamento se necessario, tenga presente che la maggior parte delle compagnie aeree e fornitori tratta un cambiamento di nome come una cancellazione, a cui si applicano condizioni e tariffe standard.<br>I voli devono essere presi nella sequenza che appaiono sul tuo biglietto o sulla conferma dell&#039;etichetta. Se si prevede di non prendere un volo prenotato, si prega di contattare la compagnia aerea per quanto possibile per discutere le opzioni. Se non si effettua il check-in in tempo per una prenotazione confermata, la compagnia aerea può registrarti come un &#039;no-show&#039;, che potrebbe comportare l&#039;addebito extra e / o l&#039;intero itinerario di volo e / o renderlo nullo.<br>&lt;strong&gt;Se si annulla la prenotazione&lt;/strong&gt;<br>Se annulli i tuoi accordi, puoi avere diritto a un rimborso parziale. Oltre ai termini e condizioni di cancellazione del Fornitore, le nostre tariffe standard saranno applicate, come indicato nella conferma ricevuta o confermata. Dobbiamo ricevere da voi il vostro voucher originale prima che sia possibile prendere in considerazione qualsiasi rimborso applicabile. Se decidete di annullare gli accordi prima della scadenza del saldo, i depositi versati non sono rimborsabili.<br>I rimborsi saranno pagati solo dopo aver ricevuto i fondi dal fornitore. In genere i biglietti aerei non possono essere rimborsati se sono utilizzati parzialmente. Non siamo responsabili di un mancato pagamento da parte del Fornitore di un rimborso.<br>Se il motivo della tua cancellazione è coperto dalle condizioni della tua polizza assicurativa, potresti essere in grado di recuperare le spese di cancellazione tramite il tuo assicuratore.<br>Avviso importante per quanto riguarda le prenotazioni aeree<br>Se arrivi a un biglietto aereo o al check-in con il tuo biglietto confermato e scopri che la compagnia aerea non mostra alcuna prenotazione per te - non lasciare il bancone. Controlla il tuo biglietto. Se la casella di stato visualizza &quot;OK&quot; per il volo in questione, le politiche di linea aerea richiedono in genere di ospitarli in quel volo, oppure, se non è possibile, dovranno trovarti un volo sostitutivo o pagare la compensazione di imbarco negata. Se necessario chiedere di parlare con un supervisore.<br>&lt;strong&gt;Se hai una denuncia&lt;/strong&gt;<br>Se hai un problema durante la tua vacanza, informi immediatamente il relativo fornitore (ad esempio il tuo hotel). Se non dovessero essere in grado di risolvere la questione, vi preghiamo di contattarci immediatamente tramite il nostro sito web all&#039;indirizzo email www.pvt.jo. Se non riesci a contattarci tempestivamente, non saremo autorizzati ad esaminare la tua denuncia e cercare di rettificare eventuali errori mentre sei fuori e questo potrebbe influenzare i tuoi diritti in base al presente accordo.<br>&lt;strong&gt;Documenti di viaggio e destinazioni&lt;/strong&gt;<br>È vostra responsabilità assicurare che tutti i dettagli dei documenti di viaggio siano corretti e riportare immediatamente agli errori o alle discrepanze. I vostri documenti di viaggio sono preziosi e dovrebbero essere salvaguardati come se fossero contanti. Non è sempre possibile sostituire i documenti di viaggio in caso di perdita, furto, danni, ecc.&lt;/p&gt;\r\n&lt;p&gt;Prima di prenotare viaggi internazionali, ti consigliamo di esaminare i divieti, le avvertenze e le avvertenze del tuo governo applicabili alle tue destinazioni. Offrendo viaggi a qualsiasi destinazione particolare, non rappresentiamo che il viaggio in tale destinazione sia sicuro o senza rischi.<br>L&#039;utente accetta inoltre che, in relazione alle tue attività, non consentirà l&#039;utilizzo dei nostri servizi o siti web da chiunque risieda o rimane in un paese per il quale tale uso sia vietato ai sensi delle norme nazionali.<br>&lt;strong&gt;Requisiti di passaporto, di visto e di immigrazione&lt;/strong&gt;<br>E &#039;vostra responsabilità di completare il passaporto, il visto e altri requisiti di immigrazione applicabili al tuo itinerario. Dovresti confermare queste con le ambasciate e / oi consolati pertinenti. Non accettiamo alcuna responsabilità nel caso in cui non sia in grado di viaggiare a causa della mancata osservanza di tali requisiti.<br>È inoltre richiesto di condurre un valido International Student I.D. e Youth International I.D. o un insegnante internazionale I.D. se viaggiate su un biglietto speciale per studenti / giovani / insegnanti. È vostra responsabilità verificare con il nostro esperto di viaggi che ti sta assistendo.<br>&lt;strong&gt;Assicurazione&lt;/strong&gt;<br>L&#039;assicurazione di viaggio è una parte vitale delle vostre disposizioni. Si raccomanda vivamente di aver assunto un&#039;assicurazione adeguata per tutta la durata del viaggio. L&#039;assicurazione viaggio è un elemento obbligatorio di alcuni accordi di viaggio. Potremmo essere in grado di organizzare l&#039;assicurazione di viaggio per essere forniti, fornirvi un preventivo e rispondere a tutte le domande che si possono avere per quanto riguarda l&#039;assicurazione.<br>&lt;strong&gt;Informazione sui materiali pericolosi&lt;/strong&gt;<br>La legge federale vieta il trasporto di materiali pericolosi a bordo di aeromobili nel bagaglio o sulla persona. Una violazione può comportare cinque anni di reclusione e penalità di $ 250.000 o più (49 U.S.C. 5124). I materiali pericolosi includono esplosivi, gas compressi, liquidi infiammabili e solidi, ossidanti, veleni, corrosivi e materiali radioattivi. Esempi: vernici, fluidi più leggeri, fuochi d&#039;artificio, gas di lacrimogeni, bottiglie di ossigeno e radiofarmaceutici.&lt;/p&gt;\r\n&lt;p&gt;Vi sono eccezioni speciali per piccole quantità (fino a 70 once in totale) di medicinali e articoli da toilette trasportati nel vostro bagaglio e alcuni materiali da fumo portati sulla vostra persona. Per ulteriori informazioni, consulta le informazioni contenute nella pagina web di articoli proibiti di TSA all&#039;indirizzo http://www.tsa.gov/traveler-information/prohibited-items.<br>&lt;strong&gt;Uso dei nostri servizi e sito web&lt;/strong&gt;<br>L&#039;utente accetta di utilizzare solo il nostro sito web oi suoi servizi per effettuare prenotazioni o acquisti legittimi e non effettuare prenotazioni speculative, false o fraudolente in previsione della domanda. Utilizzerai solo il nostro sito web e servizi in conformità alla legge applicabile.<br>Indennizzo<br>L&#039;utente accetta di indennizzare noi e le nostre affiliate, e qualsiasi nostro fornitore e gli agenti, direttori, dipendenti e agenti di tali parti da e contro qualsiasi rivendicazione, cause di azione, richieste, perdite, danni o altri costi (inclusi i costi ragionevoli spese legali e contabili) da voi o da terzi a seguito di<br>(a) la tua violazione del presente Contratto.<br>(b) la tua violazione di qualsiasi legge o diritti di terzi.<br>(c) l&#039;utilizzo del nostro sito web.<br>&lt;strong&gt;politica sulla riservatezza&lt;/strong&gt;<br>L&#039;utente acconsente al trattamento e alla condivisione di informazioni personali su di te e su altri membri del tuo gruppo che ci hai fornito in conformità ai termini e alle finalità previste dalla nostra politica sulla privacy. Dichiari di aver letto e di accettare i termini della nostra politica sulla privacy, che potete trovare sul nostro sito web.&lt;/p&gt;\r\n&lt;p&gt;3.&lt;strong&gt; Condizioni aggiuntive&lt;/strong&gt;<br>&lt;strong&gt;Garanzie, obblighi di responsabilità e limitazione della responsabilità&lt;/strong&gt;<br>PER L&#039;AVANZAMENTO DEL DOPPIO, I RIFERIMENTI QUI PER &quot;US&quot; &quot;NOI&quot; E &quot;NOSTRI&quot; RICHIAMIAMO ANCHE I NOSTRI AFFILIATI. LE INFORMAZIONI, IL SOFTWARE, I PRODOTTI E I SERVIZI FORNITI DALL&#039;UTENTE O DEI NOSTRI FORNITORI O PUBBLICATI NEL SITO WEB, POSSONO COMPRENDERE INSERIMENTI O ERRORI, INCLUSI ERRORI DI PREZZO. NON GARANTIAMO LA PRECISIONE DI QUESTO RESPONSABILITÀ PER QUALSIASI ERRORE O ALTRE INACCURAZIONI RELATIVE A TALI INFORMAZIONI CHE SONO VISUALIZZATE NEL SITO WEB. RISPETTIAMO ESPRESSAMENTE IL DIRITTO DI CORRETTI QUALSIASI ERRORI DI PRESENTAZIONE SUL SITO WEB E / O SU PRENOTAZIONI PRONUNCIATE SOTTO UN PREZZO INCORRETTO. IN TALE EVENTUALE, SE DISPONIBILE, OFFRIAMO L&#039;OPPORTUNITA &#039;DI TENERE LA VOSTRA PRENOTAZIONE IN ATTESA AL PREZZO CORRETTO O VIA ANNULLARE LA VOSTRA PRENOTAZIONE SENZA PENALITÀ.<br>QUALSIASI VALUTAZIONE PER I FORNITORI SONO INTENDITA SOLTANTO COME GENERALGUIDELINES, E NON GARANTISCE L&#039;ACCURATEZZA DELLE VALUTAZIONI. NON SIANO GARANZIE SULLA DISPONIBILITA DI PRODOTTI E SERVIZI SPECIFICI. NESSUNA RAPPRESENTANZA SULLA SUITABILITÀ DEGLI INFORMAZIONI, SOFTWARE, PRODOTTI E SERVIZI FORNITI DALL&#039;UTENTE O CONTENUTI NEL SITO WEB PER QUALSIASI SCOPO. L&#039;INCLUSIONE O L&#039;OFFERTA DI QUALSIASI PRODOTTO O SERVIZI DA US NON COSTITUISCE LA NOSTRA RILASCIO O RACCOMANDAZIONE DI TALE PRODOTTO O SERVIZIO. TUTTE LE INFORMAZIONI, IL SOFTWARE, I PRODOTTI E I SERVIZI SONO FORNITI &quot;COME SONO&quot; SENZA GARANZIA DI QUALUNQUE TIPO. DECLINCIAMO TUTTE LE GARANZIE CHE IL NOSTRO SITO WEB, I SUOI ​​SERVER O QUALSIASI EMAIL inviati da noi o dai nostri fornitori sono privi di virus o altri componenti dannosi. PER QUESTO INFORMAZIONE, SOFTWARE, PRODOTTI E SERVIZI, COMPRESI TUTTE LE GARANZIE IMPLICITE E LE CONDIZIONI DI COMMERCIABILITÀ, IDONEITÀ PER UNO SCOPO PARTICOLARE, IL TITOLO E LA NON RIFERIMENTO. I DICHIARAZIONE DI GARANZIA POSSONO VARIE DALLA STATO A STATO.<br>I VIAGGIATORI, ALBERGHI E ALTRI FORNITORI FORNITI SUI VIAGGI O ALTRI SERVIZI SU QUESTO SITO WEB SONO CONTRATTI INDIPENDENTI E NON AGENTI O DIPENDENTI DEL GOVERNO. NON SONO NON RESPONSABILI PER LE ATTIVITÀ, ERRORI, OMISSIONI, RAPPRESENTAZIONI, GARANZIE, VIOLAZIONI O NEGLIGENZA DI QUESTI FORNITORI O PER QUALSIASI DANNI PERSONALI, MORTE, DANNI DI PROPRIETÀ, O ALTRI DANNI O SPESE RISULTANTI DI QUESTI FORNITORI. Non abbiamo alcuna responsabilità e non comporteremo alcun rimborso nel caso di qualsiasi ritardo, cancellazione, overbooking, aggressione, forza maggiore o altre cause al di fuori del nostro controllo, e non abbiamo nessuna responsabilità per qualsiasi spesa aggiuntiva, omissioni, ritardi, re-route o atti DI QUALSIASI GOVERNO O AUTORITA.<br>IN NESSUN CASO SIAMO RESPONSABILE PER QUALSIASI DANNO DIRETTO, INDIRETTO, PUNITIVO, INCIDENTALE, SPECIALE O CONSEQUENZIALE DERIVANTI DA QUALSIASI MODO CONNESSO, IL TUO ACCESSO, VISUALIZZAZIONE O UTILIZZO DI QUESTO SITO WEB O DEI NOSTRI SERVIZI O CON IL RITARDO O INCAPACITA &#039;DI ACCESSO, DISPLAY O UTILIZZO IL NOSTRO SITO WEB SIANTO BASATO SU UNA TEORIA DI NEGLIGENZA, CONTRATTO, RISOLUZIONE, RESPONSABILITA&#039; O ALTRIMENTI E ANCHE SE SONO STATI INFORMATI DELLA POSSIBILITA DI TALI DANNI.<br>QUALORA, A DISPOSIZIONE DELLA LIMITAZIONE SOPRA, SI RISERVA RESPONSABILE PER QUALSIASI PERDITA O DANNO CHE ESPRESSA O IN QUALSIASI MODO COLLEGATA CON QUALUNQUE DEI PROVVEDIMENTI DESCRITTI SOPRA, QUINDI LA NOSTRA RESPONSABILITÀ NON SARÀ ALCUNE NELLA AGGREGATA, LA MAGGIORE ( A) LE TASSE DI SERVIZI CHE PAGATE AI NOMI IN CONNESSIONE CON TALI TRANSAZIONI SU QUESTO SITO WEB, O (B) DOLLARI UNAI DOLLARI (US $ 100.00) O L&#039;EQUIVALENTE IN VALUTA LOCALE.<br>LA LIMITAZIONE DI RESPONSABILITÀ RIFIUTA LA DESTINAZIONE DEL RISCHIO TRA LE PARTI. LE LIMITAZIONI SPECIFICATE IN QUESTA SEZIONE SARANNO SOPRATTUTTO E APPLICARE ANCHE SE QUALSIASI RIMEDIO LIMITATO SPECIFICATO A QUESTI TERMINI SI TROVA DI NON ESSERE FATTO DEL SUO SCOPO ESSENZIALE.<br>&lt;strong&gt;Generale&lt;/strong&gt;<br>Noi agiamo come un imprenditore indipendente e non esiste alcuna joint venture, partnership o rapporto di lavoro fra te e noi o i nostri Fornitori a seguito di questo Accordo o l&#039;utilizzo del nostro sito web.<br>Ci riserviamo il diritto in qualsiasi momento di modificare il presente accordo senza preavviso. Consultare il nostro sito web all&#039;indirizzo www.pvt.jo di tanto in tanto per esaminare la versione più recente dell&#039;accordo. L&#039;accesso continuo o l&#039;utilizzo del nostro sito web o dei servizi significa accettare le modifiche apportate all&#039;accordo. Non puoi assegnare i tuoi diritti o gli obblighi derivanti dal presente accordo a terzi. Possiamo terminare il presente Accordo in qualsiasi momento per qualsiasi motivo, e tale risoluzione non pregiudica alcun diritto a sollievo a cui siamo legittimi sotto legge o in patrimonio netto.<br>Il presente Accordo è disciplinato dalle leggi dello Stato del Giordano senza tener conto dei suoi principi di conflitto di leggi. Qualora una qualsiasi delle disposizioni del presente Contratto sia ritenuta invalida, illegale o inapplicabile, l&#039;esecutività delle restanti disposizioni non sarà in alcun modo compromessa o compromessa.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Prenotazione Tours Condizioni:&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Leggere attentamente le seguenti condizioni di prenotazione;<br>&lt;strong&gt;PV&lt;/strong&gt; Travels si riserva il diritto di negare la partecipazione a chiunque sia inadatto, malato, o in qualche modo pregiudizievole per la sicurezza del gruppo. La partecipazione di qualsiasi persona a qualsiasi programma è continuamente soggetta alla discrezione degli istruttori e / o delle guide.&lt;/p&gt;\r\n&lt;p&gt;I viaggi &lt;strong&gt;PV Travels&lt;/strong&gt; non si assume alcuna responsabilità per le azioni di persone e / o società che forniscono beni e / o servizi come parte dei pacchetti o per eventuali costi aggiuntivi che possono derivare dal programma di complicazione o di prolungamento per qualsiasi motivo.&lt;/p&gt;\r\n&lt;p&gt;Tutti i problemi o le condizioni mediche o sanitarie che possono influire sulla partecipazione a qualsiasi corso o programma devono essere cancellate dal medico prima di effettuare il tour.&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;Procedura di prenotazione di prenotazione:&lt;/strong&gt;<br>Compila il nostro modulo di registrazione regolare per creare un account sul nostro sito web e per controllare le statistiche di prenotazione. Al momento della prenotazione, è necessario un pagamento o un deposito appropriato più le seguenti informazioni:&lt;/p&gt;\r\n&lt;p&gt;A: Nome e indirizzo postale, telefono e numeri di fax.&lt;/p&gt;\r\n&lt;p&gt;B: Il programma e le date che si desidera prenotare e le informazioni di contatto per l&#039;emergenza.&lt;/p&gt;\r\n&lt;p&gt;C: Elenco con passaporto completo Dettagli dei clienti o persone che partecipano al tour proposto.&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;Pagamento&lt;/strong&gt;<br>I prezzi indicati sono in dollari statunitensi. Non includono l&#039;assicurazione di viaggio. Tutti i prezzi sono soggetti a modifiche prima dell&#039;inizio del tour. Se desideri ricevere una ricevuta stampata, ti preghiamo di specificare una richiesta.<br>Non confermeremo alcuna prenotazione fino a quando non verrà ricevuto il pagamento&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;Cancellazione e rimborso della prenotazione Tour:&lt;/strong&gt;<br>PV Travels si riserva il diritto di modificare o ritirare in parte o di annullare le attrezzature fornite in un determinato pacchetto senza preavviso. Tutti i pacchetti sono estensibili a tariffa pro-rate come citato al momento della prenotazione solo o soggetto a disponibilità. Le tariffe sono soggette a modifiche senza preavviso a causa di un improvviso aumento delle imposte governative e dei costi del carburante.&lt;/p&gt;\r\n&lt;p&gt;Ci riserviamo il diritto di annullare un tour a causa della scarsa iscrizione o condizioni climatiche severe (NOTA: PV Travels si riserva il diritto di modificare, alterare o annullare qualsiasi parte del tuo itinerario tutto o il servizio in qualsiasi momento dopo la prenotazione a causa del tempo, delle condizioni o altri motivi senza penalità).&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Politica di rimborso.&lt;/strong&gt;<br>Nessun rimborso per soggiorni brevi e strutture non utilizzate come gite giornaliere.<br>Se si annulla la prenotazione per qualsiasi ragione le seguenti penalità si applicano, le seguenti tariffe saranno applicate a tutte le prenotazioni confermate a PV Travels:&lt;/p&gt;\r\n&lt;p&gt;A: Se la cancellazione avviene 45 giorni o più prima dell&#039;inizio del programma, il rimborso completo con la detrazione di minatori per qualsiasi tasse di testo o materiali&lt;/p&gt;\r\n&lt;p&gt;B: canoni di cancellazione del 50% Quando la cancellazione avviene tra 44 e 25 giorni prima dell&#039;inizio del programma,&lt;/p&gt;\r\n&lt;p&gt;C: 100% o la tassa del pacchetto completo se la cancellazione avviene tra gli ultimi 24 giorni prima dell&#039;inizio del programma.&lt;/p&gt;\r\n&lt;p&gt;D: I depositi non rimborsabili non fanno parte della politica di cancellazione e devono essere informati per iscritto e la prova del riconoscimento da parte nostra deve essere conservata.<br> <br>&lt;strong&gt;Per ulteriori informazioni contattaci all&#039;indirizzo: &lt;a href=&quot;mailto:info@pvt.jo&quot;&gt;info@pvt.jo&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;', 1, 340, 'it', '', 'one col', 'termini-e-condizioni'),
(378, 'Prima Che Tu Vada', 'Prima Che Tu Vada', 'Consigli per il viaggiatore prima di partire', 'Prima Che Tu Vada', '&lt;p&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;Prima Che tu Vada&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Ricercare informazioni di base sulla destinazione.&lt;/li&gt;\r\n&lt;li&gt;Lasciare una copia del tuo itinerario con un familiare o un amico di fiducia.&lt;/li&gt;\r\n&lt;li&gt;Se si guida, assicurarsi che il veicolo sia in buone condizioni di funzionamento.&lt;/li&gt;\r\n&lt;li&gt;Ottenere copie di mappe della destinazione per individuare percorsi, attrazioni e servizi essenziali.&lt;/li&gt;\r\n&lt;li&gt;Prendi in considerazione l&#039;adesione ad AAA o ad un altro club turistico per assistenza stradale o altre assistenza.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;Consigli Internazionali di Viaggio&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Lo sapevi che hai bisogno di un passaporto attuale valido se viaggiate ovunque al di fuori degli Stati Uniti, tra cui Canada e il Messico? Se non si dispone di un passaporto attuale valido, visitare il sito Web del Dipartimento di Stato Usa per richiedere o rinnovare il passaporto.&lt;/li&gt;\r\n&lt;li&gt;Oltre a un passaporto, potrebbe anche essere necessario un visto per visitare alcuni paesi. Verificare con il sito Web del Dipartimento di Stato degli Stati Uniti o i siti web del turismo o degli affari esteri di paesi o paesi ospitanti.&lt;/li&gt;\r\n&lt;li&gt;Piano di guida in un altro paese? Controllare se la tua patente di guida è valida all&#039;estero. Potrebbe essere necessario anche un permesso di guida internazionale o una traduzione della patente di guida statunitense. Visitare il sito web di IDA di AAA per applicare.&lt;/li&gt;\r\n&lt;li&gt;Trova l&#039;indirizzo e il numero di telefono del consolato o dell&#039;ambasciata Usa.&lt;/li&gt;\r\n&lt;li&gt;Ricercare informazioni di base sul paese o sui paesi che intendi visitare per aiutarti a familiarizzare con le leggi ei costumi locali. La tua biblioteca o agente di viaggio sono risorse preziose qui. Inoltre, consulta il Dipartimento di Stato degli Stati Uniti per vedere se sono presenti avvertimenti o consigli per considerazioni particolari per il paese o per i paesi in cui intendi visitare.&lt;/li&gt;\r\n&lt;li&gt;Conoscere alcune parole e frasi fondamentali nella lingua del paese o dei paesi che intendi visitare.&lt;/li&gt;\r\n&lt;li&gt;Registri con il Dipartimento di Stato degli Stati Uniti per rendere più facile per il governo degli Stati Uniti di aiutarti in un&#039;emergenza all&#039;estero.&lt;/li&gt;\r\n&lt;li&gt;Effettuare fotocopie del passaporto, dei biglietti aerei, del visto, trasportare un set di copie in un luogo sicuro e lasciare un altro set di copie a casa con un familiare o un amico di fiducia.&lt;/li&gt;\r\n&lt;li&gt;L&#039;assicurazione sulla salute e sull&#039;infortunio non può essere valida al di fuori degli Stati Uniti. Controllare con il proprio fornitore di assicurazioni se è necessario un&#039;ulteriore assicurazione contro le malattie e gli infortuni.&lt;/li&gt;\r\n&lt;li&gt;Alcuni paesi hanno restrizioni sulle cose che puoi portare con te o portatevi a casa con te.&lt;/li&gt;\r\n&lt;li&gt;Ci possono essere restrizioni per riportare alcune cose negli Stati Uniti con te. Per ulteriori informazioni, consultare la legislazione doganale e la protezione delle frontiere statunitensi.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;Condividere&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Luce da viaggio.&lt;/li&gt;\r\n&lt;li&gt;Se avete bisogno di farmaci da prescrizione, portatevi abbastanza per durare la durata del viaggio. Inoltre, se si indossano occhiali, portare una coppia aggiuntiva.&lt;/li&gt;\r\n&lt;li&gt;Conservare i medicinali nei contenitori originali. Potresti anche aver bisogno di una lettera del tuo medico che spiega perché ti serve alcuni medicinali.&lt;/li&gt;\r\n&lt;li&gt;Non imballare o portare oggetti vietati, come armi, oggetti taglienti o sostanze pericolose.&lt;/li&gt;\r\n&lt;li&gt;Non portare un sacco di soldi o carte di credito. Invece, metti i controlli dei viaggiatori, una o due carte di credito e solo una piccola quantità di denaro.&lt;/li&gt;\r\n&lt;li&gt;Non imballare o portare oggetti di valore, come un gioiello.&lt;/li&gt;\r\n&lt;li&gt;Assicurarsi che il bagaglio sia etichettato con il tuo nome e numero di telefono, ma utilizza un tag di bagaglio. Puoi anche utilizzare l&#039;indirizzo e il numero di telefono del tuo lavoro sui tuoi articoli di viaggio.&lt;/li&gt;\r\n&lt;li&gt;Ricorda le regole per ciò che puoi fare e cosa deve essere controllato quando vola. Visitare il sito Web dell&#039;amministrazione Transportation Security per ulteriori informazioni su queste regole.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;All&#039;Aeroporto e All&#039;Aria &lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Non lasciare incustodito il bagaglio.&lt;/li&gt;\r\n&lt;li&gt;Non lasciare che altri membri del personale aeroportuale gestiscano i bagagli.&lt;/li&gt;\r\n&lt;li&gt;Non accettare pacchetti di sconosciuti.&lt;/li&gt;\r\n&lt;li&gt;Segnala qualsiasi attività sospetta.&lt;/li&gt;\r\n&lt;li&gt;Seguire tutte le norme e le istruzioni di sicurezza.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;Sulla Strada&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Indossare la cintura di sicurezza.&lt;/li&gt;\r\n&lt;li&gt;Non bere e guidare, e non cavalcare con chiunque abbia bevuto.&lt;/li&gt;\r\n&lt;li&gt;Assicurarsi che i bambini siano in seggiolini per bambini approvati.&lt;/li&gt;\r\n&lt;li&gt;Non guidare se si sente sonnolento.&lt;/li&gt;\r\n&lt;li&gt;Non utilizzare telefoni cellulari o altri dispositivi elettronici durante la guida.&lt;/li&gt;\r\n&lt;li&gt;Non attaccare l&#039;escursione, e non prendere gli escursionisti.&lt;/li&gt;\r\n&lt;li&gt;Prestare attenzione alle condizioni stradali e ai vostri dintorni.&lt;/li&gt;\r\n&lt;li&gt;Parcheggiare in aree ben illuminate e ben curate.&lt;/li&gt;\r\n&lt;li&gt;Mantenga le porte della tua auto bloccate.&lt;/li&gt;\r\n&lt;li&gt;Non collocare il bagaglio o altri oggetti di valore in un luogo dove i criminali possono facilmente vederli.&lt;/li&gt;\r\n&lt;li&gt;Se avete problemi con l&#039;auto, accettate solo l&#039;assistenza di polizia o di un altro personale autorizzato.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;Nel Tuo Hotel&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Trovare le uscite più vicine, l&#039;allarme antincendio, l&#039;estintore / il tubo flessibile più vicino alla vostra stanza.&lt;/li&gt;\r\n&lt;li&gt;Tieni sempre bloccato la porta della tua camera d&#039;albergo.&lt;/li&gt;\r\n&lt;li&gt;Chiedi ai visitatori di incontrarvi nella hall o in altri spazi pubblici del tuo hotel.&lt;/li&gt;\r\n&lt;li&gt;Utilizzare la cassaforte dell&#039;hotel per immagazzinare oggetti di valore.&lt;/li&gt;\r\n&lt;li&gt;Non entrare in un ascensore da solo con gli sconosciuti sospetti.&lt;/li&gt;\r\n&lt;li&gt;Chiedere al personale dell&#039;hotel informazioni sulle politiche di sicurezza se non siete sicuri.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;Informazioni&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Prestare attenzione ai vostri dintorni.&lt;/li&gt;\r\n&lt;li&gt;Non prendete più denaro, assegni di viaggio o carte di credito di quanto non ti serve.&lt;/li&gt;\r\n&lt;li&gt;Non accettare corse da sconosciuti.&lt;/li&gt;\r\n&lt;li&gt;Evita grandi folle, dimostrazioni o confronti pubblici.&lt;/li&gt;\r\n&lt;li&gt;Mantenere un basso profilo.&lt;/li&gt;\r\n&lt;li&gt;Non avere troppo alcool per bere.&lt;/li&gt;\r\n&lt;li&gt;Soggiorno in luoghi ben illuminati e ben curati.&lt;/li&gt;\r\n&lt;li&gt;Non &quot;flash&quot; il tuo denaro o altri oggetti di valore.&lt;/li&gt;\r\n&lt;li&gt;Non discutere i piani di viaggio con gli sconosciuti.&lt;/li&gt;\r\n&lt;li&gt;Individuare la posizione della stazione di polizia più vicina, dell&#039;ospedale e di altri posti di sicurezza.&lt;/li&gt;\r\n&lt;li&gt;Segnala qualsiasi attività sospetta alla polizia.&lt;/li&gt;\r\n&lt;li&gt;Se sei derubato, non resistere.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt; &lt;/p&gt;', 1, 322, 'it', '', 'one col', 'prima-che-tu-vada'),
(379, 'Privacy e Politica', 'Privacy e Politica', ' Politiche sulla privacy', 'Politica', '&lt;p&gt;<br>A &lt;a href=&quot;http://www.pvt.jo&quot;&gt;PV Travels,&lt;/a&gt; una delle nostre principali priorità è la privacy dei nostri visitatori. Questo documento della politica sulla privacy contiene i tipi di informazioni raccolti e registrati da &lt;a href=&quot;http://www.pvt.jo&quot;&gt;www.pvt.jo&lt;/a&gt; e come lo usiamo.&lt;/p&gt;\r\n&lt;p&gt;Se hai domande aggiuntive o richiedi maggiori informazioni sulla nostra politica sulla privacy, non esitate a contattarci via email all&#039;indirizzo &lt;a href=&quot;mailto:info@pvt.jo&quot;&gt;info@pvt.jo&lt;/a&gt;.&lt;/p&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Log files&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;<br>&lt;a href=&quot;http://www.pvt.jo&quot;&gt;www.pvt.jo&lt;/a&gt; segue una procedura standard di utilizzo dei file di registro. Questi file registrano i visitatori quando visitano i siti web. Tutte le aziende di hosting l lo fanno e una parte dell&#039;analisi dei servizi di hosting. Le informazioni raccolte dai file di registro includono indirizzi IP (Internet Protocol), tipo di browser, ISP (Internet Service Provider), timbro di data e ora, pagine di riferimento / uscita e forse il numero di clic. Questi non sono collegati a qualsiasi informazione che sia personalmente identificabile. Lo scopo delle informazioni è quello di analizzare le tendenze, gestire il sito, monitorare il movimento degli utenti sul sito web e raccogliere informazioni demografiche.&lt;/p&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Cookies e Web Beacons&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Come qualsiasi altro sito web, &lt;a href=&quot;http://www.pvt.jo&quot;&gt;www.pvt.jo&lt;/a&gt; usa &#039;cookie&#039;. Questi cookie vengono utilizzati per memorizzare informazioni incluse le preferenze dei visitatori e le pagine sul sito web che il visitatore ha visitato. Le informazioni vengono utilizzate per ottimizzare l&#039;esperienza degli utenti personalizzando il  contenuto della nostra pagina web in base al tipo di browser del visitatore e / o ad altre informazioni.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;&lt;strong&gt;DoubleClick DART Cookie&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;<br>Google è uno dei fornitori di terze parti sul nostro sito. Utilizza anche i cookie, conosciuti come cookie DART, per pubblicare annunci ai visitatori del sito in base alla loro visita a www.website.come in altri siti su Internet. Tuttavia, i visitatori possono decidere di rifiutare l&#039;utilizzo dei cookie DART visitando la Normativa sulla privacy degli annunci Google e della rete di contenuti al seguente URL - &lt;a href=&quot;http://www.google.com/privacy_ads.html&quot;&gt;http://www.google.com/privacy_ads.html&lt;/a&gt;.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;&lt;strong&gt;I nostri partner pubblicitari&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;<br>Alcuni degli inserzionisti del nostro sito possono utilizzare i cookie ei web beacons. I nostri partner pubblicitari includono:&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Google&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;Ciascuno dei nostri partner pubblicitari ha le proprie norme sulla privacy per il proprio sito web. &lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;&lt;strong&gt;Politiche sulla privacy&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;<br>Puoi consultare questo elenco per trovare la Politica sulla privacy per ciascuno dei partner pubblicitari di www.pvt.jo.<br>I server pubblicitari o le reti pubblicitarie di terze parti utilizzano tecnologie come cookie, JavaScript o traccianti Web utilizzati nelle rispettive pubblicità e nei collegamenti visualizzati sul sito www.pvt.jo, che vengono inviati direttamente al browser degli utenti. Riceveranno automaticamente l&#039;indirizzo IP quando si verifica. Queste tecnologie vengono utilizzate per misurare l&#039;efficacia delle loro campagnie pubblicitarie e / o per personalizzare i contenuti pubblicitari che si vedono nei siti web visitati.<br>Tieni presente che www.pvt.jo non ha accesso o controlli su questi cookie utilizzati da inserzionisti di terze parti.&lt;/p&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Politiche sulla privacy di terza parte&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;<br>&lt;a href=&quot;http://www.pvt.jo&quot;&gt;www.pvt.jo&lt;/a&gt; La Privacy Policy non si applica ad altri inserzionisti o siti web. Quindi, ti consigliamo di consultare le rispettive Norme sulla privacy di questi server  di terze parti per informazioni più dettagliate. Può includere le loro pratiche e istruzioni su come disattivare alcune opzioni. Potete trovare un elenco completo di queste norme sulla privacy ei loro link qui: Informativa sulla privacy Links.<br>Puoi scegliere di disattivare i cookie tramite le opzioni del browser. Per conoscere informazioni più dettagliate sulla gestione dei cookie con browser web specifici, è possibile trovare i siti web dei browser. Cosa sono i cookie?&lt;/p&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Informazioni per i bambini&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;<br>Un&#039;altra parte della nostra priorità è l&#039;aggiunta di protezione per i bambini durante l&#039;utilizzo di Internet. Incoraggiamo i genitori e i tutori di osservare, partecipare e / o monitorare e guidare la loro attività online.<br>www.pvt.jo non sa raccogliere informazioni personali identificabili da bambini di età inferiore ai 13 anni. Se pensi che il tuo figlio ha fornito questo tipo di informazioni sul nostro sito web, ti incoraggiamo a contattarci immediatamente e faremo del nostro meglio per eliminare tempestivamente tali  informazioni dai nostri record.&lt;/p&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Solo la politica di privacy online&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;<br>Questa politica sulla privacy si applica solo alle nostre attività online ed è valida per i visitatori del nostro sito web per quanto riguarda le informazioni che hanno condiviso e / o raccolto in www.pvt.jo. Questa politica non è applicabile a tutte le informazioni raccolte in linea o su canali diversi da questo sito web.&lt;/p&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Consenso&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;<br>Usando il nostro sito web, tu acconsenti alla nostra Privacy Policy e accetti i Termini e le Condizioni.&lt;/p&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Aggiornare&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;<br>Questa politica sulla privacy è stata aggiornata l&#039;ultima volta il 20 maggio 2016. Se ci saranno aggiornamenti, modifiche alla nostra politica sulla  privacy, queste saranno pubblicate in questa pagina.&lt;/p&gt;', 1, 337, 'it', '', 'one col', 'privacy-e-politica'),
(380, 'Opportunità di lavoro', 'Opportunità di lavoro', 'Lavoro in Giordania', 'Lavoro ,turismo', '&lt;p&gt;La Giordania è una delle nazioni più affascinanti del Medio Oriente. Dai siti biblici, castelli, antiche cittadine a rovinate città romane, troverete facilmente qualcosa in Giordania che vi affascina. Giordania è la casa di Petra, antica città persa di Nabataean, paragonabile a Machu Picchu, come anche Angkor Wat e Amman, la sua capitale e una città araba moderna e culturalmente diversificata. Ci sono molte opportunità per gli individui che vogliono scoprire un aspetto diverso della nazione da volontariato.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;&lt;strong&gt;Riepilogo del lavoro:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;<br>Stiamo cercando una persona qualificata che parli e scrivi italiano e spagnolo per lavorare nella nostra agenzia di viaggi a Petra.&lt;/p&gt;\r\n&lt;p&gt;Sarai in primo luogo responsabile per le email dei nostri clienti e per analizzarle tutte e risponderle in meno di un&#039;ora.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;&lt;strong&gt;Responsabilità:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Eseguire, mantenere, riconciliare, rivedere, combinare, analizzare e inserire i dati nelle lingue richieste sul nostro sito Web.&lt;/li&gt;\r\n&lt;li&gt;Identifica e risolvi tutte le email.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Titoli di studio:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Avere esperienza lavorativa come contabile.&lt;/li&gt;\r\n&lt;li&gt;Il diploma di laurea più due anni di esperienza applicabile, o combinazione di istruzione e esperienza di lavoro rilevante.&lt;/li&gt;\r\n&lt;li&gt;Competenza nelle applicazioni aziendali di base, come ad esempio Microsoft Office; conoscenza dell&#039;utente di Excel.&lt;/li&gt;\r\n&lt;li&gt;Conoscenza di base dei sistemi contabili e internet; abilità nell&#039;usare il computer.&lt;/li&gt;\r\n&lt;li&gt;Comprensione e capacità di applicare competenze e concetti contabili.&lt;/li&gt;\r\n&lt;li&gt;Capacità di elaborare messaggi e-mail professionali, memo, lettere aziendali e rapporti e per comunicare in modo chiaro e efficace informazioni a pubblico interno e gruppi di clienti.&lt;/li&gt;\r\n&lt;li&gt;Capacità di apprendere le competenze di gestione del progetto e di partecipare come parte di un team di progetto.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Benefici:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Vacanze a pagamento =&amp;gt; Sì&lt;/li&gt;\r\n&lt;li&gt;Congedo di malattia =&amp;gt; Sì&lt;/li&gt;\r\n&lt;li&gt;Benefici per la salute per includere medici e dentali =&amp;gt; No&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Applicare:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Invia un curriculum dettagliato della tua esperienza.&lt;/li&gt;\r\n&lt;li&gt;Inviate una lettera di copertura per spiegare perché saresti una buona misura&lt;/li&gt;\r\n&lt;li&gt;Invia il tuo CV completo alla nostra email a &lt;strong&gt;&lt;a href=&quot;mailto:khaled@pvt.jo&quot;&gt;khaled@pvt.jo&lt;/a&gt; &lt;/strong&gt;Oppure da Whatsapp a &lt;strong&gt;+96277 77 67 938&lt;/strong&gt;&lt;/li&gt;\r\n&lt;/ul&gt;', 1, 355, 'it', '', 'one col', 'opportunità-di-lavoro-'),
(381, 'فرصة عمل  في الأردن ', 'فرصة عمل  في الأردن ', 'عمل في مكتبنا السياحي في البتراء ', 'فرصة عمل في المجال السياحي', '&lt;p style=&quot;text-align: right;&quot;&gt;&lt;strong&gt;الأردن&lt;/strong&gt; هو واحد من أكثر الدول الرائعة في الشرق الأوسط. من مواقع مقدسة وقلاع قديمة إلى المدن الرومانية، وسوف تجد بسهولة شيئا  يفتنك في الأردن. الأردن هو بيت البتراء، وهي مدينة نبطية قديمة، مماثلة لماشو بيتشو، فضلا عن أنغكور وات وعمان، عاصمتها ومدينة عربية حديثة ومتنوعة ثقافيا. هناك العديد من الفرص للأفراد الذين يرغبون في اكتشاف جانب مختلف  من خلال العمل التطوعي&lt;/p&gt;\r\n&lt;p style=&quot;text-align: right;&quot;&gt;.&lt;strong&gt;:ملخص الوظيفة&lt;/strong&gt;<br>نحن نبحث عن  شخص مؤهل  يتحدث ويكتب الإيطالية والإسبانية للعمل في شركتنا السياحية في البتراء.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: right;&quot;&gt;سوف تكون في المقام الأول مسؤول عن  عملائنا وترد على رسائل البريد الإلكتروني وفي أقل من ساعة واحدة.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: right;&quot;&gt;&lt;strong&gt;المسؤوليات&lt;/strong&gt;<br>تشغيل، صيانة، التوفيق، مراجعة، الجمع، تحليل كل هذه القضايا في موقعنا على الانترنت وإدخال البيانات في اللغات المطلوبة.<br>الرد على جميع رسائل البريد الإلكتروني.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: right;&quot;&gt;&lt;strong&gt;المؤهلات&lt;/strong&gt;<br>وجود خبرة في العمل كمحاسب<br>درجة البكالوريوس بالإضافة إلى سنتين من الخبرة المنطبقة، أو مزيج من التعليم وخبرة العمل ذات الصلة<br>الكفاءة في تطبيقات الأعمال الأساسية، مثل مايكروسوفت أوفيس.  معرفة استخدام  إكسيل<br>المعرفة الأساسية للنظم المحاسبية والإنترنت؛ ثقافة الحاسوب<br>فهم والقدرة على تطبيق المهارات والمفاهيم المحاسبية<br>القدرة على صياغة رسائل البريد الإلكتروني المهنية والمذكرات ورسائل الأعمال والتقارير، و بشكل واضح وفعال التواصل المعلومات للجمهور الداخلي ومجموعات العملاء<br>القدرة على تعلم مهارات إدارة المشاريع والمشاركة كجزء من فريق المشروع<br>&lt;strong&gt;فوائد&lt;/strong&gt;<br>عطلة مدفوعة =&amp;gt; نعم<br>إجازة مرضية =&amp;gt; نعم<br>الفوائد الصحية لتشمل الطبية وطب الأسنان =&amp;gt; لا<br>&lt;strong&gt;للتقديم:&lt;/strong&gt;<br>إرسال السيرة الذاتية بالتفصيل <br>إرسال خطاب تغطية شرح لماذا ستكون الشخص المناسب<br>أرسل سيرتك الذاتية إلى بريدك الإلكتروني على khaled@pvt.jo أو عبر واتس اب على الرقم 96277 77 67 938&lt;/p&gt;', 1, 355, 'Ar', '', 'one col', 'فرصة-عمل-في-الأردن-'),
(382, 'Opportunità di lavoro in Giordania', 'Opportunità di lavoro', 'Lavoro in Giordania,turismo', 'Lavoro nella nostra agenzia di viaggi a Petra', '&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;h3&gt;&lt;strong&gt;Riepilogo del lavoro:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;p&gt;<br>Stiamo cercando una persona qualificata che parli e scrivi italiano e spagnolo per lavorare nella &lt;a href=&quot;http://www.pvt.jo&quot;&gt;&lt;strong&gt;nostra agenzia di viaggi a Petra.&lt;/strong&gt;&lt;/a&gt;&lt;/p&gt;\r\n&lt;p&gt;Sarai in primo luogo responsabile per le email dei nostri clienti e per analizzarle tutte e risponderle in meno di un&#039;ora.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;&lt;strong&gt;Responsabilità:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Eseguire, mantenere, riconciliare, rivedere, combinare, analizzare e inserire i dati nelle lingue richieste sul nostro sito Web.&lt;/li&gt;\r\n&lt;li&gt;Identifica e risolvi tutte le email.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Titoli di studio:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Avere esperienza lavorativa come contabile.&lt;/li&gt;\r\n&lt;li&gt;Il diploma di laurea più due anni di esperienza applicabile, o combinazione di istruzione e esperienza di lavoro rilevante.&lt;/li&gt;\r\n&lt;li&gt;Competenza nelle applicazioni aziendali di base, come ad esempio Microsoft Office; conoscenza dell&#039;utente di Excel.&lt;/li&gt;\r\n&lt;li&gt;Conoscenza di base dei sistemi contabili e internet; abilità nell&#039;usare il computer.&lt;/li&gt;\r\n&lt;li&gt;Comprensione e capacità di applicare competenze e concetti contabili.&lt;/li&gt;\r\n&lt;li&gt;Capacità di elaborare messaggi e-mail professionali, memo, lettere aziendali e rapporti e per comunicare in modo chiaro e efficace informazioni a pubblico interno e gruppi di clienti.&lt;/li&gt;\r\n&lt;li&gt;Capacità di apprendere le competenze di gestione del progetto e di partecipare come parte di un team di progetto.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Benefici:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Vacanze a pagamento =&amp;gt; Sì&lt;/li&gt;\r\n&lt;li&gt;Congedo di malattia =&amp;gt; Sì&lt;/li&gt;\r\n&lt;li&gt;Benefici per la salute per includere medici e dentali =&amp;gt; No&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Applicare:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Invia un curriculum dettagliato della tua esperienza.&lt;/li&gt;\r\n&lt;li&gt;Inviate una lettera di copertura per spiegare perché saresti una buona misura.&lt;/li&gt;\r\n&lt;li&gt;Invia il tuo CV completo alla nostra email a &lt;a href=&quot;mailto:khaled@pvt.jo&quot;&gt;&lt;strong&gt;khaled@pvt.jo&lt;/strong&gt;&lt;/a&gt; Oppure da Whatsapp a &lt;strong&gt;+96277 77 67 938&lt;/strong&gt;&lt;/li&gt;\r\n&lt;/ul&gt;', 1, 356, 'it', '', 'one col', 'opportunità-di-lavoro-in-giordania-');
INSERT INTO `en33_pages` (`id`, `name`, `title`, `meta_desc`, `meta_key`, `contents`, `published`, `lang_id`, `lang`, `icon`, `layout`, `url`) VALUES
(383, 'فرصة عمل  في مكتبنا في الاردن  ', 'فرصة عمل  في الأردن ', 'عمل في مكتبنا السياحي في البتراء ', 'عمل في مجال السياحة', '&lt;p style=&quot;text-align: right;&quot;&gt;.&lt;strong&gt;:ملخص الوظيفة&lt;/strong&gt;<br>نحن نبحث عن  شخص مؤهل  يتحدث ويكتب الإيطالية والإسبانية للعمل في شركتنا السياحية في البتراء.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: right;&quot;&gt;سوف تكون في المقام الأول مسؤول عن  عملائنا وترد على رسائل البريد الإلكتروني وفي أقل من ساعة واحدة.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: right;&quot;&gt;&lt;strong&gt;المسؤوليات&lt;/strong&gt;<br>تشغيل، صيانة، التوفيق، مراجعة، الجمع، تحليل كل هذه القضايا في موقعنا على الانترنت وإدخال البيانات في اللغات المطلوبة.<br>الرد على جميع رسائل البريد الإلكتروني.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: right;&quot;&gt;&lt;strong&gt;المؤهلات&lt;/strong&gt;<br>وجود خبرة في العمل كمحاسب<br>درجة البكالوريوس بالإضافة إلى سنتين من الخبرة المنطبقة، أو مزيج من التعليم وخبرة العمل ذات الصلة<br>الكفاءة في تطبيقات الأعمال الأساسية، مثل مايكروسوفت أوفيس.  معرفة استخدام  إكسيل<br>المعرفة الأساسية للنظم المحاسبية والإنترنت؛ ثقافة الحاسوب<br>فهم والقدرة على تطبيق المهارات والمفاهيم المحاسبية<br>القدرة على صياغة رسائل البريد الإلكتروني المهنية والمذكرات ورسائل الأعمال والتقارير، و بشكل واضح وفعال التواصل المعلومات للجمهور الداخلي ومجموعات العملاء<br>القدرة على تعلم مهارات إدارة المشاريع والمشاركة كجزء من فريق المشروع<br>&lt;strong&gt;فوائد&lt;/strong&gt;<br>عطلة مدفوعة =&amp;gt; نعم<br>إجازة مرضية =&amp;gt; نعم<br>الفوائد الصحية لتشمل الطبية وطب الأسنان =&amp;gt; لا<br>&lt;strong&gt;للتقديم:&lt;/strong&gt;<br>إرسال السيرة الذاتية بالتفصيل <br>إرسال خطاب تغطية شرح لماذا ستكون الشخص المناسب<br>أرسل سيرتك الذاتية إلى بريدك الإلكتروني على khaled@pvt.jo أو عبر واتس اب على الرقم 96277 77 67 938&lt;/p&gt;', 1, 356, 'Ar', '', 'one col', 'فرصة-عمل-في-مكتبنا-في-الاردن-'),
(384, 'Tour Combinati', 'Tour Combinati', 'Tour Combinati in Giordania, Oman e Israele', 'Tour Combinati in Giordania, Oman e Israele', '', 1, 341, 'it', '', 'Combined_tours', 'tour-combinati'),
(385, 'Tours Combinados', 'Tours Combinados', 'Tours Combinados en Jordania, Omán e Israel', 'Tours Combinados en Jordania, Omán e Israel', '', 1, 341, 'es', '', 'Combined_tours', 'tours-combinados'),
(386, 'Emplois de Volontariat en Jordanie', 'Emplois de Volontariat en Jordanie', 'Emplois de Volontariat en Jordanie', 'Emplois de Volontariat en Jordanie', '&lt;p&gt;La Jordanie est l’un des pays les plus fascinants du Moyen-Orient. Des sites bibliques, des châteaux, des citadelles anciennes aux villes romaines en ruines, vous trouverez facilement quelque chose en Jordanie qui vous fascine. La Jordanie est la patrie de Petra, une ancienne ville perdue nabatéenne comparable au Machu Picchu ainsi qu’Angkor Vat et Amman, sa capitale et sa ville arabe moderne et culturellement diversifiée. Il existe de nombreuses possibilités pour les personnes qui souhaitent découvrir un aspect différent de la nation en faisant du bénévolat.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;Job Brief:&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;\r\n&lt;p&gt;<br>Nous recherchons une personne qualifiée qui parle et écrit l&#039;italien et l&#039;espagnol pour travailler dans notre agence de voyages à Petra.&lt;/p&gt;\r\n&lt;p&gt;Vous serez principalement responsable des courriels de nos clients, de leur analyse et de leur réponse en moins d’une heure.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;&lt;strong&gt;Responsabilités:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Exécutez, maintenez, rapprochez, passez en revue, combinez, analysez et entrez les données dans les langues requises sur notre site Web.&lt;/li&gt;\r\n&lt;li&gt;Identifiez et résolvez tous les emails.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;h3&gt;Qualifications:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Avoir une expérience de travail en tant que comptable.&lt;/li&gt;\r\n&lt;li&gt;Baccalauréat, plus deux années d&#039;expérience pertinente, ou combinaison de formation et d&#039;expérience de travail pertinente.&lt;/li&gt;\r\n&lt;li&gt;Maîtrise des applications professionnelles de base, telles que Microsoft Office; connaissance de l&#039;utilisateur d&#039;Excel.&lt;/li&gt;\r\n&lt;li&gt;Connaissance de base des systèmes de comptabilité et d&#039;Internet; connaissances informatiques.&lt;/li&gt;\r\n&lt;li&gt;Compréhension et capacité d&#039;appliquer les compétences et les concepts comptables.&lt;/li&gt;\r\n&lt;li&gt;Capacité à rédiger des courriels professionnels, des notes de service, des lettres commerciales et des rapports, et à communiquer des informations.&lt;/li&gt;\r\n&lt;li&gt;Claires et efficaces aux audiences internes et aux groupes de clients.&lt;/li&gt;\r\n&lt;li&gt;Capacité à acquérir des compétences en gestion de projet et à participer à une équipe de projet.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Avantages:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Vacances payées =&amp;gt; Oui&lt;/li&gt;\r\n&lt;li&gt;Congé de maladie =&amp;gt; Oui&lt;/li&gt;\r\n&lt;li&gt;Les avantages pour la santé comprennent les soins médicaux et dentaires =&amp;gt; Non&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;<br>&lt;strong&gt;Appliquer:&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Soumettez votre CV en détaillant votre expérience.&lt;/li&gt;\r\n&lt;li&gt;Soumettez une lettre d&#039;accompagnement expliquant pourquoi vous conviendrait parfaitement.&lt;/li&gt;\r\n&lt;li&gt;Envoyez votre CV complet à notre email à &lt;a href=&quot;mailto:khaled@pvt.jo&quot;&gt;&lt;strong&gt;khaled@pvt.jo&lt;/strong&gt;&lt;/a&gt; ou par Whatsapp au &lt;strong&gt;+96277 77 67 938&lt;/strong&gt;&lt;/li&gt;\r\n&lt;/ul&gt;', 1, 355, 'fr', 'fa-search', 'one col', 'emplois-de-volontariat-en-jordanie'),
(387, 'Where to go in Jordan', 'Where to go in Jordan', 'Amman - Jordan River and Bethany - Desert Castles - Madaba - Mount Nebo - Dead Sea - Ajloun - Little Petra - Petra - Tomb of Aaron - Aqaba - Azraq and Shawmari Reserve - Dana Biosphere Reserve - Wadi Rum', 'Where To Go In Jordan', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/Royal Hotel.jpg&quot; alt=&quot;amman&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Amman&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;In this day you will be able to enjoy the innumerable resources that the city has to offer, between a walk in Downtown, a visit to archaeological sites, a hot tea in Weibdeh or try the typical shisha at Rainbow Street &lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/amman/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Jordan River/Jordan River website 800x500.jpg&quot; alt=&quot;Jordan River and Bethany&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Jordan River and Bethany&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Jordan River is a 251-kilometre-long (156 mi) river in the Middle East that flows roughly north to south through the Sea of Galilee and on to the Dead Sea. Jordan and the Gola...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/jordan-river-and-bethany/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Oval forum.jpg&quot; alt=&quot;Oval Plaza&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Oval Plaza&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The spacious plaza measures 90mx80m and is surrounded by a broad sidewalk and colonnade of 1st century AD Ionic columns located in Jerash. There are two alters in the middle...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/oval-plaza/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Desert Castles/Qasr_Kharana_in_Jordan.jpg&quot; alt=&quot;Desert castles&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Desert Castles&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Stretching East of Amman, the parched desert plain rolls on to Iraq and Saudi Arabia. This is a place where endless sand and barren basalt landscapes give proof to man’s ability &lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/desert-castles/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Madaba/madaba mosque.jpg&quot; alt=&quot;Madaba&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Madaba&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Madaba is best known for its Byzantine and Umayyad mosaics, especially a large Byzantine-era mosaic map of the Holy Land. Madaba is located 19 miles South-West of the capital Amman.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/madaba&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Mount_nebo/Monte-nebo.jpg&quot; alt=&quot;mount nebo&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Mount Nebo&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Mount nebo is one of the biblical sites that can be seen during a trip to Jordan. According to the Bible, it was from Mount Nebo that Moses contemplated the Promised Land after God forbade him&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/mount-nebo/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Deadsea/Dead Sea website 800x500.jpg&quot; alt=&quot;Dead Sea&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Dead Sea&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Dead Sea is one of the most spectacular natural and spiritual landscapes in the whole World. This unique place has extremely high content of salts and minerals which gives its waters&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/the-dead-sea/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/lotsCave-1.jpg&quot; alt=&quot;Lot´s Cave&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Lot´s Cave&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;To the south of the Dead Sea and near the town of Safi there is a steep slope that is the location of a monastery, a Byzantine basilica from the 7th century AD, a reservoir and some mosaics alon ...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/lots-cave/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Ajlun/Ajloun website 800x500.jpg&quot; alt=&quot;Ajlun&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Ajloun&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Travelling north of Jordan, Ajloun and its Castle, definitely worth a visit. The hills and green spaces are unparalleled. The road to Ajloun, located 25 kilomet...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/ajloun/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Petra/Little Petra 800x500.jpg&quot; alt=&quot;Little Petra&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Little Petra&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Little Petra is also known in Arabic as Siq al-Barid &quot;the cold canyon&quot;. Like Petra, it is a Nabataean site, with buildings carved into the walls of the sandstone...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/little-petra/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Petra/khazna4.jpg&quot; alt=&quot;Petra&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Petra &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Undoubtedly the most famous attraction in Jordan is the Nabatean city of Petra, nestled away in the mountains south of the Dead Sea. Petra, which means &quot;...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/petra/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Afra hotsprings in Tafileh new.jpg&quot; alt=&quot;Afra Hot Springs&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Afra Hot Springs&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Jordan is the leading destination for medical tourism in the Middle East and the Afra Hot Springs are a clear example. Located 26 km north of the city of Tafila...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/afra-hot-springs/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Qasr_Amra.jpg&quot; alt=&quot;Qasr Amra&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Qasr Amra&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Qasr Amra, also transcribed as Quseir Amra or Qusayr Amra, is the best-known of the desert castles located in present-day eastern Jordan. It was built early in the 8th...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/qasr-amra/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Petra/df82e914176ce65aacd067c64bd46e1c.jpg&quot; alt=&quot;Tomb of Aaron&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Tomb of Aaron&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Tomb of Aaron is the name of the supposed burial place of Aaron, the brother of Moses. There are two descriptions of its location in the Pentateuch, and different&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/tomb-of-aaron/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/800px-Montreal_Castle_Visitor_center.jpg&quot; alt=&quot;Montreal Castle&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Montreal Castle&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Montreal is a Crusader castle on the eastern side of the Arabah, perched on the side of a rocky, conical mountain, looking out over fruit trees below. The ruins, called S...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/montreal-castle/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/1024px-Qasr_Haraneh_5.jpg&quot; alt=&quot;Qasr Al-Kharanah&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Qasr Al-Kharanah&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Qasr Al-Kharanah, is one of the best-known of the desert castles located in present-day eastern Jordan, about 60 kilometers (37 mi) east of Amman and relatively clos...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/qasr-al-kharanah/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Aqaba/Aqaba website 800x500.jpg&quot; alt=&quot;Aqaba&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Aqaba&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Aqaba is the only coastal city in Jordan and the largest and most populous city on the Gulf of Aqaba. Situated in southernmost Jordan, Aqaba is the administrative centre....&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/aqaba/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Azraq/Azraq.jpg&quot; alt=&quot;Azraq and Shawmari Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Azraq&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Azraq means &quot;the blue&quot; in Arabic, it is a small town in Zarqa Governorate in central-eastern Jordan, 100 kilometres (62 mi) east of Amman...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/azraq/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Dana/DanaReserve.jpg&quot; alt=&quot;Dana Biosphere Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Dana Biosphere Reserve&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Dana Biosphere Reserve is Jordan&#039;s largest nature reserve, located in south-central Jordan. Dana Biosphere Reserve was founded in 1989 in the area...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/dana-biosphere-reserve/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/wadi-rum/Wadi Rum  website 800x500.jpg&quot; alt=&quot;wadi rum&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Wadi Rum&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;When you arrive in this desert it is easy to understand why it was chosen as the location of films set on the planet Mars.The color of its sand ...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/wadi-rum/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/Roman Theater website 800x500.jpg&quot; alt=&quot;Roman Theatre&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Roman Theatre&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Amman&#039;s Roman Theatre is a 6,000-seat, 2nd-century Roman theatre. A famous landmark in the Jordanian capital, it dates back to the Roman period when the cit..&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/roman-theatre/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Main website 800x500.jpg&quot; alt=&quot;Ma&#039;in Hot Springs&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Ma&#039;in Hot Springs&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Ma&#039;in hot springs are located 58 km south of Amman in Madaba Governorate and is 27 km away from Madaba. It is 120 meters below sea level...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/main-hot-springs/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/Umm_ar-Rasas_12.JPG&quot; alt=&quot;Umm ar-Rasas &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Umm ar-Rasas &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Umm ar-Rasas is located 30 km southeast of Madaba, which is the capital city of the Madaba Governorate in central Jordan. It was once accessible by branches of...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/umm-ar-rasas/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/king abdullah mosque website 800x500.jpg&quot; alt=&quot;King Abdullah I Mosque&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   King Abdullah I Mosque &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The blue-domed King Abdullah I Mosque, built in the 1980s by the late King Hussein as a memorial to his grandfather, is open to Non-Muslim visitors. The mosqu...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/king-abdullah-i-mosque/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/1024px-King_Hussein_Mosque_(Amman)_at_night.jpg&quot; alt=&quot;King Hussein Mosque&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   King Hussein Mosque&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;King Hussein Bin Talal Mosque, better known as the King Hussein Mosque, is the largest mosque in Jordan. Not to be confused with the 1924 Grand Al...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/king-hussein-bin-talal-mosque/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/al-rainbow-st.jpg&quot; alt=&quot;al-rainbow-st.jpg&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Rainbow Street&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Rainbow Street originally named Abu Bakr al Siddiq Street, is a public space in the historic area of Jabal Amman, near the center of downtown Amman, Jordan...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/rainbow-street/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/citadel.jpg&quot; alt=&quot;Temple of Hercules &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Temple of Hercules &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Temple of Hercules is a historic site in the Amman Citadel in Amman, Jordan. It is thought to be the most significant Roman structure in the Amman Citadel...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/temple-of-hercules/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/thecaveofthesevensleepers.jpg&quot; alt=&quot;Cave of the Seven Sleepers&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Cave of the Seven Sleepers&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The legend of the ‘seven sleepers’ involves seven Christian boys who were persecuted by the Roman Emperor Trajan, then escaped to a cave and...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/cave-of-the-seven-sleepers/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/citadel-ruins-amman-jordan-602a71756bb4.jpg&quot; alt=&quot;Amman Citadel&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Amman Citadel&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Amman Citadel is an historical site at the center of downtown Amman, Jordan. Known in Arabic as Jabal al-Qal&#039;a, the L-shaped hill is one of the seven jabals...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/amman-citadel/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Ajloun forest reserve website 800x500.jpg&quot; alt=&quot;Ajloun Forest Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Ajloun Forest Reserve&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Ajloun Forest Reserve is a nature reserve located in the Ajloun Governorate in north-west Jordan. Established by the Royal Society for the Conservatio...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/ajloun-forest-reserve/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/Dibeen_Forest_Reserve.jpg&quot; alt=&quot;Dibbeen Forest Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Dibbeen Forest Reserve&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Dibbeen Forest Reserve is a nature reserve located in the north-west of Jordan. It is situated just south of the Roman site of Jerash and covers an area of 8.5 squar...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/dibbeen-forest-reserve/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Natural Reserves/Shaumari website 800x500.jpg&quot; alt=&quot;Shaumari Wildlife Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Shaumari Wildlife Reserve&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Shaumari Wildlife Reserve is a Jordanian nature reserve near the town of Azraq, approximately 100 km (62 mi) east of Amman.It is a regionally important reserve created in 1975...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/shaumari-wildlife-reserve/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Natural Reserves/wetland.jpg&quot; alt=&quot;Azraq Wetland Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Azraq Wetland Reserve&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Azraq Wetland Reserve is a nature reserve located near the town of Azraq in the eastern desert of Jordan. An oasis for migratory birds, Azraq was established in 1978 and covers 12 square...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/azraq-wetland-reserve/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Natural Reserves/Yarmouk.jpg&quot; alt=&quot;Yarmouk Forest Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Yarmouk Forest Reserve&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Royal Society for the Conservation of Nature is implementing the Integrated Ecosystem Management in the Jordan Rift Valley project, which aims to establish a network of reserves and...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/yarmouk-forest-reserve/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Natural Reserves/River-canyon-of-Wadi-Mujib.jpg&quot; alt=&quot;Wadi Mujib&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Wadi Mujib&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;In 2011, UNESCO declared Mujib biosphere reserve. It extends to the Kerak and Madaba mountains to the north and south, reaching 900 metres (3,000 ft) above sea level in some places....&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/wadi-mujib/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Irbid.jpg&quot; alt=&quot;Irbid&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Irbid&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Irbid is the second largest city in Jordan. A brief walk through the famous Dar As-Saraya museum reveals Irbid’s ancient origins. The museum, housed in a traditional 19th century....&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/irbid/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Jerash2.jpg&quot; alt=&quot;Jerash&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Jerash&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Jerash, located 48 km north of Amman and nestled in a quiet valley among the mountains of Gilead, is the grandeur of Imperial Rome being one of the largest and most well preserved...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/jerash/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/AsSalt website 800x500.jpg&quot; alt=&quot;Al-Salt&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Al-Salt&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Al-Salt is a thriving city located in the North West of the capital Amman. Built on three main mountains (the Cadital, Gadaa and Salalem), surrounded by the city square, Al-Salt is...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/al-salt/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/1024px-Umayyad_Palace020.jpg&quot; alt=&quot;Umayyad Palace&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Umayyad Palace&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Umayyad Palace is a large palatial complex from the Umayyad period, located on the Citadel Hill of Amman, Jordan. Built during the first half of the 8th century, it is now largely ruined, ...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/ummayyad-palace/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Karak.jpg&quot; alt=&quot;Karak&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Karak&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Variously known throughout history as Qir Heres, Qir Moab, and Hareseth, Karak has been a prized possession of a number of civilizations. It lies on the ancient ...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/karak/&quot; class=&quot;btn orange h-pad&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 387, 'en', '', 'one col', 'where-to-go-in-jordan'),
(388, 'Amman', 'Amman', 'Check out the main information you need to know about Amman, the city built on main seven hills and full of history.', 'Amman, Jabals, capital of Jordan, Roman theatre, Citadel', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Amman is the capital and most populous city of Jordan, and the country&#039;s economic, political and cultural centre. Situated in north-central Jordan, Amman is the administrative centre of the Amman Governorate. The city has a population of 4,007,526 and a land area of 1,680 square kilometers (648.7 square miles).  Today, Amman is considered to be among the most modernized Arab cities. It is a major tourist destination in the region, particularly among Arab and European tourists.&lt;/p&gt;\r\n&lt;p&gt;<br> Amman is divided into two parts: the western part, not only geographically, full of nightclubs, pubs, central commerce, and the eastern part, which still preserves important archaeological sites, like the Citadel, the Roman Amphitheatre...as well as the typical Arab &quot;suq&quot; (traditional market).&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;The largest museum in Jordan is The Jordan Museum. It contains much of the valuable archaeological findings in the country, including some of the Dead Sea Scrolls, the Neolithic limestone statues of &#039;Ain Ghazal, and a copy of the Mesha Stele. Other museums include the Jordan National Gallery of Fine Arts, Jordan Archaeological Museum, The Children&#039;s Museum Jordan, The Martyrs&#039; Memorial and Museum, the Royal Automobile Museum, the Prophet Mohammad Museum, the Museum of Parliamentary Life, the Jordan Folklore Museum, and museums at the University of Jordan.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;Amman is considered one of the most liberal and westernized cities in the Arab world. The city has become one of the most popular destinations for Western expatriates and college students who seek to live, study, or work in the Middle East.  The city&#039;s culinary scene has changed from its shawerma stands and falafel joints to embrace many popular western restaurants and fast-food outlets such as Asian fusion restaurants, French bistros and Italian trattorias.&lt;/p&gt;\r\n&lt;h5&gt;&lt;/h5&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Amman/Royal Hotel.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d433870.8268373916!2d35.66743569022686!3d31.8354533233864!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151b5fb85d7981af:0x631c30c0f8dc65e8!2sAmman!5e0!3m2!1sen!2sjo!4v1564595824430!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 388, 'en', '', 'one col', 'amman'),
(389, 'Amman', 'Amman', 'Amman est la capitale et la ville la plus peuplée de Jordanie, ainsi que le centre économique, politique et culturel du pays.', 'Amman est la capitale et la ville la plus peuplée de Jordanie, ainsi que le centre économique, politique et culturel du pays.', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;Amman est la capitale et la ville la plus peuplée de Jordanie, ainsi que le centre économique, politique et culturel du pays. Situé au centre-nord de la Jordanie, Amman est le centre administratif du gouvernorat d&#039;Amman. La ville a une population de 4 007 526 habitants et une superficie de 1 680 kilomètres carrés (648,7 milles carrés). Aujourd&#039;hui, Amman est considérée comme l&#039;une des villes arabes les plus modernisées. C&#039;est une destination touristique majeure dans la région, en particulier parmi les touristes arabes et européens.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;Amman est divisée en deux parties: la partie occidentale, non seulement géographiquement, regorgeant de discothèques, de pubs, de commerces centraux et la partie orientale, qui conserve encore d’importants sites archéologiques, tels que la citadelle, l’amphithéâtre romain ... &quot;souq&quot; arabe typique (marché traditionnel).&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;Le plus grand musée de Jordanie est le Jordan Museum. Il contient une grande partie des découvertes archéologiques de valeur dans le pays, notamment des manuscrits de la mer Morte, des statues néolithiques en calcaire d&#039;Ain Ghazal et une copie de la stèle Mesha. Parmi les autres musées, vous trouverez la Galerie nationale des beaux-arts de Jordanie, le musée archéologique de Jordanie, le musée des enfants de Jordanie, le Mémorial et le musée des Martyrs, le musée de l&#039;automobile royale, le musée du prophète Mohammed, le musée de la vie parlementaire, le musée du folklore jordanien et des musées à l&#039;Université de Jordanie.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;Amman est considérée comme l&#039;une des villes les plus libérales et occidentalisées du monde arabe. La ville est devenue l&#039;une des destinations les plus populaires pour les expatriés et les étudiants occidentaux qui souhaitent vivre, étudier ou travailler au Moyen-Orient. La scène culinaire de la ville a changé: ses stands de shawerma et ses joints de falafel ont été remplacés par de nombreux restaurants occidentaux populaires et des établissements de restauration rapide tels que les restaurants asiatiques de fusion, les bistrots français et les trattorias italiennes.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Amman/Royal Hotel.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d433870.8268373916!2d35.66743569022686!3d31.8354533233864!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151b5fb85d7981af:0x631c30c0f8dc65e8!2sAmman!5e0!3m2!1sen!2sjo!4v1564595824430!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 388, 'fr', '', 'one col', 'amman');
INSERT INTO `en33_pages` (`id`, `name`, `title`, `meta_desc`, `meta_key`, `contents`, `published`, `lang_id`, `lang`, `icon`, `layout`, `url`) VALUES
(390, 'Amman', 'Amman', 'Amman è la capitale e la città più popolosa della Giordania e il centro economico, politico e culturale del paese.', 'Amman è la capitale e la città più popolosa della Giordania e il centro economico, politico e culturale del paese.', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Amman è la capitale e la città più popolosa della Giordania e il centro economico, politico e culturale del paese. Situato nella Giordania centro-settentrionale, Amman è il centro amministrativo del Governatorato di Amman. La città ha una popolazione di 4.007.526 e una superficie di 1.680 chilometri quadrati (648,7 miglia quadrate). Oggi Amman è considerata tra le città arabe più modernizzate. È una delle principali destinazioni turistiche della regione, in particolare tra i turisti arabi ed europei.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;Amman è divisa in due parti: la parte occidentale, non solo geograficamente, piena di locali notturni, pub, commercio centrale e la parte orientale, che conserva ancora importanti siti archeologici, come la Cittadella, l&#039;Anfiteatro romano ... così come il tipico &quot;suq&quot; arabo (mercato tradizionale).&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;Il più grande museo della Giordania è il Jordan Museum. Contiene molti dei preziosi reperti archeologici del paese, tra cui alcuni rotoli del Mar Morto, le statue neolitiche di calcare di &#039;Ain Ghazal e una copia della Stele di Mesha. Altri musei includono la Galleria Nazionale di Belle Arti della Giordania, il Museo archeologico della Giordania, il Museo dei bambini della Giordania, il Memoriale e il Museo dei martiri, il Museo dell&#039;Automobile Reale, il Museo del Profeta Mohammad, il Museo della vita parlamentare, il Museo del folklore giordano e musei presso l&#039;Università della Giordania.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;Amman è considerata una delle città più liberali e occidentalizzate del mondo arabo. La città è diventata una delle destinazioni più popolari per espatriati occidentali e studenti universitari che cercano di vivere, studiare o lavorare in Medio Oriente. La scena culinaria della città è cambiata dalle sue bancarelle di shawerma e dai giunti di falafel per abbracciare molti famosi ristoranti occidentali e fast-food come ristoranti fusion asiatici, bistrot francesi e trattorie italiane.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Amman/Royal Hotel.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d433870.8268373916!2d35.66743569022686!3d31.8354533233864!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151b5fb85d7981af:0x631c30c0f8dc65e8!2sAmman!5e0!3m2!1sen!2sjo!4v1564595824430!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 388, 'it', '', 'one col', 'amman'),
(391, 'أين تذهب في الأردن', 'أين تذهب في الأردن', 'Where To Go In Jordan', 'Where To Go In Jordan', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/Royal Hotel.jpg&quot; alt=&quot;amman&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Amman&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;In this day you will be able to enjoy the innumerable resources that the city has to offer, between a walk in Downtown, a visit to archaeological sites, a hot tea in Weibdeh or try the typical shisha at Rainbow Street &lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/amman/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Jordan River/Jordan River website 800x500.jpg&quot; alt=&quot;Jordan River and Bethany&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Jordan River and Bethany&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Jordan River is a 251-kilometre-long (156 mi) river in the Middle East that flows roughly north to south through the Sea of Galilee and on to the Dead Sea. Jordan and the Gola...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/jordan-river-and-bethany/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Oval forum.jpg&quot; alt=&quot;Oval Plaza&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Oval Plaza&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The spacious plaza measures 90mx80m and is surrounded by a broad sidewalk and colonnade of 1st century AD Ionic columns located in Jerash. There are two alters in the middle...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/oval-plaza/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Desert Castles/Qasr_Kharana_in_Jordan.jpg&quot; alt=&quot;Desert castles&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Desert Castles&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Stretching East of Amman, the parched desert plain rolls on to Iraq and Saudi Arabia. This is a place where endless sand and barren basalt landscapes give proof to man’s ability &lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/desert-castles/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Madaba/madaba mosque.jpg&quot; alt=&quot;Madaba&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Madaba&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Madaba is best known for its Byzantine and Umayyad mosaics, especially a large Byzantine-era mosaic map of the Holy Land. Madaba is located 19 miles South-West of the capital Amman.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/madaba&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Mount_nebo/Monte-nebo.jpg&quot; alt=&quot;mount nebo&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Mount Nebo&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Mount nebo is one of the biblical sites that can be seen during a trip to Jordan. According to the Bible, it was from Mount Nebo that Moses contemplated the Promised Land after God forbade him&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/mount-nebo/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Deadsea/Dead Sea website 800x500.jpg&quot; alt=&quot;Dead Sea&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Dead Sea&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Dead Sea is one of the most spectacular natural and spiritual landscapes in the whole World. This unique place has extremely high content of salts and minerals which gives its waters&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/the-dead-sea/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/lotsCave-1.jpg&quot; alt=&quot;Lot´s Cave&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Lot´s Cave&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;To the south of the Dead Sea and near the town of Safi there is a steep slope that is the location of a monastery, a Byzantine basilica from the 7th century AD, a reservoir and some mosaics alon ...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/lots-cave/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Ajlun/Ajloun website 800x500.jpg&quot; alt=&quot;Ajlun&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Ajloun&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Travelling north of Jordan, Ajloun and its Castle, definitely worth a visit. The hills and green spaces are unparalleled. The road to Ajloun, located 25 kilomet...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/ajloun/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Petra/Little Petra 800x500.jpg&quot; alt=&quot;Little Petra&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Little Petra&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Little Petra is also known in Arabic as Siq al-Barid &quot;the cold canyon&quot;. Like Petra, it is a Nabataean site, with buildings carved into the walls of the sandstone...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/little-petra/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Petra/khazna4.jpg&quot; alt=&quot;Petra&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Petra &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Undoubtedly the most famous attraction in Jordan is the Nabatean city of Petra, nestled away in the mountains south of the Dead Sea. Petra, which means &quot;...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/petra/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Afra hotsprings in Tafileh new.jpg&quot; alt=&quot;Afra Hot Springs&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Afra Hot Springs&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Jordan is the leading destination for medical tourism in the Middle East and the Afra Hot Springs are a clear example. Located 26 km north of the city of Tafila...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/afra-hot-springs/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Qasr_Amra.jpg&quot; alt=&quot;Qasr Amra&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Qasr Amra&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Qasr Amra, also transcribed as Quseir Amra or Qusayr Amra, is the best-known of the desert castles located in present-day eastern Jordan. It was built early in the 8th...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/qasr-amra/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Petra/df82e914176ce65aacd067c64bd46e1c.jpg&quot; alt=&quot;Tomb of Aaron&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Tomb of Aaron&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Tomb of Aaron is the name of the supposed burial place of Aaron, the brother of Moses. There are two descriptions of its location in the Pentateuch, and different&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/tomb-of-aaron/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/800px-Montreal_Castle_Visitor_center.jpg&quot; alt=&quot;Montreal Castle&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Montreal Castle&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Montreal is a Crusader castle on the eastern side of the Arabah, perched on the side of a rocky, conical mountain, looking out over fruit trees below. The ruins, called S...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/montreal-castle/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/1024px-Qasr_Haraneh_5.jpg&quot; alt=&quot;Qasr Al-Kharanah&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Qasr Al-Kharanah&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Qasr Al-Kharanah, is one of the best-known of the desert castles located in present-day eastern Jordan, about 60 kilometers (37 mi) east of Amman and relatively clos...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/qasr-al-kharanah/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Aqaba/Aqaba website 800x500.jpg&quot; alt=&quot;Aqaba&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Aqaba&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Aqaba is the only coastal city in Jordan and the largest and most populous city on the Gulf of Aqaba. Situated in southernmost Jordan, Aqaba is the administrative centre....&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/aqaba/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Azraq/Azraq.jpg&quot; alt=&quot;Azraq and Shawmari Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Azraq&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Azraq means &quot;the blue&quot; in Arabic, it is a small town in Zarqa Governorate in central-eastern Jordan, 100 kilometres (62 mi) east of Amman...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/azraq/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Dana/DanaReserve.jpg&quot; alt=&quot;Dana Biosphere Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Dana Biosphere Reserve&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Dana Biosphere Reserve is Jordan&#039;s largest nature reserve, located in south-central Jordan. Dana Biosphere Reserve was founded in 1989 in the area...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/dana-biosphere-reserve/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/wadi-rum/Wadi Rum  website 800x500.jpg&quot; alt=&quot;wadi rum&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Wadi Rum&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;When you arrive in this desert it is easy to understand why it was chosen as the location of films set on the planet Mars.The color of its sand ...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/wadi-rum/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/Roman Theater website 800x500.jpg&quot; alt=&quot;Roman Theatre&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Roman Theatre&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Amman&#039;s Roman Theatre is a 6,000-seat, 2nd-century Roman theatre. A famous landmark in the Jordanian capital, it dates back to the Roman period when the cit..&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/roman-theatre/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Main website 800x500.jpg&quot; alt=&quot;Ma&#039;in Hot Springs&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Ma&#039;in Hot Springs&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Ma&#039;in hot springs are located 58 km south of Amman in Madaba Governorate and is 27 km away from Madaba. It is 120 meters below sea level...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/main-hot-springs/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/Umm_ar-Rasas_12.JPG&quot; alt=&quot;Umm ar-Rasas &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Umm ar-Rasas &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Umm ar-Rasas is located 30 km southeast of Madaba, which is the capital city of the Madaba Governorate in central Jordan. It was once accessible by branches of...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/umm-ar-rasas/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/king abdullah mosque website 800x500.jpg&quot; alt=&quot;King Abdullah I Mosque&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   King Abdullah I Mosque &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The blue-domed King Abdullah I Mosque, built in the 1980s by the late King Hussein as a memorial to his grandfather, is open to Non-Muslim visitors. The mosqu...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/king-abdullah-i-mosque/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/1024px-King_Hussein_Mosque_(Amman)_at_night.jpg&quot; alt=&quot;King Hussein Mosque&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   King Hussein Mosque&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;King Hussein Bin Talal Mosque, better known as the King Hussein Mosque, is the largest mosque in Jordan. Not to be confused with the 1924 Grand Al...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/king-hussein-bin-talal-mosque/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/al-rainbow-st.jpg&quot; alt=&quot;al-rainbow-st.jpg&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Rainbow Street&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Rainbow Street originally named Abu Bakr al Siddiq Street, is a public space in the historic area of Jabal Amman, near the center of downtown Amman, Jordan...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/rainbow-street/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/citadel.jpg&quot; alt=&quot;Temple of Hercules &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Temple of Hercules &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Temple of Hercules is a historic site in the Amman Citadel in Amman, Jordan. It is thought to be the most significant Roman structure in the Amman Citadel...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/temple-of-hercules/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/thecaveofthesevensleepers.jpg&quot; alt=&quot;Cave of the Seven Sleepers&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Cave of the Seven Sleepers&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The legend of the ‘seven sleepers’ involves seven Christian boys who were persecuted by the Roman Emperor Trajan, then escaped to a cave and...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/cave-of-the-seven-sleepers/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/citadel-ruins-amman-jordan-602a71756bb4.jpg&quot; alt=&quot;Amman Citadel&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Amman Citadel&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Amman Citadel is an historical site at the center of downtown Amman, Jordan. Known in Arabic as Jabal al-Qal&#039;a, the L-shaped hill is one of the seven jabals...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/amman-citadel/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Ajloun forest reserve website 800x500.jpg&quot; alt=&quot;Ajloun Forest Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Ajloun Forest Reserve&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Ajloun Forest Reserve is a nature reserve located in the Ajloun Governorate in north-west Jordan. Established by the Royal Society for the Conservatio...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/ajloun-forest-reserve/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/Dibeen_Forest_Reserve.jpg&quot; alt=&quot;Dibbeen Forest Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Dibbeen Forest Reserve&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Dibbeen Forest Reserve is a nature reserve located in the north-west of Jordan. It is situated just south of the Roman site of Jerash and covers an area of 8.5 squar...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/dibbeen-forest-reserve/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Natural Reserves/Shaumari website 800x500.jpg&quot; alt=&quot;Shaumari Wildlife Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Shaumari Wildlife Reserve&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Shaumari Wildlife Reserve is a Jordanian nature reserve near the town of Azraq, approximately 100 km (62 mi) east of Amman.It is a regionally important reserve created in 1975...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/shaumari-wildlife-reserve/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Natural Reserves/wetland.jpg&quot; alt=&quot;Azraq Wetland Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Azraq Wetland Reserve&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Azraq Wetland Reserve is a nature reserve located near the town of Azraq in the eastern desert of Jordan. An oasis for migratory birds, Azraq was established in 1978 and covers 12 square...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/azraq-wetland-reserve/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Natural Reserves/Yarmouk.jpg&quot; alt=&quot;Yarmouk Forest Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Yarmouk Forest Reserve&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Royal Society for the Conservation of Nature is implementing the Integrated Ecosystem Management in the Jordan Rift Valley project, which aims to establish a network of reserves and...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/yarmouk-forest-reserve/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Natural Reserves/River-canyon-of-Wadi-Mujib.jpg&quot; alt=&quot;Wadi Mujib&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Wadi Mujib&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;In 2011, UNESCO declared Mujib biosphere reserve. It extends to the Kerak and Madaba mountains to the north and south, reaching 900 metres (3,000 ft) above sea level in some places....&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/wadi-mujib/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Irbid.jpg&quot; alt=&quot;Irbid&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Irbid&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Irbid is the second largest city in Jordan. A brief walk through the famous Dar As-Saraya museum reveals Irbid’s ancient origins. The museum, housed in a traditional 19th century....&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/irbid/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Jerash2.jpg&quot; alt=&quot;Jerash&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Jerash&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Jerash, located 48 km north of Amman and nestled in a quiet valley among the mountains of Gilead, is the grandeur of Imperial Rome being one of the largest and most well preserved...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/jerash/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/AsSalt website 800x500.jpg&quot; alt=&quot;Al-Salt&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Al-Salt&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Al-Salt is a thriving city located in the North West of the capital Amman. Built on three main mountains (the Cadital, Gadaa and Salalem), surrounded by the city square, Al-Salt is...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/al-salt/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/1024px-Umayyad_Palace020.jpg&quot; alt=&quot;Umayyad Palace&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Umayyad Palace&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The Umayyad Palace is a large palatial complex from the Umayyad period, located on the Citadel Hill of Amman, Jordan. Built during the first half of the 8th century, it is now largely ruined, ...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/ummayyad-palace/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Karak.jpg&quot; alt=&quot;Karak&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Karak&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Variously known throughout history as Qir Heres, Qir Moab, and Hareseth, Karak has been a prized possession of a number of civilizations. It lies on the ancient ...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;Ar/karak/&quot; class=&quot;btn orange h-pad&quot;&gt;المزيد&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 387, 'Ar', '', 'one col', 'where-to-go-in-jordan');
INSERT INTO `en33_pages` (`id`, `name`, `title`, `meta_desc`, `meta_key`, `contents`, `published`, `lang_id`, `lang`, `icon`, `layout`, `url`) VALUES
(392, 'Dónde ir en Jordania', 'Dónde ir en Jordania', 'Ammán - Río Jordán y Betania - Los Castillos del Desierto - Madaba -  El Monte Nebo - El Mar Muerto  - Ajloun - Pequeña Petra - Petra -  Wadi Rum - La Tumba de Aaron - Aqaba - Azraq y la Reserva Shawmari - Reserva de la Biosfera de Dana', 'Dónde ir en Jordania', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/Royal Hotel.jpg&quot; alt=&quot;amman&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;  Ammán&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;En este día podrá disfrutar de los innumerables recursos que la ciudad tiene para ofrecer, entre una caminata en el centro, una visita a sitios arqueológicos, un té caliente en Weibdeh o probar la típica shisha en Rainbow Street...&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/amman/&quot; class=&quot;btn orange h-pad&quot;&gt;Leer Mas&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Jordan River/Jordan River1.jpg&quot; alt=&quot;Río Jordán y Betania&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Río Jordán y Betania&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;El río Jordán es un río de 251 kilómetros de largo (156 millas) en el Medio Oriente que desemboca en el Mar de Galilea y en el Mar Muerto. Jordania y los Altos del Golán bordean el rí...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/rio-jordan-y-betania/&quot; class=&quot;btn orange h-pad&quot;&gt;Leer Mas&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Oval forum.jpg&quot; alt=&quot;Oval Plaza&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Oval Plaza&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;La espaciosa plaza mide 90mx80m y está rodeada por una amplia acera y columnata de columnas jónicas del siglo I dC ubicadas en Jerash. Hay dos alteraciones en el medio...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/oval-plaza/&quot; class=&quot;btn orange h-pad&quot;&gt;Leer Mas&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Desert Castles/Qasr_Kharana_in_Jordan.jpg&quot; alt=&quot;Desert castles&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Los Castillos del Desierto&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Extendiéndose al Este de Ammán, la llanura desértica se extiende hacia Irak y Arabia Saudita. Este es un lugar donde la arena interminable y los áridos paisajes de basalto...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/los-castillos-del-desierto/&quot; class=&quot;btn orange h-pad&quot;&gt;Leer Mas&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Madaba/madaba mosque.jpg&quot; alt=&quot;Madaba&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Madaba&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Madaba es mejor conocido por sus mosaicos bizantinos y omeyas, especialmente un gran mapa de mosaicos de la Tierra Santa de la era bizantina. Madaba se encuentra...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/madaba/&quot; class=&quot;btn orange h-pad&quot;&gt;Leer Mas&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Mount_nebo/Monte-nebo.jpg&quot; alt=&quot;mount nebo&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   El Monte Nebo&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Te sentirás inspirado por la sensación bíblica de principio a fin mientras experimentas este recorrido divino en el Monte Nebo. Según la Biblia, fue desde el Monte Nebo que Moisés contempló...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/monte-nebo/&quot; class=&quot;btn orange h-pad&quot;&gt;Leer Mas&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Deadsea/dead-sea.jpg&quot; alt=&quot;El Mar Muerto&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   El Mar Muerto&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;El Mar Muerto es uno de los paisajes naturales y espirituales más espectaculares del mundo. Este lugar único tiene un contenido extremadamente alto de sales y minerales...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/el-mar-muerto/&quot; class=&quot;btn orange h-pad&quot;&gt;Leer Mas&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/lotsCave-1.jpg&quot; alt=&quot;Cueva de Lot&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Cueva de Lot&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Al sur del Mar Muerto y cerca del pueblo de Safi hay una pendiente pronunciada que es la ubicación de un monasterio, una basílica bizantina del siglo VII d. C., un embalse y algunos...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/cueva-de-lot/&quot; class=&quot;btn orange h-pad&quot;&gt;Leer Mas&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Ajlun/ajloun-castle-ajloun-4.jpg&quot; alt=&quot;Ajlun&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Ajloun&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Viajando al norte de Jordania están Ajloun y su Castillo, lugares que definitivamente valen la pena visitar. Las colinas y los espacios verd...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/ajloun/&quot; class=&quot;btn orange h-pad&quot;&gt;Leer Mas&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Petra/Little Petra22.jpg&quot; alt=&quot;Little Petra&quot; class=&quot;full-width&quot; height=&quot;186&quot; width=&quot;281&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   La Pequeña Petra&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;La pequeña Petra también se conoce en árabe como Siq al-Barid &quot;el cañón frío&quot;. Al igual que Petra, es un sitio nabateo, con edificios tall...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/la-pequeña-petra/&quot; class=&quot;btn orange h-pad&quot;&gt;Leer Mas&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Petra/khazna4.jpg&quot; alt=&quot;Petra&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   Petra &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Sin lugar a dudas, la atracción más famosa de Jordania es la ciudad Nabatea de Petra, ubicada en las montañas al Sur del ...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/petra/&quot; class=&quot;btn orange h-pad&quot;&gt;Leer Mas&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Afra Hot Springs Jordan2.jpg&quot; alt=&quot;Aguas Termales Afra&quot; class=&quo