INSERT INTO `en33_pages` (`id`, `name`, `title`, `meta_desc`, `meta_key`, `contents`, `published`, `lang_id`, `lang`, `icon`, `layout`, `url`) VALUES
(1821, 'Sehenswürdigkeiten in Jordanien', 'Sehenswürdigkeiten in Jordanien', 'Sehenswürdigkeiten in Jordanien', 'Sehenswürdigkeiten in Jordanien', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/Royal Hotel.jpg&quot; alt=&quot;amman&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Amman&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;pre class=&quot;tw-data-text tw-text-large tw-ta&quot; data-placeholder=&quot;Übersetzung&quot; id=&quot;tw-target-text&quot; style=&quot;text-align: left;&quot; dir=&quot;ltr&quot;&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;An diesem Tag können Sie die unzähligen Ressourcen der Stadt genießen, darunter ein Spaziergang in der Innenstadt, ein Besuch archäologischer Stätten, ein heißer Tee in Weibdeh oder eine typische Shisha in der Rainbow Street&lt;/span&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;ge/amman/&quot; class=&quot;btn orange h-pad&quot;&gt;Mehr...&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Jordan River/Jordan River website 800x500.jpg&quot; alt=&quot;Jordan River and Bethany&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Bethanien Jenseits Des Jordan&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;pre class=&quot;tw-data-text tw-text-large tw-ta&quot; data-placeholder=&quot;Übersetzung&quot; id=&quot;tw-target-text&quot; style=&quot;text-align: left;&quot; dir=&quot;ltr&quot;&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;Der Jordan ist ein 251 Kilometer langer Fluss im Nahen Osten, der ungefähr von Norden nach Süden durch den See Genezareth und weiter zum Toten Meer fließt. Jordanien und die Gola ...&lt;/span&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;ge/bethanien-jenseits-des-jordan/&quot; class=&quot;btn orange h-pad&quot;&gt;Mehr...&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Oval forum.jpg&quot; alt=&quot;Oval Plaza&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Ovales Forum&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;pre class=&quot;tw-data-text tw-text-large tw-ta&quot; data-placeholder=&quot;Übersetzung&quot; id=&quot;tw-target-text&quot; style=&quot;text-align: left;&quot; dir=&quot;ltr&quot;&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;Der 90 x 80 m große Platz ist von einem breiten Bürgersteig und einer Kolonnade aus ionischen Säulen aus dem 1. Jahrhundert nach Christus umgeben, die sich in Jerash befinden. Es gibt zwei Änderungen in der Mitte ...&lt;/span&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;ge/ovales-forum/&quot; class=&quot;btn orange h-pad&quot;&gt;Mehr...&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Desert Castles/Qasr_Kharana_in_Jordan.jpg&quot; alt=&quot;Desert castles&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Wüsten Burgen&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;pre class=&quot;tw-data-text tw-text-large tw-ta&quot; data-placeholder=&quot;Übersetzung&quot; id=&quot;tw-target-text&quot; style=&quot;text-align: left;&quot; dir=&quot;ltr&quot;&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;Östlich von Amman erstreckt sich die ausgedörrte Wüstenebene bis in den Irak und nach Saudi-Arabien. Dies ist ein Ort, an dem endloser Sand und unfruchtbare Basaltlandschaften die Fähigkeiten des Menschen unter Beweis stellen&lt;/span&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;ge/wuesten-burgen/&quot; class=&quot;btn orange h-pad&quot;&gt;Mehr...&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Madaba/madaba mosque.jpg&quot; alt=&quot;Madaba&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Madaba&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;pre class=&quot;tw-data-text tw-text-large tw-ta&quot; data-placeholder=&quot;Übersetzung&quot; id=&quot;tw-target-text&quot; style=&quot;text-align: left;&quot; dir=&quot;ltr&quot;&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;Madaba ist am bekanntesten für seine byzantinischen und umayyadischen Mosaike, insbesondere eine große Mosaikkarte des Heiligen Landes aus byzantinischer Zeit. Madaba liegt 30 km südwestlich der Hauptstadt Amman.&lt;/span&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href