INSERT INTO `en33_pages` (`id`, `name`, `title`, `meta_desc`, `meta_key`, `contents`, `published`, `lang_id`, `lang`, `icon`, `layout`, `url`) VALUES
(1822, 'Über Uns', 'Über Uns', 'Über Uns', 'Über Uns', '&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;strong&gt;&lt;/strong&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;&lt;strong&gt;PV Travels&lt;/strong&gt; ist ein arabischer Reiseveranstalter und der erste echte Nahost-Reiseservice, der speziell für die Bedürfnisse heutiger Reisender entwickelt wurde. Egal, ob Sie ein Öko-Trekker, ein spiritueller Sucher oder ein Geschäftsmann sind, mit unserem umfassenden Fachwissen können wir unabhängig von Ihrer Religion auf alle Ihre individuellen Bedürfnisse eingehen. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;Wir sind Ihre persönlichen Experten für Urlaubsdesigner. Wir kümmern uns um alle Aspekte Ihrer Reise, von individuellen Routen über Unterkünfte bis hin zu Reiseleitern und Aktivitäten. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;&lt;strong&gt;PV Travels&lt;/strong&gt; ist spezialisiert auf die Bereitstellung einer breiten Palette von Bodendiensten für &lt;a href=&quot;en/&quot;&gt;Touristen im Nahen Osten&lt;/a&gt;. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;Die Liebe zum Detail bei der Durchführung von Reiserouten hat viele internationale Reiseveranstalter und -großhändler dazu veranlasst, PV Travels mit der Betreuung ihrer Kunden zu beauftragen.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;&lt;strong&gt;PV Travels Services umfassen:  &lt;/strong&gt;   &lt;/span&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;Bieten klassische Touren, &lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;Trekking- und Abenteuerprogramme     &lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;Destination Services     &lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;Freizeitreise     &lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;FAM-Reisen     &lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;Teambuilding-Reisen     &lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;Gruppenreisen     &lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;Geschäftsreise     &lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;Incentive-Reisen     &lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;American Express Travel Services     &lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;Besprechungen, Veranstaltungen und Konferenzen     &lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;Produktionsdienstleistungen     &lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;Logistik     &lt;/span&gt;&lt;/li&gt;\r\n&lt;li&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;Bodentransport in Fahrzeugen mit mehreren Klassen &lt;/span&gt;&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;&lt;span lang=&quot;de&quot; tabindex=&quot;0&quot;&gt;&lt;strong&gt;Um mehr über PV Travels zu erfahren, senden Sie bitte eine E-Mail an&lt;/strong&gt; &lt;strong&gt;&lt;u&gt;&lt;a href=&quot;mailto:info@pvt.jo&quot;&gt;info@pvt.jo&lt;/a&gt;&lt;/u&gt;&lt;/strong&gt;<br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;div class=&quot;tw-ta-container tw-nfl&quot; id=&quot;z6maec&quot;&gt;\r\n&lt;pre class=&quot;tw-data-placeholder tw-text-small tw-ta&quot; data-placeholder=&quot;&quot; id=&quot;tw-target-rmn&quot; style=&quot;text-align: left;&quot; dir=&quot;ltr&quot;&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;u&gt;&lt;a href=&quot;mailto:info@pvt.jo&quot;&gt;&lt;/a&gt;&lt;/u&gt;&lt;/strong&gt;&lt;/p&gt;', 1, 321, 'ge', '', 'one col', 'ueber-uns'),
(1823, 'Naturreservate in Jordanien', 'Naturreservate in Jordanien', 'Naturreservate in Jordanien', 'Naturreservate in Jordanien', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Dana/DanaReserve.jpg&quot; alt=&quot;Dana Biosphere Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Dana-Biosphärenreservat&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;&lt;span lang=&quot;de&quot;&gt;Das Dana-Biosphärenreservat ist das größte Naturschutzgebiet in Jordanien und befindet sich im südlichen Zentraljordanland. Das Dana Biosphere Reserve wurde 1989 in der Gegend um das Dana Village gegründet.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;ge/dana-biospharenreservat/&quot; class=&quot;btn orange h-pad&quot;&gt;Mehr...&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/more places/Ajloun forest reserve website 800x500.jpg&quot; alt=&quot;Ajloun Forest Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Ajloun Waldreservat&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;&lt;span lang=&quot;de&quot;&gt;Das Ajloun Forest Reserve ist ein Naturschutzgebiet im Gouvernement Ajloun im Nordwesten Jordaniens. Gegründet von der Royal Society for the Conservation of Nature ...&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;ge/ajloun-waldreservat/&quot; class=&quot;btn orange h-pad&quot;&gt;Mehr...&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/Dibeen_Forest_Reserve.jpg&quot; alt=&quot;Dibbeen Forest Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Dibbeen Waldreservat&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;div class=&quot;QmZWSe&quot;&gt;\r\n&lt;div class=&quot;DHcWmd&quot;&gt;\r\n&lt;div id=&quot;tw-target&quot; class=&quot;&quot;&gt;\r\n&lt;div id=&quot;kAz1tf&quot; class=&quot;g9WsWb&quot;&gt;\r\n&lt;div class=&quot;tw-ta-container tw-nfl&quot; id=&quot;tw-target-text-container&quot; tabindex=&quot;0&quot;&gt;\r\n&lt;pre class=&quot;tw-data-text tw-text-large tw-ta&quot; data-placeholder=&quot;Übersetzung&quot; id=&quot;tw-target-text&quot; style=&quot;text-align: left;&quot; dir=&quot;ltr&quot;&gt;&lt;span lang=&quot;de&quot;&gt;Das Dibbeen Waldreservat ist ein Naturschutzgebiet im Nordwesten Jordaniens. Es liegt südlich der römischen Stätte Jerash und erstreckt sich über eine Fläche von 8,5 Quadratkilometern ...&lt;/span&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;ge/dibbeen-waldreservat/&quot; class=&quot;btn orange h-pad&quot;&gt;Mehr...&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Natural Reserves/Shaumari website 800x500.jpg&quot; alt=&quot;Shaumari Wildlife Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Shaumari Naturschutzgebiet&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;&lt;span lang=&quot;de&quot;&gt;Das Shaumari Wildlife Reserve ist ein jordanisches Naturschutzgebiet in der Nähe der Stadt Azraq, etwa 100 km östlich von Amman.Das regional bedeutende Naturschutzgebiet wurde 1975 ...&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;ge/shaumari-naturschutzgebiet/&quot; class=&quot;btn orange h-pad&quot;&gt;Mehr...&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Natural Reserves/wetland.jpg&quot; alt=&quot;Azraq Wetland Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Azraq Feuchtgebietreservat&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;&lt;span lang=&quot;de&quot;&gt;Das Azraq Feuchtgebietreservat ist ein Naturschutzgebiet in der Nähe der Stadt Azraq in der östlichen Wüste von Jordanien. Azraq, eine Oase für Zugvögel, wurde 1978 gegründet und umfasst 12 ...&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;ge/al-azraq-oase/&quot; class=&quot;btn orange h-pad&quot;&gt;Mehr...&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Natural Reserves/Yarmouk.jpg&quot; alt=&quot;Yarmouk Forest Reserve&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Yarmouk Waldreservat&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;&lt;span lang=&quot;de&quot;&gt;Die Royal Society for the Conservation of Nature implementiert das integrierte Ökosystem-Management im Jordan Rift Valley-Projekt, mit dem ein Netzwerk von Reservaten und ...&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;ge/yarmouk-waldreservat/&quot; class=&quot;btn orange h-pad&quot;&gt;Mehr...&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Natural Reserves/River-canyon-of-Wadi-Mujib.jpg&quot; alt=&quot;Wadi Mujib&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Wadi Mujib&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;&lt;span lang=&quot;de&quot;&gt;Im Jahr 2011 erklärte die UNESCO das Biosphärenreservat Mujib. Es erstreckt sich bis zu den Bergen Kerak und Madaba im Norden und Süden und erreicht an einigen Stellen 900 Meter über dem Meeresspiegel ....&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;ge/wadi-mujib/&quot; class=&quot;btn orange h-pad&quot;&gt;Mehr...&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1318, 'ge', '', 'one col', 'naturreservate-in-jordanien'),
(1824, 'Sockets in Jordan. Do I need an adaptor?', 'Sockets in Jordan. Do I need an adaptor?', '', '', '&lt;p&gt;Although it might sound quite extraordinary Jordan has two different types of electrical sockets. If you are wondering why, welcome to the club! No one seems to know exactly what the reason is behind this mystery.&lt;/p&gt;\r\n&lt;p&gt;These are the two sockets you will find during your stay in this Middle Eastern wonder:&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;img src=&quot;uploads/filemanager/Sockets/socket jordan pvt.png&quot; alt=&quot;&quot; /&gt;&lt;/p&gt;\r\n&lt;p&gt;(Sames as UK)&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;img src=&quot;uploads/filemanager/Sockets/socket jordan pvt 2.png&quot; alt=&quot;&quot; /&gt;&lt;/p&gt;\r\n&lt;p&gt;(Same as most of Europe)&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;You might find both sockets in one same room but you might find yourself with one or the other only. So our advice woud be for you to get a multi socket adaptor. They aren’t too expensive, they usually range between 5 and 35$, and you will be able to use them for your future travels too. You can usually find them in electronic shops and they come in really handy as they don’t take much sapce in your luggage either. Here are some examples:&lt;/p&gt;\r\n&lt;p&gt;&lt;img src=&quot;uploads/filemanager/Sockets/multi socket 2.png&quot; alt=&quot;multi socket jordan pvt&quot; /&gt;  &lt;img src=&quot;uploads/filemanager/Sockets/multi-socket.png&quot; alt=&quot;multi socket jordan 2 pvt&quot; /&gt;&lt;/p&gt;\r\n&lt;p&gt;Please also note that the standard voltage in Jordan is 250V and 50Hz.&lt;/p&gt;', 0, 1824, 'en', '', 'one col', 'sockets-in-jordan.-do-i-need-an-adaptor'),
(1825, 'Restaurants in Petra', 'Restaurants in Petra', '', 'Restaurants, Petra, organic food, vegetarian food', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/my moms recipe restaurant pvt.jpeg&quot; alt=&quot;My mom’s Reciepe  Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;My Mom&#039;s Recipe Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;&lt;span style=&quot;font-size: 14px; text-align: left; color: #111111; text-decoration-line: inherit;&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-size: 14px; text-align: left; color: #111111; text-decoration-line: inherit;&quot;&gt;Traditional and delicious Jordanian food: t&lt;span&gt;heir most famous dishes are<br> their Mansaf and hummus. Live music.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/my-moms-recipe-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Petra Kitchen.jpeg&quot; alt=&quot;Petra Kitchen&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Petra Kitchen&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;A true Jordanian experience: here you cook your own food and enjoy the flavoursome meals at the end.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/petra-kitchen/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Al qantarah restaurant pvt.jpg&quot; alt=&quot;Al Qantarah Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;<br>\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Al Qantarah Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Locally produced, organic and fresh food. They bake their bread and grill their meat in the ‘Taboun’.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/restaurant-al-qantarah/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;strong&gt;Read&lt;/strong&gt; More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Sanabel bakery.jpg&quot; alt=&quot;Sanabel sweets and bakeries &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Sanabel Sweets and Bakeries&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The staff is outstandingly kind and will immediately offer you to try different samples of their treats.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/sanabel-sweets-and-bakeries/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Sandstone restaurant petra pvt.jpg&quot; alt=&quot;Sandstone Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Sandstone Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Near the visitors center, this restaurant offers a mix of juicy grills and delicious salads and mezze.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/sandstone-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/red cave restaurant petra pvt.jpg&quot; alt=&quot;Red cave restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Red Cave Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Wide range of dishes: mezze, soups, grills and also Bedouine specialities such as the Gallayah.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/red-cave-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/The basin restaurant petra pvt.jpg&quot; alt=&quot;The Basin Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;The Basin Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;The only restaurant located inside Petra’s archaeological area. They serve i&lt;span&gt;nternational and local dishes.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/the-basin-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/al wadi restaurant petra pvt.jpg&quot; alt=&quot;Al wadi restaurant &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Al Wadi Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Large portions of delicious local food such as Mansaf and Maklouba, grills, soups and more.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/al-wadi-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1825, 'en', '', 'one col', 'restaurants-in-petra'),
(1826, 'My Mom&#039;s Recipe Restaurant', 'My Mom&#039;s Recipe Restaurant', '', '', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;My Mom’s Recipe restaurant offers traditional mouth-watering Jordanian food. Lunch consists on a buffet and dinner is a la carte. Their most famous dishes are their Mansaf and hummus. Mansaf is the favourite of most locals, it is made of lamb (or chicken) cooked with a delicious fermented yogurt sauce and served with rice. And Hummus, well… we all know hummus! They also have a wide selection of grills and salads. Their main dishes range from 8 to 12 JD. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;The restaurant is big and suitable for groups, it has a breezy beautiful rooftop where you can sit and relax which happens to be cool even during hot summer days. Its rooms are tastefully decorated, filled with the traditional patterns of Jordan. At My Mom’s Recipe they offer live music that you can sit and listen to or you can dance along. Their staff members are known to be very welcoming and hospitable. It is conveniently located in the tourist area of Petra.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/my moms recipe restaurant petra.jpg&quot; alt=&quot;My mom&#039;s recipe Restaurant Petra &quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d13775.613589587205!2d35.4704252!3d30.3252655!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0:0x5d98363a3c78eac9!2sMy Mom&#039;s Recipe Restaurant!5e0!3m2!1sen!2sjo!4v1579344331132!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1826, 'en', '', 'one col', 'my-moms-recipe-restaurant'),
(1827, 'Petra Kitchen', 'Petra Kitchen', '', '', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;If you want the true Jordanian experience stop searching, this is the best spot in town. You cook your own food and have the pleasure to enjoy the flavoursome meals at the end. The cooking session usually lasts for two hours and you prepare the food with a local chef and other staff members who will not only show you the secrets of their cuisine but will also introduce you to their culture and history and will give you a chance to witness the outstanding hospitality of Jordanians. The courses are run in the evenings and if you are planning to stay in Petra for a while you can also join a 5 day-long cooking course.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;<br>All their ingredients are fresh and they are proud to state that there are no freezers nor fridges in their kitchen. They cook the food they buy on the same day and they ensure there is 0 food waste. If there are leftovers these are provided to local families in-need. They also count with numerous vegetarian options. Moreover, their produce is 100% local: They pick and produce their own oil, grow their herbs and even their furniture is purchased from local shops and cooperatives. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;<br>Petra Kitchen is the ideal place to meet people, learn how to cook Jordanian dishes or chill on the terrace and drink some delicious local wine. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Petra Kitchen.jpeg&quot; alt=&quot;Petra Kitchen &quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3443.9063408890875!2d35.46911255055766!3d30.325181781691654!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15016ed1bd9661bf:0x5b61bbdbc82401ac!2sPetra Kitchen!5e0!3m2!1sen!2ses!4v1577266785362!5m2!1sen!2ses&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1827, 'en', '', 'one col', 'petra-kitchen'),
(1828, 'Al Qantarah Restaurant', 'Al Qantarah Restaurant', '', '', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;Al Qantarah offers a fix-rate buffet both for lunch and dinner that consists on a selection of salads, soups, mezze, meats and desserts which are served in handmade pottery dishes. They believe in sustainable tourism values and thus their food is locally produced, organic and fresh as they proudly state. Moreover, they bake their bread and grill their meat in an old clay oven called ‘Taboun’. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: Arial, sans-serif; text-decoration-line: inherit;&quot;&gt;The restaurant is in a gorgeous stone-made building covered with arches where you can discover the traditional Jordanian architecture. It is spacious and can host big groups of diners. It is also decorated with beautiful local artwork.&lt;/span&gt;<br>&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;The atmosphere is pleasant and it is definitely a favourite amongst both locals and visitors. They also play live traditional music. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Al qantarah restaurant pvt.jpg&quot; alt=&quot;Petra Kitchen &quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3443.811125286482!2d35.468405850557865!3d30.3278897816907!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15016ed122c46ef9:0x97f9cf5fe8d881ea!2sAlqantarah Restaurant!5e0!3m2!1sen!2ses!4v1577269520587!5m2!1sen!2ses&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1828, 'en', '', 'one col', 'al-qantarah-restaurant'),
(1829, 'Sanabel sweets and bakeries', 'Sanabel sweets and bakeries', 'For those of you with a sweet-tooth you won’t regret stopping by Sanabel. The staff is outstandingly kind and will immediately offer you to try different samples of their delicious Jordanian treats.', 'Jordanian sweets, Arab sweets, Petra, Sanabel', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;For those of you with a sweet-tooth you won’t regret stopping by Sanabel. The staff is outstandingly kind and will immediately offer you to try different samples of their delicious Jordanian treats. It is clearly the best store in Petra for your sweet delights. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;Their bread is their cherry on top. They bake the most delicious Arabic bread in town and it is all offered at a very affordable price. Don’t miss out on this truly Jordanian experience. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Sanabel bakery.jpg&quot; alt=&quot;Sanabel Sweets and Bakeries&quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3444.0208882834613!2d35.47640015055771!3d30.321923681692702!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1501692d5040f91d:0xf85011a756e27662!2sSANABEL Sweets and Bakeries!5e0!3m2!1sen!2ses!4v1577269684772!5m2!1sen!2ses&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1829, 'en', '', 'one col', 'sanabel-sweets-and-bakeries'),
(1830, 'Sandstone Restaurant', 'Sandstone Restaurant', 'Conveniently located near the visitors center the Sandstone Restaurant offers a mix of juicy grills and delicious salads and mezze.', 'visitors center, Petra, Mezze, Sandstone', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;Conveniently located near the visitors center the Sandstone Restaurant offers a mix of juicy grills and delicious salads and mezze. They also serve local wine and beer as well as other alcoholic drinks. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: Arial, sans-serif; text-decoration-line: inherit;&quot;&gt;The Sandstone Restaurant counts with an outdoor terrace where you can sit back and relax whilst enjoying the views. It is clearly a popular choice amongst both locals and visitors and a perfect place to indulge in the traditional Jordanian foods.&lt;/span&gt;<br>&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Sandstone restaurant petra pvt.jpg&quot; alt=&quot;Sandstone Restaurant&quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3443.903071056889!2d35.4679897505578!3d30.32527478169155!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15016ed1ca504bb5:0xd9577f278a03538d!2sSandstone!5e0!3m2!1sen!2ses!4v1577271743770!5m2!1sen!2ses&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1830, 'en', '', 'one col', 'sandstone-restaurant'),
(1831, 'Red Cave Restaurant', 'Red Cave Restaurant', 'Red Cave offers a wide range of dishes: you can find a variety of mezze (Arabic appetizers), soups, grills and also Bedouine specialities such as the Gallayah.', 'mezze, zuppe, grigliate, Gallayah, ristorante a Petra', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;Red Cave offers a wide range of dishes: you can find a variety of mezze (Arabic appetizers), soups, grills and also Bedouine specialities such as the Gallayah. They also serve the delicious Makloubah which is a traditional Middle Eastern dish and literally means ‘upside-down’, it consists of rice, fried vegetables and meat and it’s cooked in a pot which is flipped upside-down before it is served (hence its name!). Food is offered as a buffet and diners have the option to help-themselves to what they most desire. They also organize ‘a la carte’ buffets if requested one day in advance. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: Arial, sans-serif; text-decoration-line: inherit;&quot;&gt;We personally believe the food is delicious, the place is gorgeous and cosy and the staff are very friendly. However, truth must be said, there seem to be a variety of reviews and opinions about it: it is one of those love or hate places!&lt;/span&gt;<br>&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/red cave restaurant petra pvt.jpg&quot; alt=&quot;Red Cave Restaurant&quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3443.9034824202276!2d35.46781751496511!3d30.32526308178106!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15016ed22e61a421:0xfd8b65879bb40ebc!2sRed Cave Restaurant!5e0!3m2!1sen!2ses!4v1577275228517!5m2!1sen!2ses&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1831, 'en', '', 'one col', 'red-cave-restaurant'),
(1832, 'The Basin Restaurant', 'The Basin Restaurant', '', '', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;The Basin Restaurant is the only restaurant located in the heart of Petra’s archaeological area. Its outdoor sitting allows you to eat surrounded by the spectacular ruins of Petra. It is the ideal spot to have a break and get some energy on your way to or back from the Monastery. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;They offer a lunch buffet of a variety of international and local dishes. Make sure you pre-book to secure a place as it can get quite busy. &lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/The basin restaurant petra pvt.jpg&quot; alt=&quot;The Basin Restaurant&quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3443.7004046180555!2d35.43777431498687!3d30.33103848177892!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15016ef6d52042dd:0x85beac287ee6c5cd!2sThe Basin Restaurant!5e0!3m2!1sen!2ses!4v1577296632639!5m2!1sen!2ses&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1832, 'en', '', 'one col', 'the-basin-restaurant'),
(1833, 'Al Wadi Restaurant', 'Al Wadi Restaurant', 'Al Wadi restaurant is another clear example of the incredible hospitality of Jordanian people. The staff are outstandingly friendly and always ready to help you out with anything you need.', 'Restaurants in Petra, Al Wadi Restaurant', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;Al Wadi restaurant is another clear example of the incredible hospitality of Jordanian people. The staff are outstandingly friendly and always ready to help you out with anything you need. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: Arial, sans-serif; text-decoration-line: inherit;&quot;&gt;They serve large portions of delicious local food such as Mansaf (lamb, rice and a fermented yogurt sauce) and Maklouba (literally ‘upside-down’ – rice, vegetables and meat cooked in a pot and tipped upside-down before being served), grills, soups, mezze but also international dishes such as pizza and spaghetti. And to make your mouth-watering experience even better they serve all these dishes with the best homemade bread!&lt;/span&gt;<br>&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;The restaurant is located right in the center of the town, ten minutes away from the Petra archaeological site and offers beautiful views to the mountain &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/al wadi restaurant petra pvt.jpg&quot; alt=&quot;Al Wadi Restaurant&quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3444.0281725881187!2d35.478101650550606!3d30.321716481692825!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1501692d6fdd32f9:0xe7706d5a63a8819d!2sAl Wadi Restaurant!5e0!3m2!1sen!2ses!4v1577297236812!5m2!1sen!2ses&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1833, 'en', '', 'one col', 'al-wadi-restaurant'),
(1834, 'Restaurants in Aqaba', 'Restaurants in Aqaba', '', 'Restaurants, Aqaba', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/Captains Tourist Restaurant Aqaba.jpg&quot; alt=&quot;Captains Tourist Restaurant &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Captain&#039;s Tourist Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Very popular, a classic situated in the heart of Aqaba, it follows a maritime-themed decoration.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/captains-tourist-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/ali baba restaurant Restaurant Aqaba.jpg&quot; alt=&quot;Ali Baba Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Ali Baba Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Traditional Jordanian food such as a wide selection of mezze, seafood, mixed grill, and vegetarian options.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/ali-baba-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/The royal yacht club Restaurant Aqaba.jpg&quot; alt=&quot;The Royal Yacht Club of Jordan&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;<br>\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;The Royal Yacht Club of Jordan&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;With a luxurious terrace facing the port, this is the best place in town to watch the beautiful Aqaba sunsets.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/the-royal-yacht-club-jordan-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/gelato uno aqaba Restaurant Aqaba.jpg&quot; alt=&quot;Gelato Uno&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Gelato Uno&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;There’s never a bad time for a delicious and refreshing ice-cream in the always warm Aqaba!&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/gelato-uno/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1834, 'en', '', 'one col', 'restaurants-in-aqaba'),
(1835, 'Captain&#039;s Tourist Restaurant', 'Captain&#039;s Tourist Restaurant', '', '', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;Captain’s Tourist Restaurant is a classic. It is situated in the heart of the portal city and follows a maritime-themed decoration, even their staff wear nautical costumes! It is a popular restaurant and many tourists that go there decide to repeat and thus it is a very busy restaurant. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;They serve high quality food cooked from freshly sourced ingredients, especially seafood, which is generally harder to find in other cities in Jordan. &lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/Captains Tourist Restaurant Aqaba.jpg&quot; alt=&quot;Captain&#039;s Restaurant&quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3471.485623466954!2d35.000513950516186!3d29.53134888198396!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15007036e384e875:0x3cb66e677f54f66b!2sCaptains restaurant!5e0!3m2!1sen!2sjo!4v1579348625153!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1835, 'en', '', 'one col', 'captains-tourist-restaurant');
INSERT INTO `en33_pages` (`id`, `name`, `title`, `meta_desc`, `meta_key`, `contents`, `published`, `lang_id`, `lang`, `icon`, `layout`, `url`) VALUES
(1836, 'Ali Baba Restaurant', 'Ali Baba Restaurant', '', '', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;Ali Baba serves traditional Jordanian food such as a wide selection of mezze (Arabic appetizers), seafood and mixed grill. They also count with vegetarian options. There you can try the mouth-watering traditional Aqaba seafood dish: the Sayiadya. Ali Baba also offers alcoholic drinks. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;It is very popular amongst tourists, but you don’t usually spot many locals anymore. It has a lovely large terrace where you can sit and relax after a long day exploring the city as it is located right in the heart of the historic old city . It is also a great place for chilling and people-watching.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/ali baba restaurant Restaurant Aqaba.jpg&quot; alt=&quot;Ali Baba Restaurant &quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3471.563088461576!2d35.00095115051621!3d29.529091881984762!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x150070363353dd73:0x71b5e1363c4a4799!2sAlibaba Restaurant!5e0!3m2!1sen!2sjo!4v1579349245962!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1836, 'en', '', 'one col', 'ali-baba-restaurant'),
(1837, 'The Royal Yacht Club Jordan Restaurant', 'The Royal Yacht Club Jordan Restaurant', 'High quality variety of international food in Aqaba.', 'Japanese food, Italian food, Arab meze, wines', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;With its wood-panelled setting and its luxurious terrace facing the port The Royal Yacht Club is most likely the best place in town to watch the beautiful Aqaba sunsets. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot;&gt;&lt;span style=&quot;font-family: Arial, sans-serif; text-decoration-line: inherit;&quot;&gt;Sit down and relax in this classy restaurant indulging in a high-quality variety of food from different corners of the world: Handmade Italian pasta and pizza, Japanese sushi, Arabic mezze and many others. They also have a wide selection of local and imported wines.&lt;/span&gt;<br>&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/The royal yacht club Restaurant Aqaba.jpg&quot; alt=&quot;The Royal Yacht Club Jordan Restaurant&quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3471.5460788871073!2d34.99716785051613!3d29.52958748198458!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1500712ca50f90c7:0xac771e8948db096d!2sThe Royal Yacht Club of Jordan!5e0!3m2!1sen!2sjo!4v1579349591219!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1837, 'en', '', 'one col', 'the-royal-yacht-club-jordan-restaurant'),
(1838, 'Gelato Uno', 'Gelato Uno', 'Delicious ice cream shop in Aqaba.', 'Ice cream, Aqaba, Summer, Ice cream shop', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;You will find that Aqaba has very mild winters, unlike other cities in Jordan, and can have extremely hot summers so there’s never a bad time for a delicious and refreshing ice-cream! This restaurant is a popular choice amongst locals and tourists who are looking to cool down after a long hot day. &lt;/span&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;It can be a perfect place to go with kids too as the owner also runs the pizzeria next door. &lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/gelato uno aqaba Restaurant Aqaba.jpg&quot; alt=&quot;Ali Baba Restaurant &quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3471.5014326667547!2d35.00152545051614!3d29.530888281984055!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x150070371fe742b3:0x3e735af66dd672e!2sGelato uno!5e0!3m2!1sen!2sjo!4v1579349727105!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1838, 'en', '', 'one col', 'gelato-uno'),
(1839, 'Primal Bistro &amp; Café', 'Primal Bistro &amp; Café', '', '', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; color: #302f2f; font-size: 14pt;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt; color: #302f2f;&quot;&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 14pt;&quot; lang=&quot;de&quot;&gt;Primal ist das erste und einzige Paleo-Restaurant in Amman. Ihre Vision ist es, dass Sie wieder gesund und rein essen.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt; color: #302f2f;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-size: 14pt; color: #302f2f;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 14pt;&quot; lang=&quot;de&quot;&gt;Primal befindet sich im wohlhabendsten Viertel der Stadt, dem Wadi Abdoun und ist stolz darauf, ein für jeden geeignetes Menü zu haben. Wir bieten ein Menü, das völlig glutenfrei, zuckerfrei, laktosefrei und mit unzähligen vegetarischen und pflanzlichen veganen Optionen verfeinert ist. Darüber hinaus serviert Primal eine große Auswahl an einheimischem und importiertem Bier, Wein und Sekt.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot; lang=&quot;de&quot;&gt;Das moderne und wunderschön eingerichtete Haus bietet einen verglasten Bereich sowie Sitzgelegenheiten im Freien.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt;&quot;&gt; &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/primal bistro and cafe restaurants Amman.jpg&quot; width=&quot;445&quot; height=&quot;295&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3385.270109805313!2d35.88204971548299!3d31.95356813281916!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151ca0f7312a01b9:0xbf3c31d4862d8d04!2sPrimal restaurant!5e0!3m2!1sen!2sjo!4v1576404328748!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1567, 'ge', '', 'one col', 'primal-bistro-amp-café'),
(1840, 'Fatatri', 'Fatatri', '', '', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 12pt;&quot;&gt;<br>&lt;/span&gt;&lt;span style=&quot;font-size: 12pt;&quot; lang=&quot;de&quot;&gt;Dieses Restaurant verbindet ägyptische und jordanische Kultur und ist auf &quot;Feteer&quot; spezialisiert, ein köstliches Gebäck, das aus einem sehr dünnen Teig besteht, der mit frischen Zutaten nach Wahl des Kunden gefüllt und im Ofen gebacken wird. Der Teig enthält nur Mehl, Wasser und etwas Salz, aber keine Konservierungsmittel oder Zusätze.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 12pt;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 12pt;&quot;&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 12pt;&quot; lang=&quot;de&quot;&gt;Dieses Restaurant bietet seinen Kunden nicht nur einen exzellenten Service, sondern konzentriert sich auch auf die persönliche Entwicklung seiner Mitarbeiter, um ihnen die Möglichkeit zu geben, neue Fähigkeiten zu erlernen. Fatatri ist das erste Restaurant in der Stadt, das seinem Team kostenlosen Englischunterricht bietet. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 12pt;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 12pt;&quot;&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 12pt;&quot; lang=&quot;de&quot;&gt;Schauen Sie unbedingt während Ihres Aufenthalts in Amman vorbei und beobachten Sie, wie die außergewöhnlich talentierten Köche den Teig verteilen und in die Luft werfen, bevor Sie ihn mit frischen Zutaten aus der Region füllen.&lt;/span&gt;&lt;/p&gt;\r\n&lt;div class=&quot;tw-ta-container tw-nfl&quot; id=&quot;z6maec&quot;&gt;\r\n&lt;pre class=&quot;tw-data-placeholder tw-text-small tw-ta&quot; data-placeholder=&quot;&quot; id=&quot;tw-target-rmn&quot; style=&quot;text-align: left;&quot; dir=&quot;ltr&quot;&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 12pt;&quot;&gt; &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 12pt;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 12pt;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/fatatri restaurant amman.jpg&quot; width=&quot;404&quot; height=&quot;249&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;510&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3385.436976592755!2d35.925943950599674!3d31.94903998113775!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151b5f9b63402caf:0x18c1effcef8bfa3f!2zRmF0YXRyaSDZgdi32LfYsdmK!5e0!3m2!1sen!2sjo!4v1576344251915!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt; &lt;iframe width=&quot;510&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d13540.974558857148!2d35.844875003039505!3d31.954286381136168!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151ca19aaa5157c9:0x7c9ec4b22728d0d2!2sFatatri 7th Circle!5e0!3m2!1sen!2sjo!4v1576344303377!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1566, 'ge', '', 'one col', 'fatatri'),
(1841, 'Al-Quds Falafel', 'Al-Quds Falafel', '', '', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;<br><br>&lt;/span&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 14pt;&quot; lang=&quot;de&quot;&gt;Das Restaurant Al-Quds befindet sich in der lebhaften und pulsierenden Rainbow Street und serviert die besten Falafel in Amman. Viele Einheimische und Touristen kommen vorbei, um nach einem Spaziergang durch die Rainbow Street ein leckeres Falafel-Sandwich zu sich zu nehmen. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt; &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 14pt;&quot; lang=&quot;de&quot;&gt;Aufgrund seiner geringen Größe gibt es außer einer kleinen Bank außerhalb des Ladens nicht viele Sitzgelegenheiten. Sie können jedoch Ihr Essen zum Mitnehmen kaufen oder es sogar online bestellen.&lt;/span&gt;&lt;/p&gt;\r\n&lt;div class=&quot;tw-ta-container tw-nfl&quot; id=&quot;z6maec&quot;&gt;\r\n&lt;pre class=&quot;tw-data-placeholder tw-text-small tw-ta&quot; data-placeholder=&quot;&quot; id=&quot;tw-target-rmn&quot; style=&quot;text-align: left;&quot; dir=&quot;ltr&quot;&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt; &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/e28c2eb2e503cacfa05fa26ffe47dd5c-al-quds.jpg&quot; width=&quot;426&quot; height=&quot;340&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d13541.683034851729!2d35.9265022!3d31.9494801!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0:0x376a889bafb7348c!2sAl Quds Falafel!5e0!3m2!1sen!2sjo!4v1576341855898!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1565, 'ge', '', 'one col', 'al-quds-falafel'),
(1842, 'Fakhreldin Restaurant', 'Fakhreldin Restaurant', '', '', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; color: #302f2f; font-size: 14pt;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt; color: #302f2f;&quot;&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 14pt;&quot; lang=&quot;de&quot;&gt;&quot;Feine levantinische Küche in der Eleganz eines authentischen jordanischen Hauses&quot;.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt; color: #302f2f;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-size: 14pt; color: #302f2f;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 14pt;&quot; lang=&quot;de&quot;&gt;Das Fakhreldin Restaurant befindet sich in einem der ältesten Viertel von Amman. Es wurde in der goldenen Zeit der Mitte des 20. Jahrhunderts entworfen und gebaut und war im Laufe der Jahre auch die Heimat mehrerer prominenter Würdenträger in Jordanien. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot; lang=&quot;de&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt;&quot;&gt;&lt;span style=&quot;color: #302f2f;&quot;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 14pt;&quot; lang=&quot;de&quot;&gt;Das Fakhreldin Restaurant zeichnet sich durch seinen Service und sein Essen aus und hat sich als eines der Top-Restaurants in Amman einen kritischen Ruf erworben. Für die fantastische Auswahl an Grills, traditionellen orientalischen Vorspeisen und süßen arabischen Desserts werden Fleisch, Hähnchen und Meeresfrüchte von bester Qualität verwendet.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt;&quot;&gt;&lt;span style=&quot;color: #302f2f;&quot;&gt;&lt;/span&gt;<br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/fakhreldin.jpg&quot; width=&quot;444&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3385.322932494197!2d35.918252650599904!3d31.952134781136916!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151b5f99a48f39f3:0x3fd68db1f2177c00!2sFakhreldin Restaurant!5e0!3m2!1sen!2sjo!4v1576340310025!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1564, 'ge', '', 'one col', 'fakhreldin-restaurant'),
(1843, 'Habibah sweets', 'Habibah sweets', '', '', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt;&quot;&gt; <br>&lt;/span&gt;<br>&lt;o:p&gt;&lt;/o:p&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt;&quot;&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 14pt;&quot; lang=&quot;de&quot;&gt;Das familiengeführte Süßwarengeschäft wurde 1951 gegründet und verkauft traditionelle Pralinen und Gebäck.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 14pt;&quot; lang=&quot;de&quot;&gt;Sie sind berühmt für ihr Kanafeh, ein traditionelles orientalisches Dessert aus feinem Grießteig, einer Schicht Käse und Sirup auf Zuckerbasis.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;<br> &lt;/span&gt;&lt;/span&gt;<br>&lt;o:p&gt;&lt;/o:p&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt;&quot;&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 14pt;&quot; lang=&quot;de&quot;&gt;Al-Haj Mahmoud Habibah kam 1934 aus Nablus und begann seine Arbeit in einem kleinen Kunafa-Laden in Jerusalem. Ein Jahr später zog er nach Amman. Seitdem bietet er sowohl Einheimischen als auch Besuchern, die rund um den Block anstehen und auf ihren süßen Leckerbissen warten, anmutig seine Süßigkeiten an.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt;&quot;&gt; &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/habibah sweets amman.jpg&quot; width=&quot;443&quot; height=&quot;332&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d13540.969057553559!2d35.926048531992045!3d31.954323699295294!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151b5f99d8819489:0xcc54b3d129d39825!2sHabibah Sweets!5e0!3m2!1sen!2sjo!4v1576339669181!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1563, 'ge', '', 'one col', 'habibah-sweets'),
(1844, 'Hashem Downton', 'Hashem Downton', '', '', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;span lang=&quot;de&quot;&gt;Das Hashem Downtown ist das älteste Restaurant der Stadt und wird seit 1956 betrieben. Es ist auf jeden Fall ein Muss während Ihrer Reise nach Jordanien.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;<br>&lt;/span&gt;&lt;span lang=&quot;de&quot;&gt;Es ist als das Restaurant bekannt, das niemals schließt, weil es rund um die Uhr Essen serviert! Darin finden Sie die köstlichsten Hummus, Falafel und Foul in der Stadt.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;span lang=&quot;de&quot;&gt;Die Wände des Restaurants sind mit Bildern von vielen Prominenten geschmückt, die es in den letzten 60 Jahren besucht haben, wie Seine Majestät König Abdullah II., Königin Rania, Kronprinz SH Prinz Hussein, Palästinenserpräsident Yasser Arafat, Omar Alsherif, Melhim Brakat, Kamal Alshinawi, George Wassof.&lt;/span&gt;&lt;/p&gt;\r\n&lt;div class=&quot;tw-ta-container tw-nfl&quot; id=&quot;z6maec&quot;&gt;\r\n&lt;pre class=&quot;tw-data-placeholder tw-text-small tw-ta&quot; data-placeholder=&quot;&quot; id=&quot;tw-target-rmn&quot; style=&quot;text-align: left;&quot; dir=&quot;ltr&quot;&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/hashem restaurant.jpg&quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d6770.621150646353!2d35.9297785!3d31.9524701!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0:0xe7dab884a8b945e2!2sHashem Restaurant Down Town!5e0!3m2!1sen!2sjo!4v1576336687523!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1562, 'ge', '', 'one col', 'hashem-downton'),
(1845, 'Kan Zamaan', 'Kan Zamaan', '', '', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;span lang=&quot;de&quot;&gt;Das Kan Zamaan Restaurant ist eine der besten Touristenattraktionen in Amman. Das Restaurant ist ein attraktiver historischer Ort, der großartiges Essen serviert. Das Restaurant hat die schönsten alten Steinbögen und die Dekoration passt gut zur Umgebung. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span lang=&quot;de&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;span lang=&quot;de&quot;&gt;Kan Zamaan ist ein herausragendes Wahrzeichen, das ein neues Licht auf sein kulturelles und historisches Erbe wirft, da es weiterhin lokale Gourmets mit seiner einzigartigen, authentischen, orientalischen und lokalen Küche begeistert, die mit vergessenen Aromen garniert ist. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;span lang=&quot;de&quot;&gt;Sie servieren eine große Auswahl an feinem orientalischem kaltem und heißem Mezze, gegrilltem Fleisch, frischem Fladenbrot, das täglich im arabischen Ziegelofen zubereitet und gebacken wird, frischen Meeresfrüchten und lokal inspirierten Gerichten. Sie bieten auch köstliches hausgemachtes knafeh an. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;<br>&lt;/span&gt;&lt;span lang=&quot;de&quot;&gt;Obwohl es etwas außerhalb des Stadtzentrums liegt, ist es auf jeden Fall die Fahrt wert! Sie spielen oft Oud-Live-Musik und organisieren verschiedene Arten von Veranstaltungen.&lt;/span&gt;&lt;/p&gt;\r\n&lt;div class=&quot;tw-ta-container tw-nfl&quot; id=&quot;z6maec&quot;&gt;\r\n&lt;pre class=&quot;tw-data-placeholder tw-text-small tw-ta&quot; data-placeholder=&quot;&quot; id=&quot;tw-target-rmn&quot; style=&quot;text-align: left;&quot; dir=&quot;ltr&quot;&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/Kan Zaman restaurants amman.jpg&quot; width=&quot;442&quot; height=&quot;294&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d108388.24555803406!2d35.8260677583293!3d31.90299239899252!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151ca7f5ef5df9a1:0x47a0e8f9731d5096!2sKan Zaman!5e0!3m2!1sen!2sjo!4v1576335113536!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1560, 'ge', '', 'one col', 'kan-zamaan'),
(1846, 'Shams El Balad', 'Shams El Balad', '', '', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;span lang=&quot;de&quot;&gt;Shams El Balad ist ein geschäftiges Restaurant in der Gegend von Jabal Amman, „inspiriert von der Stadt, in der es lebt, und den Menschen, aus denen es besteht“.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;span lang=&quot;de&quot;&gt;Es befindet sich in einem typisch ammanischen Haus mit einer hervorragenden Aussicht auf die Zitadelle und den Ummayad-Palast.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;span lang=&quot;de&quot;&gt;Sie servieren gesunde, köstliche lokale Gerichte, die vom Handwerk, den Produkten und der Kultur der Region inspiriert sind. Ihre Zutaten sind zu 100% aus biologischem Anbau und stammen direkt von den Bauernhöfen.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;span lang=&quot;de&quot;&gt;Shams El Balad ist eine Feier des jordanischen Erbes, des Landes und der Menschen, die unermüdlich daran arbeiten, sie zu schützen, damit wir alle Freude daran haben.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;<br>&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Restaurants/shams el balad.jpg&quot; width=&quot;438&quot; height=&quot;251&quot; /&gt;&lt;/div&gt;\r\n&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3385.370890586393!2d35.92490201447644!3d31.950833381229334!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151b5f9b233d8d97:0x9926edf16bfbf80b!2sShams AlBalad!5e0!3m2!1sen!2sjo!4v1576315988858!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/div&gt;', 1, 1559, 'ge', '', 'one col', 'shams-el-balad'),
