(1921, 'Restaurantes en Aqaba', 'Restaurantes en Aqaba', '', 'Restaurantes, Aqaba', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/Captains Tourist Restaurant Aqaba.jpg&quot; alt=&quot;Captains Tourist Restaurant &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Captain&#039;s Tourist Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Un clásico situado en el corazón de Aqaba, sirven platos de alta calidad cocinados con ingredientes frescos.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/captains-tourist&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/ali baba restaurant Restaurant Aqaba.jpg&quot; alt=&quot;Ali Baba Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Ali Baba Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Comida tradicional jordana, mezze, mariscos, parrillada mixta. También ofrecen platos vegetarianos.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/ali-baba&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/The royal yacht club Restaurant Aqaba.jpg&quot; alt=&quot;The Royal Yacht Club of Jordan&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;<br>\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;The Royal Yacht Club of Jordan&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Con su lujosa terraza, este es probablemente el mejor lugar de la ciudad para ver las puestas de sol.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/the-royal-yacht-club-restaurant&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/gelato uno aqaba Restaurant Aqaba.jpg&quot; alt=&quot;Gelato Uno&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Gelato Uno&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;¡Nunca hay un mal momento para un delicioso y refrescante helado después de un largo día caluroso!&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/gelato-uno/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1834, 'es', '', 'one col', 'restaurantes-en-aqaba'),
(1922, 'Restaurants a Petra', 'Restaurants a Petra', '', 'Restaurants, Petra', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/my moms recipe restaurant pvt.jpeg&quot; alt=&quot;My mom’s Reciepe  Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;My Mom&#039;s Recipe Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;&lt;span style=&quot;font-size: 14px; text-align: left; color: #111111; text-decoration-line: inherit;&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-size: 14px; text-align: left; color: #111111; text-decoration-line: inherit;&quot;&gt;&lt;span&gt;Cuisine jordanienne, leurs plats les<br> plus célèbres sont leur Mansaf et leur houmous. Musique traditionnelle.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/my-moms-recipe-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Petra Kitchen.jpeg&quot; alt=&quot;Petra Kitchen&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Petra Kitchen&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: left;&quot;&gt;Vous cuisinez votre propre nourriture et avez le plaisir de savourer d’excellents plats à la fin.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/petra-kitchen&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Al qantarah restaurant pvt.jpg&quot; alt=&quot;Al Qantarah Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;<br>\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Al Qantarah Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Produits frais, bios et locaux, ils font cuire leur pain et grillent leur viande dans le &quot;Taboun&quot;.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/restaurant-al-qantarah/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Sanabel bakery.jpg&quot; alt=&quot;Sanabel sweets and bakeries &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Boulangerie Patisserie Sanabel&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;C&#039;est le meilleur magasin de Petra pour vos délices, le personnel est extrêmement gentil. P&lt;span&gt;rix abordable.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/boulangerie-patisserie-sanabel/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Sandstone restaurant petra pvt.jpg&quot; alt=&quot;Sandstone Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Sandstone Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Situé près du centre des visiteurs, le restaurant  propose un mélange de grillades juteuses et salades.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/restaurant-sandstone/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/red cave restaurant petra pvt.jpg&quot; alt=&quot;Red cave restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Red Cave Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Large gamme de plats: mezze, des soupes, des grillades et aussi des spécialités bédouines (Gallayah).&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/restaurant-red-cave/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/The basin restaurant petra pvt.jpg&quot; alt=&quot;The Basin Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;The Basin Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Le seul restaurant situé au cœur de la zone archéologique de Petra. Plats internationaux et locaux.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/le-restaurant-basin/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/al wadi restaurant petra pvt.jpg&quot; alt=&quot;Al wadi restaurant &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Al Wadi Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Grandes portions de délicieux plats locaux (Mansaf et Maklouba), grillades, soupes, mezze, pizza...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/restaurant-al-wadi/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1825, 'fr', '', 'one col', 'restaurants-a-petra'),
(1923, 'Ristoranti a Petra', 'Ristoranti a Petra', '', 'Ristoranti, Petra', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/my moms recipe restaurant pvt.jpeg&quot; alt=&quot;My mom’s Reciepe  Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;My Mom&#039;s Recipe Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;&lt;span style=&quot;font-size: 14px; text-align: left; color: #111111; text-decoration-line: inherit;&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size: 14px; text-align: left; color: #111111; text-decoration-line: inherit;&quot;&gt;&lt;span&gt;Cibo tradizionale, le loro specialita<br>sono il Mansaf e l’hummus. Il pranzo<br>é un buffet e la cena é a la carte.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/my-moms-recipe-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Petra Kitchen.jpeg&quot; alt=&quot;Petra Kitchen&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Petra Kitchen&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: left;&quot;&gt;Cucini i tuoi propri piatti con uno chef locale e poi hai l’occasione di degustarli. C&lt;span&gt;ultura e storia locale.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/petra-kitchen/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Al qantarah restaurant pvt.jpg&quot; alt=&quot;Al Qantarah Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;<br>\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Al Qantarah Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Ingredienti sono organici, locali <br>e freschi. Preparano il loro pane<br>e fanno le grigliate in il “Taboun”.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/al-qantarah-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Sanabel bakery.jpg&quot; alt=&quot;Sanabel sweets and bakeries &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Boulangerie Patisserie Sanabel&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;&lt;span&gt;Chiaramente il miglior posto a Petra che offre dolci. Non perdetevi un esperienza tipicamente Giordana.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/sanabel-sweets-and-bakeries/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Sandstone restaurant petra pvt.jpg&quot; alt=&quot;Sandstone Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Sandstone Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Localizzato accanto al centro turistico, ed offre una varieta di grigliate, insalate e mezze.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/sandstone-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/red cave restaurant petra pvt.jpg&quot; alt=&quot;Red cave restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Red Cave Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Grande varietà di piatti: mezze, zuppe, grigliate and specialita beduine come il Gallayah.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/red-cave-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/The basin restaurant petra pvt.jpg&quot; alt=&quot;The Basin Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;The Basin Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Unico ristorante situato nel cuore dell’area archeologica di Petra. Pietanze internazionali e locali.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/the-basin-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/al wadi restaurant petra pvt.jpg&quot; alt=&quot;Al wadi restaurant &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Al Wadi Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Piatti locali di porzioni generose, come il Mansaf e il Maqlouba, grigliate, zuppe, pizza e pasta.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/al-wadi-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1825, 'it', '', 'one col', 'ristoranti-a-petra'),
(1924, 'Restaurantes en Petra', 'Restaurantes en Petra', '', 'Restaurantes, Petra', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/my moms recipe restaurant pvt.jpeg&quot; alt=&quot;My mom’s Reciepe  Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;My Mom&#039;s Recipe Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;&lt;span style=&quot;font-size: 14px; text-align: left; color: #111111; text-decoration-line: inherit;&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-size: 14px; text-align: left; color: #111111; text-decoration-line: inherit;&quot;&gt;&lt;span&gt;Comida tradicional jordana que te hará agua la boca. Sus platos más famosos son su Mansaf y hummus.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/my-moms-recipe-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Petra Kitchen.jpeg&quot; alt=&quot;Petra Kitchen&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Petra Kitchen&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: left;&quot;&gt;&lt;span&gt;Usted cocina su propia comida y tiene el placer de disfrutar las sabrosas comidas al final. &lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/petra-kitchen/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Al qantarah restaurant pvt.jpg&quot; alt=&quot;Al Qantarah Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;<br>\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Al Qantarah Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Alimentos orgánicos, frescos y producidos localmente; asan su pan y carne en el &quot;Taboun&quot;.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/al-qantarah-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Sanabel bakery.jpg&quot; alt=&quot;Sanabel sweets and bakeries &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Sanabel Panadería&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;&lt;span&gt;Claramente la mejor tienda en Petra para dulces delicias y su pan es la guinda del pastel.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/sanabel/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Sandstone restaurant petra pvt.jpg&quot; alt=&quot;Sandstone Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Sandstone Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Ubicado cerca del centro de visitantes, allá ofrecen parrillas jugosas, ensaladas y mezze.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/sandstone-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/red cave restaurant petra pvt.jpg&quot; alt=&quot;Red cave restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Red Cave Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Amplía gama de platos: mezze, sopas, parrillas y especialidades beduinas (Gallayah).&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/red-cave-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/The basin restaurant petra pvt.jpg&quot; alt=&quot;The Basin Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;The Basin Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: left;&quot;&gt;&lt;span&gt;El único en la zona arqueológica de Petra, ofrecen platos locales y internacionales. Mesas al aire libre.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/the-basin-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/al wadi restaurant petra pvt.jpg&quot; alt=&quot;Al wadi restaurant &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Al Wadi Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Sirven grandes porciones de comida local como Mansaf y Maklouba, parrillas, sopas y mezze.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/al-wadi-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1825, 'es', '', 'one col', 'restaurantes-en-petra'),
(1925, 'Restaurants à Amman', 'Restaurants à Amman', '', 'Restaurants, Amman', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/shams el balad.jpg&quot; alt=&quot;Shams EL balad Restaurants Amman&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt; Shams El Balad&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;pre class=&quot;tw-data-text tw-text-large tw-ta&quot; data-placeholder=&quot;Translation&quot; id=&quot;tw-target-text&quot; dir=&quot;ltr&quot;&gt;&lt;span lang=&quot;fr&quot;&gt;Profitez de leur vue imprenable sur la citadelle et de leurs plats à base d&#039;ingrédients 100% bio.&lt;/span&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/shams-el-balad/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/hashem.jpg&quot; alt=&quot;Hashem Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Hashem Downtown&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;pre class=&quot;tw-data-text tw-text-large tw-ta&quot; data-placeholder=&quot;Translation&quot; id=&quot;tw-target-text&quot; dir=&quot;ltr&quot;&gt;&lt;span lang=&quot;fr&quot;&gt;Hashem Downtown est le plus ancien restaurant de la ville, il existe depuis 1956. Incontournable!&lt;/span&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/hashem-downtown/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/Kan Zaman restaurants amman.jpg&quot; alt=&quot;Kan Zaman Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;<br>\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Kan Zamaan Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;&lt;span&gt;Un lieu patrimonial attrayant qui sert une excellente cuisine. Cuisine unique, authentique et locale.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/kan-zamaan/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/fakhreldin restaurant.jpg&quot; alt=&quot;Fakhreldin Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Fakhreldin Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Salué par la critique comme l&#039;un des meilleurs restaurants d&#039;Amman. Viande, poulet et fruits de mer.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/fakhreldin-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/habibah sweets in Amman.jpg&quot; alt=&quot;Habibah Sweets&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt; Habibah Sweets&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;pre class=&quot;tw-data-text tw-text-large tw-ta&quot; data-placeholder=&quot;Translation&quot; id=&quot;tw-target-text&quot; dir=&quot;ltr&quot;&gt;&lt;span lang=&quot;fr&quot;&gt;Boutique familiale, ils vendent des chocolats et des pâtisseries traditionnelles. Célèbres kanafeh.&lt;/span&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/habibah-sweets/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/fatatri restaurant amman.jpg&quot; alt=&quot;Fatatri &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Fatatri&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;&lt;span&gt;Alliant culture égyptienne et jordanienne, ce restaurant est spécialisé dans la &quot;feteer&quot;. &lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/fatatri/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/primal bistro and cafe restaurants Amman.jpg&quot; alt=&quot;primal Restaurant AMman&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Primal Restaurant Amman&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;&lt;span&gt;Le premier et le seul restaurant paléo d&#039;Amman. Sans gluten, sans sucre raffiné et sans lactose.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/primal-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/al quds.jpg&quot; alt=&quot;Al-quds falafel&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Al-Quds Falafel&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;pre class=&quot;tw-data-text tw-text-large tw-ta&quot; data-placeholder=&quot;Translation&quot; id=&quot;tw-target-text&quot; dir=&quot;ltr&quot;&gt;&lt;span lang=&quot;fr&quot;&gt;Sur la célèbre rue Rainbow, le restaurant Al-Quds est connu pour servir le meilleur falafel d&#039;Amman.&lt;/span&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/al-quds-falafel/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1558, 'fr', '', 'one col', 'restaurants-a-amman'),
(1926, 'Ristorante a Amman', 'Ristorante a Amman', '', 'Ristorante, Amman', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/shams el balad.jpg&quot; alt=&quot;Shams EL balad Restaurants Amman&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt; Shams El Balad&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;pre class=&quot;tw-data-text tw-text-large tw-ta&quot; data-placeholder=&quot;Translation&quot; id=&quot;tw-target-text&quot; dir=&quot;ltr&quot;&gt;&lt;span lang=&quot;it&quot;&gt;Goditi la splendida vista sulla cittadella e i suoi piatti realizzati con &lt;span&gt;ingredienti 100% organici.&lt;/span&gt;&lt;/span&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/shams-el-balad/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/hashem.jpg&quot; alt=&quot;Hashem Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Hashem Downtown&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;&lt;span&gt;Il ristorante più antico della città,  attivo dal 1956. É aperto 24/24h e offre piatti tradizionali.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/hashem-downtown/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/Kan Zaman restaurants amman.jpg&quot; alt=&quot;Kan Zaman Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;<br>\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Kan Zamaan Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;pre class=&quot;tw-data-text tw-text-large tw-ta&quot; data-placeholder=&quot;Translation&quot; id=&quot;tw-target-text&quot; dir=&quot;ltr&quot;&gt;&lt;span lang=&quot;it&quot;&gt;Un luogo di eredità attraente che serve ottimo cibo. Cucina unica, autentica, orientale e locale.&lt;/span&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/kan-zamaan/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/fakhreldin restaurant.jpg&quot; alt=&quot;Fakhreldin Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Fakhreldin Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;&lt;span&gt;Ha guadagnato il plauso della critica come uno dei migliori ristoranti di Amman. Carne, pollo e frutti di mare.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/fakhreldin-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/habibah sweets in Amman.jpg&quot; alt=&quot;Habibah Sweets&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt; Habibah Sweets&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;span&gt;Negozio di famiglia, o&lt;/span&gt;ffrono dolci tradizionali e sono particolarmente famosi per il loro Knafeh.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/habibah-sweets/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/fatatri restaurant amman.jpg&quot; alt=&quot;Fatatri &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Fatatri&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;&lt;span&gt;Combinando la cultura egiziana e giordana questo ristorante è specializzato in &quot;feteer&quot;.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/fatatri/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/primal bistro and cafe restaurants Amman.jpg&quot; alt=&quot;primal Restaurant AMman&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Primal Restaurant Amman&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;&lt;span&gt;Il primo ed unico ristorante paleo di Amman. Cucina senza glutine e lattosio, vegana e &lt;a id=&quot;fprsl&quot; class=&quot;gL9Hy&quot; href=&quot;https://www.google.com/search?rlz=1C1CHBD_en-GBJO840JO840&amp;amp;sxsrf=ACYBGNQryPNPN8N6ygv_BChunONjhVd7cw:1582035879854&amp;amp;q=cucina+vegetariana&amp;amp;spell=1&amp;amp;sa=X&amp;amp;ved=2ahUKEwjVz4_1ptvnAhWvxYUKHZAKB20QkeECKAB6BAgRECU&quot; data-ved=&quot;2ahUKEwjVz4_1ptvnAhWvxYUKHZAKB20QkeECKAB6BAgRECU&quot;&gt;vegetariana&lt;/a&gt;. &lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/primal-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/al quds.jpg&quot; alt=&quot;Al-quds falafel&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Al-Quds Falafel&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span&gt;Sulla famosa Rainbow Street, il ristorante Al-Quds è noto per servire il miglior falafel di Amman.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/al-quds-falafel/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1558, 'it', '', 'one col', 'ristorante-a-amman'),
(1927, 'Al-Quds Falafel', 'Al-Quds Falafel', 'Sulla famosa Rainbow Street, il ristorante Al-Quds è noto per servire il miglior falafel di Amman.', 'Falafel, Rainbow Street, Al-Quds', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;<br>Situato sulla vivace e vibrante Rainbow Street, il ristorante Al-Quds è noto per servire il miglior falafel di Amman. Molti abitanti del posto e turisti entrano per avere un delizioso sandwich di falafel dopo una passeggiata lungo Rainbow street.&lt;/p&gt;\r\n&lt;p&gt;Grazie alle sue dimensioni ridotte non ha molte opzioni di seduta oltre a una piccola panchina fuori dal negozio, tuttavia è possibile acquistare il cibo da asporto o addirittura ordinarlo online.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/e28c2eb2e503cacfa05fa26ffe47dd5c-al-quds.jpg&quot; width=&quot;426&quot; height=&quot;340&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d13541.683034851729!2d35.9265022!3d31.9494801!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0:0x376a889bafb7348c!2sAl Quds Falafel!5e0!3m2!1sen!2sjo!4v1576341855898!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1565, 'it', '', 'one col', 'al-quds-falafel');
INSERT INTO `en33_pages` (`id`, `name`, `title`, `meta_desc`, `meta_key`, `contents`, `published`, `lang_id`, `lang`, `icon`, `layout`, `url`) VALUES
(1928, 'Restaurantes en Amman', 'Restaurantes en Amman', '', '', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/shams el balad.jpg&quot; alt=&quot;Shams EL balad Restaurants Amman&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt; Shams El Balad&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;span&gt;Disfruta de su increíble vista de la ciudadela y sus platos hechos con ingredientes 100% orgánicos.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/shams-el-balad/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/hashem.jpg&quot; alt=&quot;Hashem Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Hashem Downtown&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Hashem Downtown is the oldest restaurant in town, it has been running since 1956. ¡Imperdible!&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/hashem-downtown/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/Kan Zaman restaurants amman.jpg&quot; alt=&quot;Kan Zaman Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;<br>\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Kan Zamaan Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;&lt;span&gt;Un lugar patrimonial atractivo que sirve buena comida. Cocina única, auténtica, oriental y local.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/kan-zamaan/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/fakhreldin restaurant.jpg&quot; alt=&quot;Fakhreldin Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Fakhreldin Restaurant&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;pre class=&quot;tw-data-text tw-text-large tw-ta&quot; data-placeholder=&quot;Translation&quot; id=&quot;tw-target-text&quot; dir=&quot;ltr&quot;&gt;&lt;span lang=&quot;es&quot;&gt;Se ha ganado la aclamación de la crítica como uno de los mejores restaurantes de Ammán. &lt;/span&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/fakhreldin-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/habibah sweets in Amman.jpg&quot; alt=&quot;Habibah Sweets&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt; Habibah Sweets&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;<br>Tienda familiar, venden chocolates y pasteles tradicionales. Son famosos por su knafeh.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/habibah-sweets/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/fatatri restaurant amman.jpg&quot; alt=&quot;Fatatri &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Fatatri&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Este restaurante, que combina la cultura egipcia y jordana, se especializa en el delicioso &quot;feteer&quot;.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/fatatri/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/primal bistro and cafe restaurants Amman.jpg&quot; alt=&quot;primal Restaurant AMman&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Primal Restaurant Amman&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;El primer y único restaurante paleo en Amman. Totalmente sin gluten, sin azúcar refinada y sin lactosa.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/primal-restaurant/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/al quds.jpg&quot; alt=&quot;Al-quds falafel&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Al-Quds Falafel&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;Ubicado en la famosa calle Rainbow, es conocido por servir el mejor falafel de Ammán.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/al-quds-falafel/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1558, 'es', '', 'one col', 'restaurantes-en-amman'),
(1929, 'Restaurants in Jordan', 'Restaurants in Jordan', 'Restaurants in Jordan: Amman, Petra and Aqaba', 'Restaurants in Amman, Petra, Aqaba', '\n&lt;div class=&quot;row&quot;&gt;\n    &lt;!-- Amman --&gt;\n    &lt;div class=&quot;md-3 bd-3 d-pad&quot;&gt;\n        &lt;div class=&quot;white shadow-box&quot;&gt;\n            &lt;img src=&quot;uploads/filemanager/Photos/Amman/amman_jabal_amman_view.jpg&quot; alt=&quot;Jabal Amman&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; style=&quot;object-fit: cover;&quot; /&gt;\n            &lt;div class=&quot;orange-text&quot; style=&quot;text-align: center; margin-top: 10px;&quot;&gt;&lt;strong&gt;Restaurants in Amman&lt;/strong&gt;&lt;/div&gt;\n            &lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\n                &lt;p style=&quot;text-align: justify;&quot;&gt;From paleo cuisine to the most traditional Arab cuisine, there are plenty of options in the capital!&lt;/p&gt;\n            &lt;/div&gt;\n            &lt;div class=&quot;align-center pad&quot;&gt;\n                &lt;a href=&quot;en/restaurants-amman/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;\n            &lt;/div&gt;\n        &lt;/div&gt;\n    &lt;/div&gt;\n    \n    &lt;!-- Aqaba --&gt;\n    &lt;div class=&quot;md-3 bd-3 d-pad&quot;&gt;\n        &lt;div class=&quot;white shadow-box&quot;&gt;\n            &lt;img src=&quot;uploads/filemanager/yuliya-kosolapova-Aqaba Facebook.jpg&quot; alt=&quot;Sunset in Aqaba&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; style=&quot;object-fit: cover;&quot; /&gt;\n            &lt;div class=&quot;orange-text&quot; style=&quot;text-align: center; margin-top: 10px;&quot;&gt;&lt;strong&gt;Restaurants in Aqaba&lt;/strong&gt;&lt;/div&gt;\n            &lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\n                &lt;p style=&quot;text-align: justify;&quot;&gt;Enjoy the seafood offered in the charming portal city or just watch the amazing sunset Aqaba offers!&lt;/p&gt;\n            &lt;/div&gt;\n            &lt;div class=&quot;align-center pad&quot;&gt;\n                &lt;a href=&quot;en/restaurants-in-aqaba/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;\n            &lt;/div&gt;\n        &lt;/div&gt;\n    &lt;/div&gt;\n\n    &lt;!-- Petra --&gt;\n    &lt;div class=&quot;md-3 bd-3 d-pad&quot;&gt;\n        &lt;div class=&quot;white shadow-box&quot;&gt;\n            &lt;img src=&quot;uploads/filemanager/Photos/Petra/Khaznah.jpg&quot; alt=&quot;Treasury in Petra&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; style=&quot;object-fit: cover;&quot; /&gt;\n            &lt;div class=&quot;orange-text&quot; style=&quot;text-align: center; margin-top: 10px;&quot;&gt;&lt;strong&gt;Restaurants in Petra&lt;/strong&gt;&lt;/div&gt;\n            &lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\n                &lt;p style=&quot;text-align: justify;&quot;&gt;There is a lot to explore in the rose city: cooking classes, organic food, classic mansaf and maqlouba...&lt;/p&gt;\n            &lt;/div&gt;\n            &lt;div class=&quot;align-center pad&quot;&gt;\n                &lt;a href=&quot;en/restaurants-in-petra/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;\n            &lt;/div&gt;\n        &lt;/div&gt;\n    &lt;/div&gt;\n\n    &lt;!-- Madaba --&gt;\n    &lt;div class=&quot;md-3 bd-3 d-pad&quot;&gt;\n        &lt;div class=&quot;white shadow-box&quot;&gt;\n            &lt;img src=&quot;uploads/filemanager/Photos/Madaba/general-view-of-the-Madaba.jpg&quot; alt=&quot;Madaba&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; style=&quot;object-fit: cover;&quot; /&gt;\n            &lt;div class=&quot;orange-text&quot; style=&quot;text-align: center; margin-top: 10px;&quot;&gt;&lt;strong&gt;Restaurants in Madaba&lt;/strong&gt;&lt;/div&gt;\n            &lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\n                &lt;p style=&quot;text-align: justify;&quot;&gt;Discover delicious local cuisine in the city of mosaics, blending rich history with flavorful dining.&lt;/p&gt;\n            &lt;/div&gt;\n            &lt;div class=&quot;align-center pad&quot;&gt;\n                &lt;a href=&quot;en/restaurants-in-madaba/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;\n            &lt;/div&gt;\n        &lt;/div&gt;\n    &lt;/div&gt;\n\n    &lt;!-- Jerash --&gt;\n    &lt;div class=&quot;md-3 bd-3 d-pad&quot;&gt;\n        &lt;div class=&quot;white shadow-box&quot;&gt;\n            &lt;img src=&quot;uploads/filemanager/Photos/Jerash/ruins-of-jerash.jpg&quot; alt=&quot;Jerash&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; style=&quot;object-fit: cover;&quot; /&gt;\n            &lt;div class=&quot;orange-text&quot; style=&quot;text-align: center; margin-top: 10px;&quot;&gt;&lt;strong&gt;Restaurants in Jerash&lt;/strong&gt;&lt;/div&gt;\n            &lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\n                &lt;p style=&quot;text-align: justify;&quot;&gt;Enjoy a delightful meal with views of the ancient Roman ruins in Jerash.&lt;/p&gt;\n            &lt;/div&gt;\n            &lt;div class=&quot;align-center pad&quot;&gt;\n                &lt;a href=&quot;en/restaurants-in-jerash/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;\n            &lt;/div&gt;\n        &lt;/div&gt;\n    &lt;/div&gt;\n\n    &lt;!-- Ajlun --&gt;\n    &lt;div class=&quot;md-3 bd-3 d-pad&quot;&gt;\n        &lt;div class=&quot;white shadow-box&quot;&gt;\n            &lt;img src=&quot;uploads/filemanager/Photos/Ajlun/Ajlun-Castle-from-outside1.jpg&quot; alt=&quot;Ajlun&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; style=&quot;object-fit: cover;&quot; /&gt;\n            &lt;div class=&quot;orange-text&quot; style=&quot;text-align: center; margin-top: 10px;&quot;&gt;&lt;strong&gt;Restaurants in Ajlun&lt;/strong&gt;&lt;/div&gt;\n            &lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\n                &lt;p style=&quot;text-align: justify;&quot;&gt;Experience authentic dining in the lush green hills surrounding Ajlun Castle.&lt;/p&gt;\n            &lt;/div&gt;\n            &lt;div class=&quot;align-center pad&quot;&gt;\n                &lt;a href=&quot;en/restaurants-in-ajlun/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;\n            &lt;/div&gt;\n        &lt;/div&gt;\n    &lt;/div&gt;\n\n    &lt;!-- Kerak --&gt;\n    &lt;div class=&quot;md-3 bd-3 d-pad&quot;&gt;\n        &lt;div class=&quot;white shadow-box&quot;&gt;\n            &lt;img src=&quot;uploads/filemanager/Photos/Hotels in Kerak/il-kerak-resthouse-visto.jpg&quot; alt=&quot;Kerak&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; style=&quot;object-fit: cover;&quot; /&gt;\n            &lt;div class=&quot;orange-text&quot; style=&quot;text-align: center; margin-top: 10px;&quot;&gt;&lt;strong&gt;Restaurants in Kerak&lt;/strong&gt;&lt;/div&gt;\n            &lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\n                &lt;p style=&quot;text-align: justify;&quot;&gt;Savor the traditional flavors of Jordan in the historic crusader city of Kerak.&lt;/p&gt;\n            &lt;/div&gt;\n            &lt;div class=&quot;align-center pad&quot;&gt;\n                &lt;a href=&quot;en/restaurants-in-kerak/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;\n            &lt;/div&gt;\n        &lt;/div&gt;\n    &lt;/div&gt;\n\n    &lt;!-- The rest of Jordan --&gt;\n    &lt;div class=&quot;md-3 bd-3 d-pad&quot;&gt;\n        &lt;div class=&quot;white shadow-box&quot;&gt;\n            &lt;img src=&quot;uploads/filemanager/Photos/testimonials/food.jpg&quot; alt=&quot;The Rest of Jordan&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; style=&quot;object-fit: cover;&quot; /&gt;\n            &lt;div class=&quot;orange-text&quot; style=&quot;text-align: center; margin-top: 10px;&quot;&gt;&lt;strong&gt;The Rest of Jordan&lt;/strong&gt;&lt;/div&gt;\n            &lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\n                &lt;p style=&quot;text-align: justify;&quot;&gt;Explore hidden culinary gems and authentic eateries throughout the rest of the country.&lt;/p&gt;\n            &lt;/div&gt;\n            &lt;div class=&quot;align-center pad&quot;&gt;\n                &lt;a href=&quot;en/restaurants-in-other-cities/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;\n            &lt;/div&gt;\n        &lt;/div&gt;\n    &lt;/div&gt;\n&lt;/div&gt;\n', 1, 1929, 'en', '', 'one col', 'restaurants-in-jordan'),
(1930, 'Restaurants en Jordanie', 'restaurants en Jordanie', '', 'Restaurants en Jordanie, Amman, Aqaba, Petra', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/amman_jabal_amman_view.jpg&quot; alt=&quot;Jabal Amman&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   &lt;strong&gt;    R&lt;span&gt;estaurants à Amman&lt;/span&gt;&lt;/strong&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;pre class=&quot;tw-data-text tw-text-large tw-ta&quot; data-placeholder=&quot;Translation&quot; id=&quot;tw-target-text&quot; dir=&quot;ltr&quot;&gt;&lt;span lang=&quot;fr&quot;&gt;De la cuisine paléo à la cuisine arabe la plus traditionnelle, la capitale regorge d&#039;options!&lt;/span&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/restaurants-a-amman&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/yuliya-kosolapova-Aqaba Facebook.jpg&quot; alt=&quot;Sunset in Aqaba&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;&lt;strong&gt;         Restaurants à Aqaba&lt;/strong&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;pre class=&quot;tw-data-text tw-text-large tw-ta&quot; data-placeholder=&quot;Translation&quot; id=&quot;tw-target-text&quot; dir=&quot;ltr&quot;&gt;&lt;span lang=&quot;fr&quot;&gt;Profitez des fruits de mer offerts dans la charmante ville-portail ou tout admirez le coucher de soleil! &lt;/span&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/restaurants-a-aqaba/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Petra/Khaznah.jpg&quot; alt=&quot;Treasury in Petra&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;<br>\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;Restaurants à Petra&lt;/strong&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;pre class=&quot;tw-data-text tw-text-large tw-ta&quot; data-placeholder=&quot;Translation&quot; id=&quot;tw-target-text&quot; dir=&quot;ltr&quot;&gt;&lt;span lang=&quot;fr&quot;&gt;Il y a beaucoup à explorer dans la ville rose: cours de cuisine, cuisine bio, mansaf et maqlouba classique...&lt;/span&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;fr/restaurants-a-petra/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1929, 'fr', '', 'one col', 'restaurants-en-jordanie'),
(1931, 'Ristoranti in Giordania', 'Ristoranti in Giordania', '', 'Ristoranti in Giordania, Aqaba, Amman, Petra', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/amman_jabal_amman_view.jpg&quot; alt=&quot;Jabal Amman&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   &lt;strong&gt;    Ristoranti a Amman&lt;/strong&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Dalla cucina paleo alla cucina araba più tradizionale, ci sono molte opzioni nella capitale!&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/ristorante-a-amman&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/yuliya-kosolapova-Aqaba Facebook.jpg&quot; alt=&quot;Sunset in Aqaba&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;&lt;strong&gt;        Ristoranti ad Aqaba&lt;/strong&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Goditi i frutti di mare offerti nell&#039;affascinante città portale o semplicemente guarda il tramonto!&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/ristoranti-a-aqaba&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Petra/Khaznah.jpg&quot; alt=&quot;Treasury in Petra&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;<br>\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;Ristoranti a Petra&lt;/strong&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;span&gt;C&#039;è molto da esplorare nella città delle rose: lezioni di cucina, piatti organici, locali e tradizionale.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;it/ristoranti-a-petra&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1929, 'it', '', 'one col', 'ristoranti-in-giordania'),
(1932, 'Restaurantes en Jordania', 'Restaurantes en Jordania', '', 'Restaurantes en Jordania, Amman, Aqaba, Petra', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/amman_jabal_amman_view.jpg&quot; alt=&quot;Jabal Amman&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   &lt;strong&gt;    Restaurantes en Amman&lt;/strong&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;span&gt;Desde la cocina paleo hasta la cocina árabe más tradicional, ¡hay muchas opciones en la capital!&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/restaurantes-en-amman&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/yuliya-kosolapova-Aqaba Facebook.jpg&quot; alt=&quot;Sunset in Aqaba&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;&lt;strong&gt;         Restaurantes en Aqaba&lt;/strong&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;span&gt;¡Disfruta de los mariscos que se ofrecen en la encantadora ciudad portal o mira la puesta de sol!&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/restaurantes-en-aqaba&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Petra/Khaznah.jpg&quot; alt=&quot;Treasury in Petra&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;<br>\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;Restaurantes en Petra&lt;/strong&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;pre class=&quot;tw-data-text tw-text-large tw-ta&quot; data-placeholder=&quot;Translation&quot; id=&quot;tw-target-text&quot; dir=&quot;ltr&quot;&gt;&lt;span lang=&quot;es&quot;&gt;Hay mucho a explorar en la ciudad rosada: clases de cocina, comida orgánica, los platos clásicos...&lt;/span&gt;&lt;/pre&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;es/restaurantes-en-petra/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1929, 'es', '', 'one col', 'restaurantes-en-jordania'),
(1933, 'Come attraversare il confine tra Giordania e Israele /Palestina', 'Come attraversare il confine tra Giordania e Israele/Palestina', 'Come attraversare il confine tra Giordania - Israele e Territori palestinesi, tutto quello che devi sapere sugli attraversamenti di Allenby, Jordan River e Wadi Araba.', 'il confine, Giordania, Israel,  Palestina, trasporti, visti', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;***Please note that, as of March 12th, all three border crossings described here are closed for departing and arriving passengers. This is a government measure to avoid the propagation of the coronavirus disease (COVID-19) in Jordan.***&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Come dettagliato &lt;a href=&quot;it/visti-per-la-giordania/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;qui,&lt;/a&gt; i visti per la Giordania possono essere ottenuti presso l&#039;aeroporto internazionale Queen Alia (a meno che per nazionalità limitata). Tuttavia, ci sono tre valichi di frontiera disponibili per i viaggiatori tra Giordania, Israele e Territori palestinesi occupati (oPT). Ogni punto ha un nome diverso da entrambe le parti giordana e israeliana / palestinese.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;it/sheikh-hussein-jordan-river-crossing/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;1 – Sheikh Hussein/Jordan River Crossing&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;it/ponte-allenby-king-hussein/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;2 – Ponte Allenby/King Hussein&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;it/wadi-araba-yitzhak-rabin-crossing/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;3 – Wadi Araba/Yitzhak Rabin Crossing&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong style=&quot;font-family: inherit; font-style: inherit; font-variant-ligatures: inherit; font-variant-caps: inherit; text-decoration-line: inherit;&quot;&gt;&lt;a href=&quot;en/wadi-araba-yitzhak-rabin-crossing/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Timbri:&lt;/strong&gt; Durante l&#039;attraversamento in Giordania da Israele / territori palestinesi, le autorità giordane potrebbero timbrare il passaporto dichiarando che si è entrati nel paese attraverso determinati attraversamenti. Pertanto, ciò significa che sei stato in Israele e nei territori palestinesi, che sono occupati da Israele. Questo timbro potrebbe essere negato in alcuni paesi, come il Libano.&lt;/p&gt;\r\n&lt;p&gt;Pertanto, tienilo a mente quando pianifichi i prossimi viaggi nella regione. Puoi anche chiedere alle autorità giordane di timbrare un foglietto, se hai intenzione di andare in altri paesi che non hanno relazioni amichevoli con Israele. Lo stesso vale quando si viaggia in Libano e successivamente si entra in Israele: è possibile che si debbano affrontare interrogativi da parte delle autorità israeliane sul perché si sia visitato in Libano.&lt;/p&gt;\r\n&lt;p&gt;Si prega di notare che le festività pubbliche possono influire sugli orari di apertura e sulle operazioni ai valichi di frontiera su entrambi i lati. Pianifica in anticipo e controlla se date importanti come il Ramadan, il capodanno musulmano o lo Yom Kippur avranno un impatto sulle tue vacanze.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;a href=&quot;https://www.google.com/maps/d/edit?mid=1kOGjGGMh0vMyqKsVN5xAORX5ua7xJQZh&amp;amp;ll=31.030942274246865,35.28009029999998&amp;amp;z=8&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Border Crossings/Border Crossings.jpg&quot; /&gt;&lt;/a&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; &lt;span style=&quot;font-size: 14px; text-decoration-line: inherit;&quot;&gt; &lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1875, 'it', '', 'one col', 'come-attraversare-il-confine-tra-giordania-e-israele-palestina'),
(1934, 'Ponte Allenby / King Hussein', 'Ponte Allenby / King Hussein', 'La traversata più famosa e il punto principale per i palestinesi di circolare nella regione.', 'Ponte Allenby, Ponte King Hussein, Visti, Giordania, Orario operativo', '&lt;p&gt;La traversata più famosa e il punto principale per i palestinesi di circolare nella regione. È anche il valico di frontiera più vicino per i turisti che vengono in Giordania da Gerusalemme.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Ubicazione:&lt;/strong&gt; situato nella valle meridionale della Giordania, dista 57 km da Amman, 220 km da Petra e 320 km da Wadi Rum. Da parte palestinese, è vicino a Gerico.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Visti:&lt;/strong&gt; le autorità giordane non rilasciano visti a questo valico di frontiera. Dal gennaio 2020, anche i possessori del Jordan Pass devono ottenere in anticipo un visto per entrare in Giordania attraverso il ponte King Hussein. In quella zona, l&#039;autorità giordana più vicina che può rilasciare visti è l&#039;ufficio rappresentativo giordano a Ramallah: Ein Mujid. Edificio Abraj, 7 ° piano. Numeri di telefono: (+970) 2-297 4625/6 o (+970) 2-297 4624&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;strong&gt;Importante:&lt;/strong&gt; i visti rilasciati all&#039;aeroporto Queen Alia sono a ingresso unico. Tuttavia, se lasci la Giordania, entri in Palestina / Israele e desideri tornare in Giordania, puoi utilizzare lo stesso visto rilasciato all&#039;aeroporto, purché sia ancora valido. Tale regola si applica solo se si entra / esce dalla Palestina / Israele attraverso il ponte King Hussein.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;strong&gt;Commissioni di uscita:&lt;/strong&gt; 10 JD (circa US $ 15) per lasciare la Giordania verso Israele; 177 NIS (circa US $ 53) per lasciare Israele verso la Giordania.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Trasporti:&lt;/strong&gt; i taxi sono disponibili su entrambi i lati del confine e organizziamo anche trasferimenti. Tuttavia, se desideri prendere i mezzi pubblici:&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;strong&gt;In Giordania:&lt;/strong&gt; gli autobus Jett sono disponibili da / per il ponte King Hussein da/per la stazione degli autobus di Abdali ad Amman. Orari e prezzi di partenza &lt;a href=&quot;https://www.jett.com.jo/en/schedule&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;sono disponibili qui&lt;/a&gt;. Questo biglietto include il trasporto da Amman al confine e verso l&#039;area tra l&#039;uscita giordana e il confine palestinese / israeliano. Ciò significa che non è necessario pagare il 7JOD per la navetta: mostra il tuo biglietto Jett quando torni sull&#039;autobus per continuare la traversata.&lt;/p&gt;\r\n&lt;p&gt;Dalla traversata ai territori palestinesi e a Gerusalemme: ci sono autobus tra la frontiera e Gerico o Gerusalemme. Da Gerico, ci sono taxi pubblici condivisi (servizi) verso altre città della Cisgiordania.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Orario operativo (lato giordano):&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Domenica - Giovedì: 07:30 - 22:00<br>Venerdì - Sabato: 07:30 - 13:00&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Orario operativo (lato israeliano):&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Domenica - Giovedì: 07: 30-24h<br>Venerdì e sabato: 8h-15h&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Tuttavia, gli ultimi orari per l&#039;arrivo dei passeggeri a fini di transito / attraversamento sono:<br><br>- Turisti: da domenica a giovedì - fino alle 21h<br>- Palestinesi e residenti a Gerusalemme est: da domenica a giovedì - fino alle 22h<br>- Venerdì e sabato, l&#039;ultima ora per l&#039;arrivo dei passeggeri (turisti, palestinesi e residenti a Gerusalemme est) è alle 12h.&lt;/p&gt;', 1, 1876, 'it', '', 'one col', 'ponte-allenby-king-hussein'),
(1935, 'Sheikh Hussein / Jordan River Crossing', 'Sheikh Hussein / Jordan River Crossing', '', 'Sheikh Hussein, Jordan River Crossing, Visti, Ubicazione, orario operativo', '&lt;p&gt;&lt;strong&gt;Ubicazione: &lt;/strong&gt;a 90 km da Amman, si trova nel nord della Giordania. Le città più grandi più vicine sono Irbid e Ajloun. Si trova vicino alla città israeliana di Beit She&#039;an e al Lago di Tiberiade (Mare di Galilea).&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Visti:&lt;/strong&gt; la maggior parte delle nazionalità (ad eccezione di quelle riservate) possono ottenere visti per la Giordania a questo valico di frontiera. Costa 40JOD.&lt;/p&gt;\r\n&lt;p&gt;Commissioni di uscita: 10 JD (circa US$15) per lasciare la Giordania verso Israele; 102 NIS (circa $30) per lasciare Israele verso la Giordania.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Trasporto:&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;In Giordania:&lt;/strong&gt; i trasporti pubblici sono disponibili da / per Irbid e da lì dovresti prendere un taxi per la traversata. A partire da febbraio 2020, non ci sono autobus che vanno a Nazaret, per esempio.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;In Israele:&lt;/strong&gt; gli autobus sono disponibili per diverse destinazioni in Israele. All&#039;interno della traversata, un autobus porta i passeggeri dal terminal israeliano al terminal giordano e il viaggio costa 5 NIS.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Orario operativo (lato giordano):&lt;/strong&gt;<br>Domenica - Venerdì: 8h - 18h<br>Sabato: 8h30 - 18h&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Orario operativo (lato israeliano):&lt;/strong&gt;<br>Domenica-giovedì: 7h - 20h30<br>Venerdì - Sabato: 8h30 - 18h30&lt;/p&gt;', 1, 1877, 'it', '', 'one col', 'sheikh-hussein-jordan-river-crossing'),
(1936, 'Wadi Araba / Yitzhak Rabin Crossing', 'Wadi Araba / Yitzhak Rabin Crossing', 'Come attraversare il confine tra Giordania - Israele e Territori palestinesi, tutto quello che devi sapere sugli attraversamenti di Ponte Wadi Araba.', 'Wadi Araba, Yitzhak Rabin Crossing, Orario operativo, Visti', '&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Wadi Araba / Yitzhak Rabin Crossing&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Ubicazione:&lt;/strong&gt; nel sud della Giordania, a 324 km da Amman e vicino ad Aqaba; dalla parte israeliana, è vicino a Eilat. Le due città sono località del Mar Rosso.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Visti:&lt;/strong&gt; nonostante le informazioni fornite sui canali ufficiali, i visti per la Giordania vengono rilasciati a questo passaggio e sono gratuiti come parte dell&#039;Autorità speciale della zona economica di Aqaba. Un soggiorno minimo di tre notti in Giordania ti esonererà dal pagamento del visto (40JOD) e della tassa di partenza, se lasci la Giordania dallo stesso attraversamento o da un altro punto di Aqaba. In tal caso, le tasse per i visti non verranno riscosse, senza la necessità di esibire un Jordan Pass al tuo arrivo. Tuttavia, se trascorri meno di 3 notti in Giordania e torni in Israele, dovrai pagare il visto e le tasse di uscita. Queste regole si applicano solo all&#039;attraversamento del Wadi Araba.&lt;/p&gt;\r\n&lt;p&gt;Se desideri estendere il visto ottenuto all&#039;incrocio di Wadi Araba, dovrai pagare la tassa 40JOD. L&#039;estensione del visto è prevista anche ad Amman, non solo ad Aqaba.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Commissioni di uscita:&lt;/strong&gt; 10 JD (circa US $ 15) per lasciare la Giordania verso Israele; 102 NIS (circa $ 30) per lasciare Israele verso la Giordania. Un soggiorno minimo di tre notti in Giordania esonera i turisti dal pagamento della tassa di partenza di 10 JOD quando lasciano la Giordania attraverso la traversata del Wadi Araba.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Trasporto:&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;In Giordania:&lt;/strong&gt; è necessario prendere un taxi dall&#039;incrocio fino ad Aqaba. Da lì, sono disponibili autobus per Amman o Petra.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;In Israele:&lt;/strong&gt; non ci sono mezzi pubblici da o verso l&#039;incrocio e i viaggiatori possono usare i taxi da Eilat o le auto private.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Orario operativo (lato giordano):&lt;/strong&gt;<br>Domenica - Giovedì: 6:30 - 20:00<br>Venerdì - Sabato: 8h - 20h&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Orario operativo (lato israeliano):&lt;/strong&gt;<br>Domenica - Giovedì: dalle 6:30 alle 20:00<br>Venerdì - Sabato: 8h - 20h&lt;/p&gt;', 1, 1878, 'it', '', 'one col', 'wadi-araba-yitzhak-rabin-crossing'),
(1937, 'Cómo cruzar los puntos fronterizos entre Jordania/Israel/Territorios Palestinos', 'Cómo cruzar los puntos fronterizos entre Jordania/Israel/Territorios Palestinos?', '', '', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;***Please note that, as of March 12th, all three border crossings described here are closed for departing and arriving passengers. This is a government measure to avoid the propagation of the coronavirus disease (COVID-19) in Jordan.***&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Como se detalla &lt;a href=&quot;es/visas-para-jordania/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;aquí,&lt;/a&gt; los visados pueden conseguirse en el Aeropuerto Internacional Reina Alia de Amán (excepto para algunas nacionalidades restringidas). Sin embargo, hay tres pasos fronterizos disponibles para los viajeros entre Jordania, Israel y los Territorios Palestinos Ocupados (oPT). Cada punto tiene un nombre diferente en ambos los lados jordano e israelí/palestino:&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;es/sheikh-hussein-frontera-rio-jordan/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;1 – Sheikh Hussein/ Frontera Río Jordán&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;es/puente-king-hussein-allenby/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;2 – Puente del Rey Hussein/Allenby&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;es/frontera-wadi-araba-itzjak-rabin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;3 – Wadi Araba/Frontera Yitzhak Rabin&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Sellos&lt;/strong&gt;: al cruzar a Jordania desde Israel/Territorios Palestinos, las autoridades jordanas pueden sellar su pasaporte indicando el paso fronterizo que ha usado para entrar en Jordania. Por lo tanto, eso significa que ha estado en Israel y /o en los territorios palestinos, que están ocupados por Israel. Este sello puede tener su entrada denegada en ciertos países, como el Líbano.&lt;/p&gt;\r\n&lt;p&gt;Por lo tanto, tenga esto en cuenta para planificar sus viajes en la región. También puede solicitar a las autoridades jordanas que sellen un pedazo de papel si planea ir a otros países que no tienen una relación amistosa con Israel. Lo mismo es válido cuando se viaja al Líbano y luego se ingresa a Israel: es posible que las autoridades israelíes le pregunten por qué ha visitado Líbano.&lt;/p&gt;\r\n&lt;p&gt;Tenga en cuenta que las fiestas públicas pueden afectar los horarios de apertura y las operaciones en los pasos fronterizos en ambos lados. Planifique con anticipación y verifique si las fechas importantes como el Ramadán, el Año Nuevo musulmán, o Yom Kippur afectarán sus vacaciones.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;a href=&quot;https://www.google.com/maps/d/edit?mid=1kOGjGGMh0vMyqKsVN5xAORX5ua7xJQZh&amp;amp;ll=31.030942274246865,35.28009029999998&amp;amp;z=8&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Border Crossings/Border Crossings.jpg&quot; /&gt;&lt;/a&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; &lt;span style=&quot;font-size: 14px; text-decoration-line: inherit;&quot;&gt; &lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1875, 'es', '', 'one col', 'como-cruzar-los-puntos-fronterizos-entre-jordania-israel-palestina'),
(1938, 'Sheikh Hussein/ Frontera Río Jordán', 'Sheikh Hussein/ Frontera Río Jordán', 'Todo lo que necesita saber sobre cómo cruzar el paso fronterizo Sheikh Hussein/ Frontera Río Jordán: horarios, tasas, transporte y visados.', 'Sheikh Hussein, Frontera Río Jordán, visados, horarios', '&lt;p&gt;&lt;strong&gt;Ubicación:&lt;/strong&gt; a 90 km de Amán, se encuentra en el norte de Jordania. Las ciudades más grandes más cercanas son Irbid y Ajloun. Está cerca de la ciudad israelí de Beit She&#039;an y del lago Tiberíades (Mar de Galilea).&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Visados:&lt;/strong&gt; la mayoría de las nacionalidades (excepto las restringidas) pueden obtener visados para Jordania en este paso fronterizo. Cuesta 40JOD.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Tasas de salida:&lt;/strong&gt; 10 JOD (alrededor de US$ 15) para salir de Jordania hacia Israel; 102 NIS (alrededor de US$ 30) para salir de Israel a Jordania.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Transporte:&lt;/strong&gt; <br>&lt;em&gt;En Jordania:&lt;/em&gt; los transportes públicos están disponibles hacia/desde Irbid, y desde allí debe tomar un taxi hasta el paso. No hay autobuses que vayan a Nazaret, por ejemplo.<br><br>En Israel: los autobuses están disponibles para varios destinos en Israel. Dentro del paso, un autobús lleva a los pasajeros desde la terminal israelí a la terminal jordana y el viaje cuesta 5 NIS.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Horario de funcionamiento (lado jordano):&lt;/strong&gt;<br>Domingo - viernes: 8h - 18h<br>Sábado: 8h30 - 18h&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;Horario de funcionamiento (lado israelí):&lt;/strong&gt;<br>Domingo - jueves: 7h - 20h30<br>Viernes - sábado: 8h30 - 18h30&lt;/p&gt;', 1, 1877, 'es', '', 'one col', 'sheikh-hussein-frontera-rio-jordan'),
(1939, 'Comment traverser la frontière entre la Jordanie et Israël/Palestine', 'Comment traverser la frontière entre la Jordanie et Israël/Palestine', 'Comment traverser la frontière entre la Jordanie - Israël et les territoires palestiniens, tout ce que vous devez savoir sur les traversées d&#039;Allenby, du Jourdain et du Wadi Araba.', 'Pont King Hussein, Pont Allenby, Wadi Araba, Pont Sheikh Hussein, Israël, Territoires palestiniens, frontière', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;***Please note that, as of March 12th, all three border crossings described here are closed for departing and arriving passengers. This is a government measure to avoid the propagation of the coronavirus disease (COVID-19) in Jordan.***&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;a href=&quot;fr/visas-en-jordanie/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Comme détaillé ici,&lt;/a&gt; les visas pour la Jordanie peuvent être obtenus à l&#039;aéroport international Queen Alia (sauf pour les nationalités restreintes). Cependant, trois postes frontaliers sont disponibles pour les voyageurs entre la Jordanie, Israël et les territoires palestiniens occupés (oPT). Chaque frontière a un nom différent à la fois du côté jordanien et israélien / palestinien.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;fr/traversee-sheikh-hussein-jourdain/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;1 – Traversée Sheikh Hussein / Jourdain&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;fr/pont-king-hussein-allenby/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;2 – Pont King Hussein /Allenby&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;fr/traversée-wadi-araba-yitzhak-rabin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;3 – Traversée Wadi Araba / Yitzhak Rabin&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Timbres:&lt;/strong&gt; Lors du passage en Jordanie depuis les territoires israéliens / aba, Pont Sheikh Hussein, Jordanie, Israel, palestiniens, les autorités jordaniennes peuvent tamponner votre passeport indiquant que vous êtes entré dans le pays via un certain passage. Par conséquent, cela signifie que vous êtes allé en Israël et dans les territoires palestiniens, qui sont occupés par Israël. Ce tampon peut vous valoir un refus de visa dans certains pays, comme le Liban.&lt;/p&gt;\r\n&lt;p&gt;Par conséquent, gardez cela à l&#039;esprit lorsque vous planifiez des voyages à venir dans la région. Vous pouvez également demander aux autorités jordaniennes de tamponner un bout de papier à la place, si vous prévoyez de vous rendre dans d&#039;autres pays qui n&#039;ont pas de relation amicale avec Israël. La même chose est valable lorsque vous voyagez au Liban et entrez en Israël par la suite - vous pourriez être confronté à des questions des autorités israéliennes sur les raisons de votre visite au Liban.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;a href=&quot;https://www.google.com/maps/d/edit?mid=1kOGjGGMh0vMyqKsVN5xAORX5ua7xJQZh&amp;amp;ll=31.030942274246865,35.28009029999998&amp;amp;z=8&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Border Crossings/Border Crossings.jpg&quot; /&gt;&lt;/a&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; &lt;span style=&quot;font-size: 14px; text-decoration-line: inherit;&quot;&gt; &lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1875, 'fr', '', 'one col', 'comment-traverser-la-frontiere-entre-la-jordanie-et-israel-palestine');
INSERT INTO `en33_pages` (`id`, `name`, `title`, `meta_desc`, `meta_key`, `contents`, `published`, `lang_id`, `lang`, `icon`, `layout`, `url`) VALUES
(1940, 'Pont King Hussein/Allenby', 'Pont King Hussein/Allenby', 'Horaires, transport, visa, frais de sortie: découvrez tout ce que vous devez savoir sur le pont Allenby / King Hussein entre la Jordanie, Israël / les territoires palestiniens.', 'Pont King Hussein, Pont Allenby', '&lt;p&gt;Le passage le plus célèbre et le principal point de circulation des Palestiniens dans la région. C&#039;est également le poste frontalier le plus proche pour les touristes qui viennent en Jordanie depuis Jérusalem.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Situation:&lt;/strong&gt; Situé dans le sud de la vallée du Jourdain, il est à 57 km d&#039;Amman, à 220 km de Petra et à 320 km de Wadi Rum. Du côté palestinien, c&#039;est près de Jéricho.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Visas:&lt;/strong&gt; les autorités jordaniennes ne délivrent pas de visas à ce poste frontière. Depuis janvier 2020, même les détenteurs d&#039;un Jordan Pass doivent obtenir un visa au préalable pour entrer en Jordanie via le pont du Roi Hussein. Dans ce domaine, l&#039;autorité jordanienne la plus proche qui peut délivrer des visas est le bureau de représentation jordanien à Ramallah: Ein Mujid. Bâtiment Abraj, 7e étage. Numéros de téléphone: (+970) 2-297 4625/6 ou (+970) 2-297 4624&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;em&gt;Important&lt;/em&gt;: les visas délivrés à l&#039;aéroport Queen Alia sont uniquement à entrée unique. Cependant, si vous quittez la Jordanie, entrez en Palestine / Israël et souhaitez revenir en Jordanie, vous pouvez utiliser le même visa délivré à l&#039;aéroport, tant qu&#039;il est toujours valide. Cette règle ne s&#039;applique que si vous entrez / quittez la Palestine / Israël via le Pont du roi Hussein.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;strong&gt;Frais de sortie:&lt;/strong&gt; 10 JD (environ USS15) pour quitter la Jordanie vers Israël; 177 NIS (environ US$53) pour quitter Israël vers la Jordanie.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Transport: &lt;/strong&gt;Des taxis sont disponibles des deux côtés de la frontière et nous organisons également des transferts. Cependant, si vous souhaitez prendre les transports en commun:&lt;/p&gt;\r\n&lt;p&gt;En Jordanie: des bus Jett sont disponibles depuis / vers le pont King Hussein depuis / vers la gare routière Abdali d&#039;Amman. Les heures de départ et les prix &lt;a href=&quot;https://www.jett.com.jo/en/schedule&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;sont disponibles ici.&lt;/a&gt; Ce billet comprend le transport d&#039;Amman à la frontière et à la zone entre la sortie jordanienne et la frontière israélo-palestinienne. Cela signifie que vous n&#039;avez pas besoin de payer le 7JOD pour la navette: montrez simplement votre billet Jett lorsque vous remontez dans le bus pour continuer la traversée.&lt;/p&gt;\r\n&lt;p&gt;Du passage aux territoires palestiniens et à Jérusalem: il y a des bus entre le poste frontière et Jéricho ou Jérusalem. Depuis Jéricho, il existe des taxis publics partagés (services) vers d&#039;autres villes de Cisjordanie.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Heures d&#039;ouverture (côté jordanien):&lt;/strong&gt;<br>Dimanche - jeudi: 07h30 - 22h<br>Vendredi - samedi: 07h30 - 13h&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Heures d&#039;ouverture (côté israélien):&lt;/strong&gt;<br>Dimanche - jeudi: 07: 30-24h<br>Vendredi et samedi: 8h-15h<br><br>Cependant, les dernières heures d&#039;arrivée des passagers à des fins de transit / traversée sont:<br><br>- Touristes: du dimanche au jeudi - jusqu&#039;à 21h<br>- Palestiniens et résidents de Jérusalem-Est: du dimanche au jeudi - jusqu&#039;à 22h<br>- Vendredi et samedi, la dernière heure d&#039;arrivée des passagers (touristes, Palestiniens &amp;amp; résidents de Jérusalem-Est) est 12h.&lt;/p&gt;', 1, 1876, 'fr', '', 'one col', 'pont-king-hussein-allenby'),
(1941, 'Traversée Sheikh Hussein/Jourdain', 'Traversée Sheikh Hussein/Jourdain', 'Horaires, transport, visa, frais de sortie: découvrez tout ce que vous devez savoir sur le Traversée Sheikh Hussein/Jourdain entre la Jordanie et Israël.', 'Traversée Sheikh Hussein, Jourdain, Jordanie, Israël, visa', '&lt;p&gt;&lt;strong&gt;Situation:&lt;/strong&gt; à 90 km d&#039;Amman, elle est située au nord de la Jordanie. Les grandes villes les plus proches sont Irbid et Ajlun. C&#039;est près de la ville israélienne de Beit She&#039;an et du lac de Tibériade (mer de Galilée).&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Visas: &lt;/strong&gt;La plupart des nationalités (à l&#039;exception des ressortissants restreints) peuvent obtenir des visas pour la Jordanie à ce poste frontalier. Il en coûte 40JOD.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Frais de sortie:&lt;/strong&gt; 10 JD (environ US$15) pour quitter la Jordanie vers Israël; 102 NIS (environ US$30) pour quitter Israël vers la Jordanie.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Transport: &lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;En Jordanie:&lt;/p&gt;\r\n&lt;p&gt;Les transports publics sont disponibles depuis / vers Irbid, et de là, vous devriez prendre un taxi pour le croisement. Depuis février 2020, il n&#039;y a pas de bus qui se rendent à Nazareth, par exemple.<br><br>En Israël:&lt;/p&gt;\r\n&lt;p&gt;Des bus sont disponibles vers plusieurs destinations en Israël. Entre les deux postes forntières un bus emmène les passagers du terminal israélien au terminal jordanien et le trajet coûte 5 NIS.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Heures d&#039;ouverture (côté jordanien):&lt;/strong&gt;<br>Dimanche - vendredi: 8h - 18h<br>Samedi: 8h30 - 18h<br><br>&lt;strong&gt;Heures d&#039;ouverture (côté israélien):&lt;/strong&gt;<br>Dimanche-jeudi: 7h - 20h30<br>Vendredi - samedi: 8h30 à 18h30&lt;/p&gt;', 1, 1877, 'fr', '', 'one col', 'traversee-sheikh-hussein-jourdain'),
(1942, 'Traversée Wadi Araba/Yitzhak Rabin', 'Traversée Wadi Araba/Yitzhak Rabin', 'Horaires, transport, visa, frais de sortie: découvrez tout ce que vous devez savoir sur le Traversée Wadi Araba/Yitzhak Rabin entre la Jordanie et Israël.', 'Traversée Wadi Araba, Traversée Yitzhak Rabin, Jordanie, Israël', '&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Emplacement:&lt;/strong&gt; Au sud de la Jordanie, à 324 km d&#039;Amman et près d&#039;Aqaba; du côté israélien, c&#039;est près d&#039;Eilat. Les deux villes sont des stations balnéaires de la mer Rouge.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Visas: &lt;/strong&gt;Malgré les informations fournies sur les canaux officiels, les visas pour la Jordanie sont délivrés à ce point de passage et sont gratuits dans le cadre de l&#039;Aqaba Special Economic Zone Authority. Un séjour minimum de trois nuits en Jordanie vous exonérera du paiement du visa (40JOD) et de la taxe de départ, si vous quittez la Jordanie du même passage ou d&#039;un autre point à Aqaba. Dans ce cas, vos frais de visa seront annulés, sans qu&#039;il soit nécessaire de présenter un Jordan Pass à votre arrivée. Cependant, si vous passez moins de 3 nuits en Jordanie et que vous revenez en Israël, vous devrez payer le visa et les frais de sortie. Ces règles s&#039;appliquent uniquement au passage de Wadi Araba.&lt;/span&gt;<br><br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Si vous souhaitez prolonger le visa obtenu au passage de Wadi Araba, vous devrez payer les frais de 40JOD. L&#039;extension de visa est également fournie à Amman, pas seulement à Aqaba.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Frais de sortie:&lt;/strong&gt; 10 JD (environ 15 $ US) pour quitter la Jordanie vers Israël; 102 NIS (environ 30 $ US) pour quitter Israël vers la Jordanie. Un séjour minimum de trois nuits en Jordanie exempte les touristes de payer la taxe de départ de 10 JOD lorsqu&#039;ils quittent la Jordanie via le passage du Wadi Araba.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Transport:&lt;/strong&gt; &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;En Jordanie: Vous devez prendre un taxi de la frontière jusqu&#039;à Aqaba. De là, des bus sont disponibles pour Amman ou Petra.&lt;/span&gt;<br><br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;En Israël: il n&#039;y a pas de transport public vers ou depuis la zone tampon, les voyageurs peuvent utiliser les taxis d&#039;Eilat ou des voitures privées.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Heures d&#039;ouverture (côté jordanien):&lt;/strong&gt;&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Dimanche - jeudi: 6h30 - 20h&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Vendredi - samedi: 8h - 20h&lt;/span&gt;<br><br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Heures d&#039;ouverture (côté israélien):&lt;/strong&gt;&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Dimanche - jeudi: 6h30 à 20h&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Vendredi - samedi: 8h - 20h&lt;/span&gt;&lt;/p&gt;', 1, 1878, 'fr', '', 'one col', 'traversée-wadi-araba-yitzhak-rabin'),
(1943, 'Puente King Hussein/ Allenby', 'Puente King Hussein/ Allenby', 'Puente King Hussein, Puente Allenby, Jerusalem, Jordania, Israel, Palestina', 'Todo lo que necesita saber sobre cómo cruzar el Puente King Hussein/ Allenby: horarios, tasas, transporte y visados.', '&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;El paso más famoso y el punto principal para que los palestinos circulen en la región. También es el paso fronterizo más cercano para los turistas que vienen a Jordania desde Jerusalén.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Ubicación:&lt;/strong&gt; en el sur del valle del Jordán, a 57 km de Amán, a 220 km de Petra y a 320 km de Wadi Rum. Del lado palestino, está cerca de Jericó.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Visados:&lt;/strong&gt; las autoridades jordanas no emiten visas en este punto fronterizo. Desde enero de 2020, incluso los titulares del Jordan Pass deben obtener sus visados de antemano para ingresar a Jordania a través del puente King Hussein. En esa área, la autoridad jordana más cercana que puede emitir visas es la Oficina de Representación jordana en Ramallah: Ein Mujid. Edificio Abraj, 7 ° piso. Números de teléfono: (+970) 2-297 4625/6 o (+970) 2-297 4624&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Importante:&lt;/strong&gt; los visados emitidos en el Aeropuerto Queen Alia son de entrada única. Sin embargo, si sale de Jordania, ingresa a Palestina / Israel y desea regresar a Jordania, puede usar el mismo visado emitido en el aeropuerto, mientras sea válido. Esa regla se aplica solo si ingresa/sale de Palestina/Israel a través del puente Rey Hussein.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Tasa de salida:&lt;/strong&gt; 10 JD (alrededor de US$ 15) para salir de Jordania hacia Israel; 177 NIS (alrededor de US$ 53) para salir de Israel hacia Jordania.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Transporte:&lt;/strong&gt; Los taxis están disponibles en ambos lados de la frontera y también organizamos los traslados. Sin embargo, si desea tomar el transporte público:<br>&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;En Jordania: los autobuses Jett están disponibles hacia / desde el puente King Hussein desde / hasta la estación de autobuses Abdali en Amán. Los horarios y precios de salida &lt;a href=&quot;https://www.jett.com.jo/en/schedule&quot;&gt;están disponibles aquí.&lt;/a&gt;<br>&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Este boleto incluye el transporte desde Amán a la frontera y al área entre la salida jordana y la frontera palestina / israelí. Eso significa que no necesita pagar 7JOD por el servicio de transporte: solo muestre su boleto de Jett cuando regrese en el autobús para continuar el cruce.<br>&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Desde el paso hasta los territorios palestinos y Jerusalén: hay autobuses entre el paso fronterizo y Jericó o Jerusalén. Desde Jericó, hay taxis públicos compartidos (servicios) a otras ciudades de Cisjordania.<br>&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Horas de funcionamiento (lado jordano):&lt;/strong&gt;&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Domingo - jueves: 7h30 - 22h&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Viernes - sábado: 7h30 - 13h<br>&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Horas de funcionamiento (lado israelí):&lt;/strong&gt;&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Domingo - jueves: 7h30 - 24h&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Viernes y sábados: 8h - 15h<br>&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Sin embargo, los últimos horarios para la llegada de pasajeros con fines de tránsito / cruce son:<br>&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Turistas: domingo - jueves: hasta las 21h&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Palestinos y residentes de Jerusalén Este: domingo a jueves: hasta las 22h&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Los viernes y sábados, la última hora para la llegada de pasajeros (turistas, palestinos y residentes de Jerusalén Este) es a las 12h.&lt;/span&gt;&lt;/p&gt;', 1, 1876, 'es', '', 'one col', 'puente-king-hussein-allenby'),
(1944, 'Frontera Wadi Araba/Itzjak Rabin', 'Frontera Wadi Araba/Itzjak Rabin', 'Opening times, transport, visa, exit fees: find out all you need to know about Allenby/King Hussein Bridge between Jordan, Israel/Palestinian territories', 'Todo lo que necesita saber sobre cómo cruzar la Frontera Wadi Araba/Itzjak Rabin: horarios, tasas, transporte y visados.', '&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Ubicación:&lt;/strong&gt; en el sur de Jordania, a 324 km de Ammán y cerca de Aqaba; en el lado israelí está cerca de Eilat. Las dos ciudades son centros turísticos del Mar Rojo.<br>&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Visados:&lt;/strong&gt; a pesar de la información proporcionada en los canales oficiales, visados son emitidos en este paso y son gratuitos como parte de la Autoridad de la Zona Económica Especial de Aqaba. Una estancia mínima de tres noches en Jordania lo eximirá de pagar el visado (40JOD) y la tasa de salida, solamente si sale de Jordania desde el mismo paso o desde otro punto en Aqaba. En ese caso, las tarifas de su visa no se aplicarán, sin la necesidad de mostrar un Jordan Pass a su llegada. Sin embargo, si pasa menos de 3 noches en Jordania y regresa a Israel, deberá pagar el visado y las tasas de salida. Estas reglas se aplican solo al cruce de Wadi Araba. Si desea extender el visado obtenido en el paso fronterizo de Wadi Araba, deberá pagar la tarifa de 40 JOD. La extensión del visado también se consigue en Amman, no solo en Aqaba.<br>&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Tasas de salida:&lt;/strong&gt; 10 JD (alrededor de US$ 15) para salir de Jordania hacia Israel; 102 NIS (alrededor de US$ 30) para salir de Israel hacia Jordania. Una estancia mínima de tres noches en Jordania exime a los turistas de pagar el impuesto de salida de 10 JOD cuando dejan la Jordania a través de la frontera de Wadi Araba.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Transporte:<br><br>&lt;/strong&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;En Jordania: puede tomar un taxi desde el paso hasta Aqaba. Desde allí, los autobuses están disponibles para Amman o Petra.<br>&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;En Israel: no hay transporte público hacia o desde el cruce y los viajeros pueden usar taxis desde Eilat o automóviles privados.<br>&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Horas de funcionamiento (lado jordano):&lt;/strong&gt;&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Domingo - jueves: 6h30 - 20h&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Viernes - sábado: 8h - 20h<br>&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Horas de funcionamiento (lado israelí):&lt;/strong&gt;&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Domingo - jueves: 6h30 - 20h&lt;/span&gt;<br>&lt;span style=&quot;font-size: 12pt;&quot;&gt;Viernes - sábado: 8h - 20h&lt;/span&gt;&lt;/p&gt;', 1, 1878, 'es', '', 'one col', 'frontera-wadi-araba-itzjak-rabin'),
(1945, 'Coronavirus updates in Jordan and the region', 'Coronavirus updates in Jordan and the region', 'The latest relevant updates about the novel coronavirus pandemic in Jordan and other countries of the Middle East.', 'Coronavirus, pandemic, COVID-19, Jordan, Oman, Israel, Palestine, Lebanon, Middle East', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p style=&quot;text-align: right;&quot;&gt;                                           &lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;em&gt;Last updated on February 02, 2021&lt;/em&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;em&gt;<br>On January 20th, t&lt;/em&gt;&lt;em&gt;he one-week mandatory quarantine was lifted, making it easier for visitors to enter the Hashemite Kingdom of Jordan. Since then, only a PCR test &lt;span&gt;done within maximum 72 hours prior to arrival is requested. The PCR test fees can either be:&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;em&gt;&lt;span&gt;<br>1- Added to the flight ticket price.<br>2- Or paid at the check in counter in the departure country.&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;em&gt;The latest measures and procedures in place can be found on &lt;a href=&quot;http://www.visitjordan.gov.jo&quot;&gt;www.visitjordan.gov.jo&lt;/a&gt;.&lt;/em&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;em&gt;Prior to this recent decision, all travellers should register on a platform called &quot;gateway2jordan&quot;. A QR code was then created upon payment of the PCR test fee. If you have paid for the test, but have not used it, be aware that the &lt;/em&gt;&lt;em&gt;&lt;span&gt;QR code has no expiration date and can be used at any date as long as it was not refunded.&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;em&gt;&lt;span&gt;In case of not registering on gateway2jordan platform before, you are required to fill out the declaration form through &lt;a href=&quot;http://carc.jo/en/covid19-related-measures&quot;&gt;this link &lt;/a&gt;and present it on the check in counter in the departure country.&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;em&gt;The World Travel and Tourism Council (WTTC) has awarded Jordan the &lt;a href=&quot;https://wttc.org/COVID-19/Safe-Travels-Global-Protocols-Stamp&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;“Safe Travels Stamp”&lt;/a&gt; thanks to the country’s health safety protocols that were deemed to be in line with the Council’s standards, which makes Jordan a safe destination for Travel &amp;amp; Tourism. We welcome such decision and hope to receive your visit when possible!&lt;/em&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;em&gt;Stay safe&lt;/em&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;On March 2nd, 2020, when the first case of COVID-19 was reported in Jordan, our staff started to work from their homes. We are all experiencing challenging and uncertain times, in which the situation rapidly evolves and plans need to be adapted.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;We strongly encourage our customers to postpone the holidays booked with us, if necessary. Jordan is a beautiful country and we look forward to welcoming you with the best service. Clients that have booked their holidays through our website may change the dates of their trip. A voucher of the same value of the services purchased will be provided, and this credit will be available up until 12 months after the notification date.&lt;/p&gt;\r\n&lt;p&gt;Furthermore, we would like to reinforce the importance of social distancing at the moment, to slow the propagation of the novel coronavirus. Up to date information about the number of cases globally is available &lt;a href=&quot;https://who.sprinklr.com/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;here&lt;/a&gt; on a daily basis. &lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Remember to wash your hands frequently, maintain social distancing, avoid touching eyes, nose and mouth, and practice respiratory hygiene. Check out the &lt;a href=&quot;https://www.who.int/emergencies/diseases/novel-coronavirus-2019/advice-for-public&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;basic protective measures&lt;/a&gt; against the novel coronavirus that the World Health Organisation recommends.&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Safe Travels - Jordan_800x500.jpg&quot; /&gt;  &lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; &lt;/div&gt;\r\n&lt;/div&gt;', 1, 1945, 'en', 'fa-no-icon', 'one col', 'coronavirus'),
(1946, 'Sobre a Jordânia', 'Sobre a Jordânia', 'Tudo sobre a Jordânia, ums dos países mais acolhedores do Oriente Médio: clima, geografia, culinária, aeroportos e fronteiras.', 'Jordânia, Religião, Culinária, Língua, Fronteiras, Aeroportos', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;Seu nome oficial é “Reino Hachemita da Jordânia”: país árabe no oeste da Ásia, na margem leste do rio Jordão. A capital Amã é a cidade mais populosa da Jordânia, bem como o centro econômico, político e cultural do país. A Jordânia está estrategicamente localizada na encruzilhada da Ásia, África e Europa. O país é conhecido como um oásis de estabilidade no Oriente Médio. É um importante destino turístico, atraindo também o turismo médico devido ao seu setor de saúde bem desenvolvido.&lt;/p&gt;\r\n&lt;p&gt;A Jordânia é um país relativamente pequeno, semi-árido, com uma área de 89.342 km2 (34.495 milhas quadradas) e uma população de 10 milhões, tornando-a o 11º país árabe mais populoso. O Islã sunita, praticado por cerca de 95% da população, é a religião dominante na Jordânia e coexiste com uma minoria cristã nativa da região.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Clima&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Os invernos na Jordânia são geralmente curtos e frios. Janeiro é o mês mais frio, com temperaturas de 5 a 10 ° C. Cerca de 70% da chuva esperada anualmente cai durante este período. Amã pode estar especialmente fria em Janeiro e Fevereiro e a neve não é incomum. No entanto, durante esses meses, o vale do Jordão e a área ao redor de Aqaba são razoavelmente quentes durante o dia, com noites frias. Mas o inverno no deserto pode ser bem frio e seco. Prepare-se!<br><br>A primavera começa em Março, quando as flores silvestres florescem. Os vales são verdes e as temperaturas ficam entre 15 e 20 ° C. Esta é uma das melhores épocas para ver a beleza do país!<br>Junho, Julho e Agosto são geralmente sem chuva e as temperaturas diárias podem atingir 40 °C ou mais, especialmente quando o Sirocco (um vento quente e seco do sul) sopra. Às vezes, esses ventos podem ser muito fortes e podem causar tempestades de areia. Em Julho, a Jordânia recebe cerca de 13 horas de sol por dia, em média. Os verões podem ser intensamente quentes no vale do Jordão, na área ao redor de Aqaba e no deserto oriental.<br><br>A melhor época para mergulhar em Aqaba é Setembro, Outubro e início de Novembro, quando a água é quente a 26 °C, e a vida marinha é abundante, incluindo arraias e tartarugas.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Aeroportos<br>&lt;/strong&gt;<br>A Jordânia possui três aeroportos comerciais, todos recebendo e despachando voos internacionais. Dois estão em Amã e o terceiro em Aqaba (Aeroporto Internacional King Hussein). O Aeroporto Internacional Queen Alia, em Amã, é o principal aeroporto internacional da Jordânia, movimentando mais de 16 milhões de passageiros anualmente. &lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Fronteiras<br><br>&lt;/strong&gt;A Jordânia faz fronteira com a Arábia Saudita ao sul e leste, com o Iraque ao nordeste, com a Síria ao norte, e com Israel e a Palestina (Cisjordânia) a oeste. O Mar Morto está localizado ao longo de suas fronteiras ocidentais e o país tem uma costa curta de 26 quilômetros (16 milhas) no Mar Vermelho, no extremo sudoeste, mas, de outra forma, fica sem litoral.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Porto de Aqaba<br>&lt;/strong&gt;<br>O porto de Aqaba é o único da Jordânia. Em 2006, foi classificado como o &quot;Melhor Terminal de Contêineres&quot; no Oriente Médio pela Lloyd&#039;s List. O porto de Aqaba foi escolhido por ser um porto de carga de trânsito para outros países vizinhos, por sua localização entre quatro países e três continentes, por ser uma porta de entrada exclusiva para o mercado local, e pelas melhorias recentes.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Geografia&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;A Jordânia fica estrategicamente na encruzilhada dos continentes da Ásia, África e Europa; o país tem cerca de 89km² , e 400km de distância entre seus pontos mais ao norte e mais ao sul (Umm Qais e Aqaba, respectivamente). O leste é um planalto árido irrigado por oásis e correntes de água sazonais. As principais cidades estão localizadas predominantemente na parte noroeste do Reino, devido a seus solos férteis e chuvas relativamente abundantes. Isso inclui Irbid, Jerash e Zarqa, no noroeste, a capital Amã e Al-Salt, no oeste central, e Madaba, Al-Karak e Aqaba, no sudoeste. As principais cidades da parte oriental do país são as cidades oásis de Azraq e Ruwaished.<br><br>No oeste, uma área montanhosa de terras aráveis e florestas sempre-verdes do Mediterrâneo caem repentinamente no vale do rio Jordão, onde ficam o famoso rio Jordão e o Mar Morto. O rio Yarmouk, um afluente oriental do rio Jordão ao norte, faz parte da fronteira entre a Jordânia e a Síria (incluindo as Colinas de Golã ocupadas). O ponto mais alto é Jabal Umm al Dami, a 1.854m acima do nível do mar, enquanto o mais baixo é o Mar Morto – 420m, o ponto mais baixo da Terra.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Ecologia e Natureza&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Mais de 2.000 espécies de plantas foram registradas na Jordânia. Muitas delas florescem na primavera após as chuvas de inverno, então o tipo de vegetação depende em grande parte dos níveis de precipitação. As regiões montanhosas do noroeste estão cobertas de florestas, enquanto mais ao sul e leste a vegetação se torna mais escassa e muda para estepe. As florestas cobrem 1.500 km², menos de 2% do território, o que faz da Jordânia um dos países menos florestados do mundo – a média internacional é de 15%.<br><br>As espécies e gêneros vegetais incluem a íris negra (a flor nacional do país), o pinheiro Aleppo, Sarcopoterium, Salvia dominica, Tamarix, Anabasis, Artemísia, Acácia, cipreste mediterrâneo e zimbro fenício. As regiões montanhosas do noroeste são cobertas por florestas naturais de pinheiro, carvalho decíduo, carvalho verde, pistache e azeitona selvagem. As espécies de mamíferos e répteis incluem o ouriço de orelhas compridas, capra nubiana, javali, lobo árabe, lagarto-monitor, texugo-do-mel, cobra de vidro, caracal, chacal-dourado e corça, entre outros. As aves incluem o corvo-encapuzado, gaio da Eurásia, o rosefinch do Sinai, e muitos outros. A reserva de Azraq, aliás, vem se tornado um lugar popular para apreciadores de pássaros observarem as aves.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Idioma&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;A língua oficial é o Árabe Padrão Moderno (MSA), uma língua literária ensinada nas escolas. A maioria dos jordanianos fala o dialeto regional, que também é usado na Síria, Palestina e Líbano. A Língua de Sinais da Jordânia é a Língua de Sinais árabe levantino. O inglês, embora sem status oficial, é amplamente falado em todo o país e é a língua de fato do comércio e dos bancos, além de ter grande presença no setor educacional. Quase todas as aulas de nível universitário são ministradas em inglês e quase todas as escolas públicas ensinam inglês junto com o árabe padrão. Checheno, circassiano, armênio, tagalog e russo são populares entre suas comunidades. O francês é oferecido como eletivo em muitas escolas, principalmente no setor privado. O alemão é uma língua cada vez mais popular; foi introduzida em larga escala desde o estabelecimento da Universidade Alemã-Jordaniana em 2005.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Cultura&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;A cultura da Jordânia baseia-se em elementos árabes e islâmicos com significativa influência ocidental. A Jordânia fica no encontro dos três continentes do mundo antigo, o que lhe deu diversidade geográfica e populacional. Aspectos notáveis da cultura incluem música, artesanato e roupas tradicionais.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Culinária&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Existe uma grande variedade no estilo jordaniano de cozinhar. A cozinha tradicional varia entre assados, refogados e grelhados de carnes e aves, até os legumes recheados (folhas de uva, berinjela, abobrinha/curgete, etc.). Também é muito comum no estilo jordaniano preparar alimentos com molhos especiais.&lt;/p&gt;\r\n&lt;p&gt;O azeite é o principal óleo de cozinha da Jordânia. Ervas, alho, temperos, cebola, molho de tomate e limão são sabores típicos encontrados nos alimentos. O mais comum e popular dos aperitivos é o hummus, que é um purê de grão de bico misturado com tahine (pasta de gergelim), limão e alho. Ful Medames é outro aperitivo bem conhecido.&lt;/p&gt;\r\n&lt;p&gt;Mansaf é o prato nacional da Jordânia, um símbolo da hospitalidade do país e influenciado pela cultura beduína. É servido em diferentes ocasiões, como casamentos, feriados religiosos e até funerais. Mansaf consiste em um prato de arroz com carne de carneiro cozida em um caldo de iogurte (jamid), e coberto com ervas e castanhas. A tradição antiga manda que se coma Mansaf com as mãos, divindo o mesmo prato com os convidados.&lt;/p&gt;\r\n&lt;p&gt;Frutas frescas simples são frequentemente servidas no final de uma refeição jordaniana, mas também há deliciosas sobremesas, como baklava, hareeseh, knafeh, halva e qatayef, um prato feito especialmente para o Ramadã. Na culinária jordaniana, beber café e chá com sabor de na&#039;na (hortelã) ou meramiyyeh (sálvia) é quase um ritual.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;medium-width&quot; src=&quot;uploads/filemanager/Photos/Jordan/Jordan Info2.jpg&quot; width=&quot;391&quot; height=&quot;1882&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3492247.663606793!2d34.87836949724749!3d31.26508142489433!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15006f476664de99:0x8d285b0751264e99!2sJordan!5e0!3m2!1sen!2sjo!4v1569426954186!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1008, 'pt', '', 'one col', 'sobre-a-jordania'),
(1947, 'Vistos para a Jordânia', 'Vistos para a Jordânia', 'Tudo sobre vistos para a Jordânia: valores, emissão na chegada ao país.', 'Vistos Jordânia, Vistos no aeroporto', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Vistos de &lt;strong&gt;entrada única&lt;/strong&gt; válidos por um mês custam &lt;strong&gt;40 JOD&lt;/strong&gt; (aproximadamente &lt;strong&gt;US$ 56&lt;/strong&gt;)&lt;/li&gt;\r\n&lt;li&gt;Vistos de &lt;strong&gt;entrada dupla&lt;/strong&gt; válidos por três meses: &lt;strong&gt;60 JOD&lt;/strong&gt; (aproximadamente &lt;strong&gt;US$ 85&lt;/strong&gt;)&lt;/li&gt;\r\n&lt;li&gt;Vistos de&lt;strong&gt; entrada múltipla&lt;/strong&gt; válidos por seis meses: &lt;strong&gt;120 JOD&lt;/strong&gt; (aproximadamente &lt;strong&gt;US$ 170&lt;/strong&gt;)&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;Grupos de cinco ou mais pessoas que chegam com um operador turístico designado da Jordânia estão isentos do custo do visto.<br><br>O visto de entrada deve ser obtido antecipadamente para algumas nacionalidades. A lista abaixo serve apenas como uma orientação e está sujeita a alterações sem aviso prévio. Recomendamos que se verifique com a missão diplomática da Jordânia em seu país antes de viajar para garantir informações atualizadas sobre a documentação necessária para viajar.<br><br>A taxa de saída se aplica aos pontos de fronteira terrestre e marítima. 10 JOD por passageiro e 5 JOD por veículo.&lt;/p&gt;\r\n&lt;p&gt;  &lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;África&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;O visto pode ser obtido na chegada:&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Argélia, Cabo Verde, Tunísia (18 a 35 anos), Lesoto, Líbia, Marrocos, Malawi, Maurício, Ruanda, São Tomé e Príncipe, Seicheles, África do Sul.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;O visto deve ser obtido antes da chegada:&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Angola, Benim, Botsuana, Burkina Faso, Burundi, Camarões, República Centro-Africana, Chade, Ilhas Comores,, República do Congo, Costa do Marfim, Djibuti, Egito, Guiné Equatorial, Eritreia, Etiópia, Gabão, Gâmbia, Gana, Guiné, Guiné-Bissau, Quênia, Lagos, Libéria, Madagascar, Mali, Mauritânia, Moçambique, Namíbia, Níger, Nigéria, Senegal, Serra Leoa, Somália, Sudão, Sudão do Sul, Suazilândia, Tanzânia, Togo, Uganda, Zâmbia, Zimbábue.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Ásia&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;O visto pode ser obtido na chegada:&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Armênia, Azerbaijão, Bahrein, Butão, Brunei, Birmânia, China, Taiwan, Geórgia, Hong Kong, Índia, Indonésia, Israel, Japão, Cazaquistão, Kuwait, Líbano, Macau, Malásia, Maldivas, Coréia do Norte, Palestina/Portadores de Passaporte emitidos pela Autoridade Palestina, China, Catar, Rússia, Arábia Saudita, Cingapura, Coréia do Sul, Síria, Tajiquistão, Tailândia, Turquemenistão, Turquia, Emirados Árabes Unidos, Uzbequistão e Iêmen.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;O visto deve ser obtido antes da chegada:&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Afeganistão, Bangladesh, Camboja, Egito, Irã, Iraque, Laos, Mongólia, Nepal, Paquistão, Papua Nova Guiné, Filipinas, Sri Lanka, Vietnã.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Europa&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;O visto pode ser obtido na chegada:&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Andorra, Áustria, Azerbaijão, Bielorrússia, Bélgica, Bósnia e Herzegovina, Grã-Bretanha, Bulgária, Croácia, Chipre, República Tcheca, Dinamarca, Cazaquistão, Estônia, Finlândia, França, Geórgia, Alemanha, Grécia, Holanda, Hungria, Islândia, Irlanda, Itália, Kosovo, Letônia, Liechtenstein, Luxemburgo, Macedônia, Malta, Mônaco, Noruega, Polônia, Portugal, Rússia, Romênia, San Marino, Espanha, Suécia, Suíça, Turquia, Ucrânia, Vaticano, Sérvia, Eslováquia, Eslovênia, Iugoslávia.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;O visto deve ser obtido antes da chegada:&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Albânia, Moldávia.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;América do Norte&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;O visto pode ser obtido na chegada:&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Canadá, México, Estados Unidos, Antígua e Barbuda, Bahamas, Barbados, Costa Rica, Dominica, República Dominicana, Granada, Guatemala, Haiti, Honduras, Jamaica, Nicarágua, Panamá, El Salvador, São Cristóvão e Nevis, Santa Lúcia, São Vicente e Granadinas.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;O visto deve ser obtido antes da chegada:&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Belize, Cuba.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Oceania&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;O visto pode ser obtido na chegada:&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Austrália, Estados Federados da Micronésia, Fiji, Ilhas Marshall, Nova Zelândia, Samoa, Ilhas Salomão, Tonga, Tuvalu, Vanuatu.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;O visto deve ser obtido antes da chegada:&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Papua Nova Guiné.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;América do Sul&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;O visto pode ser obtido na chegada:&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Argentina, Bolívia, Brasil, Chile, Equador, Guiana, Paraguai, Peru, Suriname, Uruguai, Trinidad e Tobago, Venezuela.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;O visto deve ser obtido antes da chegada:&lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Colômbia.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/testimonials/collage5.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3492247.663606793!2d34.87836949724749!3d31.265081424894323!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15006f476664de99:0x8d285b0751264e99!2sJordan!5e0!3m2!1sen!2sjo!4v1572514329525!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1364, 'pt', '', 'one col', 'vistos-para-jordania'),
(1948, 'Travessia Sheikh Hussein / Rio Jordão', 'Travessia Sheikh Hussein / Rio Jordão', 'Tudo sobre a travessia pela fronteira norte da Jordânia e Israel: horários, taxas e localização.', 'Travessia Sheikh Hussein, Rio Jordão, Fronteira Jordânia e Israel', '&lt;p&gt;&lt;strong&gt;Localização:&lt;/strong&gt; a 90 km de Amã no norte da Jordânia. As cidades mais próximas são Irbid e Ajloun. Fica perto da cidade israelense de Beit She&#039;an e do lago Tiberíades (mar da Galileia).&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Vistos:&lt;/strong&gt; 40 JOD (aproximadamente US$ 56). A maioria das nacionalidades (exceto as restritas) pode obter vistos para a Jordânia neste posto de fronteira.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Taxas de saída:&lt;/strong&gt; 10 JOD (cerca de US$ 15) para deixar a Jordânia em direção a Israel; 102 NIS (cerca de US$ 30) para deixar Israel em direção à Jordânia.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Transporte:&lt;/strong&gt; Na Jordânia: transportes públicos estão disponíveis para/de Irbid. De lá, deve-se pegar um táxi para a travessia. A partir de fevereiro de 2020, não há ônibus que vão para Nazaré, por exemplo.&lt;/p&gt;\r\n&lt;p&gt;Em Israel: os ônibus estão disponíveis para vários destinos em Israel. Dentro da travessia, um ônibus leva passageiros do terminal israelense ao terminal da Jordânia e a viagem custa 5 NIS.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Horário de funcionamento (lado da Jordânia):&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Domingo - Sexta: 8h - 18h<br>Sábado: 8h30 - 18h&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Horário de funcionamento (lado israelense):&lt;/strong&gt;<br>Domingo - Quinta: 7h - 20h30<br>Sexta-feira - Sábado: 8h30 - 18h30&lt;/p&gt;', 1, 1877, 'pt', '', 'one col', 'travessia-sheikh-hussein-rio-jordao'),
(1949, 'Ponte Allenby/Rei Hussein', 'Ponte Allenby/Rei Hussein', 'Tudo que precisa saber sobre a travessia mais famosa entre Palestina e Jordânia: a Ponte do Rei Hussein, também conhecida como Ponte Allenby.', 'Ponte Allenby, Ponte Rei Hussein, vistos, fronteira Jordânia e Jerusalém', '&lt;p&gt;É a travessia mais famosa e o ponto principal para os palestinos circularem na região. É também a passagem de fronteira mais próxima para turistas que chegam à Jordânia a partir de Jerusalém.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Localização:&lt;/strong&gt; no sul do vale do Jordão, a 57 km de Amã, a 220 km de Petra e a 320 km de Wadi Rum. No lado palestino, fica perto de Jericó.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Vistos: &lt;/strong&gt;as autoridades jordanianas não emitem vistos nesta passagem de fronteira. Desde janeiro de 2020, mesmo os titulares do Jordan Pass devem obter o visto com antecedência para entrar na Jordânia pela ponte King Hussein. Nessa área, a autoridade jordaniana mais próxima que pode emitir vistos é o Escritório de Representação da Jordânia em Ramallah: Ein Mujid, Edifício Abraj, 7º andar. Números de telefone: (+970) 2-297 4625/6 ou (+970) 2-297 4624&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;em&gt;Importante:&lt;/em&gt; os vistos emitidos no Aeroporto Rainha Alia são apenas de entrada única. No entanto, se o turista sair da Jordânia, entrar na Palestina / Israel e quiser voltar à Jordânia, poderá usar o mesmo visto emitido no aeroporto, desde que ele ainda seja válido. Essa regra se aplica somente ao entrar/sair da Palestina/Israel via Ponte Rei Hussein.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;strong&gt;Taxas de saída:&lt;/strong&gt; 10 JOD (cerca de US$ 15) para deixar a Jordânia em direção a Israel; 177 NIS (cerca de US$ 53) para deixar Israel em direção à Jordânia.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Transporte:&lt;/strong&gt; os táxis estão disponíveis nos dois lados da fronteira e também providenciamos transferências. No entanto, se gostaria de utilizar o transporte público:&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;em&gt;Na Jordânia&lt;/em&gt;: os ônibus Jett estão disponíveis para/da Ponte Rei Hussein de/para a estação de ônibus Abdali em Amã. Horários e preços de partida estão disponíveis aqui. Este bilhete inclui o transporte de Amã para a fronteira e para a área entre a saída da Jordânia e a fronteira da Palestina / Israel. Isso significa que o passageiro não precisa pagar os 7JOD pelo ônibus disponível no posto de fronteira: apenas mostre sua passagem Jett quando se dirigir ao ônibus para continuar a travessia.&lt;/p&gt;\r\n&lt;p&gt;&lt;em&gt;Da travessia para os territórios palestinos e Jerusalém:&lt;/em&gt; há ônibus entre a fronteira e Jericó ou Jerusalém. De Jericó, existem táxis públicos coletivos (serviice) para outras cidades da Cisjordânia.&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;Horário de funcionamento (lado da Jordânia):&lt;/strong&gt;<br><br>Domingo - Quinta: 7h30 - 22h<br>Sexta-feira - sábado: 7h30 - 13h&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Horário de funcionamento (lado israelense):&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Domingo - Quinta: 7h30 - 24h<br>Sextas e sábados: 8h - 15h&lt;/p&gt;\r\n&lt;p&gt;No entanto, os últimos horários para a chegada de passageiros com fins de trânsito / travessia são:&lt;/p&gt;\r\n&lt;p&gt;Turistas: domingo - quinta-feira: até 21h<br><br>Palestinos e residentes em Jerusalém Oriental: Domingo - Quinta-feira: até 22h<br><br>Na sexta e no sábado, o último horário para a chegada de passageiros (turistas, palestinos e residentes de Jerusalém Oriental) é de 12h.&lt;/p&gt;', 1, 1876, 'pt', '', 'one col', 'ponte-allenby-rei-hussein'),
(1950, 'Travessia Wadi Araba/Yitzhak Rabin', 'Travessia Wadi Araba/Yitzhak Rabin', 'Tudo que precisa saber sobre a travessia so sul da Jordânia e Israel, o ponto mais próximo da cidade de Petra.', 'Travessia Wadi Araba, Sul da Jordânia, Petra, fronteira entre Jordânia e Israel', '&lt;p&gt;&lt;strong&gt;Localização:&lt;/strong&gt; no sul da Jordânia, a 324 km de Amã e perto de Aqaba; do lado israelense, fica perto de Eilat. As duas cidades são resorts no Mar Vermelho.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Vistos:&lt;/strong&gt; apesar das informações fornecidas nos canais oficiais, os vistos para a Jordânia são emitidos nessa passagem e são gratuitos como iniciativa da Autoridade Especial da Zona Econômica de Aqaba. Uma estadia mínima de três noites na Jordânia dá a gratuidade do visto (40JOD) e da taxa e imposto de partida, caso o turista deixe Jordânia pela mesma travessia ou por outro ponto em Aqaba. Nesse caso, as taxas do seu visto serão dispensadas, sem a necessidade de mostrar um Jordan Pass na sua chegada. No entanto, se passar menos de 3 noites na Jordânia e voltar para Israel, precisará pagar as taxas de visto e saída. Essas regras se aplicam apenas ao cruzamento de Wadi Araba. Se deseja estender o visto obtido no cruzamento de Wadi Araba, precisará pagar a taxa de 40JOD. A extensão do visto também é fornecida em Amã, não apenas em Aqaba.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Taxas de saída:&lt;/strong&gt; 10 JOD (cerca de US$ 15) para deixar a Jordânia em direção a Israel; 102 NIS (cerca de US$30) para deixar Israel em direção à Jordânia. Como informado acima, uma estadia mínima de três noites na Jordânia isenta os turistas de pagar a taxa de partida de 10 JOD quando saem da Jordânia pela travessia Wadi Araba.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Transporte:&lt;/strong&gt; &lt;/p&gt;\r\n&lt;p&gt;Na Jordânia: deve pegar um táxi do cruzamento até Aqaba. De lá, os ônibus estão disponíveis para Amã ou Petra.<br><br>Em Israel: não há transporte público de / para a travessia e os viajantes podem usar táxis de Eilat ou carros particulares.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Horário de funcionamento (lado da Jordânia)::&lt;/strong&gt; &lt;/p&gt;\r\n&lt;p&gt;Domingo - Quinta: 6h30 - 20h<br>Sexta-feira - Sábado: 8h - 20h&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Horário de funcionamento&lt;/strong&gt; &lt;strong&gt;(lado israelense):&lt;/strong&gt;<br>Domingo - Quinta: 6h30 - 20h<br>Sexta-feira - Sábado: 8h - 20h&lt;/p&gt;', 1, 1878, 'pt', '', 'one col', 'travessia-wadi-araba');
INSERT INTO `en33_pages` (`id`, `name`, `title`, `meta_desc`, `meta_key`, `contents`, `published`, `lang_id`, `lang`, `icon`, `layout`, `url`) VALUES
(1951, 'Como atravessar a fronteira entre Jordânia e Israel/Palestina', 'Como atravessar a fronteira entre Jordânia e Israel/Palestina', 'Tudo o que precisa saber sobre as três travessias entre a Jordânia e Israel e Palestina: dicas, vistos, taxas, horários e localização.', 'Jordania, Israel, Palestina, fronteiras, Ponte Allenby, Ponte Rei Hussein, Wadi Araba, Travessia Sheikh Hussein', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;*** A partir de 12 de março, todos os três postos de fronteira descritos aqui estão fechados para os passageiros que partem e se destinam à Jordânia. Esta é uma medida do governo para evitar a propagação da doença por coronavírus (COVID-19) no país. ***&lt;/p&gt;\r\n&lt;p&gt;Conforme detalhado &lt;strong&gt;aqui&lt;/strong&gt;, os vistos podem ser obtidos no Aeroporto Internacional Rainha Alia (exceto para nacionalidades restritas). No entanto, existem três postos de fronteira disponíveis para viajantes entre a Jordânia, Israel e os Territórios Palestinos Ocupados (oPT). Cada ponto tem um nome diferente nos lados da Jordânia e de Israel / Palestina. Clique abaixo para ler todas as informações essenciais sobre cada travessia.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;en/sheikh-hussein-jordan-river-crossing/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;1 – Sheikh Hussein/Jordan River Crossing&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;en/allenby-king-hussein-bridge/&quot;&gt;2 – Allenby/King Hussein Bridge&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;en/wadi-araba-yitzhak-rabin-crossing/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;3 – Wadi Araba/Yitzhak Rabin Crossing&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Stamps:&lt;/strong&gt; when crossing into Jordan from Israel/Palestinian territories, Jordanian authorities might stamp your passport stating that you entered the country via that crossing. Therefore, that means that you have been to Israel and/or to the Palestinian territories, which are occupied by Israel. This stamp may have your entry denied in certain countries, like Lebanon.&lt;/p&gt;\r\n&lt;p&gt;Therefore, keep that in mind when planning upcoming trips in the region. You can also ask the Jordanian authorities to stamp a slip of paper instead, if you plan to go to other countries that do not have an amicable relation with Israel. The same is valid when travelling to Lebanon and entering Israel afterwards – you may face questioning from Israeli authorities on why you have visited Lebanon.&lt;/p&gt;\r\n&lt;p&gt;Please note that pubic holidays may affect the opening times and operations at the border crossings on both sides. Plan ahead and check if important dates such as Ramadan, Muslim New Year or Yom Kippur will impact your holidays.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;a href=&quot;https://www.google.com/maps/d/edit?mid=1kOGjGGMh0vMyqKsVN5xAORX5ua7xJQZh&amp;amp;ll=31.030942274246865,35.28009029999998&amp;amp;z=8&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Border Crossings/Border Crossings.jpg&quot; /&gt;&lt;/a&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; &lt;span style=&quot;font-size: 14px; text-decoration-line: inherit;&quot;&gt; &lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1875, 'pt', '', 'one col', 'como-atravessar-fronteiras-jordania-israel-palestina'),
(1952, 'Melhor época para visitar a Jordânia', 'Melhor época para visitar a Jordânia', 'Qual é a melhor época do ano para visitar a Jordânia? Saiba aqui!', 'Clima da Jordânia, Verão na Jordânia, Inverno na Jordânia, Primavera na Jordânia,', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;A Jordânia tem um clima quente e seco, caracterizado por verões longos, quentes e secos, e invernos curtos e frios. Como a Jordânia possui uma grande variedade de microclimas que podem variar durante o ano, o melhor horário para sua visita depende de suas expectativas ou necessidades.&lt;/p&gt;\r\n&lt;p&gt;O clima é influenciado pela localização da Jordânia entre a aridez subtropical das áreas do deserto da Arábia e a umidade subtropical da região leste do Mediterrâneo. Janeiro é o mês mais frio, com temperaturas de 5°C a 10°C, e Agosto é o mês mais quente de 20°C a 35°C. As temperaturas diárias podem ser muito quentes, especialmente no verão; chegando a 40°C ou mais, especialmente quando o Sirocco (um vento quente e seco do sul) sopra.&lt;/p&gt;\r\n&lt;p&gt;O clima na Jordânia é condicionado em parte pela altitude. As áreas central e norte são mais altas, onde pode ser bastante frio no inverno, especialmente entre dezembro e fevereiro, mas relativamente fresco durante o verão. As áreas mais baixas, como o Golfo de Aqaba e o vale do Jordão, são quentes e úmidas durante o verão, particularmente durante Julho e Agosto, mas geralmente agradáveis no inverno.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Inverno&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Em média, a Jordânia só recebe 30 dias de chuva por ano nas regiões mais altas, mas as pancadas de chuva tendem a ser fortes e curtas. Podem ocorrer nevascas em Amã e em outras áreas montanhosas durante os meses de Janeiro e Fevereiro, mas geralmente são curtas e desaparecem rapidamente. Até em Petra pode cair neve ocasionalmente, e o deserto estará frio especialmente durante a noite, mas isso varia de acordo com o ano e estação.&lt;/p&gt;\r\n&lt;p&gt;Aqaba, por outro lado, é uma ótima exceção: em média a temperatura máxima durante o dia é de cerca de 20°C em Janeiro. Por isso a cidade é bastante popular entre os europeus que têm a chance de escapar de invernos rigorosos aproveitando o sol de Aqaba. Ao viajar no inverno para a Jordânia, traga muitas roupas quentes e uma jaqueta impermeável para enfrentar as chuvas.&lt;/p&gt;\r\n&lt;p&gt; <br>&lt;strong&gt;Verão&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Durante os meses de pico do verão, o clima pode ser quente e geralmente não chove. Estas são as condições no vale do Jordão e na área do Mar Morto, mas também no deserto (incluindo Wadi Rum). O calor no deserto será seco , por isso é um pouco mais fácil de lidar do que quando há umidade. Como em qualquer outro país quente no verão, um chapéu, roupas protetoras, protetor solar e hidratação não devem ser esquecidos. Às vezes, as noites de verão costumam ser um pouco frias; portanto, tenha sempre uma jaqueta leve ou uma pashmina em mãos.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Primavera e outono&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Quando se trata dos melhores meses para visitar a Jordânia, Março até o final de Junho e Setembro a Novembro são provavelmente os mais adequados. Na primavera, as paisagens se tornam muito mais bonitas com as flores silvestres características da época.&lt;/p&gt;\r\n&lt;p&gt;Caso prefira viajar durante o inverno ou o verão, seja para aproveitar o sol do Oriente Médio ou uma brisa fresca, vá para a Jordânia, um destino para todas as estações do ano. Cada época garante uma experiência diferente e agradável.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Museum/como sacar jordan pass.jpg&quot; width=&quot;429&quot; height=&quot;400&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt;&lt;strong&gt; &lt;/strong&gt;&lt;span style=&quot;text-decoration-line: inherit;&quot;&gt; &lt;/span&gt;&lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Museum/weather.jpg&quot; style=&quot;text-decoration-line: inherit;&quot; width=&quot;883&quot; height=&quot;471&quot; /&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3492247.6636067987!2d34.87836949724749!3d31.26508142489433!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15006f476664de99:0x8d285b0751264e99!2sJordan!5e0!3m2!1sen!2sjo!4v1569845424463!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1023, 'pt', '', 'one col', 'melhor-epoca-para-visitar'),
(1953, 'Razões para visitar a Jordânia', 'Razões para visitar a Jordânia', 'Por que visitar a Jordânia? É seguro visitar a Jordânia? Veja as respostas aqui!', 'Seguro visitar Jordânia, Jordânia é perigosa, O que ver na Jordânia', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;A Jordânia é uma terra rica em história e lar de alguns dos primeiros assentamentos e aldeias da humanidade. Esta terra abriga relíquias das grandes civilizações do mundo.&lt;/p&gt;\r\n&lt;p&gt;A bela arquitetura antiga, aventuras no deserto, mergulho em alto mar, estadia em casas locais, culinária deliciosa, locais sagrados espetaculares, o Mar Vermelho e o Mar Morto são apenas algumas das razões para se visitar a Jordânia. Como há muito a se fazer por aqui, escolhemos alguns pontos favoritos para oferecer uma amostra do que é a Jordânia.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Tesouros históricos&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Começamos com aquela que é amplamente considerada a atração mais popular da Jordânia: Petra, uma cidade histórica e arqueológica localizada no sul da Jordânia. Também conhecida como &quot;Cidade Rosa&quot; devido à coloração de suas rochas, a entrada principal da cidade é uma vista deslumbrante. O “Tesouro” ou “Al-Khazneh” está localizado após o “Siq”, que é um estreito corredor de 1,5 km cercado por rochedos de 80 m de altura.&lt;/p&gt;\r\n&lt;p&gt;Alguns dos sítios arqueológicos mais bem preservados do Império Romano estão na Jordânia. Além das ruínas da cidade greco-romana de Gerasa em Jerash, não deixe de visitar a Cidadela (para vistas incríveis da cidade) e o Teatro Romano, ambos localizados perto do centro de Amã.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Segurança!&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;É absolutamente seguro viajar no país, para viajantes sozinhos ou em grupo. É a sua vez de ser arrebatado(a) por um país que oferece sol, mar, dunas de areia, as maravilhas de Petra e deliciosa comida!.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Hospitalidade da Jordânia&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;A Jordânia é famosa pela hospitalidade e bondade do povo jordaniano. Com certeza ficará feliz em descobrir que as pessoas estão sempre preparadas para ajudar e se esforçam para garantir que se divirta como hóspede no país deles. Prepare-se para receber muitos convites para jantar e chá.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;A comida&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Há mais na culinária árabe do que falafel e hummus. A comida jordaniana tradicional caseira é uma das mais saborosas e saudáveis da região. Pratos incluem Mansaf e Maqloube (à base de arroz e carne). No verão, a variedade de saladas frescas coloridas, como tabule, complementa bem a refeição.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;De norte a sul, a Jordânia é incrivelmente diversa&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Ao viajar pela Jordânia, a diversidade de paisagens e pessoas pode surpreender. Experimente o estilo de vida sereno e humilde dos beduínos no deserto de Wadi Rum acampando com eles por uma noite, mas não se esqueça de explorar o que a vida urbana em Amã também oferece.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/testimonials/food.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3492247.663606793!2d34.87836949724749!3d31.265081424894323!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15006f476664de99:0x8d285b0751264e99!2sJordan!5e0!3m2!1sen!2sjo!4v1572514329525!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1418, 'pt', '', 'one col', 'razões-para-visitar-jordania'),
(1954, 'Jordan Pass', 'Jordan Pass', 'Saiba os benefícios de comprar o Jordan Pass antes de sua chegada à Jordânia.', 'Jordan Pass, Jordânia, ingressos', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;O &lt;a href=&quot;https://www.jordanpass.jo/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Jordan Pass&lt;/a&gt; é um pacote turístico especialmente criado para visitantes. Seus portadores podem aproveitar ao máximo sua viagem visitando os principais pontos turísticos e atrações do país, economizando tempo e dinheiro.&lt;/p&gt;\r\n&lt;p&gt;Com o Jordan Pass não é preciso pagar a taxa do visto de entrada, caso ele seja adquirido antes de sua chegada à Jordânia, e caso sua estadia seja de três noites (4 dias) no mínimo. Com este pacote, o turista também tem entrada pré-paga sem complicações para mais de 40 atrações na Jordânia e acesso a brochuras digitais com informações de todas as atrações turísticas do país.&lt;/p&gt;\r\n&lt;p&gt;Simplesmente mostre o Jordan Pass na entrada de qualquer atração coberta por ele. O Jordan Pass é válido para uso dentro dos 12 meses após a data da compra. No entanto, ele expirará automaticamente após 2 semanas da primeira vez em que for digitalizado na primeira atração turística.&lt;/p&gt;\r\n&lt;p&gt;Há três categorias de Jordan Pass e sua escolha deve depender do número de dias que deseja passar explorando Petra, Patrimônio Mundial da UNESCO. Petra tem uma paisagem de tirar o fôlego, e é repleta de montanhas rochosas em tons de rosa esculpidas há mais de 2.000 anos.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;&lt;strong&gt;1 dia&lt;/strong&gt; de visita a Petra &lt;strong&gt;70 JOD&lt;/strong&gt; (aproximadamente &lt;strong&gt;99 USD&lt;/strong&gt;)&lt;/li&gt;\r\n&lt;li&gt;&lt;strong&gt;2 dias&lt;/strong&gt; consecutivos de visita a Petra &lt;strong&gt;75 JOD&lt;/strong&gt; (aproximadamente &lt;strong&gt;106 USD&lt;/strong&gt;)&lt;/li&gt;\r\n&lt;li&gt;&lt;strong&gt;3 dias&lt;/strong&gt; consecutivos de visita a Petra &lt;strong&gt;80 JOD&lt;/strong&gt; (aproximadamente &lt;strong&gt;113 USD&lt;/strong&gt;)&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/testimonials/jordanpass.png&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3492247.663606793!2d34.87836949724749!3d31.265081424894323!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15006f476664de99:0x8d285b0751264e99!2sJordan!5e0!3m2!1sen!2sjo!4v1572514329525!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1413, 'pt', '', 'one col', 'jordan-pass'),
(1955, 'Dinar jordaniano', 'Dinar jordaniano', 'Encontre informações sobre a moeda da Jordânia, o dinar.', 'Dinar Jordaniano, Dinar, moeda, conversão', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;O dinar jordaniano, abreviado como JD, é a moeda da Jordânia desde 1950. O dinar é dividido em 10 dirhams, 100 qirsh (também chamados de piastras) ou 1000 “fills”.&lt;/p&gt;\r\n&lt;p&gt;Em 1949, as notas foram emitidas pelo governo em denominações de “Meio” dinar, 1, 5, 10 e 50 dinares. Desde 1959, o Banco Central da Jordânia assumiu a produção de notas. Notas de 20 dinares foram introduzidas em 1977, seguidas pelas de 50 dinares em 1999. As notas de “meio” dinar foram substituídas por moedas em 1999.&lt;/p&gt;\r\n&lt;p&gt;O dinar é muito forte, não devido a uma economia nacional robusta ou a uma grande escala de exportações, mas porque está atrelado ao dólar americano nos últimos 20 anos.&lt;/p&gt;\r\n&lt;p&gt;O dinar fixado em dólares serviu bem à economia jordaniana: alcançou estabilidade monetária, reforçou a confiança do público, e atraiu investimentos árabes e estrangeiros.&lt;/p&gt;\r\n&lt;p&gt;Antes de viajar, recomendamos que verifique o &lt;a href=&quot;en/currency-converter/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;conversor de moedas&lt;/a&gt;.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Amman/jordanian-dinar.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3492247.663606793!2d34.87836949724749!3d31.265081424894323!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15006f476664de99:0x8d285b0751264e99!2sJordan!5e0!3m2!1sen!2sjo!4v1572870339732!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1508, 'pt', '', 'one col', 'dinar-jordaniano'),
(1956, 'Transporte na Jordânia', 'Transporte na Jordânia', 'Facilite sua viagem: encontre aqui informações essenciais sobre os meios de transporte na Jordânia.', 'Transporte na Jordânia,Táxi na Jordânia, Transporte público na Jordânia', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;strong&gt;Aluguel de carros&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Alugar um carro pode ser uma boa maneira de conhecer a Jordânia. Para isso, é necessário uma carteira de habilitação válida em seu país de origem, desde que você a tenha por pelo menos há um ano. Aqui se dirige à direita e as placas nas rodovias estão em árabe e inglês (as placas marrons foram feitas para turistas). Existem muitos postos de gasolina em Amã e em outras cidades, e na maioria das rodovias. Também podemos providenciar um aluguel de carro antes de sua viagem à Jordânia.&lt;/p&gt;\r\n&lt;p&gt; &lt;strong&gt;Ônibus&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Várias empresas oferecem ônibus fretados e passeios regulares com veículos modernos e climatizados. Caso busque transporte de Amã para algumas das atrações turísticas imperdíveis, considere usar ônibus. A JETT, uma das principais empresas de transporte do país, oferece várias viagens (algumas diárias e outras semanais) a vários destinos, incluindo Petra, Aqaba, Mar Morto e Fontes Termais Ma&#039;in, além de passeios pela cidade de Amã.&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Táxis&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Os táxis são baratos e geralmente a forma mais conveniente de transporte na Jordânia. Os táxis conhecidos como “serviice” são brancos, seguem rotas fixas e são compartilhados com outros passageiros (custam JD0,35, ou 35 piastras, por pessoa). Os táxis particulares são pintados de amarelo; eles podem ser tomados nas filas em frente aos grandes hotéis ou podem ser parados na rua. Os táxis possuem taxímetros, e é aconselhável que sempre verifique se estão ligados e funcionando. Caso o motorista se recuse a utilizar o taxímetro (isso pode ocorrer...), combine o custo da viagem antecipadamente. Alguns taxistas são amigáveis, conhecem bem a cidade e falam inglês.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/testimonials/transportation3.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3492247.663606793!2d34.87836949724749!3d31.265081424894323!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15006f476664de99:0x8d285b0751264e99!2sJordan!5e0!3m2!1sen!2sjo!4v1572514329525!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1408, 'pt', '', 'one col', 'transporte-na-jordania'),
(1957, 'Amã', 'Amã', 'Saiba mais sobre a histórica capital da Jordânia: Amã.', 'Amã, Cidadela, Teatro Romano, Museu, capital da Jordânia', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Amã é a capital e cidade mais populosa da Jordânia. Também é o centro econômico, político e cultural do país. Situada no centro-norte da Jordânia, Amã é o centro administrativo da província de Amã. A cidade possui uma população de pouco mais de 4 milhões de habitantes e uma área de 1.680 km². Hoje, Amã é considerada uma das cidades árabes mais modernizadas. É um importante destino turístico da região, principalmente entre turistas árabes e europeus.&lt;/p&gt;\r\n&lt;p&gt;Amã é dividida em duas partes: a parte oeste, cheia de boates, bares e comércio, e a parte oriental, que ainda preserva importantes sítios arqueológicos, como a Cidadela, o Anfiteatro Romano e o típico &quot;suq&quot; árabe (mercado de rua tradicional).&lt;/p&gt;\r\n&lt;p&gt;O maior museu do país é o Museu da Jordânia. Ele contém muitas das descobertas arqueológicas valiosas do país, incluindo alguns dos Manuscritos do Mar Morto, as estátuas de calcário neolítico de &#039;Ain Ghazal e uma cópia da Pedra Moabita. Outros museus incluem a Galeria Nacional de Belas Artes da Jordânia, o Museu Arqueológico da Jordânia, o Museu das Crianças, o Memorial e Museu dos Mártires, o Museu Real do Automóvel, o Museu do Profeta Mohammad, o Museu da Vida Parlamentar, o Museu do Folclore, e museus da Universidade da Jordânia.&lt;/p&gt;\r\n&lt;p&gt;Amã é considerada uma das cidades mais liberais e ocidentalizadas do mundo árabe. A cidade se tornou um dos destinos mais populares para expatriados ocidentais e estudantes universitários que procuram viver, estudar ou trabalhar no Oriente Médio. A cena culinária da cidade mudou de suas barracas de shawarma e falafel para abraçar muitos restaurantes ocidentais populares e lojas de fast-food, desde restaurantes asiáticos a bistrôs franceses e trattorias italianas.&lt;/p&gt;\r\n&lt;h5&gt;&lt;/h5&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Amman/Royal Hotel.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d433870.8268373916!2d35.66743569022686!3d31.8354533233864!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151b5fb85d7981af:0x631c30c0f8dc65e8!2sAmman!5e0!3m2!1sen!2sjo!4v1564595824430!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 388, 'pt', '', 'one col', 'ama'),
(1958, 'Rio Jordão e Betânia do Além Jordão', 'Rio Jordão e Betânia do Além Jordão', 'Saiba mais sobre esse importante local de peregrinação cristã: o famoso e sagrado Rio Jordão.', 'Rio Jordão, Jordânia, Betânia, peregrinação na Jordânia, Batismo de Jesus Cristo', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;O rio Jordão tem 251km de comprimento e flui aproximadamente de norte a sul, através do mar da Galiléia e no mar morto. A Jordânia e as Colinas de Golã fazem fronteira com o rio a leste, enquanto a Cisjordânia e Israel ficam a oeste. Tanto a Jordânia quanto a Cisjordânia tiram seus nomes do rio.&lt;/p&gt;\r\n&lt;p&gt;O rio tem grande importância no Judaísmo e no Cristianismo, pois a Bíblia diz que os hebreus o atravessaram para a Terra Prometida e que Jesus de Nazaré foi batizado por João Batista.<br>Betânia além do rio Jordão, onde João Batista pregou e batizou durante os primeiros dias de seu ministério, foi recentemente revelada após pesquisas arqueológicas e escavações ao longo de Wadi Al-Kharrar desde 1996.&lt;/p&gt;\r\n&lt;p&gt;Evidências combinadas do texto bíblico, relatos de escritores bizantinos e medievais, somados a escavações arqueológicas mais recentes, localizaram a tradição da missão de João Batista, incluindo o batismo de Jesus, em uma área adjacente ao leste do rio Jordão.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Jordan River/Jordan River website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d1723499.3313860807!2d35.56573869965196!3d32.46708428012451!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151cf2b17acb4f8d:0xd2cc3c98dd2eaaf7!2sJordan River!5e0!3m2!1sen!2sjo!4v1567437278772!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 449, 'pt', '', 'one col', 'rio-jordao-betania'),
(1959, 'Castelos do deserto', 'Castelos do deserto', 'Saiba mais sobre os vestígios que antigas e mais recentes civilizações deixaram no deserto do leste da Jordânia.', 'Castelos do deserto, deserto no Leste da Jordânia', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Estendendo-se ao leste de Amã, a planície seca do deserto segue até o Iraque e a Arábia Saudita. Neste lugar, a areia infinita e as paisagens áridas de basalto comprovam a capacidade do homem de prosperar em condições adversas.&lt;/p&gt;\r\n&lt;p&gt;A descoberta de machados de pederneira neste deserto indica a passagem de nômades do período paleolítico na região, há cerca de meio milhão de anos atrás. Entretanto, os restos mais notáveis da habitação humana são os palácios construídos pelos califas omíadas de Damasco, durante os primeiros dias do Islã (séculos 7-8).&lt;/p&gt;\r\n&lt;p&gt;Durante o auge da dinastia omíada, a arquitetura floresceu com o intercâmbio cultural que acompanhou o crescimento das rotas comerciais. Aproximadamente no ano de 750, quando a dinastia omíada foi derrubada pelos abássidas de Bagdá, uma arquitetura rica e caracteristicamente muçulmana estava evoluindo, devido à influência cosmopolita de construtores e artesãos vindos do Egito, da Mesopotâmia e de outros lugares da região.&lt;/p&gt;\r\n&lt;p&gt;Hoje é possível ver muitas relíquias dos primeiros períodos islâmicos e medievais na Jordânia. Espalhadas em todo o terreno do leste da Jordânia e nas colinas centrais, existem inúmeras ruínas históricas, incluindo castelos, fortes, torres, banhos, pousadas para caravanas e palácios fortificados. Conhecidos coletivamente como castelos do deserto ou palácios do deserto, eles originalmente faziam parte de uma cadeia que se estendia do norte de Damasco até Khirbet al-Mafjar, perto de Ariha (ou Jericó).&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;Qasr Al-Kharanah&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;Qasr Amra&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Desert Castles/qasr-amra.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3202.960326365759!2d36.46056488753891!3d31.7285686252473!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151b249e0321d58d:0xae2394f52625c2b!2sQasr al-Kharaneh!5e0!3m2!1sen!2sjo!4v1569247005481!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 395, 'pt', '', 'one col', 'castelos-do-deserto'),
(1960, 'Madaba', 'Madaba', 'A charmosa cidade de Madaba é conhecida por seus mosaicos bizantinos e igrejas antigas.', 'Madaba, Mosaicos, Mosaicos na Jordânia, Mosaico da Terra Santa', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Esta é a capital da província de Madaba, no centro da Jordânia, com uma população de cerca de 60.000 habitantes. A cidade é mais conhecida por seus mosaicos bizantinos e omíadas, especialmente o grande mosaico com o mapa da Terra Santa da época bizantina. Madaba fica a 30km ao sudoeste da capital Amã.&lt;/p&gt;\r\n&lt;p&gt;A história de Madaba data da Idade do Bronze e ela também já foi uma cidade fronteiriça moabita mencionada na Bíblia. Durante o seu domínio pelos impérios romano e bizantino dos séculos 2 ao 7, a cidade fez parte da Província Arabia criada pelo imperador romano Trajano para substituir o reino nabateu de Petra. Durante a era bizantina, a partir do século 5 em diante, Madaba teve o seu próprio bispo e várias igrejas foram construídas do século 6 ao século 7.&lt;/p&gt;\r\n&lt;p&gt;Os chãos de mosaico eram a imagem desta era e continuaram a ser feitos em Madaba até o século 8. Em 749, um devastador terremoto arrasou a cidade, que foi abandonada. Em 1897, três famílias cristãs, um grupo de 2000 pessoas, migraram para Madaba vindas da antiga cidade dos Cruzados, Karak. Depois disso, a cidade ficou predominantemente cristã. Vários mosaicos foram descobertos quando foram construídas novas casas e igrejas para receber os novos imigrantes.&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;Principais atrações de Madaba:&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Igreja Grega Ortodoxa de São Jorge: às vezes chamada de &quot;Igreja do Mapa&quot;, porque abriga o famoso Mapa de Mosaico de Jerusalém e da Terra Santa descoberto em 1896. O famoso mosaico do século 6 tem dois milhões de peças de pedra colorida, e mostra colinas, vales e aldeias até ao Delta do Nilo. (A entrada custa 1 JOD e não está inclusa no Jordan Pass)<br>Igreja dos Apóstolos: as ruínas desta igreja bizantina datam do ano 578 e estão sendo restauradas. Lá está o mosaico conhecido como &quot;Personificação do Mar&quot;, representando uma mulher emergindo do mar, cercada por criaturas aquáticas míticas e uma mistura de carneiros, touros, papagaios e vegetação exótica. O mosaico foi assinado por um artista chamado Salamanios. (Entrada inclusa no Jordan Pass).&lt;/p&gt;\r\n&lt;p&gt;<br>Igreja de São João Batista: oferece uma vista magnífica da cidade, pois é possível subir até o topo da torre do sino (ingresso não incluso no Jordan Pass).&lt;/p&gt;\r\n&lt;p&gt;<br>Madaba é uma ótima opção. Além das visitas às igrejas, é bastante agradável passear pela cidade e fazer uma refeição em um de seus vários restaurantes tradicionais.&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 14px; text-decoration-line: inherit;&quot;&gt; &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Madaba/madaba mosque.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d54304.0835391128!2d35.7633807408465!3d31.71575236400819!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151cacd00bad3bc5:0x4d6d5834c1003e2b!2sMadaba!5e0!3m2!1sen!2sjo!4v1564829017080!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 398, 'pt', '', 'one col', 'madaba'),
(1961, 'Monte Nebo', 'Monte Nebo', 'Importante local bíblico, os livros sagrados dizem que Moisés avistou a Terra Prometida deste local.', 'Moisés, Monte Nebo, Terra Santa, Moisés morte, Terra  Prometida, êxodo', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Monte Nebo é um dos locais bíblicos que podem ser vistos durante sua viagem à Jordânia.&lt;/p&gt;\r\n&lt;p&gt;Segundo a Bíblia, foi do Monte Nebo que Moisés contemplou a Terra Prometida depois que Deus proibiu sua entrada. Além disso, para os cristãos, é nesta montanha onde está o túmulo de Moisés. Para os muçulmanos, seria em Nabi Musa, do outro lado do rio Jordão, na Palestina.&lt;/p&gt;\r\n&lt;p&gt;<br>Atrações deste lugar magnífico:&lt;/p&gt;\r\n&lt;p&gt;• Monumento da Serpente Neustã: a escultura da cruz com uma serpente foi criada pelo escultor italiano Giovanni Fantoni. É um símbolo da serpente de bronze criada por Moisés no deserto e da cruz na qual foi crucificado Jesus.&lt;/p&gt;\r\n&lt;p&gt;• Ruínas da Basílica de Moisés: no ponto mais alto do monte, Syagha, foram descobertas as ruínas de uma igreja e de um mosteiro. A igreja, descoberta em 1933, foi construída na segunda metade do século 4 para assinalar o local da morte de Moisés. O desenho da igreja segue o padrão de uma basílica típica. A cerca de 1 km a leste do Monte Nebo, é possível ver as nascentes de Moisés (Ayun Musa), uma coleção de nascentes de água doce que estariam onde, durante o êxodo, Moisés foi instruído por Deus a atirar um galho de árvore para que as amargas fontes se tornassem doces o suficiente para beber.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Mount_nebo/Monte-nebo.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d13568.31599039157!2d35.71652272680265!3d31.768331250610355!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151cad7ed4c82179:0x131a1cf280726293!2sMount+Nebo!5e0!3m2!1sen!2sjo!4v1564830031400!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 401, 'pt', '', 'one col', 'monte-nebo'),
(1962, 'Mar Morto', 'Mar Morto', 'Sabia que o Mar Morto é um lago? O Mar Morto é uma das paisagens naturais e espirituais mais espetaculares do mundo', 'Mar Morto, lago de sal, boiar no Mar Morto, flutuar no Mar Morto, Mar Morto Jordânia', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;O Mar Morto é um lago de sal com fronteira com a Jordânia ao leste, e Israel e Cisjordânia a oeste.&lt;/p&gt;\r\n&lt;p&gt;Encontra-se no vale do rio Jordão, que é a única fonte de água importante a desaguar no Mar Morto. Sua superfície e margens estão a 430,5 metros abaixo do nível do mar, a menor elevação da Terra. Assim que as águas chegam ao Mar Morto, ficam retidas e, ao evaporarem, deixam para trás uma densa e rica mistura de sais e minerais que fornecem à indústria, à agricultura e à medicina alguns dos seus melhores produtos.&lt;/p&gt;\r\n&lt;p&gt;Sua água é 9,6 vezes mais salgada que a água do oceano, por isso é possível flutuar no Mar Morto tão facilmente, uma experiência verdadeiramente única. A água do Mar Morto é rica em sais de cloreto de magnésio, sódio, potássio, bromo e outros. Estes sais e minerais conferem a essas águas os poderes curativos e as qualidades terapêuticas reconhecidas há mais de 2000 anos.&lt;/p&gt;\r\n&lt;p&gt;Atualmente, visitantes de todo o mundo vão ao Mar Morto para tratar vários problemas de saúde, como a psoríase. Pacientes com rinossinusite que receberam irrigação nasal com soro fisiológico do Mar Morto exibiram um alívio melhor dos sintomas em comparação com o spray salino padrão, por exemplo. Também já foi sugerida uma terapia com lama do Mar Morto para aliviar temporariamente a dor em pacientes com osteoartrite dos joelhos. O tratamento com compressas de lama ricas em minerais pode ser usado para complementar a terapia médica convencional.&lt;/p&gt;\r\n&lt;p&gt;O Mar Morto é uma das paisagens naturais e espirituais mais espetaculares do mundo; há muito o que se fazer em suas margens!&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Deadsea/Dead Sea website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d435268.73507000995!2d35.21009266120768!3d31.536874322287797!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15033c2eaf9fbba1:0xf38cff48a0c15882!2sDead+Sea!5e0!3m2!1sen!2sjo!4v1564839572942!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 404, 'pt', '', 'one col', 'mar-morto'),
(1963, 'Caverna de Ló', 'Caverna de Ló', 'Caverna de Ló - o  irmão de Abraão que fugiu com esposa e filhas da pecaminosidade de Sodoma.', 'Caverna de Ló, Sodoma, Abrãao, irmão de Abraão', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Ao sul do Mar Morto e perto da cidade de Safi, há uma encosta íngreme onde fica um mosteiro, uma basílica bizantina do século 7, um reservatório e alguns mosaicos junto à Caverna de Ló.&lt;/p&gt;\r\n&lt;p&gt;Ruínas da caverna datam até a Idade de Bronze (3300–2000 AC) e uma inscrição na caverna menciona o nome de Ló. Ele era irmão de Abraão e fugiu com sua esposa e suas duas filhas da pecaminosidade de Sodoma. Apesar de ser avisada pelos anjos que os ajudaram, sua esposa olhou para a cidade e se transformou em uma coluna de sal (Gênesis 19: 1-26).&lt;/p&gt;\r\n&lt;p&gt;Hoje, a rocha de formato estranho em uma encosta acima do Mar Morto leva o nome &quot;Esposa de Ló&quot;.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/more places/lotsCave-1.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d4834.194547909319!2d35.501409864684625!3d31.04597675930109!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1503a3a06035257b:0x4a4d7bd7cdd7141f!2sLot&#039;s Cave!5e0!3m2!1sen!2sjo!4v1573733393148!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1533, 'pt', '', 'one col', 'caverna-de-lo'),
(1964, 'Ajlun', 'Ajlun', 'Cidade no norte da Jordânia, Ajlun é verde e cercada de lindas paisagens, além da reserva natural e de um antigo castelo.', 'Ajlun, Castelo de Ajlun, Reserva Natural de Ajlun', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Localizada ao norte da Jordânia (76 km noroeste de Amã), a cidade montanhosa de Ajlun é famosa por suas impressionantes ruínas do Castelo de Ajloun, do século XII. As vistas de Ajlun são muito bonitas, e a região é cercada de colinas verdes e oliveiras. Ajlun também é capital da província de Ajlun.&lt;/p&gt;\r\n&lt;p&gt;O Castelo de Ajlun está no lugar onde ficava um antigo mosteiro que foi renovado para servir como forte. Algumas das pedras com as quais o castelo foi construído têm cruzes esculpidas, dando credibilidade à narrativa, recontada por um historiador árabe do século XIII, de que &quot;um antigo mosteiro estava no local, habitado por um cristão chamado Ajloun; quando o mosteiro caiu em ruínas, o castelo tomou seu lugar e o nome do monge &quot;.&lt;/p&gt;\r\n&lt;p&gt;Em 1184, Izz al-Din Usama, general do exército de Saladino, transformou o antigo monastério em fortaleza para controlar as minas de ferro de Ajlun e impedir que os francos invadissem a cidade. O Castelo de Ajlun dominava as três rotas principais de entrada na Jordânia e protegia as rotas comerciais entre a Jordânia e a Síria. Tornou-se assim um elo importante da cadeia defensiva contra os Cruzados, que passaram décadas a tentar conquistar o castelo e a aldeia vizinha.&lt;/p&gt;\r\n&lt;p&gt;O castelo original tinha quatro torres, frestas nas grossas muralhas, e era rodeado por um fosso com uma largura média de 16 metros e até 15 metros de profundidade.&lt;/p&gt;\r\n&lt;p&gt;No centro de Ajloun está a Grande Mesquita de Ajlun, uma das mais antigas existentes na Jordânia , cuja história remonta há cerca de 800 anos. Seu edifício foi anteriormente uma igreja cristã bizantina, e há relatos de escrita grega nas seções mais antigas.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Ajlun/Ajloun website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d53934.297894855255!2d35.7322292455951!3d32.34156536287274!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151c87da460049bd:0x3fbf8443e03b269a!2sAjloun!5e0!3m2!1sen!2sjo!4v1564839902477!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 407, 'pt', '', 'one col', 'ajlun'),
(1965, 'Pequena Petra (Little Petra)', 'Pequena Petra (Little Petra)', 'Assim como Petra, foi construída pelos nabateus e tem muitas estruturas parecidas com a famosa &quot;Petra&quot;.', 'Pequena Petra, Petra, Nabateus, Wadi Musa', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;A “Pequena Petra” também é conhecida em árabe como Siq al-Barid (&quot;o cânion frio&quot;), por conta de sua posição e paredes altas que impedem a entrada da maior parte da luz solar disponível. É um sítio arqueológico localizado ao norte de Petra e da cidade de Wadi Musa, na província de Ma&#039;an, na Jordânia. Assim como Petra, foi construída pelos nabateus e, como o próprio nome sugere, é muito menor que Petra. No entanto, está repleta de túmulos, templos, triclínios (salas de jantar), casas, canais de água e cisternas esculpidas nas paredes dos cânions de arenito.&lt;/p&gt;\r\n&lt;p&gt;A “Pequena Petra” faz parte do Parque Arqueológico de Petra, embora seja acessada separadamente, e também faz parte do título de Petra como Patrimônio Mundial da UNESCO. A “Pequena Petra” é aberta ao público durante o dia, mas o sítio é operado separadamente e não se exige um ingresso como em Petra. Os beduínos locais vendem lembranças e lanches no pequeno estacionamento, e o número de turistas que incluem a “Pequena Petra” em seu itinerário vem aumentando. Os guias recomendam o local como menos lotado e mais descontraído do que Petra. A “Casa Pintada” é um dos destaques do sítio arqueológico.&lt;/p&gt;\r\n&lt;p&gt;No extremo oeste do cânion, uma escada leva ao topo de uma rocha onde um beduíno instalou um salão de chá, do qual se pode apreciar a vista deslumbrante. Também é possível caminhar pela trilha de 6 km do final do cânion que une a Pequena Petra ao mosteiro de Petra, conhecido em árabe como Ad Deir. É aconselhável fazer esse caminho com um guia. A trilha, embora óbvia em muitos lugares, não é formalmente marcada. Os turistas também são advertidos a não tentar a trilha sozinhos, ou no final do dia, pois as noites na região costumam ser frias. Também é proibido entrar em Petra sem ter pago a entrada do sítio arqueológico.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Petra/Little Petra 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3442.1499734441923!2d35.44871971471867!3d30.37509898176327!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15016f643bc2d24b:0xafd3ecb219086144!2sTriclinium!5e0!3m2!1sen!2sjo!4v1564842717941!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 410, 'pt', '', 'one col', 'pequena-petra'),
(1966, 'Petra', 'Petra', 'Sem dúvida, o símbolo da Jordânia, a atração mais famosa e visitada do país é a cidade nabateana de Petra.', 'Petra, Jordânia, Cidade Rosada, Cidade Rosa, Sete Maravilhas do Mundo Moderno', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Sem dúvida, o símbolo da Jordânia, a atração mais famosa e visitada do país é a cidade nabateana de Petra. Situada nas montanhas ao sul do Mar Morto, Petra significa &quot;pedra&quot; em grego, e talvez seja a cidade antiga mais espetacular que resta no mundo moderno.&lt;/p&gt;\r\n&lt;p&gt;Petra é Patrimônio Mundial da UNESCO desde 1985 e uma das Sete Maravilhas do Mundo Moderno. A UNESCO a descreveu como &quot;uma das propriedades culturais mais preciosas do patrimônio cultural humano&quot;.&lt;/p&gt;\r\n&lt;p&gt;Petra foi a capital dos nabateus, árabes nômades que se estabeleceram e dominaram o sul da Jordânia há mais de 2000 anos, durante o período pré-romano. Eles eram particularmente hábeis na captação de água da chuva, na agricultura e esculpiram elaborados templos, túmulos e edifícios em rocha sólida. Petra floresceu no século I, quando sua famosa fachada “Al-Khazneh” ou “O Tesouro” - que se acredita ser o mausoléu do rei nabateu Aretas IV - foi construída e sua população atingiu um pico estimado em 20.000 habitantes.&lt;/p&gt;\r\n&lt;p&gt;O viajante e poeta vitoriano Dean Burgon deu a Petra uma descrição que se mantém até hoje: &quot;A não ser no Oriente pode-se encontrar, uma cidade de um vermelho-rosado quase tão velha como o próprio tempo”.&lt;/p&gt;\r\n&lt;p&gt;No entanto, as palavras dificilmente podem fazer justiça à magnitude de Petra. A fim de melhor aproveitar a atmosfera desta maravilha antiga, visite o sítio ao silêncio do início da manhã, ou no final da tarde, quando a rocha de arenito brilha em vermelho com uma grandeza silenciosa. É certamente uma joia imperdível para os visitantes da Jordânia e do Oriente Médio.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Petra/khazna4.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d13776.124196576167!2d35.471370226142305!3d30.321634658514736!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15016930021ab6b1:0xe43a697bc3a3e0b9!2sWadi+Musa!5e0!3m2!1sen!2sjo!4v1564843293999!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 413, 'pt', '', 'one col', 'petra');
INSERT INTO `en33_pages` (`id`, `name`, `title`, `meta_desc`, `meta_key`, `contents`, `published`, `lang_id`, `lang`, `icon`, `layout`, `url`) VALUES
(1967, 'Águas Termais de Afra', 'Águas Termais de Afra', 'Em Afra, a água mineral quente flui de 15 nascentes diferentes, variando a temperatura entre 45°C a 48°C.', 'Afra, águas termais, fontes termais', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;A Jordânia é o principal destino do turismo médico no Oriente Médio e as Águas Termais de Afra são um exemplo claro disso. Localizadas 26km ao norte da cidade de Tafilah, estas fontes são menos conhecidas que as Águas Termais de Ma&#039;in; no entanto, seus benefícios médicos são os mesmos.&lt;/p&gt;\r\n&lt;p&gt;A água mineral quente flui de 15 nascentes diferentes, variando a temperatura entre 45°C a 48°C. Muitos dos que frequentam as fontes termais buscam tratamento para doenças físicas crônicas, como problemas de pele e circulatórios, dores nos ossos, articulações, costas e músculos.&lt;/p&gt;\r\n&lt;p&gt;Essas águas ricas em minerais podem ajudar no tratamento da infertilidade, arteriosclerose, anemia e reumatismo. A água nas nascentes contêm elementos com propriedades curativas, incluindo sódio, cálcio, cloreto, radônio, sulfeto de hidrogênio e dióxido de carbono.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/more places/Afra hotsprings in Tafileh new.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3421.064055628116!2d35.63937391464292!3d30.968694581273997!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x150399e4b5f8abbd:0xd4f0bfbbe4f12c45!2sAfra Hot Springs!5e0!3m2!1sen!2sjo!4v1573817160896!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1553, 'pt', '', 'one col', 'afra'),
(1968, 'Qasr Amra', 'Qasr Amra', 'Saiba mais sobre o mais conhecido dos castelos do deserto da Jordânia.', 'Castelos do deserto, Amra, Castelo de Amra, Qasr Amra', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Qasr Amra, também transcrito como Quseir Amra ou Qusayr Amra, é o mais conhecido dos castelos do deserto localizados no leste da atual Jordânia. Foi construído no início do século 8, em algum momento entre 723 e 743, por Walid Ibn Yazid, o futuro califa omíada Walid II, cujo domínio da região estava aumentando na época. É considerado um dos exemplos mais importantes da arte e arquitetura islâmicas primitivas. A descoberta de uma inscrição durante os trabalhos em 2012 permitiu uma datação mais precisa da estrutura.&lt;/p&gt;\r\n&lt;p&gt;O edifício é na verdade o remanescente de um complexo maior que incluía um castelo real, do qual apenas a fundação permanece. Hoje, o que se destaca é uma pequena cabana de campo, destinada a um retiro real, sem nenhuma função militar.&lt;/p&gt;\r\n&lt;p&gt;É mais notável pelos afrescos que permanecem no teto. Eles retratam, entre outros, um grupo de governantes, caçadoras e mulheres nuas; acima de uma câmara de banho, uma representação precisa do zodíaco. Isso levou à sua designação como Patrimônio Mundial da UNESCO, um dos cinco no país.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/more places/Qasr_Amra.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3390.846227094984!2d36.58511081466424!3d31.801940540367088!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151b1e25b3292441:0x3a24cdc0130d66cc!2sQuseir &#039;Amra!5e0!3m2!1sen!2sjo!4v1573815079356!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1548, 'pt', '', 'one col', 'qasr-amra'),
(1969, 'Túmulo de Aarão', 'Túmulo de Aarão', 'O “Túmulo de Aarão” é o nome do suposto local de sepultamento de Aarão, o irmão de Moisés.', 'Túmulo de Aarão, Moisés, irmão de Moisés', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;O “Túmulo de Aarão” é o nome do suposto local de sepultamento de Aarão, o irmão de Moisés. Existem duas descrições de sua localização no Pentateuco e diferentes interpretações. Embora na tradição judaica a localização do túmulo de Aarão, como a de Moisés, esteja envolta em mistério, a tradição islâmica o coloca no monte Hor, perto de Petra.&lt;/p&gt;\r\n&lt;p&gt;O Monte Hor é geralmente associado à montanha perto de Petra, conhecida em árabe como Jabal Hārūn (Montanha de Aarão), que é o pico mais alto da região, a 1350 metros acima do nível do mar. <br>Há muito tempo é um local de peregrinação para muitas pessoas ao redor do mundo, e vale a pena uma viagem se você tiver um dia extra em Petra. É necessária boa aptidão física para a longa caminhada até lá e de volta.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Petra/df82e914176ce65aacd067c64bd46e1c.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d58385.40267440271!2d35.40021674186123!3d30.314549972328816!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15016e0979667d99:0x1e772ea247cdc050!2sTomb of Prophet Aaron!5e0!3m2!1sen!2sjo!4v1567438509722!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 433, 'pt', '', 'one col', 'tumulo-de-aarao'),
(1970, 'Castelo de Montreal', 'Castelo de Montreal', 'Fortificação dos cruzados construída em 1115.', 'Castelos do deserto, Castelo Montreal, Jordânia', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Montreal é um castelo dos cruzados no lado oriental da Arabah, situado em uma montanha rochosa com vista para as árvores frutíferas abaixo. As ruínas, chamadas Shoubak, estão localizadas na cidade de mesmo nome.&lt;/p&gt;\r\n&lt;p&gt;O castelo foi construído em 1115 por Baldwin I de Jerusalém durante sua expedição à região. Originalmente chamado de &#039;Krak de Montreal&#039; ou &#039;Mons Regalis&#039;, foi nomeado em homenagem ao próprio rei por sua contribuição à construção.&lt;/p&gt;\r\n&lt;p&gt;Pouco resta das fortificações originais dos cruzados. Embora o local nunca tenha sido totalmente escavado, sabe-se que havia um conjunto de três paredes que permanecem parcialmente. Os restos mais significativos do castelo cruzado são os restos de uma parede que corria dentro das adições muçulmanas posteriores e duas capelas.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/more places/800px-Montreal_Castle_Visitor_center.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d5779.69196469746!2d35.55591747806706!3d30.531629823334526!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1503dfdeae5e6ee9:0x955a7c3f09c03796!2sShobak Castle - Montreal!5e0!3m2!1sen!2sjo!4v1573740239429!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1543, 'pt', '', 'one col', 'castelo-de-montreal'),
(1971, 'Qasr Al-Kharanah', 'Qasr Al-Kharanah', 'Localizado no leste da Jordânia, acredita-se que tenha sido construído algum tempo antes do início do século 8.', 'Qasr Al-Kharanah, Castelos do deserto', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Qasr Al-Kharanah é um dos mais conhecidos castelos do deserto. Está localizado no leste da Jordânia, a cerca de 60km a leste de Amã e relativamente perto da fronteira com a Arábia Saudita.&lt;/p&gt;\r\n&lt;p&gt;Acredita-se que tenha sido construído algum tempo antes do início do século 8, com base em inscrições encontradas nos aposentos superiores, apesar das influências visíveis dos sassânidas (última dinastia do império persa pré-islâmico). Uma casa grega ou bizantina pode ter existido no local. É um dos primeiros exemplos da arquitetura islâmica na região.&lt;/p&gt;\r\n&lt;p&gt;Ele permanece muito bem preservado pois está localizado próximo a uma rodovia principal e a uma curta distância de carro de Amã, tornando-se um dos mais visitados dos castelos do deserto.<br>O castelo fica ao sul da Highway 40, uma importante estrada no deserto, que liga Amã a Azraq, à fronteira da Arábia Saudita e a áreas remotas do leste da Jordânia e do Iraque.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/more places/Qasr_Kharana_in_Jordan.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3393.523797847304!2d36.46069021454189!3d31.72890078130113!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151b249e0321d58d:0xae2394f52625c2b!2sQasr al-Kharaneh!5e0!3m2!1sen!2sjo!4v1573737457143!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1538, 'pt', '', 'one col', 'qasr-al-kharanah'),
(1972, 'Aqaba', 'Aqaba', 'Conheça Aqaba, a única cidade costeira da Jordânia, ao sul do país e no Mar Vermelho.', 'Aqaba, Mar Vermelho, sul da Jordânia', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Ao sul do país, Aqaba é a única cidade costeira da Jordânia e a maior e mais populosa cidade do Golfo de Aqaba. Aqaba é o centro administrativo da província de Aqaba e hoje desempenha um papel importante no desenvolvimento da economia da Jordânia, por meio dos vibrantes setores de comércio e turismo. O porto de Aqaba também serve outros países da região.&lt;/p&gt;\r\n&lt;p&gt;A localização estratégica de Aqaba, na ponta nordeste do Mar Vermelho, entre os continentes da Ásia e da África, tornou seu porto importante ao longo de milhares de anos. Além disso, a localização de Aqaba ao lado de Wadi Rum e Petra a colocou no triângulo dourado do turismo na Jordânia, que fortaleceu a localização da cidade no mapa mundial e a tornou uma das principais atrações turísticas do reino.&lt;/p&gt;\r\n&lt;p&gt;A cidade é administrada pela Autoridade Especial da Zona Econômica de Aqaba , que transformou Aqaba em uma cidade com isenção de impostos e baixa tributação, atraindo vários mega projetos como o Ayla Oasis, Saraya Aqaba, Marsa Zayed e expansão do porto de Aqaba.&lt;/p&gt;\r\n&lt;p&gt;As escavações em Tall Hujayrat Al-Ghuzlan e Tall Al-Magass em Aqaba revelaram que a cidade é um assentamento habitado desde 4000 AC, com uma próspera produção de cobre em larga escala. Este período é amplamente desconhecido devido à ausência de fontes históricas escritas.&lt;/p&gt;\r\n&lt;p&gt;Arqueólogos da Universidade da Jordânia descobriram os sítios arqueológicos onde encontraram um pequeno prédio cujas paredes estavam inscritas com desenhos de humanos e animais, sugerindo seu uso como local religioso. As pessoas que habitavam a área haviam desenvolvido um extenso sistema de água para irrigar suas plantações, que eram principalmente de uva e trigo.&lt;/p&gt;\r\n&lt;p&gt;Várias panelas de barro de tamanhos diferentes também foram encontradas, sugerindo que a produção de cobre era uma atividade importante na região; as panelas eram usadas para derreter o cobre e remodelá-lo. Estudos científicos realizados no local revelaram que houve dois terremotos, com o último deixando o local completamente destruído.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Aqaba/Aqaba website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d222065.98469071987!2d34.93504817367495!3d29.580974377533497!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15007039ff2efa81:0x595faa556d2e6acc!2sAqaba!5e0!3m2!1sen!2sjo!4v1567429408155!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 437, 'pt', '', 'one col', 'aqaba'),
(1973, 'Azraq', 'Azraq', 'Pequena cidade que se tornou importante por sua localização próxima ao grande oásis da região.', 'Azraq, Oásis, Wetland', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Azraq (&quot;Azul&quot; em árabe) é uma pequena cidade na província de Zarqa, no leste da Jordânia, a 100km ao leste de Amã. Azraq tem sido um importante assentamento em uma área remota e árida do deserto da Jordânia. O valor estratégico da cidade e de seu castelo (Qasr Azraq) é sua localização no meio do oásis de Azraq, a única fonte permanente de água doce em aproximadamente 12.000 km² de deserto.&lt;/p&gt;\r\n&lt;p&gt;A cidade está localizada em uma importante rota do deserto que facilitava o comércio na região. O oásis de Azraq tem uma longa história começando no período do Paleolítico Inferior. Muitos sítios paleolíticos foram documentados na Reserva de Azraq. Durante o período epipalaeolítico, o oásis também foi um importante foco de assentamento.&lt;/p&gt;\r\n&lt;p&gt;Atividades de assentamentos do período nabatiano também foram documentadas na área. Qasr Azraq foi construído pelos romanos no século 3 e foi fortemente modificado na Idade Média pelos mamelucos. No período omíada, um reservatório de água foi construído no sul de Azraq. Durante a Revolta Árabe no início do século 20, Qasr Azraq foi uma importante sede para T. E. Lawrence.&lt;/p&gt;\r\n&lt;p&gt;A reserva de Shaumari também fica perto de Azraq, a apenas 10km ao sul da cidade. Shaumari é um centro de reprodução para alguns dos animais selvagens mais ameaçados e raros do Oriente Médio. Nesta pequena reserva, há um grande rebanho de magníficos Órixes da Árabia. Existem também avestruzes, onagros e graciosas gazelas do deserto. Esses animais são protegidos da caça e destruição de habitats que antes ameaçavam sua existência. A Reserva Shawmari abriga uma rica variedade de plantas do deserto, incluindo Atriplex, uma fonte natural de alimentos para os onagros e órixes.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Azraq/Azraq.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d11401.630850688458!2d36.815294921211134!3d31.83247760249731!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151aefcf61ef9c43:0x51bd54d22be06412!2sAzraq!5e0!3m2!1sen!2sjo!4v1567432850018!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 441, 'pt', '', 'one col', 'azraq'),
(1974, 'Reserva da Biosfera de Dana', 'Reserva da Biosfera de Dana', 'Encontre aqui informações essenciais sobre Dana, a maior reserva natural da Jordânia', 'Dana, Reserva da Biosfera de Dana, Reserva Florestal', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;A Reserva da Biosfera de Dana é a maior reserva natural da Jordânia, localizada no centro-sul do país. A reserva foi fundada em 1989 na área da vila de Dana e do vale de Dana, abrangendo uma região de 308 km².&lt;/p&gt;\r\n&lt;p&gt;O povo da tribo Ata&#039;ta (ou Al Atata) são os habitantes nativos da Reserva da Biosfera de Dana. Sua história em Dana data de 400 anos, mas seu assentamento original data de mais de 6000 anos. Além da presença do povo Ata&#039;ta, as descobertas arqueológicas sugerem assentamentos paleolíticos, egípcios, nabateus e romanos em Dana.&lt;/p&gt;\r\n&lt;p&gt;A Reserva da Biosfera de Dana vai de uma altitude de 1.500 metros no planalto de Qadisiyah até a área desértica de Wadi Araba. A geologia variada de Dana contém calcário, arenito e granito, e o vale possui falésias de arenito cortadas pelo vento. Dana é a única reserva natural na Jordânia que atravessa quatro zonas biogeográficas: Mediterrânea, Irã-Turaniana, Saara-Árabe e Sudaniana.&lt;/p&gt;\r\n&lt;p&gt;O ambiente diversificado de Dana abriga 703 espécies de plantas, 215 espécies de pássaros e 38 espécies de mamíferos. Dana é a área de vida vegetal mais diversificada do país, composta por vários tipos de vegetação, incluindo o zimbro fenício, carvalho verde e acácias. Dana é a área mais austral do mundo para hospedar o cipreste do Mediterrâneo, o “Cupressus sempervirens”. Das centenas de espécies de plantas que habitam Dana, três são encontradas apenas lá. Muitas plantas, especialmente árvores e arbustos, crescem nas terras altas da reserva natural.&lt;/p&gt;\r\n&lt;p&gt;A capra nubiana (íbex-da-núbia), o canário sírio, o caracal e o francelho menor são nativos de Wadi Dana.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Dana/DanaReserve.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d130545.41267706566!2d35.41421210493362!3d30.70507101520399!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1503c4aa62495d51:0x5272a01aefeb1b7b!2sDana Biosphere Reserve!5e0!3m2!1sen!2sjo!4v1567434620456!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 445, 'pt', '', 'one col', 'reserva-dana'),
(1975, 'Wadi Rum', 'Wadi Rum', 'Este é com certeza uma das paisagens mais incríveis do país.', 'Wadi Rum, deserto, filmes Jordânia', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Também conhecido como “O Vale da Lua&quot;, é uma área protegida no vale do sul da Jordânia. São 720 km² de deserto. Ao se chegar a Wadi Rum, é fácil entender por que ele foi escolhido como o cenário de filmes ambientados no planeta Marte, como o recente “Perdido em Marte” (2015). A cor de sua areia e suas rochas de granito, basalto e arenito esculpidas pelo vento criam um espetáculo natural como poucos no planeta.&lt;/p&gt;\r\n&lt;p&gt;Um labirinto de paisagens rochosas monolíticas se eleva do chão do deserto a alturas de 1.750m, impondo um desafio natural para os alpinistas sérios. Os caminhantes podem desfrutar da tranquilidade do vazio do deserto e descobrir os cânions, poços de água, e desenhos rupestres feitos nas rochas há 4000 anos, além de muitos outros tesouros espetaculares que esse vasto deserto reserva.&lt;/p&gt;\r\n&lt;p&gt;Por milhares de anos, pessoas habitaram Wadi Rum, lutando para sobreviver nas condições difíceis do deserto. Caçadores, agricultores, comerciantes e pastores chamaram essa área de lar. Até os famosos nabateus residiram em Wadi Rum, deixando para trás várias estruturas após sua partida.<br>Um passeio com um veículo 4x4, adentrando o deserto por quilômetros será a sua fuga da civilização em direção a um lugar onde se pode encontrar tranquilidade, paz, calma interior, e o silêncio, apesar do incessante cantar do vento.&lt;/p&gt;\r\n&lt;p&gt;Um por do sol deslumbrante e noites cheias de estrelas definitivamente fazem do deserto de Wadi Rum uma das maravilhas da Jordânia que não se pode perder.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/wadi-rum/Wadi Rum  website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d222100.77456736425!2d35.266207873795295!3d29.565157302724135!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1500926872782d31:0x33e433bd6669a483!2sWadi+Rum+Protected+Area!5e0!3m2!1sen!2sjo!4v1564843941559!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 416, 'pt', '', 'one col', 'wadi-rum'),
(1976, 'Teatro Romano', 'Teatro Romano', 'Saiba mais sobre este famoso marco da capital Amã.', 'Teatro Romano, Anfiteatro', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;O Teatro Romano de Amã data do século 2 e é um marco famoso na capital da Jordânia. O teatro foi construído no período romano, durante o reinado de Antonius Pius ( de 138 a 161), quando a cidade era conhecida como Filadélfia. O teatro e o vizinho Odeon ficam na Praça Hachemita, e o Nymphaeum (templo para as ninfas) fica a uma curta caminhada de lá.&lt;/p&gt;\r\n&lt;p&gt;Construída na encosta da colina, a estrutura é grande e inclinada, e orientada para o norte para manter o sol longe dos espectadores – o teatro podia acomodar cerca de 6.000 pessoas.&lt;/p&gt;\r\n&lt;p&gt;Foi dividido em três seções horizontais (diazomata). Entradas laterais (paradoi) existiam no nível do solo, uma levando à orquestra e a outra ao palco. Os quartos por trás dessas entradas agora abrigam o Museu da Tradição Popular da Jordânia e o Museu Folclórico da Jordânia.&lt;/p&gt;\r\n&lt;p&gt;A seção mais alta de assentos de um teatro, mesmo longe do palco, oferece aqui excelentes vistas, enquanto os atores podem ser ouvidos com clareza devido à inclinação da cavea.&lt;/p&gt;\r\n&lt;p&gt;O teatro agora é usado como local de atividades culturais, incluindo a Feira Internacional do Livro de Amã, a cerimônia de premiação da Maratona de Amã e concertos musicais, principalmente o Festival de Música Al-Balad.&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 14px; text-decoration-line: inherit;&quot;&gt;  &lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Amman/Roman Theater website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3385.3373746429806!2d35.93709841454884!3d31.951742881228967!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151ca07139c70a21:0xc5b2f8903093b109!2sRoman Theatre!5e0!3m2!1sen!2sjo!4v1569238232056!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 903, 'pt', '', 'one col', 'teatro-romano'),
(1977, 'Fontes Termais de Ma&#039;in', 'Fontes Termais de Ma&#039;in', 'Essas fontes ficam 58km ao sul de Amã e têm lindas cachoeiras.', 'Fontes termais, Ma&#039;in, Amã, Madaba, Águas termais, Jordânia, Wadi Mujib', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;As Fontes Termais de Ma&#039;in estão localizadas 58km ao sul de Amã, na província de Madaba, e a 27 km da cidade de Madaba, e são acessíveis por várias rotas. Está 120 metros abaixo do nível do mar. A região de Ma&#039;in contém um total de 63 fontes a diferentes temperaturas, mas de composição química semelhante, contendo elementos importantes como sódio, cálcio, cloreto, radônio, sulfeto de hidrogênio e dióxido de carbono. As temperaturas em algumas fontes atingem 63°C.&lt;/p&gt;\r\n&lt;p&gt;As fontes termais são aquecidas por água quente que vem do topo da montanha basáltica. As cachoeiras de Ma&#039;in descem do topo das montanhas e formam belas ondas, complementando as águas que cruzam a área protegida de Mujib em direção ao Mar Morto, através das montanhas de Ma&#039;in e até as nascentes.&lt;/p&gt;\r\n&lt;p&gt;Turistas frequentam as fontes termais em busca de tratamento para doenças físicas crônicas, como doenças da pele e circulatórias, dores nos ossos, articulações, costas e músculos. O tratamento com água quente também pode ser útil em casos de reumatismo crônico, espasmo muscular, dor nas costas, vasos sanguíneos, sinusite e tratamento contra exaustão nervosa e psicológica. Também estão disponíveis chuveiros, banhos de espuma, banheiras de hidromassagem, banhos para pés e tratamentos a vapor. O tratamento a vapor ajuda a curar doenças respiratórias crônicas, especialmente entre fumantes.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/more places/Main website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3397.907380099696!2d35.60676176515284!3d31.60899758134052!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1503462a9b32f693:0x8bde7907a1dce411!2sMa&#039;in Hot Springs!5e0!3m2!1sen!2sjo!4v1590604953982!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 908, 'pt', '', 'one col', 'fontes-termais-main'),
(1978, 'Umm ar-Rasas', 'Umm ar-Rasas', 'Este Patrimônio Mundial da UNESCO é valorizado pelos arqueólogos por suas extensas ruínas que datam dos períodos romano, bizantino e islâmico.', 'Umm ar-Rasas', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Umm ar-Rasas está localizado 30 km a sudeste de Madaba, no centro da Jordânia. Anteriormente, era acessível por estradas menores da “King’s Highway” (Rodovia do Rei), na região semi-árida do deserto da Jordânia.&lt;/p&gt;\r\n&lt;p&gt;As forças armadas romanas utilizaram o local como guarnição estratégica, que depois foram convertidas e habitadas por comunidades cristãs e islâmicas. Em 2004, Umm ar-Rasas se tornou Patrimônio Mundial da UNESCO e é valorizado pelos arqueólogos por suas extensas ruínas que datam dos períodos romano, bizantino e islâmico. O Studium Biblicum Franciscanum realizou escavações no extremo norte do local em 1986, mas grande parte da área permanece enterrada sob escombros.&lt;/p&gt;\r\n&lt;p&gt;A descoberta mais importante no local foi o piso de mosaico da Igreja de Santo Estêvão - perfeitamente preservado, este piso de mosaico é o maior da Jordânia. No painel central, são mostradas cenas de caça e pesca, enquanto outro painel ilustra as cidades mais importantes da região. A descoberta de inscrições gregas dentro dos mosaicos confirmou que eles datam de 756 a 785.&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 14px; text-decoration-line: inherit;&quot;&gt;  &lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Amman/Umm_ar-Rasas_12.JPG&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3401.8640093096997!2d35.91821121453478!3d31.50042158137617!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1504a7f97c1e3e51:0x49339bb222c31da4!2sUmm ar-Rasas!5e0!3m2!1sen!2sjo!4v1569243892218!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 913, 'pt', '', 'one col', 'umm-ar-rasas'),
(1979, 'Mesquita Rei Abdullah I', 'Mesquita Rei Abdullah I', 'Construída nos anos 80 pelo falecido Rei Hussein como um memorial a seu avô, esta bela mesquista está aberta a visitantes não muçulmanos.', 'Mesquita Rei Abdullah I, Mesquita, Amã, Religião, locais religiosos na Jordânia', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;A Mesquita Rei Abdullah I, de cúpula azul, foi construída nos anos 80 pelo falecido Rei Hussein como um memorial a seu avô. O local está aberto a visitantes não muçulmanos.&lt;/p&gt;\r\n&lt;p&gt;A mesquita tem uma área de 1.615 m² com capacidade para abrigar 3.000 fiéis. É octogonal e distinta por não ter pilares em seu interior. Sua cúpula de 35 metros de diâmetro tem uma altura de 31 metros. Uma fonte de radiação foi colocada no meio, com a forma de uma estrela dourada, culminando nos Noventa e Nove Nomes Mais Bonitos de Alá, ao redor da cúpula. O lustre suspenso de 168 lanternas consiste em três círculos com versos do sagrado Alcorão, com a palavra Alá escrita em todas as lanternas.&lt;/p&gt;\r\n&lt;p&gt;A terra fértil é expressa na forma de um tapete vermelho feito de um tecido ornamental destinado a direcionar os fiéis para a Qibla (direção a Caaba, em Meca). Todas as paredes, incluindo a Qibla, púlpito e o Mihrab, são revestidas com painéis de madeira e mármore.&lt;/p&gt;\r\n&lt;p&gt;Perto da entrada, há um pequeno museu islâmico, incluindo aquisições pessoais e fotos do falecido rei Abdullah Bin Al-Hussein.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Amman/king abdullah mosque website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3384.9898309254945!2d35.9107204145492!3d31.961172581225963!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151ca076535df843:0x796660fbe467ee11!2sKing Abdullah I Mosque!5e0!3m2!1sen!2sjo!4v1569245457631!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 918, 'pt', '', 'one col', 'mesquita-rei-abdullah-primeiro'),
(1980, 'Mesquita Rei Hussein Bin Talal', 'Mesquita Rei Hussein Bin Talal', 'Esta mesquita está localizada a uma altitude de 1.013 metros e pode ser vista de diversos pontos de Amã.', 'Mesquita, Amã, locais religiosos em Amã, Jordânia, Mesquita Rei Hussein Bin Talal', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;A Mesquita Rei Hussein Bin Talal, mais conhecida como Mesquita Rei Hussein, é a maior mesquita da Jordânia. Não deve ser confundida com a Mesquita Grand Al-Husseini de 1924, também conhecida como Mesquita do Rei Hussein, no centro de Amã.&lt;/p&gt;\r\n&lt;p&gt;A Mesquita Rei Hussein foi construída em 2005 no Oeste de Amã, dentro do parque público Al Hussein, na rua Rei Abdullah II, perto do Centro Médico Rei Hussein. A mesquita está localizada a uma altitude de 1.013 metros e pode ser vista de diversos pontos de Amã. Sua estrutura é quadrada e possui quatro minaretes e piso de mármore. Em 2012, o rei Abdullah abriu o Museu do Profeta Muhammad, que abriga várias relíquias associadas ao Profeta.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/more places/1024px-King_Hussein_Mosque_(Amman)_at_night.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3384.0842433839216!2d35.82072571454997!3d31.98573168121816!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151ca228d105489f:0x2228c0c01f0bf7fa!2sKing Hussein Mosque!5e0!3m2!1sen!2sjo!4v1573644095546!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1528, 'pt', '', 'one col', 'mesquita-rei-hussein-bin-talal'),
(1981, 'Rainbow Street', 'Rainbow Street', 'Esta é provavelmente a rua mais famosa de Amã.', 'Rainbow Street, Amã, cafés, bares', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;A Rainbow Street (rua do Arco-íris, originalmente chamada Rua Abu Bakr al Siddiq) fica na área histórica de Jabal Amman. A rua corre para o leste da cidade, desde o First Circle (Primeira Rotatória) à Rua Mango, e contém vários restaurantes e bares. Nesta rua também estão o prédio do British Council, a sede da Jordan Petroleum Refinery Company, e um cinema antigo (do qual a rua tomou o nome “Rainbow”).&lt;/p&gt;\r\n&lt;p&gt;A famosa rua é também o lar de locais importantes da história moderna da Jordânia, incluindo a Casa al-Mufti, a residência do rei Talal (“casa da Vó Alice”) e a casa do ex-comandante militar e primeiro-ministro Zaid ibn Shaker. O Souk Jara, onde há uma feira de artesanatos e produtos tradicionais toda sexta-feira durante o verão, também fica perto da rua.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Amman/rainbow st23.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3385.4282117289517!2d35.92458804454395!3d31.949277841625364!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151b5f9b6d0df885:0x5ba66d57515d5d4!2sRainbow St., Amman!5e0!3m2!1sen!2sjo!4v1569248025613!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 923, 'pt', '', 'one col', 'rainbow-street'),
(1982, 'Cidadela', 'Cidadela', 'Este importante local teve uma longa história de ocupação por muitas grandes civilizações.', 'Cidadela, Amã, Templo de Hércules, sítio arqueológico Jordânia', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;A Cidadela de Amã é um local histórico conhecido em árabe como Jabal al-Qal&#039;a. Fica no alto de uma colina em forma de L que é uma das sete jabals (montanhas) que originalmente compunham Amã. Neste local foram encontradas evidências de ocupação desde o período neolítico.&lt;/p&gt;\r\n&lt;p&gt;A área foi habitada por diferentes povos e culturas até a época dos omíadas, depois da qual houve um período de declínio. Na maior parte do tempo até 1878, a antiga cidade tornou-se uma pilha de ruínas abandonadas, esporadicamente usadas por beduínos e agricultores sazonais. Apesar dessa lacuna, a Cidadela de Amã é considerada um dos lugares mais antigos e continuamente habitados do mundo.&lt;/p&gt;\r\n&lt;p&gt;A Cidadela é considerada um local importante porque teve uma longa história de ocupação por muitas grandes civilizações. A maioria das construções ainda visíveis no local são dos períodos romano, bizantino e omíada. Os principais edifícios da Cidadela são o Templo de Hércules, uma igreja bizantina e o Palácio Omíada.&lt;/p&gt;\r\n&lt;p&gt;Embora os muros da fortificação envolvam apenas o centro do local, os antigos períodos de ocupação cobriam grandes áreas. Estruturas históricas, túmulos, arcos, paredes e escadas não têm fronteiras modernas e, portanto, existe um potencial arqueológico considerável neste local, bem como nas terras vizinhas e em Amã.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Templo de Hércules&lt;/strong&gt;<br><br>O Templo de Hércules é um local histórico na Cidadela de Amã, em Amã e é uma das estruturas romanas mais significativas do sítio arqueológico. Segundo escritas encontradas, o templo foi construído quando Geminius Marcianus era governador da Província da Arábia (anos 162 a 166).&lt;/p&gt;\r\n&lt;p&gt;O templo tem cerca de 30 por 24 metros de largura e complementado com um santuário externo de 121 por 72 metros. O pórtico tem seis colunas de 10 metros de altura. Os arqueólogos acreditam que, como não há restos de colunas adicionais, o templo provavelmente não estava terminado e o mármore foi usado para construir a Igreja Bizantina nas proximidades.&lt;/p&gt;\r\n&lt;p&gt;O local também contém fragmentos de uma colossal estátua de pedra parcialmente identificada como Hércules e estimada em mais de 12 m de altura. Provavelmente foi destruída em um terremoto e hoje tudo o que resta são três dedos e um cotovelo.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Palácio Omíada&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;O Palácio Omíada é um grande complexo palaciano do período Omíada, localizado na Colina da Cidadela de Amã. Construído durante a primeira metade do século 8, pode-se observar suas ruínas, com uma câmara de entrada que teve a cúpula restaurada, conhecida como &quot;quiosque&quot; ou &quot;portal monumental&quot;.&lt;/p&gt;\r\n&lt;p&gt;Parte do palácio foi construída sobre estruturas romanas pré-existentes, e uma rua romana com colunas inteiras foi incorporada a ela. Construído por volta de 730, quando Amã era uma capital da província, o complexo provavelmente combinava os bairros residenciais do governador de Amã com escritórios administrativos.&lt;/p&gt;\r\n&lt;p&gt;O local ainda estava em uso durante os períodos islâmico Abássida (750–969) e Fatímida (969–1179), embora grande parte do novo palácio nunca tenha sido reconstruído após um terremoto devastador em 749.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Amman/Citadel website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3385.243586215153!2d35.93324341466816!3d31.954287832784978!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151b5f96539bcc23:0x83d61bcf8e637e6d!2sAmman Citadel!5e0!3m2!1sen!2sjo!4v1569324137648!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 938, 'pt', '', 'one col', 'cidadela'),
(1983, 'Caverna dos Sete Dormentes', 'Caverna dos Sete Dormentes', 'Diz a lenda que sete meninos cristãos se esconderam de um imperador romano nesta caverna...', 'Caverna dos Sete Dormentes, Imperador Trajano', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;A lenda dos &#039;sete dormentes&#039; é sobre sete meninos cristãos que foram perseguidos pelo imperador romano Trajano. Os sete escaparam para uma caverna e dormiram lá por 309 anos. Esta atração em Amã é um dos vários locais onde a caverna supostamente estaria localizada. Dentro da caverna principal - também conhecida como Ahl Al Kahf (Caverna do Povo) - existem oito túmulos menores que são selados, embora um tenha um buraco através do qual pode-se ver uma coleção assustadora de ossos humanos.&lt;/p&gt;\r\n&lt;p&gt;Acima e abaixo da caverna estão as ruínas de duas mesquitas, e a cerca de 500m a oeste há um grande cemitério bizantino ligeiramente abandonado. A caverna fica à direita de uma grande mesquita na vila de Rajib, fora da estrada de Amã para Sabah. Os ônibus de Amã para Sabah passam a 500 metros da mesquita e pode-se tomá-los na estação de ônibus Wihdat; a viagem leva 15 minutos.&lt;/p&gt;\r\n&lt;p&gt;Outra opção é pegar um microônibus na Rua Quraysh, no centro da cidade. Peça &#039;Al Kahf&#039; e o motorista lhe mostrará onde descer para trocar de ônibus para Sabah. No entanto, a maneira mais fácil é usar táxis ou contratar um motorista.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Amman/thecaveofthesevensleepers.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3387.2847646299206!2d35.971619114547224!3d31.898859381246083!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151b5ecf5dbffffd:0x39e023872646a41d!2sCave of the Seven Sleepers - Ashabul Kahfi!5e0!3m2!1sen!2sjo!4v1569251792554!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 933, 'pt', '', 'one col', 'caverna-dos-sete-dormentes'),
(1984, 'Reserva Florestal de Ajlun', 'Reserva Florestal de Ajlun', 'Rara região da Jordânia, onde a natureza criou uma verde e vasta floresta.', 'Reserva florestal Ajlun, Ajlun, norte da Jordânia', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;A Reserva Florestal de Ajloun é uma reserva natural localizada na província de Ajloun, no noroeste da Jordânia. Foi criada em 1988 pela Sociedade Real para a Conservação da Natureza no entorno da vila de Umm Al-Yanabi e compreende uma área de 13 km².&lt;/p&gt;\r\n&lt;p&gt;A reserva abriga um programa de criação em cativeiro para a corça, um tipo de cervo extinto localmente. Em outubro de 2018, a Reserva Natural de Ajloun conquistou um lugar entre os 100 principais destinos sustentáveis no mapa global do turismo. A reserva abriga uma grande variedade de plantas e animais.&lt;/p&gt;\r\n&lt;p&gt;A natureza da reserva é rara na Jordânia, pois as áreas arborizadas representam apenas 1% da área do país. A geografia da reserva contém principalmente colinas e vales, além de algumas nascentes. Há também uma série de trilhas para turistas, que podem se hospedar em tendas ou cabanas entre os meses de março e novembro, desfrutando do clima mediterrâneo de Ajlun.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/more places/Ajloun forest reserve website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3369.329984173763!2d35.758272914562575!3d32.38351498109251!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151c7d17cb36d133:0x53bba70d2502bf6e!2sAjloun Forest Reserve!5e0!3m2!1sen!2sjo!4v1569327411898!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 943, 'pt', '', 'one col', 'reserva-florestal-ajlun'),
(1985, 'Reserva Florestal de Dibeen', 'reserva-florestal-dibeen', 'Esta reserva abriga um dos exemplos de flora mais antiga e original da Jordânia.', 'Reserva Florestal de Dibbeen, Floresta, Jordânia', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;A Reserva Florestal de Dibeen está localizada no noroeste da Jordânia. Fica ao sul de Jerash e cobre uma área de 8,5 km² de colinas cobertas de pinheiros e carvalhos. A área abriga os maiores “Pinheiros de Aleppo”, um dos exemplos de flora mais antiga e original da Jordânia.&lt;/p&gt;\r\n&lt;p&gt;Pelo menos 17 espécies ameaçadas foram identificadas na reserva, incluindo o esquilo-vermelho persa, quatro tipos de morcegos, lobos cinzentos e hienas listradas. Os pássaros da floresta também vivem na floresta. Também se acredita, mas não está provado, que esta reserva tenha a última população de Tritões Listrados do Sul que vivem na Jordânia.&lt;/p&gt;\r\n&lt;p&gt;A área foi protegida como reserva natural em 2004, sob a iniciativa da Sociedade Real para a Conservação da Natureza. A floresta é conhecida como o lugar mais seco da região e abrange 60km com variadas altitudes de 500 a 1000 metros acima do nível do mar. As rochas da reserva são uma mistura de tipos de calcário que formaram encostas íngremes.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Amman/dibeen.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3374.4793190297023!2d35.8053235!3d32.245183499999996!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151c843e1ede9d9f:0xcf22a0306db1d0d6!2sDibbeen Forest Reserve!5e0!3m2!1sen!2sjo!4v1569330505118!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 948, 'pt', '', 'one col', 'reserva-florestal-de-dibbeen'),
(1986, 'Reserva de vida selvagem de Shaumari', 'Reserva de vida selvagem de Shaumari', 'Pequena reserva próxima da cidade de Azraq, onde há um grande rebanho de magníficos Órixes da Árabia.', 'Shaumari, Reserva de vida selvagem, Azraq', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;A Reserva de Shaumari fica perto da cidade de Azraq, a aproximadamente 100km ao leste de Amã. É uma reserva de importância regional criada em 1975 pela Sociedade Real para a Conservação da Natureza como um centro de reprodução para manter a vida selvagem no país.&lt;/p&gt;\r\n&lt;p&gt;Nesta pequena reserva de 22km², há um grande rebanho de magníficos Órixes da Árabia. Existem também avestruzes, onagros e graciosas gazelas do deserto. Esses animais são protegidos da caça e destruição de habitats que antes ameaçavam sua existência. A Reserva Shawmari abriga uma rica variedade de plantas do deserto, incluindo Atriplex, uma fonte natural de alimentos para os onagros e órixes.&lt;/p&gt;\r\n&lt;p&gt;Uma área de playground e piquenique está localizada nas dependências externas do Centro de Visitantes. A torre de observação é o local perfeito para apreciar a vida selvagem da reserva – as primeiras horas da manhã são as melhores para observar o órix em seu ambiente natural.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Natural Reserves/Shaumari website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d434296.30246477743!2d36.50174023281251!3d31.744842400000014!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151ae73d85479d73:0x62da93d4f0cd05ac!2sShawmari Wildlife Reserve!5e0!3m2!1sen!2sjo!4v1571307355790!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1323, 'pt', '', 'one col', 'reserva-shaumari');
INSERT INTO `en33_pages` (`id`, `name`, `title`, `meta_desc`, `meta_key`, `contents`, `published`, `lang_id`, `lang`, `icon`, `layout`, `url`) VALUES
(1987, 'Reserva natural de Azraq', 'Reserva natural de Azraq', 'Este oásis é uma área única na Jordânia e tem uma importância que data de séculos.', 'Oásis, Azraq, Jordânia, Reserva natural', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Azraq é um singular oásis de zonas úmidas no deserto semi-árido do leste da Jordânia, perto da cidade de Azraq. Esta é uma das várias e belas reservas naturais geridas pela Sociedade Real para a Conservação da Natureza. A reserva de Azraq foi fundada em 1978 e abrange 12km². Fazem parte das suas atrações várias lagoas naturais e antigas, um terreno pantanoso que é inundado conforme a estação do ano e um lodaçal conhecido como Qa&#039;a Al-Azraq. Uma ampla variedade de aves faz uma paragem na reserva todos os anos para descansar das árduas rotas migratórias entre a Ásia, Europa e África.&lt;/p&gt;\r\n&lt;p&gt;A melhor época para visitar Azraq é no final do Outono, do Inverno ou do Verão. A água das chuvas cria com frequência lagoas e pântanos na reserva que continuam a atrair várias espécies de aves sazonais. O êxito das visitas para observar aves depende, em grande parte, da quantidade de água acumulada na reserva.&lt;/p&gt;\r\n&lt;p&gt;Azraq tem uma história geológica muito interessante. As zonas úmidas foram criadas a cerca de 250.000 anos atrás, e suas lagoas são preenchidas por uma complexa rede de aquíferos alimentados principalmente pela área de Jabal al-Druze no sul da Síria – as águas demoram 50 anos para seguir o seu rumo. Embaixo do oásis também existe uma grande concentração de sal, e as famílias da região sobrevieram por décadas graças à sua extração.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Natural Reserves/wetland.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d434293.6999982929!2d36.5017375889217!3d31.74539733502253!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151aefcdd0feb1e3:0xd129e902745e4a7f!2zQXpyYXEgV2V0bGFuZCBSZXNlcnZlINmF2K3ZhdmK2Kkg2KfZhNij2LLYsdmCINin2YTZhdin2KbZitip!5e0!3m2!1sen!2sjo!4v1571310160856!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1328, 'pt', '', 'one col', 'reserva-azraq'),
(1988, 'Reserva Florestal de Yarmouk', 'Reserva Florestal de Yarmouk', 'Esta reserva florestal está localizada no noroeste da Jordânia, na fronteira com as colinas de Golã.', 'Reserva Florestal de Yarmouk, Colinas de Golã, Norte da Jordânia', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Anunciada como reserva natural em 2010 pelo Primeiro Ministro, Yarmouk passou a fazer parte da rede de reservas nacionais administrada e gerenciada pela Sociedade Real para a Conservação da Natureza.&lt;/p&gt;\r\n&lt;p&gt;A Reserva Florestal de Yarmouk está localizada no noroeste da Jordânia, na fronteira com as colinas de Golã, e sua área total é de 20 km2. Yarmouk contém duas áreas topográficas principais: montanhas cobertas por carvalhos até 500 m de altura acima do nível do mar, pontuadas por vales de pequenas e médias descidas em direção ao rio Yarmouk. Esses pequenos e médios vales descendentes têm um escoamento sazonal, com exceção do vale Shag Al Bared.&lt;/p&gt;\r\n&lt;p&gt;A reserva está na zona biogeográfica do Mediterrâneo, o que proporciona um clima quente no verão e frio no inverno.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Natural Reserves/Yarmouk.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d429949.15073077497!2d35.406596132812496!3d32.660036500000004!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151c6cfa069372d5:0x68b2414e1a73135e!2sYarmouk Nature Reserve!5e0!3m2!1sen!2sjo!4v1571312238579!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1333, 'pt', '', 'one col', 'reserva-yarmouk'),
(1989, 'Wadi Mujib', 'Wadi Mujib', 'Esta é a reserva natural de altitude mais baixa do mundo e com uma paisagem fantástica perto da costa leste do Mar Morto.', 'Mar Morto, Wadi Mujib, Karak, Madaba, Reserva Biosfera de Mujib', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Reserva Biosfera de Mujib é a reserva natural com a altitude mais baixa do mundo com a sua paisagem fantástica perto da costa leste do Mar Morto. A reserva situa-se no fundo do desfiladeiro de Wadi Mujib que entra no Mar Morto a 410 m acima do nível do mar.&lt;/p&gt;\r\n&lt;p&gt;A reserva estende-se pelas montanhas de Karak e Madaba para o Norte e para o Sul, alcançando os 900 m acima do nível do mar em alguns pontos. Esta variação de 1300 m de altitude, combinada com o fornecimento anual de água para o vale vindo de sete afluentes, significa que Wadi Mujib tem uma magnífica biodiversidade que ainda hoje é explorada e documentada. Foram registadas mais de 300 espécies de plantas, 10 espécies de carnívoros e variadas espécies de aves permanentes e migratórias.&lt;/p&gt;\r\n&lt;p&gt;Algumas das áreas remotas da montanha e do vale são difíceis de alcançar, constituindo um porto de abrigo para várias espécies de felídeos, cabras e outros animais da montanha. Os penhascos de arenito de Mujib são o habitat natural de uma das cabras de montanha mais belas do mundo: o íbex-da-núbia (capra nubiana).&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Natural Reserves/River-canyon-of-Wadi-Mujib.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d871616.856943661!2d35.26433948772292!3d31.420921119192695!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1503389aa3d5d8cf:0xcb15ddf0bb1651df!2sWadi Al Mujib!5e0!3m2!1sen!2sjo!4v1571386522932!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1338, 'pt', '', 'one col', 'wadi-mujib'),
(1990, 'Irbid', 'Irbid', 'Com antigas origens, Irbid é a segunda maior cidade da Jordânia.', 'Irbid, maiores cidades da Jordânia', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Irbid é a segunda maior cidade da Jordânia e uma breve caminhada pelo famoso museu Dar As-Saraya revela suas antigas origens. Instalado em um edifício tradicional de estilo otomano do século 19, o museu apresenta várias exposições de cerâmica, esculturas, mosaicos e jóias que remontam a 3200 AC. Reserve alguns minutos para sentar e apreciar o belo pátio do edifício ao sair, que apresenta vários sarcófagos antigos.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Entre em qualquer padaria nesta época do ano e encante seus olhos com o tradicional pão Eid de Irbid, assado com anis e gergelim preto em comemoração ao Ramadã. Caso deseje mais variedade, confira o sofisticado Jawharat Al-Sharq, que oferece uma variedade de doces de confeitaria. O famoso kunafeh, sobremesa de queijo com uma camada de sêmola e uma calda de açúcar, também deve ser apreciada!&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;span&gt;Na região de Irbid, Umm Qays e Pella (conhecida localmente por Tabaqit Fahl) foram &lt;/span&gt;&lt;a target=&quot;_blank&quot; href=&quot;http://pt.visitjordan.com/Portals/0/decapolis.html&quot; rel=&quot;noopener&quot;&gt;cidades da Liga de Decápolis&lt;/a&gt;&lt;span&gt;, e cada uma tem o seu próprio encanto.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/more places/Irbid.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d53808.15680382611!2d35.81239002226448!3d32.55258369412188!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151c76916dac0453:0x5416e113d81f7d82!2sIrbid!5e0!3m2!1sen!2sjo!4v1571645112419!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1372, 'pt', '', 'one col', 'irbid'),
(1991, 'Jerash', 'Jerash', 'Esta cidade é um símbolo da grandeza da Roma Imperial, sendo um dos maiores e mais bem preservados locais da arquitetura romana no mundo fora da Itália.', 'Jerash, ruínas romanas, cidades históricas da Jordânia, Gerasa', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Jerash fica a 48 km ao norte de Amã e se localiza em um vale entre as montanhas de Gileade. Esta cidade é um símbolo da grandeza da Roma Imperial, sendo um dos maiores e mais bem preservados locais da arquitetura romana no mundo fora da Itália. Esta cidade fascinante é um ótimo destino para uma viagem de um dia (saindo de Amã), principalmente na primavera, quando as flores silvestres estão florescendo. A viagem levará menos de uma hora, mas o transportará 2000 anos no tempo.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;A era dourada da cidade foi durante o domínio romano, durante o qual era conhecida por Gerasa. Escondida durante séculos na areia, antes de ser escavada e restaurada nos últimos 70 anos, Jerash é um belo exemplo do grandioso urbanismo romano provincial que é encontrado por todo o Oriente Médio com ruas pavimentadas de colunatas, templos no topo das colinas, belos teatros, amplas praças públicas, banhos públicos, fontes e muralhas da cidade nervuradas por torres e portas. Por debaixo da sua aparência externa greco-romana, Jerash preserva ainda uma mistura sutil do oriente e do ocidente. A sua arquitetura, religião e idiomas refletem um processo de união e coexistência de duas poderosas culturas: o mundo greco-romano da bacia do Mediterrâneo e as tradições do Oriente Árabe.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Jerash se desenvolveu dramaticamente no século passado, com a crescente importância da indústria do turismo na cidade. Jerash é agora a segunda atração turística mais popular na Jordânia, logo atrás das ruínas de Petra. No lado oeste da cidade, que continha a maioria dos edifícios representativos, as ruínas foram cuidadosamente preservadas, com a cidade moderna se estendendo para o leste do rio, que uma vez dividiu a antiga Jerash em dois.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Os pontos turísticos mais importantes em Jerash são o Fórum Oval, o Teatro Norte, o Cardo Maximus, O Hipódromo, as Colunas de Jerash, o Arco de Adriano.<br>&lt;strong style=&quot;font-family: inherit; font-style: inherit; font-variant-ligatures: inherit; font-variant-caps: inherit; text-decoration-line: inherit;&quot;&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong style=&quot;font-family: inherit; font-style: inherit; font-variant-ligatures: inherit; font-variant-caps: inherit; text-decoration-line: inherit;&quot;&gt;Fórum Oval&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;O Fórum Oval é uma espaçosa praça que mede 90m x 80m e é cercada por uma série de colunas jônicas do século I. Existem duas alterações no meio da praça, e uma fonte foi adicionada no século 7. Há também uma coluna central que foi recentemente erguida para carregar a Chama do Festival de Jerash. Além de abrigar o comércio daquele tempo, a praça era um local de reunião com grande significado social. Frequentemente era cenário de diversas atividades, incluindo discussões, debates políticos e encontros.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Desde 1981, Jerash recebe o Festival de Cultura e Artes de Jerash, um programa de verão de três semanas de dança, música e apresentações teatrais. O festival é frequentado até por membros da família real da Jordânia e é considerado uma das maiores atividades culturais da região.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Jerash/Jerash website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&amp;gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d107953.79358006279!2d35.82443685141487!3d32.270025073525034!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151c802ff49ac08d:0x876c24b1cbded302!2sJerash!5e0!3m2!1sen!2sjo!4v1571647837414!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1377, 'pt', '', 'one col', 'jerash'),
(1992, 'Al-Salt', 'Al-Salt', 'A menos de uma hora da capital, Al-Salt é cercada por vistas deslumbrantes e apresenta um contraste interessante com as áreas mais ocidentalizadas de Amã.', 'Al-Salt, Salt, As-Salt, cidades perto de Amã', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Al-Salt é uma próspera cidade localizada ao noroeste da capital Amã. Construída em três montanhas principais (Cadital, Gadaa e Salalem), Al-Salt é cercada por vistas deslumbrantes e apresenta um contraste interessante com as áreas mais ocidentalizadas de Amã (As-Salt fica apenas a uma hora da capital).&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;A antiga cidade de As-Salt já foi a concentração populacional mais importante na zona entre o Vale do Jordão e o deserto do leste. Devido à sua história como importante elo de ligação do comércio entre o deserto leste e o ocidente, foi um local importante para vários governantes da região.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Os romanos, os bizantinos e os mamelucos todos contribuíram para o crescimento da cidade, mas foi no final do século 19 e início do século 20, durante o domínio otomano, que As-Salt viveu o seu período áureo.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Foi nessa altura que os otomanos estabeleceram uma base administrativa regional em As-Salt e encorajaram a fixação de população vinda de outras partes do império. À medida que o status da cidade crescia, foram chegando muitos mercadores que, graças à sua recente fortuna, construíram as belas casas que ainda hoje podemos admirar em As-Salt.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Estes esplêndidos edifícios de arenito amarelo incorporam uma variedade de estilos locais e europeus. Normalmente, têm telhados em cúpula, pátios interiores e inconfundíveis janelas altas e arqueadas. Porventura, a mais bela será a mansão Abu Jaber, construída entre 1892 e 1906, com afrescos no teto executados por pintores italianos e conhecida por ser o primeiro grande exemplo de casa de mercadores do século 19 na região.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;No Museu Arqueológico e Folclórico de As-Salt encontramos artefactos que remontam ao período Calcolítico (Idade do Cobre) da era Islâmica, bem como outros objetos relacionados à história da região. No museu folclórico encontramos uma boa representação de trajes beduínos tradicionais e objetos do dia-a-dia.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/more places/AsSalt website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d108235.86286854355!2d35.65597184349933!3d32.03215570058939!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151cbd5c659cb8a7:0x31d4c6ecaa51cc1e!2sAs-Salt!5e0!3m2!1sen!2sjo!4v1571649630665!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1382, 'pt', '', 'one col', 'al-salt'),
(1993, 'Karak', 'Karak', 'Localizada nas antigas rotas de caravanas que costumavam conectar o Egito à Síria, Karak tem sido um bem precioso de várias civilizações.', 'Karak, cruzados', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Conhecida por toda a história como Qir Heres, Qir Moab e Hareseth, Karak tem sido um bem precioso de várias civilizações. Encontra-se nas antigas rotas de caravanas que costumavam conectar o Egito à Síria, e sua posição a quase 1000 metros acima do Vale do Mar Morto a tornou um local estratégico de grande importância. A cidade era a antiga capital de Moabe, e também era usada pelos gregos e romanos. Durante o tempo dos romanos, era conhecida como Characmoba.&lt;/p&gt;\r\n&lt;p&gt;Mas não foi até a chegada dos cruzados no século 12 que Karak alcançou todo o seu esplendor. Está registrado que o rei dos cruzados Baldwin I de Jerusalém mandou construir o castelo em 1132. Com sua localização a meio caminho entre Shobak e Jerusalém, Karak fazia parte de uma grande linha de castelos cruzados que se estende de Aqaba à Turquia.&lt;/p&gt;\r\n&lt;p&gt;Hoje, a cidade abriga cerca de 170.000 pessoas e continua a apresentar uma série de edifícios, restaurantes e lugares otomanos restaurados do século 19. Al-Karak fica 140km ao sul de Amã, na antiga Estrada do Rei.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/more places/Karak.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d109223.4092580792!2d35.624884392202624!3d31.18659284517212!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15037a1f8e1a87a9:0x98bd1406f49b95d4!2sKerak!5e0!3m2!1sen!2sjo!4v1571817734078!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1387, 'pt', '', 'one col', 'karak'),
(1994, 'Umm Qays and Pella', 'Umm Qays and Pella', 'Perched on a splendid hilltop overlooking the Jordan Valley and the Sea of Galilee, Gadara is known today as Umm Qays, and boasts an impressive colonnaded street, a vaulted terrace, and the ruins of two theatres.', 'Umm Qais, Pella, Irbid, historical cities, ancient cities, Jordan, Gadara', '<div class=\"row\">\r\n<div class=\"md-7\" style=\"text-align: justify;\">\r\n<p></p>\r\n<p><span></span></p>\r\n<p style=\"text-align: justify;\"><span>A northern town perched on top of a hill, Um Qais is home to the ancient Gadara ruins. Located right at the axis of Jordan’s borders with Palestine, Israel and Syria, you can enjoy the site’s stunning panoramic views of the Sea of Gallilee, the Golan Heights, and the Yarmouk River.  You can take in the sights and then dine on the terrace of a fine restaurant with a breathtaking view.<br /></span><br />Site of the famous miracle of the Gadarene swine, Gadara was renowned in its time as a cultural centre. It was the home of several classical poets and philosophers, including Theodorus, founder of a rhetorical school in Rome, and was once called “a new Athens” by a poet. <br /><br />Umm Qays (Gadara), built using stunning black basalt stones, was one of the cities of the Decapolis, planned with a Roman city layout. The Ottoman village on top of part of the ancient city was acquired by the Department of Antiquities, who now has several excavation and conservation projects at the site, including the restoration of the main (west) theatre.</p>\r\n<p><strong>Pella</strong></p>\r\n<p>A 40-minute ride from Umm Qays, Pella is a favourite of archaeologists as it is exceptionally rich in antiquities, some of which are exceedingly old. Besides the excavated ruins from the Graeco-Roman period, including an Odeon (theater), Pella offers visitors the opportunity to see the remains of a Chalcolithic settlement from the 4th millennium BC, the remains of Bronze and Iron Age walled cities, Byzantine churches and houses, an Early Islamic residential quarter, and a small medieval mosque.</p>\r\n<p style=\"text-align: justify;\"></p>\r\n</div>\r\n<div class=\"md-5 d-pad-t\"> <img class=\"full-width\" src=\"uploads/filemanager/Photos/Um-Qais/Umm Qais website 800x500.jpg\" /></div>\r\n<div class=\"md-12\"> \r\n<p> <iframe width=\"100%\" height=\"300\" style=\"border: 0;\" src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d53742.77343421341!2d35.663552711512786!3d32.66148410016477!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151c6d07287b7199:0x96d0d420e01bf0b1!2sUmm Qais!5e0!3m2!1sen!2sjo!4v1590496227252!5m2!1sen!2sjo\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe></p>\r\n</div>\r\n</div>', 1, 1994, 'en', '', 'one col', 'umm-qays-pella'),
(1995, 'Umm Qays et Pella', 'Umm Qays et Pella', 'Tout comme Jérash et Amman, Umm Qays (aujourd&#039;hui Gadara) et Pella (appelée Tabaqit Fahl par les habitants) faisaient autrefois partie des Decapolis cities, chacune dotée d&#039;attraits uniques.', 'Umm Qais, Pella, Irbid, historical cities, ancient cities, Jordan, Gadara', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;<br>Site du fameux « miracle du cochon », Gadara était réputée à l&#039;époque comme centre culturel. Plusieurs poètes et philosophes y ont habité, notamment Théodore, fondateur de l&#039;école de rhétorique de Rome. Un poète a même nommé cette ville « la nouvelle Athènes ». Perchée sur la crête d&#039;une splendide colline surplombant la vallée du Jourdain et la mer de Galilée, Gadara est connue aujourd&#039;hui sous le nom d&#039;Umm Qays. Elle est renommée pour son immense terrasse voûtée et ses rues à colonnades ainsi que pour les ruines de deux théâtres. Admirez le spectacle puis dînez sur la terrasse d&#039;un bon restaurant, avec une vue à couper le souffle sur trois pays.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Les sources thérapeutiques d&#039;eaux chaudes d&#039;Al-Himma sont situées à environ 10 km au nord d&#039;Umm Qays et étaient très prisées des Romains. Il existe deux stations thermales : une station privée de qualité et une station publique avec des horaires différents pour les hommes et les femmes.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Pella est un site particulièrement apprécié des archéologues pour sa richesse exceptionnelle en antiquités, dont certaines sont très anciennes. Outre des ruines gréco-romaines, dont un odéon (théâtre), Pella offre à ses visiteurs le spectacle des vestiges de peuplement chalcolithique datant du 4è millénaire av. J.-C., des vestiges de cités fortifiées datant de l&#039;âge du bronze et du fer et des maisons et églises byzantines, ainsi que les vestiges d&#039;un quartier résidentiel du début de l&#039;ère islamique et d&#039;une petite mosquée médiévale&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Um-Qais/Umm Qais website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d53742.77343421341!2d35.663552711512786!3d32.66148410016477!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151c6d07287b7199:0x96d0d420e01bf0b1!2sUmm Qais!5e0!3m2!1sen!2sjo!4v1590496227252!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1994, 'fr', '', 'one col', 'umm-qays-pella'),
(1996, 'Umm Qays y Pella', 'Umm Qays y Pella', 'Además de Jerash y Amán, Umm Qays (la actual Gadara) y Pella (conocida como Tabaqat Fahil) fueron en la antigüedad ciudades de la Decápolis y cada una tiene un atractivo único.', 'Umm Qays, Pella, Irbid, Gadara, ruinas, antigüedades', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;<br>Lugar en el que tuvo lugar el milagro del endemoniado de Gadara, fue considerada en su tiempo un importante centro cultural. Fue el hogar de varios poetas y filósofos clásicos como Teodoro, fundador de la escuela retórica de Roma. Un poeta describió la ciudad como la “Nueva Atenas”. Enclavada en la cumbre de una colina con vistas al Valle del Jordán y al mar de Galilea, Gadara es conocida actualmente como Umm Qays y posee unas impresionantes calles con columnas y las ruinas de dos teatros. Visite los lugares de interés y después, cene en la terraza de algún restaurante, donde podrá disfrutar de las increíbles vistas de tres países.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Las aguas termales terapéuticas de Al-Himma están aproximadamente a 10 km al norte de Umm Qays y fueron muy valoradas por los romanos. Existen dos instalaciones para el baño: un complejo lujoso privado de alta calidad y un complejo de baños públicos con horarios diferentes para hombres y mujeres.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Pella es la ciudad favorita de los arqueólogos, ya que tiene una enorme cantidad de antigüedades. Además de las ruinas excavadas del período grecorromano, incluyendo un odeón (teatro), Pella ofrece a los visitantes la oportunidad de admirar los restos de un asentamiento calcolítico perteneciente a cuatro mil años aC, vestigios de las ciudades amuralladas de las Edades del Bronce y del Hierro, iglesias y casas bizantinas, un barrio residencial islámico y una pequeña mezquita medieval.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Um-Qais/Umm Qais website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d53742.77343421341!2d35.663552711512786!3d32.66148410016477!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151c6d07287b7199:0x96d0d420e01bf0b1!2sUmm Qais!5e0!3m2!1sen!2sjo!4v1590496227252!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1994, 'es', '', 'one col', 'umm-qays-pella'),
(1997, 'أم قيس‎', 'أم قيس‎', 'Perched on a splendid hilltop overlooking the Jordan Valley and the Sea of Galilee, Gadara is known today as Umm Qays, and boasts an impressive colonnaded street, a vaulted terrace, and the ruins of two theatres.', 'Umm Qais, Pella, Irbid, historical cities, ancient cities, Jordan, Gadara', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;span&gt;A northern town perched on top of a hill, Um Qais is home to the ancient Gadara ruins. Located right at the axis of Jordan’s borders with Palestine, Israel and Syria, you can enjoy the site’s stunning panoramic views of the Sea of Gallilee, the Golan Heights, and the Yarmouk River.  You can take in the sights and then dine on the terrace of a fine restaurant with a breathtaking view.<br>&lt;/span&gt;<br>Site of the famous miracle of the Gadarene swine, Gadara was renowned in its time as a cultural centre. It was the home of several classical poets and philosophers, including Theodorus, founder of a rhetorical school in Rome, and was once called “a new Athens” by a poet. <br><br>Umm Qays (Gadara), built using stunning black basalt stones, was one of the cities of the Decapolis, planned with a Roman city layout. The Ottoman village on top of part of the ancient city was acquired by the Department of Antiquities, who now has several excavation and conservation projects at the site, including the restoration of the main (west) theatre.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Pella&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;A 40-minute ride from Umm Qays, Pella is a favourite of archaeologists as it is exceptionally rich in antiquities, some of which are exceedingly old. Besides the excavated ruins from the Graeco-Roman period, including an Odeon (theater), Pella offers visitors the opportunity to see the remains of a Chalcolithic settlement from the 4th millennium BC, the remains of Bronze and Iron Age walled cities, Byzantine churches and houses, an Early Islamic residential quarter, and a small medieval mosque.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Um-Qais/Umm Qais website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d53742.77343421341!2d35.663552711512786!3d32.66148410016477!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151c6d07287b7199:0x96d0d420e01bf0b1!2sUmm Qais!5e0!3m2!1sen!2sjo!4v1590496227252!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1994, 'Ar', '', 'one col', 'umm-qays-pella'),
(1998, 'Umm Qays / Pella', 'Umm Qays / Pella', 'Oltre a Jarash e Amman, Umm Qays (anticamente Gadara) e Pella (nota localmente come Tabaqit Fahl) furono un tempo città della Decapoli e sono entrambe caratterizzate da un&#039;atmosfera inconfondibile.', 'Umm Qays, Pella, Irbid, archeologi, Gadara', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;<br>Località in cui avvenne il famoso miracolo dei maiali di Gadara, l&#039;omonima città è stata in passato un rinomato centro culturale. Patria di molti poeti e filosofi classici, tra cui Teodoro, fondatore della scuola retorica a Roma, fu ribattezzata &quot;nuova Atene&quot; da uno di essi. Abbarbicata su una splendida altura sovrastante la Valle del Giordano e il Mare di Galilea, Gadara, oggi nota come Umm Qays, vanta splendide strade colonnate, una terrazza dal tetto a volta e le rovine di due teatri. Sfruttate l&#039;occasione per cenare sulla terrazza di un ottimo ristorante e godervi la vista mozzafiato di tre nazioni diverse.<br><br>Le calde sorgenti terapeutiche di Al-Himma si trovano a circa 10 Km a nord di Umm Qays ed erano già apprezzate dai Romani. Sono presenti due impianti termali: un complesso privato e uno pubblico, con orari di accesso separati per uomini e donne.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;<br>&lt;strong&gt;Pella&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Pella è uno dei siti preferiti dagli archeologi per la copiosità dei ritrovamenti, alcuni di straordinaria antichità. Oltre alle rovine del periodo greco-romano, tra cui un teatro, Pella offre ai visitatori l&#039;opportunità di ammirare i resti di un insediamento calcolitico del IV millennio a.C., di altre città fortificate delle Età del bronzo e del ferro, chiese e case bizantine, un antico quartiere residenziale islamico e una piccola moschea medievale.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Um-Qais/Umm Qais website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d53742.77343421341!2d35.663552711512786!3d32.66148410016477!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151c6d07287b7199:0x96d0d420e01bf0b1!2sUmm Qais!5e0!3m2!1sen!2sjo!4v1590496227252!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1994, 'it', '', 'one col', 'umm-qays-pella'),
(1999, 'Umm Qays / Pella', 'Umm Qays / Pella', 'Neben Jerash und Amman gehörten auch Umm Qays (früher Gadara) und Pella (lokal als Tabaqit Fahl bezeichnet) einst zu den Städten der Dekapolis, wobei jede Stadt ihre eigenen Reize hat.', 'Umm Qays, Pella, Gadara, Irbid', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;In Gadara vollbrachte Jesus das berühmte Wunder der Schweine von Gadara. In ihrer Blütezeit war die Stadt als kulturelles Zentrum bekannt. Es war die Heimat zahlreicher Dichter und Philosophen, u. a. Theodorus, des Gründers einer Rhetorikschule in Rom. Von einem Dichter wurde Umm Qays gar als „neues Athen“ bezeichnet. Das auf einem wunderschönen Hügel mit Blick über das Jordantal und den See Genezareth gelegene Gadara heißt heute Umm Qays und begeistert seine Besucher mit seinen Kolonnandenstrassen und den Ruinen zweier Theater. Genießen Sie eine Mahlzeit auf der Terrasse eines der hervorragenden Restaurants und bewundern Sie währenddessen den atemberaubenden Blick auf dieses Dreiländereck.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;10 km nördlich von Umm Qays liegen die heißen Heilquellen von Al-Himma, die bereits von den Römern hoch geschätzt wurden. Es gibt dort zwei Badehäuser: einen privat geführten Komplex und ein öffentliches Bad mit nach Geschlechtern getrennten Öffnungszeiten.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;strong&gt;Pella&lt;/strong&gt;<br><br>Pella ist bei Archäologen wegen seines Vielzahl an antiken Stätten extrem beliebt. Außer den freigelegten Ruinen aus der griechisch-römischen Zeit, zu denen u. a. ein Amphitheater zählt, lädt Pella den Besucher ein, eine Siedlung aus der Kupferzeit, d. h. aus dem 4. Jahrtausend v. Chr., sowie Überreste von ummauerten Städten aus der Bronze- und Eisenzeit, byzantinische Kirchen und Häuser sowie ein frühislamisches Wohnviertel und eine kleine Moschee aus dem Mittelalter zu besichtigen.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Um-Qais/Umm Qais website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d53742.77343421341!2d35.663552711512786!3d32.66148410016477!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151c6d07287b7199:0x96d0d420e01bf0b1!2sUmm Qais!5e0!3m2!1sen!2sjo!4v1590496227252!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1994, 'ge', '', 'one col', 'umm-qays-pella'),
(2000, 'Umm Qays e Pella', 'Umm Qays e Pella', 'Além de Jerash e Amã, Umm Qays (anteriormente Gadara) e Pella (localmente conhecido como Tabaqit Fahl) já foram cidades em Decapolis, e cada uma tem seu próprio charme.', 'Pella, Umm Qays, Gadara, Irbid, cidades antigas, ruínas', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Umm Qays (pronunciado Qeis) está ao norte, no topo de uma colina, e abriga as ruínas da antiga cidade conhecida como Gadara: ruas com colunatas, terraços abobadados e ruínas de dois teatros. Localizada bem no eixo das fronteiras da Jordânia com a Palestina, Israel e Síria, é possível apreciar as deslumbrantes vistas panorâmicas do local sobre o Mar da Galileia, as Colinas de Golã e o Rio Yarmouk.&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Local do conhecido milagre dos porcos de Gadarene, Gadara era conhecida na sua época por ser um centro cultural. Lá moravam vários poetas clássicos e filósofos, incluindo Teodoro, o fundador da escola retórica em Roma; um poeta apelidou a cidade de &quot;nova Atenas&quot;. As águas termais de Al-Himma ficam a 10 km ao norte de Umm Qays e eram altamente apreciadas pelos antigos romanos. Há duas instalações: um complexo gerido por privados e um complexo de banhos públicos com horários separados para homens e mulheres.<br><br>&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Pella&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Localmente conhecida como Tabaqit Fahl, Pella fica a cerca de 40 minutos de Umm Qays. É extremamente popular entre os arqueólogos por causa de sua variedade de locais antigos. Além das ruínas descobertas do período greco-romano, que incluem um anfiteatro, Pella convida o visitante a visitar um assentamento da Idade do Cobre, restos de cidades muradas da Idade do Bronze e Ferro, igrejas e casas bizantinas, bem como uma área residencial islâmica primitiva e uma pequena mesquita da Idade Média.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Um-Qais/Umm Qais website 800x500.jpg&quot; /&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; \r\n&lt;p&gt; &lt;iframe width=&quot;100%&quot; height=&quot;300&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d53742.77343421341!2d35.663552711512786!3d32.66148410016477!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151c6d07287b7199:0x96d0d420e01bf0b1!2sUmm Qais!5e0!3m2!1sen!2sjo!4v1590496227252!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1994, 'pt', '', 'one col', 'umm-qays-pella'),
(2001, 'How to cross the border between Jordan and Israel/Palestine', 'How to cross the border between Jordan and Israel/Palestine', 'How to cross the border between Jordan and Israel/Palestine between Jordan and Israel/Palestine', 'Crossing, Allenby, King Hussein, Jordan River, Sheikh Hussein, Wadi Araba, Yitzhak Rabin', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;***Please note that, as of March 12th, all three border crossings described here are closed for departing and arriving passengers. This is a government measure to avoid the propagation of the coronavirus disease (COVID-19) in Jordan.***&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;As detailed &lt;a href=&quot;en/visas-to-jordan/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;here&lt;/a&gt;, visas can be obtained at the Queen Alia International Airport (unless for restricted nationalities). However, there are three border crossings available for travellers between Jordan, Israel and the Occupied Palestinian Territories (oPT). Each point has a different name on both Jordanian and Israeli/Palestinian sides. Click below to read all essential information about each crossing.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;en/sheikh-hussein-jordan-river-crossing/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;1 – Sheikh Hussein/Jordan River Crossing&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;en/allenby-king-hussein-bridge/&quot;&gt;2 – Allenby/King Hussein Bridge&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;en/wadi-araba-yitzhak-rabin-crossing/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;3 – Wadi Araba/Yitzhak Rabin Crossing&lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Stamps:&lt;/strong&gt; when crossing into Jordan from Israel/Palestinian territories, Jordanian authorities might stamp your passport stating that you entered the country via that crossing. Therefore, that means that you have been to Israel and/or to the Palestinian territories, which are occupied by Israel. This stamp may have your entry denied in certain countries, like Lebanon.&lt;/p&gt;\r\n&lt;p&gt;Therefore, keep that in mind when planning upcoming trips in the region. You can also ask the Jordanian authorities to stamp a slip of paper instead, if you plan to go to other countries that do not have an amicable relation with Israel. The same is valid when travelling to Lebanon and entering Israel afterwards – you may face questioning from Israeli authorities on why you have visited Lebanon.&lt;/p&gt;\r\n&lt;p&gt;Please note that pubic holidays may affect the opening times and operations at the border crossings on both sides. Plan ahead and check if important dates such as Ramadan, Muslim New Year or Yom Kippur will impact your holidays.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;p&gt; &lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt; &lt;a href=&quot;https://www.google.com/maps/d/edit?mid=1kOGjGGMh0vMyqKsVN5xAORX5ua7xJQZh&amp;amp;ll=31.030942274246865,35.28009029999998&amp;amp;z=8&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;&lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Photos/Border Crossings/Border Crossings.jpg&quot; /&gt;&lt;/a&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-12&quot;&gt; &lt;span style=&quot;font-size: 14px; text-decoration-line: inherit;&quot;&gt; &lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1875, 'ge', '', 'one col', 'border-crossings'),
(2002, 'Restaurants in Jordan', 'Restaurants in Jordan', 'Restaurants in Amman, Petra, Aqaba', 'Restaurants in Amman, Petra, Aqaba', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/amman_jabal_amman_view.jpg&quot; alt=&quot;Jabal Amman&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   &lt;strong&gt;    Restaurants in Amman&lt;/strong&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;From paleo cuisine to the  most traditional Arab cuisine, there are plenty of options in the capital! &lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/restaurants-amman/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/yuliya-kosolapova-Aqaba Facebook.jpg&quot; alt=&quot;Sunset in Aqaba&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;&lt;strong&gt;         Restaurants in Aqaba&lt;/strong&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Enjoy the seafood offered in the charming portal city or just watch the amazing sunset Aqaba offers! &lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/restaurants-in-aqaba/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Petra/Khaznah.jpg&quot; alt=&quot;Treasury in Petra&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;<br>\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;Restaurants in Petra&lt;/strong&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;There is a lot to explore in the rose city: cooking classes, organic food, classic mansaf and maqlouba...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/restaurants-in-petra/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1929, 'ge', '', 'one col', 'restaurants-in-jordan');
INSERT INTO `en33_pages` (`id`, `name`, `title`, `meta_desc`, `meta_key`, `contents`, `published`, `lang_id`, `lang`, `icon`, `layout`, `url`) VALUES
(2003, 'Restaurantes na Jordânia', 'Restaurantes na Jordânia', 'Restaurantes nas principais cidades da Jordânia: Amman, Aqaba e Petra.', 'Restaurantes Jordânia, Restaurantes Petra, Aqaba, Amman', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Amman/amman_jabal_amman_view.jpg&quot; alt=&quot;Jabal Amman&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot;&gt;   &lt;strong&gt;    Restaurantes em Amã&lt;/strong&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;De comida paleo à cozinha árabe mais tradicional, há muitas opções na capital! &lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;en/restaurants-amman/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Read More&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/yuliya-kosolapova-Aqaba Facebook.jpg&quot; alt=&quot;Sunset in Aqaba&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;        Restaurantes em Aqaba&lt;/strong&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Experimente os frutos do mar oferecidos nesta encantadora cidade portuária ou simplesmente desfrute o fantástico pôr-do-sol que Aqaba oferece! &lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/restaurantes-em-aqaba&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Petra/Khaznah.jpg&quot; alt=&quot;Treasury in Petra&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;<br>\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;Restaurantes em Petra&lt;/strong&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Há muito a explorar na Cidade Rosada: aulas de culinária, comida orgânica, os clássicos mansaf e maqlouba...&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/restaurantes-em-petra&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1929, 'pt', '', 'one col', 'restaurantes-na-jordania'),
(2004, 'Restaurantes em Aqaba', 'Restaurantes em Aqaba', 'Informações sobre os melhores restaurantes em Aqaba.', 'Restaurantes, Aqaba', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/Captains Tourist Restaurant Aqaba.jpg&quot; alt=&quot;Captains Tourist Restaurant &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Restaurante Captain&#039;s Tourist &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Muito popular, um clássico situado no coração de Aqaba, o local tem uma decoração de temática marítima.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/restaurante-captains-tourist&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/ali baba restaurant Restaurant Aqaba.jpg&quot; alt=&quot;Ali Baba Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Restaurante Ali Baba &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Comida tradicional jordaniana, como uma vasta seleção de mezze, frutos do mar, grelhados e opções vegetarianas.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/restaurante-ali-baba&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/The royal yacht club Restaurant Aqaba.jpg&quot; alt=&quot;The Royal Yacht Club of Jordan&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;              &lt;span style=&quot;color: #ff8d14; text-align: center; text-decoration-line: inherit;&quot;&gt;Yacht Clube Real da Jordânia&lt;/span&gt;<br>\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Com um terraço luxuoso de frente para o porto, este é o melhor lugar da cidade para assistir ao belo pôr-do-sol de Aqaba.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/yacht-clube&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/gelato uno aqaba Restaurant Aqaba.jpg&quot; alt=&quot;Gelato Uno&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Gelato Uno&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Nunca há uma má hora para um delicioso e refrescante sorvete na sempre quente Aqaba!&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/gelato-uno/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1834, 'pt', '', 'one col', 'restaurantes-em-aqaba'),
(2005, 'Restaurante Captain&#039;s Tourist', 'Restaurante Captain&#039;s Tourist', 'Muito popular, um clássico situado no coração de Aqaba, o local tem uma decoração de temática marítima.', 'Restaurante Captain&#039;s Tourist, Aqaba', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;O Restaurante Captain&#039;s Tourist é um clássico. Está situado no coração da cidade portuária de Aqaba e segue uma decoração de temática marítima, até sua equipe veste trajes náuticos! É um restaurante popular e muitos turistas decidem repetir suas refeições, por isso é um lugar muito movimentado.&lt;/p&gt;\r\n&lt;p&gt;Eles servem comida de alta qualidade feita com ingredientes frescos, especialmente frutos do mar, o que geralmente é mais difícil de encontrar em outras cidades da Jordânia.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/Captains Tourist Restaurant Aqaba.jpg&quot; alt=&quot;Captain&#039;s Restaurant&quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3471.485623466954!2d35.000513950516186!3d29.53134888198396!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15007036e384e875:0x3cb66e677f54f66b!2sCaptains restaurant!5e0!3m2!1sen!2sjo!4v1579348625153!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1835, 'pt', '', 'one col', 'restaurante-captains-tourist'),
(2006, 'Restaurante Ali Baba ', 'Restaurante Ali Baba ', 'Comida tradicional jordaniana, como uma vasta seleção de mezze, frutos do mar, grelhados e opções vegetarianas.', 'Restaurante Ali Baba ', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;Ali Baba serve comida tradicional jordaniana, como uma vasta seleção de mezze (aperitivos árabes), frutos do mar e grelhados mistos. Também contam com opções vegetarianas. Lá pode-se provar o prato tradicional de frutos do mar de Aqaba que dá água na boca: o Sayiadya. O restaurante Ali Baba também oferece bebidas alcoólicas.&lt;/p&gt;\r\n&lt;p&gt;É muito popular entre os turistas, mas normalmente já não se vêem muitos locais. Tem um grande terraço onde se pode sentar e relaxar depois de um longo dia a explorar a cidade, uma vez que está situada mesmo no coração da histórica cidade velha. É também um ótimo local para relaxar e observar as pessoas.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/ali baba restaurant Restaurant Aqaba.jpg&quot; alt=&quot;Ali Baba Restaurant &quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3471.563088461576!2d35.00095115051621!3d29.529091881984762!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x150070363353dd73:0x71b5e1363c4a4799!2sAlibaba Restaurant!5e0!3m2!1sen!2sjo!4v1579349245962!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1836, 'pt', '', 'one col', 'restaurante-ali-baba '),
(2007, ' Yacht Clube Real da Jordânia', ' Yacht Clube Real da Jordânia', 'Com um terraço luxuoso de frente para o porto, este é o melhor lugar da cidade para assistir ao belo pôr-do-sol de Aqaba.', ' Yacht Clube Real da Jordânia, Aqaba', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;O Yacht Clube Real é provavelmente o melhor local da cidade para assistir ao belo pôr-do-sol de Aqaba.&lt;/p&gt;\r\n&lt;p&gt;Sente-se e relaxe neste restaurante de classe, com uma variedade de comida de alta qualidade de diferentes cantos do mundo: massas e pizzas italianas feitas à mão, sushi japonês, mezze árabe e muitos outros. Também oferecem uma vasta selecção de vinhos locais e importados.&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/The royal yacht club Restaurant Aqaba.jpg&quot; alt=&quot;The Royal Yacht Club Jordan Restaurant&quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3471.5460788871073!2d34.99716785051613!3d29.52958748198458!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1500712ca50f90c7:0xac771e8948db096d!2sThe Royal Yacht Club of Jordan!5e0!3m2!1sen!2sjo!4v1579349591219!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1837, 'pt', '', 'one col', 'yacht-clube'),
(2008, 'Gelato Uno', 'Gelato Uno', 'Nunca há uma má hora para um delicioso e refrescante sorvete na sempre quente Aqaba!', 'Gelados, sorvetes, Aqaba', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;Verá que Aqaba tem invernos muito amenos, ao contrário de outras cidades da Jordânia, e pode ter verões extremamente quentes, por isso nunca há má hora para um delicioso e refrescante gelado!&lt;/p&gt;\r\n&lt;p&gt;Este restaurante é uma escolha popular entre os locais e turistas que procuram refrescar-se depois de um longo dia quente. Pode ser um lugar perfeito para ir com crianças também, pois o dono também dirige a pizzaria ao lado.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants in Aqaba resized/gelato uno aqaba Restaurant Aqaba.jpg&quot; alt=&quot;Ali Baba Restaurant &quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3471.5014326667547!2d35.00152545051614!3d29.530888281984055!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x150070371fe742b3:0x3e735af66dd672e!2sGelato uno!5e0!3m2!1sen!2sjo!4v1579349727105!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1838, 'pt', '', 'one col', 'gelato-uno'),
(2009, 'Restaurantes em Petra', 'Restaurantes em Petra', 'Há muito a explorar na Cidade Rosada: aulas de culinária, comida orgânica, os clássicos mansaf e maqlouba...', 'restaurantes, petra', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/my moms recipe restaurant pvt.jpeg&quot; alt=&quot;My mom’s Reciepe  Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Restaurante My Mom&#039;s Recipe &lt;/div&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;&lt;span style=&quot;font-size: 14px; text-align: left; color: #111111; text-decoration-line: inherit;&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size: 14px; text-align: left; color: #111111; text-decoration-line: inherit;&quot;&gt;Comida tradicional e deliciosa da Jordânia: os seus pratos mais famosos são o seu Mansaf e hummus. Música ao vivo.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/my-moms-recipe&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Petra Kitchen.jpeg&quot; alt=&quot;Petra Kitchen&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Petra Kitchen&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Uma verdadeira experiência jordaniana: aqui você cozinha a sua própria comida e desfruta das refeições saborosas no final.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/petra-kitchen&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Al qantarah restaurant pvt.jpg&quot; alt=&quot;Al Qantarah Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;<br>\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Restaurante Al Qantarah &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Alimentos produzidos localmente, orgânicos e frescos. Assam o seu pão e grelham a sua carne no &quot;Taboun&quot;.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/restaurante-al-qantarah&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Sanabel bakery.jpg&quot; alt=&quot;Sanabel sweets and bakeries &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Sanabel Doces e Padaria&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;A equipe é extremamente gentil e irá imediatamente oferecer-lhe amostras diferentes de suas delícias.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/sanabel-doces&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Sandstone restaurant petra pvt.jpg&quot; alt=&quot;Sandstone Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Restaurante Sandstone &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Perto do Centro de Visitantes, este restaurante oferece uma mistura de grelhados suculentos e deliciosas saladas e mezze.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/restaurante-sandstone&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/red cave restaurant petra pvt.jpg&quot; alt=&quot;Red cave restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Restaurante Red Cave &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Grande variedade de pratos: mezze, sopas, grelhados e também especialidades beduínas, como o Gallayah.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/restaurante-red-cave&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/The basin restaurant petra pvt.jpg&quot; alt=&quot;The Basin Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Restaurante The Basin &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;O único restaurante localizado dentro da área arqueológica de Petra. Servem pratos internacionais e locais.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/restaurante-the-basin&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/al wadi restaurant petra pvt.jpg&quot; alt=&quot;Al wadi restaurant &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Restaurante Al Wadi &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Grandes porções de deliciosa comida local, como Mansaf e Maklouba, grelhados, sopas e muito mais.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/restaurante-al-wadi&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1825, 'pt', '', 'one col', 'restaurantes-em-petra'),
(2010, 'Restaurante My Mom’s Recipe', 'Restaurante My Mom’s Recipe', 'Comida tradicional e deliciosa da Jordânia: os seus pratos mais famosos são o seu Mansaf e hummus. Música ao vivo.', 'Restaurante em Petra, Música ao Vivo, comida local, Petra', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;O restaurante My Mom&#039;s Recipe (literalmente &quot;A Receita de minha mãe&quot;) oferece a tradicional comida jordaniana de dar água na boca. O almoço consiste num buffet e o jantar é à la carte. Os seus pratos mais famosos são o Mansaf e o Hommus. Mansaf é o favorito da maioria dos locais, é feito de carneiro (ou frango) cozido com um delicioso molho de iogurte fermentado (jamid) e servido com arroz. E o Hommus, bem... todos nós conhecemos o Hommus! Eles têm também uma vasta seleção de grelhados e saladas. Os seus pratos principais vão de 8 a 12 JD.&lt;/p&gt;\r\n&lt;p&gt;O restaurante é grande e adequado para grupos, tem uma cobertura muito agradável onde se pode sentar e relaxar, que por acaso é fresca mesmo durante os dias quentes de verão. Seus cômodos são decorados com bom gosto, preenchidos com os padrões tradicionais da Jordânia. No My Mom&#039;s Recipe oferecem música ao vivo, pode sentar-se e apreciar - ou pode dançar junto! Os seus funcionários são conhecidos por serem muito acolhedores e hospitaleiros. Está convenientemente localizado na zona turística de Petra.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/my moms recipe restaurant petra.jpg&quot; alt=&quot;My mom&#039;s recipe Restaurant Petra &quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d13775.613589587205!2d35.4704252!3d30.3252655!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0:0x5d98363a3c78eac9!2sMy Mom&#039;s Recipe Restaurant!5e0!3m2!1sen!2sjo!4v1579344331132!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1826, 'pt', '', 'one col', 'my-moms-recipe'),
(2011, 'Petra Kitchen', 'Petra Kitchen', 'Uma verdadeira experiência jordaniana: aqui você cozinha a sua própria comida e desfruta das refeições saborosas no final.', 'Petra Kitchen, restaurante em Petra, aula de culinária', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;Caso queira uma verdadeira experiência jordaniana, pare de procurar, pois este é o melhor lugar da cidade! Aqui se cozinha a própria comida e se tem o prazer de saborear as refeições saborosas ao final. A sessão de cozinha dura geralmente duas horas e os participantes preparam sua comida com um chef local e outros membros da equipe, que não só lhe mostrarão os segredos da sua cozinha, mas também o introduzirão na sua cultura e história, e lhe darão a oportunidade de testemunhar a excelente hospitalidade dos jordanianos.&lt;/p&gt;\r\n&lt;p&gt;Os cursos são ministrados à noite e caso planeje ficar em Petra durante algum tempo, pode também participar de um curso de culinária com 5 dias de duração.&lt;/p&gt;\r\n&lt;p&gt;Todos os seus ingredientes são frescos e eles têm orgulho em afirmar que não há congeladores nem geladeiras na sua cozinha. Eles cozinham os alimentos que compram no mesmo dia e garantem que há zero desperdício de alimentos. Se houver restos de comida, estes são fornecidos às famílias locais que deles necessitam. Também contam com numerosas opções vegetarianas. Além disso, os seus produtos são 100% locais: colhem e produzem o seu próprio óleo, cultivam as suas ervas e até o seu mobiliário é comprado em lojas e cooperativas locais.&lt;/p&gt;\r\n&lt;p&gt;Petra Kitchen é o local ideal para conhecer pessoas, aprender a cozinhar pratos jordanianos ou relaxar no terraço e beber um delicioso vinho local.&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Petra Kitchen.jpeg&quot; alt=&quot;Petra Kitchen &quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3443.9063408890875!2d35.46911255055766!3d30.325181781691654!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15016ed1bd9661bf:0x5b61bbdbc82401ac!2sPetra Kitchen!5e0!3m2!1sen!2ses!4v1577266785362!5m2!1sen!2ses&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1827, 'pt', '', 'one col', 'petra-kitchen'),
(2012, 'Restaurante Al Qantarah', 'Restaurante Al Qantarah', 'Alimentos produzidos localmente, orgânicos e frescos. Assam o seu pão e grelham a sua carne no &quot;Taboun&quot;.', 'Restaurante Al Qantarah, Petra, comida orgânica, música ao vivo', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;O Al Qantarah oferece um buffet fixo para almoço e jantar que consiste numa selecção de saladas, sopas, mezze, carnes e sobremesas que são servidas em pratos artesanais de cerâmica. Acreditam nos valores do turismo sustentável e por isso os seus alimentos são orgânicos, frescos e produzidos localmente, como orgulhosamente afirmam. Além disso, assam seu pão e grelham a sua carne num velho forno de barro chamado &quot;Taboun&quot;.&lt;/p&gt;\r\n&lt;p&gt;O restaurante encontra-se num belo edifício em pedra, coberto de arcos, onde se pode descobrir a arquitetura tradicional jordaniana. É espaçoso e pode acolher grandes grupos, além de ser decorado com belas obras de arte locais.&lt;/p&gt;\r\n&lt;p&gt;O ambiente é agradável e é definitivamente um dos favoritos tanto dos locais como dos visitantes. Eles também tocam música tradicional ao vivo.&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Al qantarah restaurant pvt.jpg&quot; alt=&quot;Petra Kitchen &quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3443.811125286482!2d35.468405850557865!3d30.3278897816907!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15016ed122c46ef9:0x97f9cf5fe8d881ea!2sAlqantarah Restaurant!5e0!3m2!1sen!2ses!4v1577269520587!5m2!1sen!2ses&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1828, 'pt', '', 'one col', 'restaurante-al-qantarah'),
(2013, 'Sanabel Doces e Padaria', 'Sanabel Doces e Padaria', 'A equipe é extremamente gentil e irá imediatamente oferecer-lhe amostras diferentes de suas delícias.', 'Doces, Padaria, Doces árabes, padaria, Petra', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;Aqueles que amam doces não se arrependerão de passar na padaria Sanabel. Sua equipe é extremamente simpática e irá imediatamente oferecer-lhe amostras diferentes dos seus deliciosos petiscos jordanianos. É claramente o melhor lugar em Petra para doces delícias.&lt;/p&gt;\r\n&lt;p&gt;O seu pão é a sua cereja do bolo. Eles fazem o pão árabe mais delicioso da cidade e tudo isso é oferecido a um preço muito acessível. Não perca esta verdadeira experiência jordaniana.&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Sanabel bakery.jpg&quot; alt=&quot;Sanabel Sweets and Bakeries&quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3444.0208882834613!2d35.47640015055771!3d30.321923681692702!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1501692d5040f91d:0xf85011a756e27662!2sSANABEL Sweets and Bakeries!5e0!3m2!1sen!2ses!4v1577269684772!5m2!1sen!2ses&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1829, 'pt', '', 'one col', 'sanabel-doces'),
(2014, 'Restaurante Sandstone ', 'Restaurante Sandstone ', 'Perto do Centro de Visitantes, este restaurante oferece uma mistura de grelhados suculentos e deliciosas saladas e mezze.', 'Restaurante Sandstone, Petra, centro de visitantes', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;Convenientemente localizado perto do centro de visitas o Restaurante Sandstone oferece uma mistura de grelhados suculentos e deliciosas saladas e mezze. Servem também vinho e cerveja locais, assim como outras bebidas alcoólicas.&lt;/p&gt;\r\n&lt;p&gt;O Restaurante Sandstone conta com um terraço ao ar livre onde se pode sentar e relaxar enquanto desfruta das vistas. É claramente uma escolha popular entre locais e visitantes e um local perfeito para se deliciarem com a comida tradicional da Jordânia.&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/Sandstone restaurant petra pvt.jpg&quot; alt=&quot;Sandstone Restaurant&quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3443.903071056889!2d35.4679897505578!3d30.32527478169155!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15016ed1ca504bb5:0xd9577f278a03538d!2sSandstone!5e0!3m2!1sen!2ses!4v1577271743770!5m2!1sen!2ses&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1830, 'pt', '', 'one col', 'restaurante-sandstone '),
(2015, 'Restaurante Red Cave ', 'Restaurante Red Cave ', 'Grande variedade de pratos: mezze, sopas, grelhados e também especialidades beduínas, como o Gallayah.', 'Restaurante Red Cave, Petra, mezze', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;<br>O Restaurante Red Cave oferece uma vasta gama de pratos: lá pode-se encontrar uma variedade de mezze (aperitivos árabes), sopas, grelhados e também especialidades beduínas, como o Gallayah. Servem também o delicioso Makloubah, que é um prato tradicional do Oriente Médio e significa literalmente &quot;ao contrário&quot;. É composto por arroz, legumes fritos e carne, e é cozinhado numa panela que é virada ao contrário antes de ser servido (daí o seu nome!).&lt;/p&gt;\r\n&lt;p&gt;A comida é oferecida como um buffet e pode-se servir-se ao que mais deseja . Eles também organizam buffets &quot;a la carte&quot;, se solicitados com um dia de antecedência.&lt;/p&gt;\r\n&lt;p&gt;Nós pessoalmente acreditamos que a comida é deliciosa, o lugar é lindo e acolhedor e o pessoal é muito simpático. No entanto, a verdade deve ser dita, parece haver uma variedade de críticas e opiniões sobre o assunto: é um daqueles lugares que se ama ou odeia!&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/red cave restaurant petra pvt.jpg&quot; alt=&quot;Red Cave Restaurant&quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3443.9034824202276!2d35.46781751496511!3d30.32526308178106!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15016ed22e61a421:0xfd8b65879bb40ebc!2sRed Cave Restaurant!5e0!3m2!1sen!2ses!4v1577275228517!5m2!1sen!2ses&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1831, 'pt', '', 'one col', 'restaurante-red-cave '),
(2016, 'Restaurante The Basin ', 'Restaurante The Basin ', 'O único restaurante localizado dentro da área arqueológica de Petra. Servem pratos internacionais e locais.', 'restaurante em Petra, sítio arqueológico de Petra', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;O restaurante The Basin é o único localizado no coração da zona arqueológica de Petra. A sua área ao ar livre permite uma refeição rodeada pelas espetaculares ruínas de Petra. É o local ideal para fazer uma pausa e recuperar a energia a caminho ou de volta do Mosteiro.&lt;/p&gt;\r\n&lt;p&gt;Oferecem um buffet de almoço com uma variedade de pratos internacionais e locais. Certifique-se de fazer uma pré-reserva para garantir um lugar, pois o restaurante pode ficar bastante ocupado na alta temporada.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/The basin restaurant petra pvt.jpg&quot; alt=&quot;The Basin Restaurant&quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3443.7004046180555!2d35.43777431498687!3d30.33103848177892!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x15016ef6d52042dd:0x85beac287ee6c5cd!2sThe Basin Restaurant!5e0!3m2!1sen!2ses!4v1577296632639!5m2!1sen!2ses&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1832, 'pt', '', 'one col', 'restaurante-the-basin '),
(2017, 'Restaurante Al Wadi ', 'Restaurante Al Wadi ', 'Grandes porções de deliciosa comida local, como Mansaf e Maklouba, grelhados, sopas e muito mais.', 'Restaurante Al Wadi , Restaurante em Petra', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;O restaurante Al Wadi é outro exemplo claro da incrível hospitalidade do povo jordaniano. Sua equipe é extraordinariamente simpática e está sempre pronta para o ajudar em tudo o que precisar.&lt;/p&gt;\r\n&lt;p&gt;Servem grandes porções de deliciosa comida local como Mansaf (carneiro, arroz e um molho de iogurte fermentado chamado jameed) e Maklouba (literalmente &quot;ao contrário&quot; - arroz, legumes e carne cozidos numa panela e virados de cabeça para baixo antes de serem servidos), grelhados, sopas, mezze, mas também pratos internacionais como pizza e espaguete. E para tornar a sua experiência de dar água na boca ainda melhor, servem todos estes pratos com o melhor pão caseiro!&lt;/p&gt;\r\n&lt;p&gt;O restaurante está localizado no centro da cidade, a dez minutos do sítio arqueológico de Petra e oferece belas vistas para a montanha.&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants Petra resized pictures/al wadi restaurant petra pvt.jpg&quot; alt=&quot;Al Wadi Restaurant&quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3444.0281725881187!2d35.478101650550606!3d30.321716481692825!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1501692d6fdd32f9:0xe7706d5a63a8819d!2sAl Wadi Restaurant!5e0!3m2!1sen!2ses!4v1577297236812!5m2!1sen!2ses&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1833, 'pt', '', 'one col', 'restaurante-al-wadi '),
(2018, 'Restaurantes em Amã', 'Restaurantes em Amã', 'Lista com os melhores restaurantes em Amã.', 'Restaurantes, Amã', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/shams el balad.jpg&quot; alt=&quot;Shams EL balad Restaurants Amman&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt; Shams El Balad&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Desfrute de uma fantástica vista da Cidadela e de pratos feitos com ingredientes 100% orgânicos.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/shams-el-balad&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/hashem.jpg&quot; alt=&quot;Hashem Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Hashem Downtown&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;O Hashem Downtown é o restaurante mais antigo da cidade, funciona desde 1956. É obrigatório passar por lá!&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/hashem-downtown&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/Kan Zaman restaurants amman.jpg&quot; alt=&quot;Kan Zaman Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;<br>\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Restaurante Kan Zamaan &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Um local atrativo que serve grandes pratos: uma cozinha única, autêntica, oriental e local.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/restaurante-kan-zamaan&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/fakhreldin restaurant.jpg&quot; alt=&quot;Fakhreldin Restaurant&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Restaurante Fakhreldin &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;span&gt;Ganhou aclamação da crítica como um dos melhores restaurantes de Amã. Carnes, frangos e mariscos de qualidade.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/restaurante-fakhreldin&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/habibah sweets in Amman.jpg&quot; alt=&quot;Habibah Sweets&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt; Doces Habibah&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Loja familiar, vendem chocolates e doces tradicionais e são famosos pelo seu kanafeh.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/doces-habibah&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/fatatri restaurant amman.jpg&quot; alt=&quot;Fatatri &quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Fatatri&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Combinando a cultura egípcia e jordaniana, este restaurante é especializado em &quot;feteer&quot;, um tipo de pastel.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/fatatri/&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/primal bistro and cafe restaurants Amman.jpg&quot; alt=&quot;primal Restaurant AMman&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Restaurante Primal Amman&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;O primeiro e único restaurante paleo em Amman. Totalmente sem glúten, sem açúcar refinado e sem lactose.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/primal&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/al quds.jpg&quot; alt=&quot;Al-quds falafel&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt;Falafel Al-Quds &lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;Na famosa Rainbow Street, o restaurante Al-Quds é conhecido por servir o melhor falafel de Amã.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/falafel-al-quds&quot; class=&quot;btn orange h-pad&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1558, 'pt', '', 'one col', 'restaurantes-em-ama');
INSERT INTO `en33_pages` (`id`, `name`, `title`, `meta_desc`, `meta_key`, `contents`, `published`, `lang_id`, `lang`, `icon`, `layout`, `url`) VALUES
(2019, 'Shams El Balad', 'Shams El Balad', 'Desfrute de uma fantástica vista da Cidadela e de pratos feitos com ingredientes 100% orgânicos.', 'Shams El Balad,', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;/div&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;Shams El Balad é um restaurante movimentado localizado em Jabal Amã &quot;inspirado na cidade em que vive e nas pessoas que a compõem&quot;. Está alojado numa casa de arquitetura tradicional, com uma vista privilegiada sobre a cidadela e o Palácio Umayyad.&lt;/p&gt;\r\n&lt;p&gt;Servem comida local saudável, de dar água na boca, inspirada no artesanato, nos produtos e na cultura da região. Os seus ingredientes são 100% orgânicos e provêm diretamente das fazendas. Shams El Balad é uma celebração do patrimônio, da terra e das pessoas que trabalham incansavelmente para os proteger, para que todos possamos desfrutá-los.&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3385.370890586393!2d35.92490201447644!3d31.950833381229334!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151b5f9b233d8d97:0x9926edf16bfbf80b!2sShams AlBalad!5e0!3m2!1sen!2sjo!4v1576315988858!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;<br>&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img class=&quot;full-width&quot; src=&quot;uploads/filemanager/Restaurants/shams el balad.jpg&quot; width=&quot;438&quot; height=&quot;251&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;', 1, 1559, 'pt', '', 'one col', 'shams-el-balad'),
(2020, 'Hashem Downtown', 'Hashem Downtown', 'O Hashem Downtown é o restaurante mais antigo da cidade, funciona desde 1956. É obrigatório passar por lá!', 'Hashem Downtown, restaurante antigo em Amã', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; <br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;O Hashem Downtown é o restaurante mais antigo da cidade, funciona desde 1956. É, sem dúvida, um ponto de passagem obrigatório durante a sua viagem à Jordânia. &lt;/p&gt;\r\n&lt;p&gt;É conhecido como o restaurante que nunca fecha porque serve comida 24 horas por dia, 7 dias por semana! Nele pode-se encontrar os mais deliciosos hommus, falafel e foul da cidade. &lt;/p&gt;\r\n&lt;p&gt;As paredes do restaurante estão decoradas com fotografias de muitas celebridades que o visitaram ao longo dos últimos 60 anos, como Sua Majestade o Rei Abdullah II, a Rainha Rania, o Príncipe Herdeiro Hussein, o Presidente palestino Yasser Arafat, Omar Alsherif, Melhim Brakat, Kamal Alshinawi, George Wassof.&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/hashem restaurant.jpg&quot; width=&quot;445&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d6770.621150646353!2d35.9297785!3d31.9524701!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0:0xe7dab884a8b945e2!2sHashem Restaurant Down Town!5e0!3m2!1sen!2sjo!4v1576336687523!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1562, 'pt', '', 'one col', 'hashem-downtown'),
(2021, 'Restaurante Kan Zamaan', 'Restaurante Kan Zamaan', 'Um local atrativo que serve grandes pratos: uma cozinha única, autêntica, oriental e local.', 'Restaurante Kan Zamaan, local histórico, restaurantes tradicionais', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;O Restaurante Kan Zamaan é uma das melhores atrações turísticas de Amã.&lt;/p&gt;\r\n&lt;p&gt;É um local atrativo que serve grandes pratos: uma cozinha única, autêntica, oriental e local. O restaurante tem surpreendentes arcos de pedra antigos e uma decoração que combina com o cenário.&lt;/p&gt;\r\n&lt;p&gt;O Kan Zamaan é um marco distinto que lança uma nova luz sobre o seu legado cultural e histórico, pois continua a encantar os amantes da comida local com a sua cozinha única, autêntica, oriental e local guarnecida com sabores esquecidos.&lt;/p&gt;\r\n&lt;p&gt;Servem uma vasta selecção de mezze finos orientais frios e quentes, carnes grelhadas, pão fresco preparado e cozido diariamente no seu forno de tijolo árabe, mariscos frescos e pratos de inspiração local. Oferecem também deliciosos knafeh caseiros.&lt;/p&gt;\r\n&lt;p&gt;Apesar de estar um pouco longe do centro da cidade, vale definitivamente a pena a viagem!  Muitas vezes tocam música ao vivo e organizam diferentes tipos de eventos. &lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/Kan Zaman restaurants amman.jpg&quot; width=&quot;442&quot; height=&quot;294&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d108388.24555803406!2d35.8260677583293!3d31.90299239899252!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151ca7f5ef5df9a1:0x47a0e8f9731d5096!2sKan Zaman!5e0!3m2!1sen!2sjo!4v1576335113536!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1560, 'pt', '', 'one col', 'restaurante-kan-zamaan'),
(2022, 'Restaurante Fakhreldin ', 'Restaurante Fakhreldin ', 'Ganhou aclamação da crítica como um dos melhores restaurantes de Amã. Carnes, frangos e mariscos de qualidade.', 'Restaurante Fakhreldin , Restaurantes finos', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt;&quot;&gt;&lt;span style=&quot;color: #302f2f;&quot;&gt;&lt;/span&gt;<br>&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&quot;Fina cozinha levantina na elegância de um autêntico lar jordaniano&quot;. O Restaurante Fakhreldin está localizado num dos bairros mais antigos de Amã. Foi concebido e construído em meados do século 20 e ao longo dos anos tem sido também o lar de vários dignitários proeminentes da Jordânia.&lt;/p&gt;\r\n&lt;p&gt;O Restaurante Fakhreldin distingue-se pelo seu serviço e comida e ganhou aclamação crítica como um dos melhores restaurantes de Amã. A melhor qualidade de carne, frango e mariscos é utilizada para a fantástica seleção de grelhados disponíveis, aperitivos tradicionais do Oriente Médio e sobremesas árabes.&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/fakhreldin.jpg&quot; width=&quot;444&quot; height=&quot;296&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3385.322932494197!2d35.918252650599904!3d31.952134781136916!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151b5f99a48f39f3:0x3fd68db1f2177c00!2sFakhreldin Restaurant!5e0!3m2!1sen!2sjo!4v1576340310025!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1564, 'pt', '', 'one col', 'restaurante-fakhreldin '),
(2023, ' Doces Habibah', ' Doces Habibah', 'Loja familiar, vendem chocolates e doces tradicionais e são famosos pelo seu kanafeh.', ' Doces Habibah, doces tradicionais, knafeh', '&lt;div cla=&quot;&quot; div=&quot;&quot; class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Um negócio familiar fundado em 1951 que comercializa chocolates e doces tradicionais. São famosos pelo seu kanafeh, que é uma sobremesa tradicional do Oriente Médio feita de massa fina de semolina, uma camada de queijo e uma calda açucarada.&lt;/p&gt;\r\n&lt;p&gt;Al-Haj Mahmoud Habibah deixou Nablus em 1947 e começou o seu trabalho numa pequena loja em Jerusalém. Um ano mais tarde, mudou-se para Amã. Desde então, tem oferecido graciosamente os seus doces tanto aos habitantes locais como aos visitantes, que fazem fila à espera da sua doçura.&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/habibah sweets amman.jpg&quot; width=&quot;443&quot; height=&quot;332&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d13540.969057553559!2d35.926048531992045!3d31.954323699295294!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151b5f99d8819489:0xcc54b3d129d39825!2sHabibah Sweets!5e0!3m2!1sen!2sjo!4v1576339669181!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1563, 'pt', '', 'one col', 'doces-habibah'),
(2024, 'Fatatri', 'Fatatri', 'Combinando a cultura egípcia e jordaniana, este restaurante é especializado em &quot;feteer&quot;, um tipo de pastel.', 'Fatatri, Fateer, comida egípcia', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: Arial, sans-serif; font-size: 12pt; text-decoration-line: inherit;&quot;&gt;&lt;/span&gt;<br>&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 12pt;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;Combinando a cultura egípcia e jordaniana, este restaurante é especializado em &quot;feteer&quot; uma massa deliciosa bem fina recheada com ingredientes frescos à escolha do cliente e assada no forno. A massa contém apenas farinha, água e um pouco de sal.&lt;/p&gt;\r\n&lt;p&gt;Este restaurante não só presta um excelente serviço aos seus clientes como também se concentra no desenvolvimento pessoal dos seus colaboradores, oferecendo-lhes a oportunidade de aprenderem novas competências. O Fatatri é o primeiro restaurante da cidade a oferecer aulas de inglês gratuitas à sua equipe.&lt;/p&gt;\r\n&lt;p&gt;Não deixe de passar por lá durante a sua estadia em Amã e observe como os chefs excepcionalmente talentosos abrem a massa e a jogam ao ar antes de a rechear com ingredientes locais frescos. &lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 12pt;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 12pt;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt; &lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;,sans-serif;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/fatatri restaurant amman.jpg&quot; width=&quot;404&quot; height=&quot;249&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;510&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3385.436976592755!2d35.925943950599674!3d31.94903998113775!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151b5f9b63402caf:0x18c1effcef8bfa3f!2zRmF0YXRyaSDZgdi32LfYsdmK!5e0!3m2!1sen!2sjo!4v1576344251915!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt; &lt;iframe width=&quot;510&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d13540.974558857148!2d35.844875003039505!3d31.954286381136168!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151ca19aaa5157c9:0x7c9ec4b22728d0d2!2sFatatri 7th Circle!5e0!3m2!1sen!2sjo!4v1576344303377!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1566, 'pt', '', 'one col', 'fatatri'),
(2025, 'Restaurante Primal Amman', 'Restaurante Primal Amman', 'O primeiro e único restaurante paleo em Amman. Totalmente sem glúten, sem açúcar refinado e sem lactose.', 'restaurante vegano em Amã, restaurante vegetariano em Amã,, comida paleo em Amã', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Primal é o primeiro e único restaurante paleo em Amã. A sua visão é &quot;voltar a comer pura e saudavelmente&quot;. Localizado no bairro mais afluente da cidade, Wadi Abdoun, Primal orgulha-se de ter um menu adequado a todos: totalmente sem glúten, sem açúcar refinado, sem lactose, e com incontáveis opções vegetarianas e veganas.&lt;/p&gt;\r\n&lt;p&gt;Além disso, Primal serve uma vasta seleção de cerveja local e importada, vinhos e espumantes. O seu moderno e lindamente decorado estabelecimento conta com uma área coberta de vidro, bem como uma outra parte ao ar livre.&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: &#039;Arial&#039;, sans-serif; font-size: 14pt;&quot;&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p class=&quot;font7&quot; style=&quot;text-align: left;&quot;&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/primal bistro and cafe restaurants Amman.jpg&quot; width=&quot;445&quot; height=&quot;295&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3385.270109805313!2d35.88204971548299!3d31.95356813281916!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x151ca0f7312a01b9:0xbf3c31d4862d8d04!2sPrimal restaurant!5e0!3m2!1sen!2sjo!4v1576404328748!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1567, 'pt', '', 'one col', 'primal'),
(2026, 'Falafel Al-Quds ', 'Falafel Al-Quds ', 'Na famosa Rainbow Street, o restaurante Al-Quds é conhecido por servir o melhor falafel de Amã.', 'Falafel Al-Quds, restaurante na Rainbow street', '&lt;div class=&quot;row&quot;&gt;\r\n&lt;div class=&quot;md-7&quot; style=&quot;text-align: justify;&quot;&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Localizado na animada e vibrante Rainbow Street, o restaurante Al-Quds é conhecido por servir o melhor falafel de Amã. Muitos moradores locais e turistas aparecem para comer um delicioso sanduíche de falafel depois de um passeio pela rua Rainbow. Devido ao seu pequeno tamanho, não há muitas opções para se sentar além de um banco em frente à loja.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-5 d-pad-t&quot;&gt;&lt;img src=&quot;uploads/filemanager/Restaurants/e28c2eb2e503cacfa05fa26ffe47dd5c-al-quds.jpg&quot; width=&quot;426&quot; height=&quot;340&quot; /&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;iframe width=&quot;100%&quot; height=&quot;250&quot; style=&quot;border: 0;&quot; src=&quot;https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d13541.683034851729!2d35.9265022!3d31.9494801!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0:0x376a889bafb7348c!2sAl Quds Falafel!5e0!3m2!1sen!2sjo!4v1576341855898!5m2!1sen!2sjo&quot; frameborder=&quot;0&quot; allowfullscreen=&quot;allowfullscreen&quot;&gt;&lt;/iframe&gt;&lt;/p&gt;', 1, 1565, 'pt', '', 'one col', 'falafel-al-quds '),
(2027, 'Hoteis na Jordânia', 'Hoteis na Jordânia', 'Informações sobre hoteis nas principais cidades da Jordânia. Jordânia', 'Hoteis em Amã, Hoteis in Jerash, Hoteis in Madaba, Hoteis in Ajlun, Hoteis in dana, hoteis no Mar morto', '&lt;div class=&quot;row &quot;&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Hotels in Irbid/34368_Nahas-Plaza.jpg&quot; alt=&quot;Hotels in Irbid&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt; Hoteis em Irbid&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p style=&quot;text-align: justify;&quot;&gt;Veja os hoteis mais requisitados em Irbid: Sedrah Hotel – Al Joude Hotel – Nahas Plaza &lt;span style=&quot;text-align: justify; text-decoration-line: inherit;&quot;&gt;...&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-center pad&quot;&gt;&lt;a href=&quot;pt/hoteis-em-irbid&quot; class=&quot;btn orange h-pad&quot;&gt;Leia Mais&lt;/a&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;md-4 bd-3  d-pad&quot;&gt;\r\n&lt;div class=&quot;white shadow-box&quot;&gt;&lt;img src=&quot;uploads/filemanager/Photos/Hotels in Ajloun/2 Star/olive.jpg&quot; alt=&quot;Hotels in Jerash&quot; class=&quot;full-width&quot; width=&quot;281&quot; height=&quot;186&quot; /&gt;\r\n&lt;div class=&quot;orange-text &quot; style=&quot;text-align: center;&quot;&gt; Hoteis em Jerash&lt;/div&gt;\r\n&lt;div class=&quot;align-justify h-pad d-pad-l d-pad-r&quot; data-truncate=&quot;3&quot;&gt;\r\n&lt;p&gt;Veja os hoteis mais requisitados em Jerash: Olive Branch Hotel – Hadrian&#039;s Gate Hotel..&lt;span style=&quot;text-align: justify; text-decoration-line: inherit;&quot;&gt;.&lt;/span&gt;&lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;align-cente