INSERT INTO `en33_tours_canned_days_contents` (`id`, `day_id`, `lang`, `title`, `place`, `description`) VALUES
(1, 1, 'en', 'Amman - Madaba - Deadsea -Petra', NULL, '&lt;p&gt;this is a test canned day&lt;/p&gt;'),
(2, 1, 'fr', 'Amman - Madaba - Deadsea -Petra', NULL, '&lt;p&gt;this is a test canned day&lt;/p&gt;'),
(3, 1, 'it', 'Amman - Madaba - Deadsea -Petra', NULL, '&lt;p&gt;this is a test canned day&lt;/p&gt;'),
(4, 1, 'es', 'Amman - Madaba - Deadsea -Petra', NULL, '&lt;p&gt;this is a test canned day&lt;/p&gt;'),
(6, 2, 'en', 'Bienvenue en Jordanie', NULL, '&lt;div class=&quot;_1YxY4SVdzdulPJLpRz_R2Y&quot;&gt;\r\n&lt;p&gt;Accueil à l’aéroport à puis transfert à l&#039;hôtel. &lt;/p&gt;\r\n&lt;/div&gt;'),
(7, 2, 'fr', 'Amman- Madaba-Mont-Nébo- Kérak- Dana', NULL, '&lt;div class=&quot;_1YxY4SVdzdulPJLpRz_R2Y&quot;&gt;\r\n&lt;p&gt;Petit déjeuner a l’hôtel Départ pour la visite de Madaba. C&#039;est l’un des sites les plus mémorables de la Terre Sainte. Appelée « la ville de la mosaïque », Madaba offre de nombreux sites à explorer. La plus remarquable découverte est une carte de Jérusalem, et des autres villes saintes, en mosaïque byzantine datant du VIème siècle, à l’intérieur de l’église Saint Georges.&lt;/p&gt;\r\n&lt;p&gt;Ensuite transfert vers le Mont Nébo depuis lequel Moïse aperçut la Terre Sainte de Canaan, et présumé lieu de sépulture de Moïse. Visite de la forteresse de Saladin à Kerak, ancienne forteresse Croisée encore entourée des fortifications de la vieille cité. Kérak s’élève à 900 mètres au-dessus du niveau de la mer. &lt;/p&gt;\r\n&lt;p&gt;Aujourd’hui, cette ville d’une population d’environ 170 000 personnes présente encore divers bâtiments ottomans restaurés du XIXème siècle et offre de nombreux restaurants, hôtels et autres services. Mais, sans conteste, c’est le château de Kérak qui domine tout. Continuation vers Petra en passant par la Route des Rois. Dîner et nuit chez l&#039;habitant &lt;/p&gt;\r\n&lt;/div&gt;\r\n&lt;h3 class=&quot;_31fj-ZKMM7BR12sglAJrqd&quot;&gt;&lt;/h3&gt;'),
(8, 2, 'it', 'Dana - Vallée de Dana - Wadi Finan', NULL, '&lt;p&gt;La randonnée commence au départ de&lt;span&gt; &lt;/span&gt;&lt;strong&gt;Dana&lt;/strong&gt;. Descente en direction du&lt;span&gt; &lt;/span&gt;&lt;strong&gt;Wadi Arabah&lt;/strong&gt;, 900 mètres plus bas, ensuite remontée en direction du plateau pour rejoindre le sentier qui passe entre arbres sauvages et montagnes de gré.&lt;/p&gt;\r\n&lt;p&gt;De sublimes vues panoramiques sur le Wadi Araba en contrebas et le désert du Néguev à l&#039;ouest; profonds Siqs &quot;canyons&quot; souvent sous l&#039;eau à la végétation dense et où poussent des palmiers sauvages. Une randonnée toute en couleur loin des sentiers habituels de marche. Nous passerons la nuit à&lt;span&gt; &lt;/span&gt;&lt;strong&gt;Wadi Finan.&lt;/strong&gt;&lt;/p&gt;'),
(9, 2, 'es', 'Randonnée et arrivée à Wadi Araba', NULL, '&lt;p&gt;&lt;span&gt;Nous poursuivons notre randonnée jusqu’à atteindre le &lt;/span&gt;&lt;strong&gt;Wadi Araba&lt;/strong&gt;&lt;span&gt;, le paysage est spectaculaire. Nous rejoignons notre campement en fin d&#039;après-midi.&lt;/span&gt;&lt;/p&gt;'),
(11, 3, 'en', 'WELCOME TO JORDAN', NULL, '<p>Upon arrival at <em><strong>Queen Alia International Airport</strong></em>, you will be met by our representative, our driver will take you to your hotel in <em><strong>Amman</strong></em>.<br />You will spend a beautiful night there.</p>'),
(12, 3, 'fr', 'Bienvenue en Jordanie', NULL, '<div class=\"vSx3NFuqXENTAm-7MW8Bh\" style=\"background-color: transparent; box-sizing: border-box; color: #49301f; font-family: Averta,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 400; letter-spacing: normal; orphans: 2; padding-bottom: 12px; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: pre-wrap; word-spacing: 0px;\" data-offset-key=\"ldpa-0-0\" data-editor=\"f5m51\" data-block=\"true\">\r\n<div class=\"public-DraftStyleDefault-block public-DraftStyleDefault-ltr\" style=\"box-sizing: border-box;\" data-offset-key=\"ldpa-0-0\"><span style=\"box-sizing: border-box;\" data-offset-key=\"ldpa-0-0\">A votre arriv&eacute;e &agrave; <strong>l\'a&eacute;roport international Reine-Alia</strong>, vous serez accueillis par notre repr&eacute;sentant, notre chauffeur va vous emm&egrave;nera &agrave; votre h&ocirc;tel &agrave; </span><span style=\"box-sizing: border-box; font-weight: bold;\" data-offset-key=\"ldpa-0-1\"><span style=\"box-sizing: border-box;\" data-text=\"true\">Amman</span></span><span style=\"box-sizing: border-box;\" data-offset-key=\"ldpa-0-2\">.</span></div>\r\n</div>\r\n<div class=\"vSx3NFuqXENTAm-7MW8Bh\" style=\"background-color: transparent; box-sizing: border-box; color: #49301f; font-family: Averta,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 400; letter-spacing: normal; orphans: 2; padding-bottom: 12px; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: pre-wrap; word-spacing: 0px;\" data-offset-key=\"a1inn-0-0\" data-editor=\"f5m51\" data-block=\"true\">\r\n<div class=\"public-DraftStyleDefault-block public-DraftStyleDefault-ltr\" style=\"box-sizing: border-box;\" data-offset-key=\"a1inn-0-0\"><span style=\"box-sizing: border-box;\" data-offset-key=\"a1inn-0-0\">Vous y passerez une belle nuit.</span></div>\r\n</div>'),
(13, 3, 'it', 'Benvenuti in Giordania', NULL, '<p><span data-offset-key=\"2aiil-0-0\">Al vostro arrivo in </span><span data-offset-key=\"2aiil-0-1\">aeroporto <strong>Queen Alia International</strong></span><span data-offset-key=\"2aiil-0-2\">&nbsp;un nostro <strong>rappresentante incaricato</strong> provveder&agrave; nelle vostra assistenza e al disbrigo delle pratiche burocratiche necessarie al vostro soggiorno nel paese.</span></p>\r\n<p><span data-offset-key=\"2aiil-0-2\">Accoglienza del vostro autista e inizio&nbsp;del nostro entusiasmante viaggio.</span></p>'),
(14, 3, 'es', 'Bienvenidos a Jordania', NULL, '<p>A su llegada al Aeropuerto Internacional Reina Alia, un nuestro representante le ayudar&agrave; en la documentaci&oacute;n necesaria para su estad&iacute;a en el pa&iacute;s.</p>\r\n<p>Bienvenido a tu conductor y comienza el nuestro emocionante viaje.</p>'),
(15, 3, 'Ar', 'مرحبا بكم في الاردن', NULL, '<h3 style=\"text-align: right;\"><span style=\"font-size: 14pt;\">.عند وصولك إلى مطار الملكة علياء الدولي ، سوف يأخذك سائقنا إلى الفندق في عمان</span><br /><span style=\"font-size: 14pt;\">سوف تقضي ليلة جميلة هناك</span></h3>'),
(41, 4, 'en', 'SECOND DAY IN PETRA', NULL, '&lt;p&gt;After breakfast, on the way to the second day of exploration! Free day to Discover &quot;&lt;strong&gt;Al Deir&lt;/strong&gt;&quot; (Arabic al-Deir, &quot;the monastery&quot;) which is one of the best known and largest buildings of the ancient city of Petra.&lt;/p&gt;\r\n&lt;p&gt;Its facade measures 45 m wide and 42 m high.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Dinner and overnight at the hote&lt;/strong&gt;l&lt;/p&gt;'),
(42, 4, 'fr', 'Deuxième journné à Petra', NULL, '&lt;p&gt;&lt;span&gt;Après le petit déjeuner en route pour le deuxième jour d&#039;exploration! Journée libre Partez à la découverte de &quot;&lt;strong&gt;Al Deir&lt;/strong&gt;&quot;(de l&#039;arabe al-Deir, « le monastère ») qui est l&#039;un des bâtiments les plus connus et le plus grand de la cité antique de Pétra. Sa façade mesure 45 m de large sur 42 m de haut. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Dîner et nuit à l&#039;hôtel &lt;/strong&gt;&lt;/p&gt;'),
(43, 4, 'it', 'Secondo giorno a Petra', NULL, '&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;2ogut&quot; data-offset-key=&quot;qlc1-0-0&quot;&gt;\r\n&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;qlc1-0-0&quot;&gt;&lt;span data-offset-key=&quot;qlc1-0-0&quot;&gt;Continuiamo la nostra esplorazione della città nabatea. Appuntamento con la guida alle ore &lt;/span&gt;&lt;strong&gt;08:00&lt;/strong&gt;&lt;span data-offset-key=&quot;qlc1-0-2&quot;&gt; al &lt;/span&gt;&lt;strong&gt;Visitor Center &lt;/strong&gt;di Petra&lt;strong&gt;.&lt;/strong&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;2ogut&quot; data-offset-key=&quot;64ouj-0-0&quot;&gt;\r\n&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;64ouj-0-0&quot;&gt;&lt;span data-offset-key=&quot;64ouj-0-0&quot;&gt;Saliremo verso l&#039;&lt;/span&gt;&lt;strong&gt;Alto Luogo del Sacrificio &lt;/strong&gt;&lt;span data-offset-key=&quot;64ouj-0-2&quot;&gt;per poi procedere verso &lt;/span&gt;&lt;span data-offset-key=&quot;64ouj-0-3&quot;&gt;Il &lt;strong&gt;Wadi Farasa&lt;/strong&gt;&lt;/span&gt;&lt;span data-offset-key=&quot;64ouj-0-4&quot;&gt;, &lt;/span&gt;&lt;strong&gt;La Tomba del Giardino&lt;/strong&gt;&lt;span data-offset-key=&quot;64ouj-0-6&quot;&gt; e &lt;/span&gt;&lt;strong&gt;La Tomba del Soldato Romano&lt;/strong&gt;&lt;span data-offset-key=&quot;64ouj-0-8&quot;&gt;.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;2ogut&quot; data-offset-key=&quot;c1nua-0-0&quot;&gt;\r\n&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;c1nua-0-0&quot;&gt;&lt;span data-offset-key=&quot;c1nua-0-0&quot;&gt;Al termine della visita guidata avrete tempo per continuare in autonomia l&#039;esplorazione dello scavo archeologico.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;2ogut&quot; data-offset-key=&quot;7u09r-0-0&quot;&gt;\r\n&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;7u09r-0-0&quot;&gt;&lt;/div&gt;\r\n&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;7u09r-0-0&quot;&gt;Sistemazione: hotel&lt;/div&gt;\r\n&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;7u09r-0-0&quot;&gt;Pasti inclusi: colazione, cena&lt;/div&gt;\r\n&lt;/div&gt;'),
(44, 4, 'es', 'Segundo dìa en Petra', NULL, '&lt;p&gt;Continuamos la nuestra exploración de la ciudad nabatea. Cita con el guía a las 08:00 en el Centro de Visitantes de Petra.<br>Subiremos al Lugar Alto del sacrificio y luego procederemos a Wadi Farasa, La Tomba del Giardino y La Tomba del Soldato Romano.<br>Al final de la visita guiada, tendrá tiempo para continuar la exploración de la excavación arqueológica.&lt;/p&gt;\r\n&lt;p&gt;Alojamiento: hotel<br>Comidas incluidas: desayuno, cena.&lt;/p&gt;'),
(45, 4, 'Ar', 'يوم الثاني في البتراء', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt; بعد تناول وجبة الفطور&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;  موعد مع زيارة حرة لمنطقة الدير من ضمن أشهر البنيات الموجودة في البتراء &lt;span class=&quot;short_text&quot; id=&quot;result_box&quot; lang=&quot;ar&quot; style=&quot;text-align: right; color: #222222; text-transform: none; text-indent: 0px; letter-spacing: normal; font-family: arial,sans-serif; font-style: normal; font-variant: normal; font-weight: 400; text-decoration: none; word-spacing: 0px; white-space: normal; position: relative; z-index: 2; word-wrap: break-word; min-height: 89px; orphans: 2; -webkit-text-stroke-width: 0px; background-color: transparent;&quot;&gt;&lt;span style=&quot;color: #222222; position: static; z-index: auto; word-wrap: break-word; min-height: 0px;&quot;&gt;تبلغ مساحتها واجهتها 45 م على ارتفاع 42 م&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h3&gt;'),
(46, 5, 'en', 'FIRST DAY IN PETRA', NULL, '&lt;p&gt;After the breakfast offered by the hotel, meet at &lt;strong&gt;08:00&lt;/strong&gt; with the guide of the &lt;strong&gt;Petra&lt;/strong&gt; Visitor Center.&lt;/p&gt;\r\n&lt;p&gt;<br>We head to the archaeological site where, with your local official guide, we will take you to the Nabataean site; cross the &lt;strong&gt;Siq&lt;/strong&gt;, famous canyon that leads directly to &lt;strong&gt;Khazné,&lt;/strong&gt; one of the jewels of the Nabataean city, through &lt;strong&gt;theaters&lt;/strong&gt; and &lt;strong&gt;royal tombs.&lt;/strong&gt;<br>We stop for lunch at the &lt;strong&gt;Al-Basin restaurant&lt;/strong&gt;, located in the Nabataean city.<br>At the end of lunch, we continue our journey to the Monastery.&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;Night at the hotel&lt;/strong&gt;&lt;/p&gt;'),
(47, 5, 'fr', 'Premier jour à Petra', NULL, '&lt;p&gt;Après le petit-déjeuner proposé par l&#039;hôtel, rendez-vous à&lt;strong&gt; 08h00&lt;/strong&gt; avec le guide du centre d&#039;accueil de &lt;strong&gt;Petra.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;<br>Nous nous dirigeons vers le site archéologique où, avec votre guide officiel local, nous vous conduirons au site nabatéen; parcourez &lt;strong&gt;le Siq&lt;/strong&gt;, célèbre canyon qui mène directement à &lt;strong&gt;Khazné&lt;/strong&gt;, l&#039;un des joyaux de la ville nabatéenne, en passant par &lt;strong&gt;les théâtres&lt;/strong&gt; et &lt;strong&gt;les tombeaux royaux.&lt;/strong&gt;<br>Nous nous arrêtons pour un déjeuner au &lt;strong&gt;restaurant Al-Basin,&lt;/strong&gt; situé dans la ville nabatéenne.<br>À la fin du déjeuner, nous continuons notre route vers le Monastaire.&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;Nuit à l&#039;hôtel&lt;/strong&gt;&lt;/p&gt;'),
(48, 5, 'it', 'Prima giornata a Petra', NULL, '&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;d39hf&quot; data-offset-key=&quot;b6jrb-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;b6jrb-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;b6jrb-0-0&quot;&gt;Dopo la colazione proposta dall&#039;hotel, alle ore &lt;/span&gt;&lt;span data-offset-key=&quot;b6jrb-0-1&quot;&gt;08:00&lt;/span&gt;&lt;span data-offset-key=&quot;b6jrb-0-2&quot;&gt; appuntamento con la guida al &lt;/span&gt;&lt;span data-offset-key=&quot;b6jrb-0-3&quot;&gt;Visitor Center&lt;/span&gt;&lt;span data-offset-key=&quot;b6jrb-0-4&quot;&gt; di Petra. &lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;d39hf&quot; data-offset-key=&quot;26vac-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;26vac-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;26vac-0-0&quot;&gt;Ci dirigiamo verso il sito archeologico dove insieme alla tua guida locale ufficiale ti accompagneremo verso il sito nabateo; camminata attraverso il &lt;/span&gt;&lt;span data-offset-key=&quot;26vac-0-1&quot;&gt;Siq&lt;/span&gt;&lt;span data-offset-key=&quot;26vac-0-2&quot;&gt;, famoso canyon che conduce direttamente a &lt;/span&gt;&lt;span data-offset-key=&quot;26vac-0-3&quot;&gt;Khazné&lt;/span&gt;&lt;span data-offset-key=&quot;26vac-0-4&quot;&gt;, uno dei gioielli della citta nabatea, procedendo per &lt;/span&gt;&lt;span data-offset-key=&quot;26vac-0-5&quot;&gt;La Strada delle Facciate&lt;/span&gt;&lt;span data-offset-key=&quot;26vac-0-6&quot;&gt;, &lt;/span&gt;&lt;span data-offset-key=&quot;26vac-0-7&quot;&gt;i Teatri&lt;/span&gt;&lt;span data-offset-key=&quot;26vac-0-8&quot;&gt;, &lt;/span&gt;&lt;span data-offset-key=&quot;26vac-0-9&quot;&gt;Le Tombe Reali&lt;/span&gt;&lt;span data-offset-key=&quot;26vac-0-10&quot;&gt;, &lt;/span&gt;&lt;span data-offset-key=&quot;26vac-0-11&quot;&gt;Il Cardo&lt;/span&gt;&lt;span data-offset-key=&quot;26vac-0-12&quot;&gt;, &lt;/span&gt;&lt;span data-offset-key=&quot;26vac-0-13&quot;&gt;Il Castello della Figlia del Faraone.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;d39hf&quot; data-offset-key=&quot;95th2-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;95th2-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;95th2-0-0&quot;&gt;Ci fermiamo per un pranzo al ristorante &lt;/span&gt;&lt;span data-offset-key=&quot;95th2-0-1&quot;&gt;Al- Basin&lt;/span&gt;&lt;span data-offset-key=&quot;95th2-0-2&quot;&gt;, situato all&#039;interno della citta nabatea.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;d39hf&quot; data-offset-key=&quot;90lps-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;90lps-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;90lps-0-0&quot;&gt;Al termine del pranzo, continuiamo il nostro cammino verso &lt;/span&gt;&lt;span data-offset-key=&quot;90lps-0-1&quot;&gt;Il Monastero&lt;/span&gt;&lt;span data-offset-key=&quot;90lps-0-2&quot;&gt;.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;d39hf&quot; data-offset-key=&quot;ck355-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;ck355-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;ck355-0-0&quot;&gt;Pernottamento in hotel&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;'),
(49, 5, 'es', 'Primer dìa en Petra', NULL, '&lt;p&gt;Después del desayuno propuesto por el hotel, a las 08:00 cita con la guía del Centro de Visitantes en Petra.<br>Nos dirigimos hacia el sitio arqueológico donde, junto con su guía oficial local, lo llevaremos al sitio de Nabataean; Camine por el Siq, un famoso cañón que conduce directamente a Khazné, una de las joyas de la ciudad nabatea, y continúa por la Strada delle Facte, los teatros, las tumbas reales, Il Cardo, el Castello della Figlia de Faraone.<br>Paramos a almorzar en el restaurante Al-Basin, ubicado dentro de la ciudad nabatea.<br>Al final del almuerzo, continuamos nuestro viaje hacia El Monastero.<br>Pernocte en el hotel.&lt;/p&gt;'),
(50, 5, 'Ar', 'أول يوم في البتراء', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;بعد الإفطار الذي يقدمه الفندق ، اجتمع في الساعة 08:00 مع الدليل مركز زوار البتراء.&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;<br>نتوجه إلى الموقع الأثري حيث المرشد السياحي المحلي ، سيأخدكم إلى الموقع النبطية.&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;عبور السيق ، الوادي الشهير الذي يؤدي مباشرة إلى خزنة ، واحدة من أسرار المدينة النبطية ، من خلال المسارح والمقابر الملكية.<br>نتوقف لتناول طعام الغداء في مطعم Al-Basin&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;، الذي يقع في المدينة النبطية.<br>في نهاية الغداء ،&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;نواصل رحلتنا إلى الدير.&lt;/h3&gt;\r\n&lt;p style=&quot;text-align: right;&quot;&gt;&lt;/p&gt;'),
(96, 6, 'en', 'FIRST DAY AT DEAD SEA', NULL, '&lt;p&gt;We take the road from &lt;strong&gt;Wadi Rum&lt;/strong&gt; to the &lt;strong&gt;Dead Sea.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;We continue our exploration to the waters of the famous Dead Sea, the highest salinity water body in the world (approximately 27.5% against around 2 and 4% in seawater oscillates).<br>Experience the &lt;strong&gt;&quot;bathing&quot;&lt;/strong&gt; in this sea where you can only float! The Dead Sea offers a landscape of beauty unique in the world.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Walking time: 1-2h&lt;/strong&gt;&lt;/p&gt;'),
(97, 6, 'fr', 'Premier jour à la mer morte', NULL, '&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;dia8t&quot; data-offset-key=&quot;87ijr-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;87ijr-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;87ijr-0-0&quot;&gt;Nous prenons la route de &lt;strong&gt;Wadi Rum&lt;/strong&gt; vers&lt;strong&gt; la mer morte. &lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;87ijr-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;87ijr-0-0&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;87ijr-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;87ijr-0-0&quot;&gt;Nous poursuivons notre exploration jusqu&#039;aux eaux de la célèbre mer Morte, étendue d&#039;eau au taux de salinité le plus élevé au monde (approximativement 27,5 % contre environs 2 et 4 % dans l’eau de mer oscille).&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;87ijr-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;87ijr-0-0&quot;&gt; Vivez l&#039;expérience de la « &lt;strong&gt;baignade&lt;/strong&gt; », dans cette mer où l&#039;on ne peut que flotter ! La mer Morte offre un paysage de toute beauté unique au monde.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;87ijr-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;87ijr-0-0&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;dia8t&quot; data-offset-key=&quot;b1pcu-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;b1pcu-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;strong&gt;Temps de marche : 1-2h&lt;/strong&gt;&lt;span data-offset-key=&quot;b1pcu-0-1&quot;&gt; &lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;'),
(98, 6, 'it', 'Primo giorno al Mar Morto', NULL, '&lt;p&gt;Prendiamo la strada da Wadi Rum al Mar Morto.&lt;/p&gt;\r\n&lt;p&gt;Continuiamo la nostra esplorazione verso le acque del famoso Mar Morto, con la concentrazione di salinità più alta del mondo (circa il 27,5% contro il 2 e il 4% medio marino).<br>Prova il &quot;bagno&quot; in questo mare dove puoi solo galleggiare! Il Mar Morto offre un paesaggio di bellezza unico al mondo.<br><br>&lt;/p&gt;'),
(99, 6, 'es', 'Primer día en el mar muerto', NULL, '&lt;p&gt;Tomamos el camino de Wadi Rum al Mar Muerto.&lt;/p&gt;\r\n&lt;p&gt;Continuamos nuestra exploración hacia las aguas del famoso Mar Muerto, con la concentración de salinidad más alta en el mundo (aproximadamente 27.5% contra 2 y 4% de promedio marino).<br>¡Prueba el &quot;baño&quot; en este mar donde solo puedes flotar! El Mar Muerto ofrece un paisaje de belleza único en el mundo.&lt;/p&gt;'),
(100, 6, 'Ar', 'اليوم الأول في البحر الميت', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;نأخذ الطريق من وادي رم إلى البحر الميت.&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;نواصل استكشافنا لمياه البحر الميت الشهيرة ، وهي أكثر مياه ملوحة في العالم ,تجربة &quot;الاستحمام&quot; في هذا البحر حيث يمكنك فقط تطفو! يقدم البحر الميت مناظر طبيعية فريدة من نوعها في العالم.&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;وقت المشي: 1-ساعات 2&lt;/h3&gt;'),
(101, 7, 'en', 'WADI RUM / AL KARAK / MADABA / MONT NEBO  / AMMAN', NULL, '&lt;p&gt;&lt;strong&gt;At 8 o&#039;clock,&lt;/strong&gt; after the Bedouin breakfast, we head north to the capital of the Hashemite Kingdom of Jordan.&lt;/p&gt;\r\n&lt;p&gt;We will make a first stop at the castle of &lt;strong&gt;Al-Karak&lt;/strong&gt;, located on a rocky spur, more than 900 m of altitude. Later, we will continue our journey by taking the old route of the Kings, until &lt;strong&gt;Mount Nebo&lt;/strong&gt; and &lt;strong&gt;Madaba&lt;/strong&gt;, until arriving at &lt;strong&gt;Amman&lt;/strong&gt;.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Night at the hotel.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Al-Karak Castle&lt;/strong&gt; was a fortress considered impregnable; we must imagine Jordan of the twelfth century. d.C, then land of conquest for the Crusaders, during the construction of the fortress, whose mission was to control the lands beyond the Jordan.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Mount Nebo&lt;/strong&gt; is considered one of the fundamental steps for those who want to immerse themselves in culture, history and religion.&lt;/p&gt;\r\n&lt;p&gt;In fact, its ancient Christian churches and archaeological museum are well suited to bear witness to millennia of civilization.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Madaba&lt;/strong&gt;, a city south of &lt;strong&gt;Amman&lt;/strong&gt;, is one of the most important Christian sites in Jordan, as well as in the Middle East. Where, according to the Holy Scriptures, Moses had the vision of the Promised Land and where Pope John Paul II, as a gesture of peace, planted an olive tree next to the Byzantine chapel of &lt;strong&gt;Madaba.&lt;/strong&gt;&lt;/p&gt;'),
(102, 7, 'fr', 'Wadi Rum / Al Karak / Madaba / Monte Nebo / Amman', NULL, '&lt;p&gt;&lt;strong&gt;À 8 heures&lt;/strong&gt;, après le petit-déjeuner bédouin, nous nous dirigeons vers le nord: vers la capitale du royaume hachémite de Jordanie. Nous ferons un premier arrêt au &lt;strong&gt;château d&#039;Al-Karak&lt;/strong&gt;, situé sur un éperon rocheux, à plus de 900 m d&#039;altitude. Plus tard, nous poursuivrons notre voyage en reprenant l&#039;ancienne route des rois, jusqu&#039;au &lt;strong&gt;mont Nebo&lt;/strong&gt; et à &lt;strong&gt;Madaba,&lt;/strong&gt; jusqu&#039;à arriver à&lt;strong&gt; Amman.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Nuit à l&#039;hôtel.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Le château d&#039;Al-Karak&lt;/strong&gt; était une forteresse considérée comme imprenable; il faut imaginer la Jordanie du &lt;strong&gt;XIIe siècle.&lt;/strong&gt; d.C, alors terre de conquête pour les Croisés, lors de la construction de la forteresse, dont la mission était de contrôler les terres au-delà du Jourdain.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Le mont Nebo&lt;/strong&gt; est considéré comme l&#039;une des étapes fondamentales pour ceux qui entendent s&#039;imprégner de culture, d&#039;histoire et de religion.&lt;/p&gt;\r\n&lt;p&gt;En fait, ses &lt;strong&gt;anciennes églises chrétiennes&lt;/strong&gt; et son musée archéologique sont bien adaptés pour témoigner de millénaires de civilisation.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Madaba&lt;/strong&gt;, une ville située au sud d&#039;&lt;strong&gt;Amman&lt;/strong&gt;, est l&#039;un des sites chrétiens les plus importants en Jordanie, ainsi qu&#039;au Moyen-Orient. Là où, selon les Saintes Écritures, Moïse avait la vision de la Terre promise et où le pape Jean-Paul II, en geste de paix, planta un olivier à côté de la chapelle byzantine de &lt;strong&gt;Madaba.&lt;/strong&gt;&lt;/p&gt;'),
(103, 7, 'it', 'Wadi Rum / Al Karak / Madaba / Monte Nebo / Amman', NULL, '&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;caa18&quot; data-offset-key=&quot;b62ik-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;b62ik-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;b62ik-0-0&quot;&gt;Alle ore &lt;/span&gt;&lt;span data-offset-key=&quot;b62ik-0-1&quot;&gt;08:00&lt;/span&gt;&lt;span data-offset-key=&quot;b62ik-0-2&quot;&gt;, dopo la colazione beduina, ci dirigiamo verso nord: verso la capitale del Regno Hashemita di Giordania. Faremo una prima tappa al &lt;/span&gt;&lt;span data-offset-key=&quot;b62ik-0-3&quot;&gt;Castello di Al-Karak&lt;/span&gt;&lt;span data-offset-key=&quot;b62ik-0-4&quot;&gt;, situato su uno sperone roccioso, a più di 900m di altezza. In seguito proseguiremo il nostro viaggio, prendendo a ritroso l&#039;antica Strada dei Re, per il &lt;/span&gt;&lt;span data-offset-key=&quot;b62ik-0-5&quot;&gt;Monte Nebo&lt;/span&gt;&lt;span data-offset-key=&quot;b62ik-0-6&quot;&gt; e&lt;/span&gt;&lt;span data-offset-key=&quot;b62ik-0-7&quot;&gt; Madaba&lt;/span&gt;&lt;span data-offset-key=&quot;b62ik-0-8&quot;&gt;, fino ad arrivare ad &lt;/span&gt;&lt;span data-offset-key=&quot;b62ik-0-9&quot;&gt;Amman&lt;/span&gt;&lt;span data-offset-key=&quot;b62ik-0-10&quot;&gt;.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;b62ik-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;b62ik-0-10&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;caa18&quot; data-offset-key=&quot;13lkr-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;13lkr-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;13lkr-0-0&quot;&gt;Pernottamento in hotel.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;13lkr-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;13lkr-0-0&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;caa18&quot; data-offset-key=&quot;bktpb-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;bktpb-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;bktpb-0-0&quot;&gt;Il Castello di Al-Karak&lt;/span&gt;&lt;span data-offset-key=&quot;bktpb-0-1&quot;&gt; era una roccaforte considerata inespugnabile; bisogna immaginare la Giordania del XII sec. d.C, allora terra di conquista per i Crociati, quando fu edificata la fortezza, la cui missione era quella di controllare le terre al di là del Giordano.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;bktpb-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;bktpb-0-1&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;caa18&quot; data-offset-key=&quot;dq2ll-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;dq2ll-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;dq2ll-0-0&quot;&gt;Il Monte Nebo&lt;/span&gt;&lt;span data-offset-key=&quot;dq2ll-0-1&quot;&gt;, viene considerata una delle tappe fondamentali per chi intende imbevarsi di cultura, storia e religione; infatti le sue antiche chiese cristiane ed il museo archeologico ben si prestano a testimoniare millenni di civiltà.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;dq2ll-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;dq2ll-0-1&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;caa18&quot; data-offset-key=&quot;brenp-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;brenp-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;brenp-0-0&quot;&gt;Madaba&lt;/span&gt;&lt;span data-offset-key=&quot;brenp-0-1&quot;&gt;, città a sud di Amman, è uno dei siti cristiani più importanti della Giordania, nonchè del Medio-oriente. Lì, dove secondo le Sacre Scritture, Mosè ebbe la visione della Terra Promessa e lì dove Papa Giovanni Paolo II come gesto di pace, piantò un albero di ulivo a fianco della Cappella bizantina di Madaba.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;'),
(104, 7, 'es', 'Wadi Rum / Al Karak / Madaba / Monte Nebo / Amman', NULL, '&lt;p&gt;A las 08:00, después de un desayuno beduino, nos dirigimos hacia el norte: hacia la capital del Reino Hachemita de Jordania. Haremos una primera parada en el Castillo de Al-Karak, ubicado en un espolón rocoso, de más de 900 m de altura. Más tarde continuaremos nuestro viaje, retomando el antiguo Camino de los Reyes, a Mount Nebo y Madaba, hasta llegar a Amman.&lt;/p&gt;\r\n&lt;p&gt;Pernocte en el hotel.&lt;/p&gt;\r\n&lt;p&gt;El castillo de Al-Karak era una fortaleza considerada inexpugnable; Hay que imaginar el Jordán del siglo XII. d.C, entonces una tierra de conquista para los cruzados, cuando se construyó la fortaleza, cuya misión era controlar las tierras más allá del Jordán.&lt;/p&gt;\r\n&lt;p&gt;Mount Nebo es considerado una de las etapas fundamentales para aquellos que pretenden imbuirse de la cultura, la historia y la religión; de hecho, sus antiguas iglesias cristianas y el museo arqueológico están bien adaptados para presenciar milenios de civilización.&lt;/p&gt;\r\n&lt;p&gt;Madaba, una ciudad al sur de Amman, es uno de los sitios cristianos más importantes de Jordania, así como en el Medio Oriente. Allí, donde según las Santas Escrituras, Moisés tuvo la visión de la Tierra Prometida y allí donde el Papa Juan Pablo II, como gesto de paz, plantó un olivo junto a la Capilla Bizantina de Madaba.&lt;/p&gt;'),
(105, 7, 'Ar', 'وادي رم / الكرك / مأدبا / جبل نيبو/ عمان', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: &#039;book antiqua&#039;, palatino, serif;&quot;&gt;عند الساعة الثامنة ، بعد الإفطار البدوي ، نتجه شمالاً إلى عاصمة المملكة الأردنية الهاشمية. سوف نتوقف أولاً في &lt;span style=&quot;text-decoration: underline;&quot;&gt;قلعة الكرك&lt;/span&gt; ، التي تقع على ارتفاع صخري ، على &lt;/span&gt;&lt;span style=&quot;font-family: &#039;book antiqua&#039;, palatino, serif;&quot;&gt;ارتفاع يزيد عن 900 م.ثم سوف نواصل رحلتنا من خلال اتخاذ الطريق للملوكي ، حتى &lt;span style=&quot;text-decoration: underline;&quot;&gt;جبل نيبو ومادبا&lt;/span&gt; ، حتى وصولا إلى عمان.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;<br>&lt;b&gt;قلعة الكرك&lt;/b&gt;&lt;span&gt; &lt;/span&gt;هي إحدى أكبر وأهم&lt;span&gt; &lt;/span&gt;&lt;a href=&quot;https://ar.wikipedia.org/wiki/قائمة_القلاع_الصليبية&quot; title=&quot;قائمة القلاع الصليبية&quot;&gt;قلاع الحملات الصليبيَّة&lt;/a&gt;&lt;span&gt; &lt;/span&gt;بالأردن وبلاد الشام، تبلغ مساحتها 25,300 متر مربع وترتفع عن سطح البحر قرابة 1000 متر. بُنيت القلعة على يد&lt;span&gt; &lt;/span&gt;&lt;a href=&quot;https://ar.wikipedia.org/wiki/فولك_ملك_بيت_المقدس&quot; title=&quot;فولك ملك بيت المقدس&quot;&gt;فولك أمير بيت المقدس&lt;/a&gt;&lt;span&gt; &lt;/span&gt;لحماية الجهة الجنوبيَّة من بلاد الشام وتأمين الطريق بين دمشق ومصر أثناء&lt;span&gt; &lt;/span&gt;&lt;a href=&quot;https://ar.wikipedia.org/wiki/الحروب_الصليبية&quot; class=&quot;mw-redirect&quot; title=&quot;الحروب الصليبية&quot;&gt;الحروب الصليبية&lt;/a&gt;،&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: &#039;book antiqua&#039;, palatino, serif;&quot;&gt;يعتبر جبل نيبو واحدة من الخطوات الأساسية لأولئك الذين يريدون الانغماس في الثقافة والتاريخ والدين.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: &#039;book antiqua&#039;, palatino, serif;&quot;&gt;مادبا ، وهي مدينة تقع جنوب عمان ، هي واحدة من أهم المواقع المسيحية في الأردن ، وكذلك في الشرق الأوسط. حيث، وفقا للكتاب المقدس  &lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span&gt;في الواقع ، فإن كنائسها المسيحية القديمة والمتحف الأثري هي مناسبة تمامًا لتشهد على مدى آلاف السنين من الحضارة&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: &#039;book antiqua&#039;, palatino, serif;&quot;&gt;، في بادرة للسلام، وزرعت شجرة زيتون بجانب الكنيسة البيزنطية في مادبا.&lt;/span&gt;&lt;/h3&gt;'),
(111, 8, 'en', 'MA&#039;IN HOT SPRINGS', NULL, '&lt;p&gt;Take the time to wander around your accommodation, in a natural and preserved environment.&lt;/p&gt;\r\n&lt;p&gt;Here springs several sources of water from the &lt;strong&gt;Wadi Mujib &lt;/strong&gt;rock, all at different temperatures. These sources have been known since ancient times for their healing properties and especially for rheumatism.&lt;/p&gt;\r\n&lt;p&gt;The entrance fee &lt;strong&gt;(15JD / person)&lt;/strong&gt; gives you access to the small natural pool of hot water located under the waterfall. Jordanian families come here to relax on weekends.&lt;/p&gt;\r\n&lt;p&gt;Today begins the relaxation and you can enjoy a care in your accommodation, at the edges of hot springs.&lt;/p&gt;'),
(112, 8, 'fr', 'Ma&#039;in Sources Chaudes', NULL, '&lt;p&gt;&lt;span&gt;Prenez le temps de vous balader autour de votre hébergement, dans un cadre naturel et préservé. Ici jaillissent plusieurs sources d’eau de la roche du &lt;strong&gt;Wadi Mujib&lt;/strong&gt;, toutes à températures différentes. Ces sources sont connues depuis l’Antiquité pour leurs vertus curatives et notamment pour les rhumatismes. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;Le droit d’entrée &lt;strong&gt;(15JD/personne)&lt;/strong&gt; vous donne accès au &lt;strong&gt;petit bassin naturel d’eau chaude&lt;/strong&gt; situé sous la cascade. Les familles jordaniennes viennent s’y détendre le week-end. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;Aujourd’hui commence la détente et vous pourrez profiter d’un soin dans votre hébergement, aux bords des sources chaudes.&lt;/span&gt;&lt;/p&gt;'),
(113, 8, 'it', 'Cascate d&#039;acqua dolce Mai&#039;in', NULL, '&lt;p&gt;Prenditi il ​​tempo per passeggiare intorno al tuo alloggio, in un ambiente naturale e preservato. Qui sgorgano diverse fonti d&#039;acqua dalla roccia di Wadi Al Mujib, tutte a temperature diverse. Queste fonti sono conosciute sin dai tempi antichi per le loro proprietà curative e specialmente per i reumatismi. Il biglietto d&#039;ingresso (15 JD / persona) ti dà accesso alla piccola piscina naturale di acqua calda situata sotto la cascata. Le famiglie giordane vengono qui per rilassarsi durante il fine settimana. Oggi inizia il relax e puoi goderti una cura nel tuo alloggio, ai bordi delle terme.&lt;/p&gt;'),
(114, 8, 'es', 'Cascadas de agua dulce Ma&#039;in', NULL, '&lt;p&gt;Tómese el tiempo para caminar alrededor de su alojamiento en un entorno natural y preservado. Aquí fluyen diferentes fuentes de agua de la roca de Wadi Al Mujib, todas a diferentes temperaturas. Estas fuentes se conocen desde la antigüedad por sus propiedades curativas y especialmente por el reumatismo. La tarifa de entrada (15 JD / persona) le da acceso a la pequeña piscina de agua caliente natural ubicada debajo de la cascada. Las familias jordanas vienen aquí para relajarse los fines de semana. La relajación comienza hoy y puede disfrutar de un cuidado en su alojamiento, en el borde del spa.&lt;/p&gt;'),
(115, 8, 'Ar', 'حمامات ماعين', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;خذ وقتك في التجول حول المنتجع ، في بيئة طبيعية ومحفوظة. هنا ينابيع حمامات معين ذات مصادر طبيعية للمياه من صخرة وادي الموجب ، وجميعها في درجات حرارة مختلفة. وقد عرفت هذه المصادر منذ العصور القديمة لخصائصها العلاجية وخاصة للروماتيزم.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;تتيح لك رسوم الدخول (15 دينار / فرد) الوصول إلى المسبح الطبيعي الصغير من المياه الساخنة الواقعة تحت الشلال. تأتي العائلات الأردنية إلى هنا للاسترخاء في عطلات نهاية الأسبوع.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;اليوم يبدأ بالاسترخاء ويمكنك التمتع بالاستجمام في منتجع، على أطراف الينابيع الساخنة.&lt;/span&gt;&lt;/h3&gt;'),
(116, 9, 'en', 'AMMAN / MADABA / MONT NEBO / DANA / AL SHOBAK / PETRA', NULL, '&lt;p&gt;Departing for the city of &lt;strong&gt;Madaba&lt;/strong&gt;, just 30 km from &lt;strong&gt;Amman&lt;/strong&gt; via a 5000-year-old road,&lt;strong&gt; the Kings Road,&lt;/strong&gt; Madaba is one of the most memorable places in the Holy Land called &lt;strong&gt;&quot;City of Mosaics&quot;.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;We continue to discover &lt;strong&gt;Mount Nebo&lt;/strong&gt;, the place where Moses saw the Holy Land of Canaan, above which you can enjoy a breathtaking view of the Dead Sea and the Jordan Valley.&lt;/p&gt;\r\n&lt;p&gt;We continue towards &lt;strong&gt;Dana&lt;/strong&gt;, the village of Dana with a breathtaking view of the valley and the wadi.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Shoubak &lt;/strong&gt;and its citadel before taking the road to the Rose city of &lt;strong&gt;Petra.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Night at the hotel&lt;/strong&gt;&lt;/p&gt;'),
(117, 9, 'fr', 'Amman / Madaba / Mont Nebo / Dana / Al Shoubak / Petra', NULL, '&lt;p&gt;Départ pour la ville de&lt;strong&gt; Madaba&lt;/strong&gt;, à seulement 30 km d&#039;Amman par une route vieille de 5000 ans, la Route des rois, Madaba est l&#039;un des endroits les plus mémorables de la Terre Sainte appelé&lt;strong&gt; &quot;ville des mosaïques&quot;.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Nous continuons la découverte de la région en direction du &lt;strong&gt;mont Nebo&lt;/strong&gt;, l&#039;endroit où Moïse a vu la Terre Sainte de Canaan au-dessus de laquelle vous pourrez profiter d&#039;une vue imprenable sur la &lt;strong&gt;mer Morte&lt;/strong&gt; et la vallée du Jourdain.&lt;/p&gt;\r\n&lt;p&gt;Nous continuons  en direction de Dana, le village de&lt;strong&gt; Dana&lt;/strong&gt; avec une vue imprenable sur la vallée et le wadi.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Shoubak&lt;/strong&gt; et sa citadelle avant de prendre la route pour la ville rose de&lt;strong&gt; Petra.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Nuit à l&#039;hôtel&lt;/strong&gt;&lt;/p&gt;'),
(118, 9, 'it', 'Amman / Madaba / Monte Nebo / Dana / Al Shoubak / Petra', NULL, '&lt;p&gt;&lt;span data-offset-key=&quot;42lm1-0-0&quot;&gt;Partenza per la città di &lt;/span&gt;&lt;span data-offset-key=&quot;42lm1-0-1&quot;&gt;Madaba&lt;/span&gt;&lt;span data-offset-key=&quot;42lm1-0-2&quot;&gt;, appena 30 Km da Amman lungo una strada che ha ben 5000 anni, &lt;/span&gt;&lt;span data-offset-key=&quot;42lm1-0-3&quot;&gt;la Strada dei Re&lt;/span&gt;&lt;span data-offset-key=&quot;42lm1-0-4&quot;&gt;, Madaba è uno dei luoghi più memorabili della Terra Santa detta “città dei mosaici”. Continuiamo la scoperta della zona verso &lt;/span&gt;&lt;span data-offset-key=&quot;42lm1-0-5&quot;&gt;Monte Nebo,&lt;/span&gt;&lt;span data-offset-key=&quot;42lm1-0-6&quot;&gt; il luogo in cui Mosè vide la Terra Santa di Canaan sopra il quale si può godere di una vista mozzafiato sul&lt;/span&gt;&lt;span data-offset-key=&quot;42lm1-0-7&quot;&gt; Mar Morto&lt;/span&gt;&lt;span data-offset-key=&quot;42lm1-0-8&quot;&gt; e la Valle del Giordano. Proseguiamo con la famosa Via dei Re verso &lt;/span&gt;&lt;span data-offset-key=&quot;42lm1-0-9&quot;&gt;Dana &lt;/span&gt;&lt;span data-offset-key=&quot;42lm1-0-10&quot;&gt;il villaggio di Dana con vista mozzafiato sulla valle e il wadi. Shoubak e la sua cittadella prima di riprendere la strada per la città rosa di Petra.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span data-offset-key=&quot;42lm1-0-10&quot;&gt;Pernottamento in hotel&lt;/span&gt;&lt;/p&gt;'),
(119, 9, 'es', 'Amman / Madaba / Monte Nebo / Dana / Al Shoubak / Petra', NULL, '&lt;p&gt;Salida hacia la ciudad de Madaba, a solo 30 km de Amman por un camino que tiene 5000 años, el Camino de los Reyes, Madaba es uno de los lugares más memorables de la Tierra Santa llamada &quot;ciudad de los mosaicos&quot;. Continuamos el descubrimiento del área hacia el Monte Nebo, el lugar donde Moisés vio la Tierra Santa de Canaán sobre la cual puede disfrutar de una vista impresionante del Mar Muerto y el Valle del Jordán. Continuamos con la famosa Via dei Re hacia Dana, el pueblo de Dana, con impresionantes vistas del valle y el wadi. Shoubak y su ciudadela antes de emprender el camino hacia la ciudad rosa de Petra.&lt;/p&gt;\r\n&lt;p&gt;Pernocte en el hotel.&lt;/p&gt;'),
(120, 9, 'Ar', 'عمان / مأدبا - جبل نيبو/ ضانا / الشوبك / البتراء', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: &#039;book antiqua&#039;, palatino, serif; font-size: 14pt;&quot;&gt;المغادرة إلى مدينة مادبا ، على بعد 30 كم من عمان عبر طريق يبلغ عمره 5000 عام ، الطريق الملوكي ، مادبا هي واحدة من أكثر الأماكن التي لا تنسى في الأرض المقدسة التي تسمى &quot;مدينة الفسيفساء&quot;.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: &#039;book antiqua&#039;, palatino, serif; font-size: 14pt;&quot;&gt;نستمر في اكتشاف جبل نيبو ، المكان الذي رأى فيه موسى أرض كنعان المقدسة ، فوقها يمكنك الاستمتاع بمنظر خلاب للبحر الميت ووادي الأردن.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: &#039;book antiqua&#039;, palatino, serif; font-size: 14pt;&quot;&gt;نستمر نحو دانا ، قرية دانا مع إطلالة خلابة على وادي شوبك.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: &#039;book antiqua&#039;, palatino, serif; font-size: 14pt;&quot;&gt;والقلعة قبل اتخاذ الطريق إلى مدينة البتراء الوردية .&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: &#039;book antiqua&#039;, palatino, serif; font-size: 14pt;&quot;&gt;ليلة مميزة في الفندق&lt;/span&gt;&lt;/h3&gt;'),
(121, 10, 'en', 'DANA / WADI GHUWEIR / PETRA', NULL, '&lt;p&gt;After breakfast, we drive to&lt;strong&gt; Ghuweire Canyon!&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Hike in this natural setting, between the hanging gardens accompanied by your local guide.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Hike 5h &lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Picnic lunch&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Then Transfer to &lt;strong&gt;Petra&lt;/strong&gt; through the desert of &lt;strong&gt;Wadi Araba&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Dinner and overnight at the hotel&lt;/strong&gt;&lt;/p&gt;'),
(122, 10, 'fr', 'Dana / Wadi Ghuweire / Pétra', NULL, '&lt;p&gt;&lt;span&gt;Après le petit déjeuner, en route pour &lt;strong&gt;le canyon du Ghuweire!&lt;/strong&gt; &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;&lt;strong&gt;Randonnée&lt;/strong&gt; dans cet écrin de nature, entre les jardins suspendus accompagné de votre guide local. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Randonnée 5h Pique nique le midi &lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;Puis Transfert à &lt;strong&gt;Pétra&lt;/strong&gt; en passant par le désert de &lt;strong&gt;Wadi Araba &lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Dîner et nuit à l&#039;hôtel &lt;/strong&gt;&lt;/p&gt;'),
(123, 10, 'it', 'Dana / Wadi Ghuweir / Petra', NULL, '&lt;p&gt;Dopo colazione, partenza per il Ghuweire Canyon! Fai un&#039;escursione in questo ambiente naturale, tra i giardini pensili accompagnati dalla tua guida locale. Escursione di 5 ore.&lt;/p&gt;\r\n&lt;p&gt;Pranzo al sacco e trasferimento a Petra attraverso il deserto di Wadi Araba&lt;/p&gt;\r\n&lt;p&gt;Cena e pernottamento in hotel&lt;/p&gt;'),
(124, 10, 'es', 'Dana / Wadi Ghuweir / Petra', NULL, '&lt;p&gt;Después del desayuno, salida hacia el cañón Ghuweire! Realice una excursión en este entorno natural, entre los jardines colgantes acompañados por su guía local. Excursión de 5 horas.&lt;/p&gt;\r\n&lt;p&gt;Almuerzo para llevar y traslado a Petra a través del desierto de Wadi Araba.&lt;/p&gt;\r\n&lt;p&gt;Cena y alojamiento en el hotel.&lt;/p&gt;'),
(125, 10, 'Ar', 'ضانا / وادي غوير/ البتراء', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;بعد الإفطار ، قم بقيادة سيارتك إلى وادي غوير!&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;تنزه في هذا المكان الطبيعي ، بين الحدائق المعلقة مصحوبة بمرشدك المحلي.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;تنزه خمس ساعات تقريبا نزهة الغداء&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;ثم نقل إلى البتراء عبر صحراء وادي عربة&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;العشاء والمبيت في الفندق&lt;/span&gt;&lt;/h3&gt;'),
(126, 11, 'en', 'MADABA / MONT NEBO / DEAD SEA / AL KARAK / PETRA', NULL, '&lt;p&gt;After breakfast visit &lt;strong&gt;Madaba.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;It is one of the most memorable sites in the Holy Land. Called &lt;strong&gt;&quot;the city of mosaic&quot;,&lt;/strong&gt; Madaba offers many sites to explore. The most remarkable discovery is a map of Jerusalem, and other holy cities, in Byzantine mosaic dating from the sixth century, inside the church of Saint George. Our discovery of the region continues to &lt;strong&gt;Mount Nebo&lt;/strong&gt; at the top of which we can enjoy a breathtaking view of the&lt;strong&gt; Dead Sea&lt;/strong&gt; and the Jordan Valley, last place where we would have seen the prophet Moses, you can also admire the mosaics of thousands years! Lunch at the Dead Sea at Dead Sea spa resort. (bathing also).&lt;/p&gt;\r\n&lt;p&gt;Then continue to &lt;strong&gt;Kerak&lt;/strong&gt;, Visit the fortress of Saladin Kerak, old fortress cross still surrounded by the fortifications of the old city. Kerak rises 900 meters above sea level. Today, this city of about 170,000 people still presents various restored Ottoman buildings of the nineteenth century and offers many restaurants, hotels and other services. But, without question, it is the castle of Kerak which dominates everything. (free visit) Transfer to Petra via the road of kings.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Dinner and overnight at the inhabitant&lt;/strong&gt;&lt;/p&gt;');
INSERT INTO `en33_tours_canned_days_contents` (`id`, `day_id`, `lang`, `title`, `place`, `description`) VALUES
(127, 11, 'fr', 'Madaba / Mont Nebo / Mer morte / Kérak / Pétra', NULL, '&lt;p&gt;&lt;span&gt;Après le petit déjeuner visite de Madaba. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;C&#039;est l’un des sites les plus mémorables de la Terre Sainte. Appelée &lt;strong&gt;« la ville de la mosaïque »,&lt;/strong&gt; Madaba offre de nombreux sites à explorer. La plus remarquable découverte est une carte de Jérusalem, et des autres villes saintes, en &lt;strong&gt;mosaïque byzantine&lt;/strong&gt; datant du VIème siècle, à l’intérieur de&lt;strong&gt; l’église Saint Georges.&lt;/strong&gt; Notre découverte de la région continue vers le &lt;strong&gt;Mont Nébo&lt;/strong&gt; au sommet duquel on peut profiter d’une vue imprenable sur la Mer Morte et la vallée du Jourdain, dernier endroit où on aurait vu le prophète Moïse, vous pourrez admirer également les mosaïques vieilles de milliers d&#039;années! Déjeuner à la mer Morte au Dead sea spa resort. &lt;strong&gt;(baignade également).&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;Puis continuation vers &lt;strong&gt;Kerak&lt;/strong&gt;, Visite de la forteresse de Saladin à Kerak, ancienne forteresse Croisée encore entourée des fortifications de la vieille cité. Kérak s’élève à 900 mètres au-dessus du niveau de la mer. Aujourd’hui, cette ville d’une population d’environ 170 000 personnes présente encore divers bâtiments ottomans restaurés du XIXème siècle et offre de nombreux restaurants, hôtels et autres services. Mais, sans conteste, c’est le château de Kérak qui domine tout. (visite libre) Transfert à &lt;strong&gt;Pétra&lt;/strong&gt; en passant par &lt;strong&gt;la route des rois.&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Dîner et nuit chez l&#039;habitant &lt;/strong&gt;&lt;/p&gt;'),
(128, 11, 'it', 'Madaba / Monte Nebo /Mar Morto / Al Karak /Petra', NULL, '&lt;p&gt;Dopo colazione, visita di Madaba, uno dei siti più memorabili della Terra Santa. Chiamata &quot;la città dei mosaici&quot;, Madaba offre molti siti da esplorare. La più notevole scoperta è il mosaico pavimentale raffigurante Gerusalemme e le altre città sante bizantine, mosaico risalente al VI secolo posto all&#039;interno della Chiesa di San Giorgio.&lt;/p&gt;\r\n&lt;p&gt;La nostra scoperta della regione continua verso il Monte Nebo, in cima al quale si può godere di una vista mozzafiato sul Mar Morto e la Valle del Giordano, l&#039;ultimo posto in cui è stato visto il profeta Mosè, inoltre si possono ammirare anche gli antichi mosaici di migliaia anni!&lt;/p&gt;\r\n&lt;p&gt;Pranzo al Mar Morto nella località termale del Mar Morto. Al termine continuiamo la nostra discesa verso Al Karak. Visita della fortezza di Saladino, antica fortezza ancora circondata dalle fortificazioni della città vecchia. Karak sorge a 900 metri sul livello del mare e oggi questa città di circa 170.000 persone presenta ancora vari edifici ottomani restaurati del XIX secolo e offre molti ristoranti, hotel e altri servizi. Ma, senza dubbio, è il castello di Karak a dominare tutto.&lt;/p&gt;\r\n&lt;p&gt;Trasferimento a Petra attraverso la strada dei Re&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;'),
(129, 11, 'es', 'Madaba / Mont Nebo / Mer morte / Kérak / Pétra', NULL, '&lt;p&gt;Después del desayuno, visita de Madaba, uno de los sitios más memorables de Tierra Santa. Llamada &quot;la ciudad de los mosaicos&quot;, Madaba ofrece muchos sitios para explorar. El descubrimiento más notable es el mosaico del piso que representa a Jerusalén y las otras ciudades santas bizantinas, un mosaico que data del siglo VI ubicado dentro de la Iglesia de San Giorgio.&lt;/p&gt;\r\n&lt;p&gt;Nuestro descubrimiento de la región continúa hacia el Monte Nebo, sobre el cual puede disfrutar de una vista impresionante del Mar Muerto y el Valle del Jordán, el último lugar donde se vio al profeta Moisés, también puede admirar el ¡Antiguos mosaicos de miles de años!&lt;/p&gt;\r\n&lt;p&gt;Almuerzo en el balneario del Mar Muerto en el Mar Muerto. Al final continuamos nuestro descenso hacia Al Karak. Visita la fortaleza de Saladino, antigua fortaleza todavía está rodeada por las antiguas fortificaciones de la ciudad. Karak se eleva a 900 metros sobre el nivel del mar y hoy en día, esta ciudad de alrededor de 170,000 habitantes todavía cuenta con varios edificios otomanos restaurados del siglo XIX y ofrece muchos restaurantes, hoteles y otras comodidades. Pero, sin lugar a dudas, es el castillo de Karak el que domina todo.&lt;/p&gt;\r\n&lt;p&gt;Traslado a Petra por la carretera de los Reyes.&lt;/p&gt;'),
(130, 11, 'Ar', 'مأدبا / جبل نيبو / البحر الميت / الكرك / البتراء', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: &#039;comic sans ms&#039;, sans-serif; font-size: 14pt;&quot;&gt;بعد الافطار وقت لزيارة مادبا.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: &#039;comic sans ms&#039;, sans-serif; font-size: 14pt;&quot;&gt;إنها واحدة من أكثر المواقع التي لا تنسى في الأرض المقدسة. يُطلق على مدينة مادبا اسم &quot;مدينة الفسيفساء&quot; ، تحتوي على العديد من المواقع لاستكشافها. اكتشاف الأبرز هي منطقة القدس وغيرها من المدن المقدسة في البيزنطي الفسيفساء يعود تاريخها إلى القرن السادس، داخل كنيسة القديس جورج. لا يزال لدينا أماكن لاكتشافها منها منطقة جبل نيبو،التي يمكن للسائح أن يتمتع بمنظر خلاب للبحر الميت ووادي الأردن، وآخر مكان كان زاره النبي موسى، يمكنك أيضا لسائح المعجب بالفسيفساء القديمة الآلاف سنوات! أن ينتهز الفرصة للغوص في تفاصيل هذه المدينة العريقة, تناول الغداء في منتجع البحر الميت في البحر الميت. (الاستحمام أيضا).&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: &#039;comic sans ms&#039;, sans-serif; font-size: 14pt;&quot;&gt; قم بزيارة قلعة صلاح الدين ، قلعة قديمة لا تزال تحيط بها تحصينات المدينة القديمة&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: &#039;comic sans ms&#039;, sans-serif; font-size: 14pt;&quot;&gt;. الكرك على بعد 900 متر فوق مستوى سطح البحر، واليوم هذه المدينة التي يبلغ عدد سكانها نحو 170000 شخص  تحتوي المباني العثمانية من القرن التاسع عشر،تحتوي على العديد من المطاعم والفنادق وغيرها الخدمات. لكن ، بلا شك ، هي قلعة الكرك التي تسيطر على كل شيء. (زيارة مجانية) الانتقال إلى البتراء عبر طريق الملوك.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: &#039;comic sans ms&#039;, sans-serif; font-size: 14pt;&quot;&gt;العشاء&lt;/span&gt;&lt;/h3&gt;'),
(136, 12, 'en', 'AMMAN / AJLOUN / JERASH / AMMAN', NULL, '&lt;p&gt;Breakfast at the hotel We take the road to &lt;strong&gt;Ajloun&lt;/strong&gt; and leave to discover the castle.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Ajloun&lt;/strong&gt; Castle, also known as&lt;strong&gt; (Qal&#039;at Ar-Rabad)&lt;/strong&gt; is a 12th century Muslim fortress located in northwestern Jordan. It is placed on a hill belonging to Jable Ajloun (Mount Ajloun), also known as Jabal &#039;Auf after Bedouins who conquered the region in the twelfth century. We continue to Jerash, second most important archaeological site after &lt;strong&gt;Petra.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Jerash &lt;/strong&gt;or&lt;strong&gt; Gerassa&lt;/strong&gt; was founded in the late 4th century BC. Its inhabitants claimed that the city was founded by Alexander the Great in favor of veterans of his army. &lt;strong&gt;Guide francophone at Jerash (duration 2h)&lt;/strong&gt; Then direction &lt;strong&gt;Amman&lt;/strong&gt;, free visit of the citadel. &lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Dinner and overnight at the hotel half board&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Departure at 10am&lt;/strong&gt;&lt;/p&gt;'),
(137, 12, 'fr', 'Amman / Ajloun /  Jerash / Amman', NULL, '&lt;p&gt;&lt;span&gt;Petit déjeuner a l’hôtel Nous prenons la route pour &lt;strong&gt;Ajloun&lt;/strong&gt; et partons a la découverte du château. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;Le château d&#039; Ajloun, aussi connu comme Qal&#039;at Ar-Rabad) est une forteresse musulmane du XII siècle située au nord-ouest de la Jordanie . Il est placé sur une colline appartenant au Jable Ajloun (Mont Ajloun), aussi connu comme Jabal &#039;Auf après des bédouins qui ont conquis la région au XIIe siècle. Nous continuons vers Jerash, deuxième site archéologique le plus important après &lt;strong&gt;Petra&lt;/strong&gt;. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;&lt;strong&gt;Jerash&lt;/strong&gt; ou Gérassa a été fondée à la fin du IVe siècle av. J.-C. Ses habitants ont prétendu que la ville avait été fondée par Alexandre le Grand en faveur de vétérans de son armée. &lt;strong&gt;Guide francophone à Jérash (durée 2h)&lt;/strong&gt; Puis direction Amman, visite libre de la citadelle. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Dîner et nuit à l&#039;hôtel demi-pension &lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Départ à 10h &lt;/strong&gt;&lt;/p&gt;'),
(138, 12, 'it', 'Amman / Ajloun / Jerash / Amman', NULL, '&lt;p&gt;Colazione in hotel. Prendiamo la strada per Ajloun e partiamo alla scoperta del castello. Il castello di Ajloun, noto anche come Qal&#039;at Ar-Rabad, è una fortezza musulmana del XII secolo situata nel nord-ovest della Giordania. Si trova su una collina appartenente a Jabal Ajloun (Mount Ajloun), noto anche come Jabal &#039;Auf dopo i beduini che conquistarono la regione nel XII secolo. Continuiamo poi verso Jarash, il secondo sito archeologico più importante dopo Petra. Jarash o Gerasa è stata fondata alla fine del 4 ° secolo aC. I suoi abitanti affermarono che la città fu fondata da Alessandro Magno in favore dei veterani del suo esercito. Concludiamo la giornata di visite con Amman, visita libera della cittadella.&lt;/p&gt;\r\n&lt;p&gt;Cena e pernottamento in hotel mezza pensione &lt;/p&gt;'),
(139, 12, 'es', 'Amman / Ajloun / Jerash / Amman', NULL, '&lt;p&gt;Desayuno en el hotel. Tomamos la carretera a Ajloun y comenzamos a descubrir el castillo. El castillo de Ajloun, también conocido como Qal&#039;at Ar-Rabad, es una fortaleza musulmana del siglo XII ubicada en el noroeste de Jordania. Se encuentra en una colina que pertenece a Jabal Ajloun (Monte Ajloun), también conocido como Jabal &#039;Auf, por los beduinos que conquistaron la región en el siglo XII. Luego continuamos hacia Jarash, el segundo sitio arqueológico más importante después de Petra. Jarash o Gerasa fue fundada a finales del siglo IV aC. Sus habitantes afirmaron que la ciudad fue fundada por Alejandro Magno en favor de los veteranos de su ejército. Concluimos el día de visitas con Amman, visita gratuita de la ciudadela.&lt;/p&gt;\r\n&lt;p&gt;Cena y alojamiento en media pensión.&lt;/p&gt;'),
(140, 12, 'Ar', 'عمان/ عجلون / جرش / عمان', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;الإفطار في الفندق نحن نأخذ الطريق إلى عجلون ونغادر لاكتشاف القلعة.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;قلعة عجلون ، المعروفة أيضاً باسم قلعة الرباط ، هي قلعة إسلامية تعود إلى القرن الثاني عشر تقع في شمال غرب الأردن. تقع على تلة  تابعة لجبل عجلون (جبل عجلون) ، المعروف أيضًا باسم جبل عوف من طرف البدو الذين سكنو في المنطقة في القرن الثاني عشر. نستمر برحلتنا إلى  جرش ، ثاني أهم موقع أثري بعد البتراء.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;تأسست جرش أو Gerassa في أواخر القرن الرابع قبل الميلاد. زعم سكانها أن المدينة أسّست من قبل الإسكندر الأكبر لصالح المحاربين القدماء في جيشه. دليل الفرنسي إلى جرش (الساعة 2 ح) ثم اتجاه عمان ، زيارة القلعة.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;العشاء والمبيت في نصف إقامة الفندق&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;رحيل في 10:00&lt;/span&gt;&lt;/h3&gt;'),
(141, 13, 'en', 'TREKKING FROM LITTLE PETRA TO PETRA', NULL, '&lt;p&gt;We take the &quot;back door&quot; of&lt;strong&gt; Petra&lt;/strong&gt;, which leads to the main site from &lt;strong&gt;Little Petra.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;The mountains form the background of the ancient site and reveal their mutant colors according to sunlight.<br>Our journey then takes us to the magnificent monastery of &lt;strong&gt;El Deir&lt;/strong&gt;, &lt;strong&gt;the royal tombs&lt;/strong&gt; and temples of &lt;strong&gt;Wadi Mudleb.&lt;/strong&gt;&lt;/p&gt;'),
(142, 13, 'fr', 'Randonnée de petit Petra à Petra', NULL, '&lt;p&gt;Nous prenons la &quot;porte arrière&quot; de&lt;strong&gt; Petra&lt;/strong&gt;, qui mène au site principal à partir de &lt;strong&gt;petit Petra. &lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Les montagnes constituent l’arrière-plan du site antique et révèlent leurs couleurs mutantes en fonction de la lumière du soleil.<br>  Notre voyage nous conduit ensuite au magnifique monastère d&#039;&lt;strong&gt;El Deir&lt;/strong&gt; et aux&lt;strong&gt; tombeaux royaux&lt;/strong&gt; et aux temples de &lt;strong&gt;Wadi Mudleb.&lt;/strong&gt;&lt;/p&gt;'),
(143, 13, 'it', 'Trekking da Piccola Petra a Petra', NULL, '&lt;p&gt;&lt;span data-offset-key=&quot;a9qs9-0-0&quot;&gt;Prendiamo la &quot;&lt;/span&gt;&lt;span data-offset-key=&quot;a9qs9-0-1&quot;&gt;Back Door&lt;/span&gt;&lt;span data-offset-key=&quot;a9qs9-0-2&quot;&gt;&quot; di &lt;/span&gt;&lt;span data-offset-key=&quot;a9qs9-0-3&quot;&gt;Petra&lt;/span&gt;&lt;span data-offset-key=&quot;a9qs9-0-4&quot;&gt;, che conduce al sito principale partendo da &lt;/span&gt;&lt;span data-offset-key=&quot;a9qs9-0-5&quot;&gt;Piccola Petra&lt;/span&gt;&lt;span data-offset-key=&quot;a9qs9-0-6&quot;&gt;. Le montagne fanno da sfondo all&#039;antico sito rivelando i loro colori mutanti a seconda della luce del sole. Il nostro cammino ci porta poi verso il magnifico monastero di &lt;/span&gt;&lt;span data-offset-key=&quot;a9qs9-0-7&quot;&gt;El Deir &lt;/span&gt;&lt;span data-offset-key=&quot;a9qs9-0-8&quot;&gt;e verso le tombe ed i templi reali di &lt;/span&gt;&lt;span data-offset-key=&quot;a9qs9-0-9&quot;&gt;Wadi Mudleb&lt;/span&gt;&lt;span data-offset-key=&quot;a9qs9-0-10&quot;&gt;. &lt;/span&gt;&lt;/p&gt;'),
(144, 13, 'es', 'Excurciòn desde la pequena Petra a Petra', NULL, '&lt;p&gt;Tomamos la &quot;Puerta trasera&quot; de Petra, que conduce al sitio principal a partir de Piccola Petra. Las montañas son el fondo del antiguo sitio que revela sus colores mutantes según la luz solar. Nuestro viaje nos lleva al magnífico monasterio de El Deir y a las tumbas y templos reales de Wadi Mudleb.&lt;/p&gt;'),
(145, 13, 'Ar', 'المشي من البتراء الصغيرة إلى البتراء', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;نأخذ &quot;الممر الخلفي&quot; من البتراء ، مما يؤدي إلى الموقع الرئيسي من البتراء الصغيرة.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;تشكل الجبال خلفية للموقع القديم و ألوانها المتحولة وفقًا لأشعة الشمس لوحة فنية ساحرة.&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;تنقلنا رحلتنا إلى دير الدير الرائع ، المقابر الملكية ومعابد وادي مدلب.&lt;/span&gt;&lt;/h3&gt;'),
(146, 14, 'en', 'AMMAN / JERASH / AJLOUN / AMMAN', NULL, '&lt;p&gt;After breakfast offered by the hotel, transfer to the cities of &lt;strong&gt;Jerash and Ajlun.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;Jerash&lt;/strong&gt;, the ancient Gerasa, is a city located in the north of the Kingdom of Jordan. It is famous for preserving one of the largest Roman excavations in the world.&lt;/p&gt;\r\n&lt;p&gt;<br>In fact, after the annexation of the Roman Empire in 63 BC. BC, it has become one of the most important cities of the Middle East.<br>At the end of the archaeological tour of Jerash transfer to &lt;strong&gt;Ajlun&lt;/strong&gt; and free time to venture out to discover the trails of the &lt;strong&gt;Ajlun Nature Reserve.&lt;/strong&gt;<br>Ajlun, also a few kilometers from the capital Amman, was of considerable importance during the Crusades, because, on the orders of Saladin, a castle was built which would play a fundamental strategic role in defending the Sultan&#039;s army. this castle is still almost entirely preserved near the hill of the city of the same name.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Night at the hotel&lt;/strong&gt;&lt;/p&gt;'),
(147, 14, 'fr', 'Amman / Jarash / Ajloun / Amman', NULL, '&lt;p&gt;Après le petit-déjeuner proposé par l&#039;hôtel, transfert vers les villes de &lt;strong&gt;Jerash et Ajlun.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;Jerash&lt;/strong&gt;, l&#039;ancienne &lt;strong&gt;Gerasa&lt;/strong&gt;, est une ville située au nord du royaume de Jordanie. Il est réputé pour préserver l&#039;une des plus grandes fouilles romaines au monde.&lt;/p&gt;\r\n&lt;p&gt;<br>En fait, après l’annexion de l’empire romain en 63 av. J.-C., elle est devenue l’une des villes les plus importantes du Moyen-Orient.<br>À la fin de la visite archéologique de Jerash transfer à &lt;strong&gt;Ajlun&lt;/strong&gt; et temps libre pour s&#039;aventurer à la découverte des sentiers de la &lt;strong&gt;réserve naturelle d&#039;Ajlun.&lt;/strong&gt;<br>Ajlun, également à quelques kilomètres de la capitale Amman, avait une importance considérable pendant les croisades, car, sur ordre de Saladin, fut érigé un château qui jouerait un rôle stratégique fondamental pour la défense de l&#039;armée du sultan. ce château est encore presque entièrement conservé près de la colline de la ville du même nom.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Nuit à l&#039;hôtel&lt;/strong&gt;&lt;/p&gt;'),
(148, 14, 'it', 'Amman / Jarash / Ajloun / Amman', NULL, '&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;b9b9n&quot; data-offset-key=&quot;6itn4-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;6itn4-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;6itn4-0-0&quot;&gt;Dopo la colazione proposta dall&#039;hotel, trasferta verso le città di &lt;/span&gt;&lt;span data-offset-key=&quot;6itn4-0-1&quot;&gt;Jerash&lt;/span&gt;&lt;span data-offset-key=&quot;6itn4-0-2&quot;&gt; ed &lt;/span&gt;&lt;span data-offset-key=&quot;6itn4-0-3&quot;&gt;Ajlun&lt;/span&gt;&lt;span data-offset-key=&quot;6itn4-0-4&quot;&gt;.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;b9b9n&quot; data-offset-key=&quot;acbju-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;acbju-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;acbju-0-0&quot;&gt;Jerash&lt;/span&gt;&lt;span data-offset-key=&quot;acbju-0-1&quot;&gt;, antica Gerasa, è una città situata al nord del Regno giordano. è rinomata per conservare uno dei più grandi scavi romani al mondo. &lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;acbju-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;acbju-0-1&quot;&gt;Divenne, infatti, dopo l&#039;annessione all&#039;&lt;/span&gt;&lt;span data-offset-key=&quot;acbju-0-2&quot;&gt;Impero Romano&lt;/span&gt;&lt;span data-offset-key=&quot;acbju-0-3&quot;&gt; nel 63 a.C, una delle città più importanti di tutto il medio-oriente.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;b9b9n&quot; data-offset-key=&quot;8i4dm-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;8i4dm-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;8i4dm-0-0&quot;&gt;Al termine delle visita dello scalo archeologico di &lt;/span&gt;&lt;span data-offset-key=&quot;8i4dm-0-1&quot;&gt;Jerash&lt;/span&gt;&lt;span data-offset-key=&quot;8i4dm-0-2&quot;&gt; trasferta verso &lt;/span&gt;&lt;span data-offset-key=&quot;8i4dm-0-3&quot;&gt;Ajlun&lt;/span&gt;&lt;span data-offset-key=&quot;8i4dm-0-4&quot;&gt; e tempo libero per avventurarsi alla scoperta dei sentieri della&lt;/span&gt;&lt;span data-offset-key=&quot;8i4dm-0-5&quot;&gt; Riserva naturale&lt;/span&gt;&lt;span data-offset-key=&quot;8i4dm-0-6&quot;&gt; di &lt;/span&gt;&lt;span data-offset-key=&quot;8i4dm-0-7&quot;&gt;Ajlun&lt;/span&gt;&lt;span data-offset-key=&quot;8i4dm-0-8&quot;&gt; .&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;b9b9n&quot; data-offset-key=&quot;6taj6-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;6taj6-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;6taj6-0-0&quot;&gt;Ajlun&lt;/span&gt;&lt;span data-offset-key=&quot;6taj6-0-1&quot;&gt;, posta anch&#039;essa a pochi km di distanza dalla capitale Amman, ricoprì una notevole importanza durante le &lt;/span&gt;&lt;span data-offset-key=&quot;6taj6-0-2&quot;&gt;Crociate&lt;/span&gt;&lt;span data-offset-key=&quot;6taj6-0-3&quot;&gt;, dal momento che per ordine di Saladino venne eretto un castello che avrebbe giocato un ruolo strategicamente fondamentale per le difese dell&#039;armata del Sultano; tale Castello è a tutt&#039;oggi quasi interamente conservato presso l&#039;altura dell&#039;omonima città.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;6taj6-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;6taj6-0-3&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;b9b9n&quot; data-offset-key=&quot;8thre-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;8thre-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;8thre-0-0&quot;&gt;Pernottamento in hotel&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;'),
(149, 14, 'es', 'Amman / Jarash / Ajloun / Amman', NULL, '&lt;p&gt;Después del desayuno propuesto por el hotel, traslado a las ciudades de Jerash y Ajlun.<br>Jerash, la antigua Gerasa, es una ciudad situada al norte del Reino de Jordania. Es famoso por preservar una de las excavaciones romanas más grandes del mundo.<br>De hecho, después de la anexión al Imperio Romano en el año 63 aC, se convirtió en una de las ciudades más importantes de Oriente Medio.<br>Al final de la visita del aeropuerto arqueológico de Jerash, se trasladó a Ajlun y tiempo libre para aventurarse a descubrir los senderos de la Reserva Natural de Ajlun.<br>Ajlun, también a pocos kilómetros de la capital Amman, tuvo una importancia considerable durante las Cruzadas, ya que por orden de Saladin se erigió un castillo que jugaría un papel estratégico para las defensas del ejército del Sultán; este castillo se conserva casi en su totalidad cerca de la colina de la ciudad homónima.&lt;/p&gt;\r\n&lt;p&gt;Pernocte en el hotel.&lt;/p&gt;'),
(150, 14, 'Ar', 'عمان / جرش / عجلون / عمان', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;بعد الإفطار التي يقدمها الفندق ، ننتقل إلى مدن جرش وعجلون.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;جرش ، مدينة جراسا القديمة ، هي مدينة تقع في شمال المملكة الأردنية. تشتهر بالحفاظ على واحدة من أكبر الحفريات الرومانية في العالم.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;في الواقع ، بعد ضم الإمبراطورية الرومانية في 63 قبل الميلاد.  أصبحت واحدة من أهم المدن في الشرق الأوسط.&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;في نهاية الجولة الأثرية في جرش نقل إلى عجلون ووقت حر للاستكشاف لاكتشاف مسارات محمية عجلون الطبيعية.&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;كانت عجلون ، التي تبعد بضعة كيلومترات عن العاصمة عمان ، ذات أهمية كبيرة خلال الحملات الصليبية ، لأنه بناء على أوامر صلاح الدين ، تم بناء قلعة تلعب دورا استراتيجيا أساسيا في الدفاع عن جيش السلطان. لا تزال هذه القلعة محفوظة بشكل شبه كامل بالقرب من تل المدينة الذي يحمل نفس الاسم.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;ليلة في الفندق&lt;/span&gt;&lt;/h3&gt;'),
(151, 15, 'en', 'RELAXATION DAY AT THE DEAD SEA', NULL, '&lt;p&gt;Free day<br>Free day of relaxation between swimming pool, bath in the &lt;strong&gt;Dead Sea&lt;/strong&gt; and its mud, rich in mineral salts for a concentration of well-being and relaxation.<br>Possibility of enjoying massages, spa treatments, saunas in the hotels.&lt;/p&gt;\r\n&lt;p&gt;The Dead Sea, a salt lake reaches a &lt;strong&gt;surface altitude of -430 m.&lt;/strong&gt; Divided between Israeli and Jordanian, it is ideal for those who want to devote themselves to the health and well-being of the skin.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Dinner and overnight at the hotel.&lt;/strong&gt;&lt;/p&gt;'),
(152, 15, 'fr', 'Détente à la mer morte', NULL, '&lt;p&gt;&lt;strong&gt;Journée libre&lt;/strong&gt;<br>Journée libre de détente entre piscine, bain dans la &lt;strong&gt;mer Morte&lt;/strong&gt; et sa boue, riche en sels minéraux pour une concentration de bien-être et de détente.<br>Possibilité de profiter de massages, traitements de spa, saunas dans les hôtels.&lt;/p&gt;\r\n&lt;p&gt;La mer Morte, un lac salé atteint une altitude de surface de -430 m. Divisé entre l&#039;Israélien et le Jordanien, il est idéal pour ceux qui veulent se consacrer à la santé et au bien-être de la peau.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Dîner et nuit à l&#039;hôtel.&lt;/strong&gt;&lt;/p&gt;'),
(153, 15, 'it', 'Giornata di relax al Mar Morto', NULL, '&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;7vpm7&quot; data-offset-key=&quot;6l3ia-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;6l3ia-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;6l3ia-0-0&quot;&gt;Giornata Libera&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;7vpm7&quot; data-offset-key=&quot;86prb-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;86prb-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;86prb-0-0&quot;&gt;Giornata libera all&#039;insegna del relax tra piscina, bagno nel &lt;/span&gt;&lt;span data-offset-key=&quot;86prb-0-1&quot;&gt;Mar Morto&lt;/span&gt;&lt;span data-offset-key=&quot;86prb-0-2&quot;&gt; ed i suoi fanghi, ricchissimi di sali oligominerali per una concentrazione di benessere e relax. &lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;7vpm7&quot; data-offset-key=&quot;9ijdt-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;9ijdt-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;9ijdt-0-0&quot;&gt;Possibilità di usufruire di massaggi,trattamenti spa, saune all&#039;interno degli hotel.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;9ijdt-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;9ijdt-0-0&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;7vpm7&quot; data-offset-key=&quot;fbdbs-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;fbdbs-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;fbdbs-0-0&quot;&gt;Cena e pernottamento in hotel.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;fbdbs-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;fbdbs-0-0&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;7vpm7&quot; data-offset-key=&quot;4otv5-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;4otv5-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;4otv5-0-0&quot;&gt;Il &lt;/span&gt;&lt;span data-offset-key=&quot;4otv5-0-1&quot;&gt;Mar Morto&lt;/span&gt;&lt;span data-offset-key=&quot;4otv5-0-2&quot;&gt;, fondamentalmente un lago di acqua salata( salatissima!!! ) raggiunge un&#039;altitudine di superficie di -430 m. Diviso tra parte israeliana e giordana, è l&#039;ideale per chi desidera dedicarsi alla salute ed al benessere della pelle.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;'),
(154, 15, 'es', 'Día de relajación en el mar muerto', NULL, '&lt;p&gt;Dia libre<br>Día libre de relajación entre la piscina, el baño en el Mar Muerto y su barro, rico en sales minerales para una concentración de bienestar y relajación.<br>Posibilidad de disfrutar de masajes, tratamientos de spa, saunas en hoteles.&lt;/p&gt;\r\n&lt;p&gt;Cena y alojamiento en el hotel.&lt;/p&gt;\r\n&lt;p&gt;El Mar Muerto, básicamente un lago de agua salada (salatissima !!!) alcanza una altitud de superficie de -430 m. Dividido entre el israelí y el jordano, es ideal para aquellos que desean dedicarse a la salud y el bienestar de la piel.&lt;/p&gt;'),
(155, 15, 'Ar', 'الاسترخاء في البحر الميت', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;يوم حر&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;يوم حر للاسترخاء بين المسبح وحوض الاستحمام في البحر الميت وطينه ، غني بالأملاح المعدنية لتركيز الرفاهية والاسترخاء.&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;إمكانية التمتع بالتدليك ، وعلاجات طبيعية ، وحمامات البخار في الفندق.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;البحر الميت ، البحيرة المالحة تصل إلى ارتفاع سطح -430 م. ينقسم بين الإسرائيليين والأردنيين ، فهو مثالي لأولئك الذين يرغبون في تكريس أنفسهم للصحة والاهتمام بالبشرة.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;العشاء والمبيت في الفندق.&lt;/span&gt;&lt;/h3&gt;'),
(161, 16, 'en', 'IRBID / UMM QAIS / PELLA / UMM AL-JIMAL / AZRAQ', NULL, '&lt;p&gt;&lt;strong&gt;Appointment with the guide at 08:00.&lt;/strong&gt; We leave for the city of &lt;strong&gt;Irbid,&lt;/strong&gt; witness in the Bible of &quot;Beth Arbei&quot;; Excursion to the Jordan Valley with a visit to the site of &lt;strong&gt;Umm Qais, the ancient Gadara, Greco-Roman city.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;The magnificent panorama of the Golan Heights and the &lt;strong&gt;Pella&lt;/strong&gt; Galilee Lake founded the 310 BC Then &lt;strong&gt;Umm al Jimal&lt;/strong&gt;, a city entirely built in basalt &lt;strong&gt;(Byzantine churches).&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Dinner and overnight at the hotel&lt;/strong&gt;&lt;/p&gt;'),
(162, 16, 'fr', 'Irbid / Umm Qais / Pella / Umm al-Jimal / Azraq', NULL, '&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;d1vmp&quot; data-offset-key=&quot;d883j-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;d883j-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;d883j-0-0&quot;&gt;&lt;strong&gt;Rendez-vous avec le guide à 08h00.&lt;/strong&gt; Nous partons pour la ville d&#039;&lt;strong&gt;Irbid,&lt;/strong&gt; témoin dans la Bible de &quot;Beth Arbei&quot;; excursion dans la vallée du Jourdain avec une visite du site d&#039;&lt;strong&gt;Umm Qais, l&#039;ancienne Gadara, ville gréco-romaine.&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;d883j-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;d883j-0-0&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;d883j-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;d883j-0-0&quot;&gt; Le magnifique panorama sur les hauteurs du Golan et le lac de Tibériade de&lt;strong&gt; Pella&lt;/strong&gt; a fondé le 310 a.C. Ensuite,&lt;strong&gt; Umm al Jimal&lt;/strong&gt;, une ville entièrement construite en basalte &lt;strong&gt;(églises byzantines)&lt;/strong&gt;.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;d883j-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;d883j-0-0&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;d1vmp&quot; data-offset-key=&quot;a7sj0-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;a7sj0-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;strong&gt;Dîner et nuit à l&#039;hôtel&lt;/strong&gt;&lt;/div&gt;\r\n&lt;/div&gt;'),
(163, 16, 'it', 'Irbid / Umm Qais / Pella / Umm al-Jimal / Azraq', NULL, '&lt;p&gt;Appuntamento con la guida alle 08:00. Partiamo per la città di Irbid, testimone nella Bibbia di &quot;Beth Arbei&quot;; Escursione nella Valle del Giordano con visita al sito di Umm Qais, l&#039;antica Gadara, città greco-romana. Il magnifico panorama delle alture del Golan e del lago Pella Galilee fondò il 310 aC.Poi Umm al Jimal, una città interamente costruita in basalto (chiese bizantine).&lt;/p&gt;\r\n&lt;p&gt;<br>Cena e pernottamento in hotel&lt;/p&gt;'),
(164, 16, 'es', 'Irbid / Umm Qais / Pella / Umm al-Jimal / Azraq', NULL, '&lt;p&gt;Cita con el guía a las 08:00. Partimos hacia la ciudad de Irbid, testigo en la Biblia de &quot;Beth Arbei&quot;; Excursión en el valle del Jordán con una visita al sitio de Umm Qais, la antigua Gadara, una ciudad grecorromana. El magnífico panorama de los Altos del Golán y el lago Pella Galilea fundaron el 310 aC Luego, Umm al Jimal, una ciudad construida completamente de basalto (iglesias bizantinas).&lt;/p&gt;\r\n&lt;p&gt;<br>Cena y alojamiento en el hotel.&lt;/p&gt;'),
(165, 16, 'Ar', 'اربد / ام قيس / بيلا / أم الجمال / الأزرق', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;الموعد مع الدليل في الساعة 08:00. باتجاه مدينة إربد ، ونشهد في الكتاب المقدس &quot;بيت أربي&quot; ؛ رحلة إلى وادي الأردن مع زيارة إلى موقع أم قيس ، المدينة اليونانية الرومانية.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;إن البانوراما الرائعة لمرتفعات الجولان وبحيرة بيلا الجليل أسست عام 310 قبل الميلاد ثم أم الجمل ، وهي مدينة بنيت بالكامل في البازلت الكنائس البيزنطية).&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;العشاء والمبيت في الفندق&lt;/span&gt;&lt;/h3&gt;'),
(166, 17, 'en', 'FREE DAY IN AQABA', NULL, '&lt;p&gt;After breakfast,<br>last free morning in Aqaba: shopping or relaxing.<br>&lt;strong&gt;Transfer to Amman overnight at the hotel.&lt;/strong&gt;&lt;/p&gt;'),
(167, 17, 'fr', 'Journée libre à Aqaba', NULL, '&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;shnl&quot; data-offset-key=&quot;et9ik-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;et9ik-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;et9ik-0-0&quot;&gt;Après le petit déjeuner, &lt;/span&gt;&lt;span data-offset-key=&quot;et9ik-0-1&quot;&gt;dernière matinée libre à&lt;strong&gt; Aqaba&lt;/strong&gt;&lt;/span&gt;&lt;span data-offset-key=&quot;et9ik-0-2&quot;&gt; : shopping ou détente.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;et9ik-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;et9ik-0-2&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;shnl&quot; data-offset-key=&quot;9pt0c-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;9pt0c-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;strong&gt;Transfert à Amman pour passer la nuit à l’hôtel. &lt;/strong&gt;&lt;/div&gt;\r\n&lt;/div&gt;'),
(168, 17, 'it', 'Giornata libera ad Aqaba', NULL, '&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;62ili&quot; data-offset-key=&quot;6geql-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;6geql-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;6geql-0-0&quot;&gt;Giornata Libera&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;6geql-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;6geql-0-0&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;62ili&quot; data-offset-key=&quot;215d1-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;215d1-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;215d1-0-0&quot;&gt;Aqaba &lt;/span&gt;&lt;span data-offset-key=&quot;215d1-0-1&quot;&gt;è una fusione di storia, natura e vita cittadina circondata da pittoresche montagne e mare blu. Immergendosi in una cornice permanentemente estiva, Aqaba vi invita a rilassarvi sulle sue spiagge, a divertirvi con i suoi sport acquatici e ad esplorare le barriere coralline del Mar Rosso, sede di centinaia di diversi tipi di coralli e spugne con la loro ricchezza di pesci dai colori brillanti ed il suo Museo Archeologico&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;215d1-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;215d1-0-1&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;62ili&quot; data-offset-key=&quot;2shbf-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;2shbf-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;2shbf-0-0&quot;&gt;Intorno alle sue strade silenziose e tra le sue strutture moderne, Aqaba detiene monumenti speciali con una ricca storia che inizia nell&#039;età del ferro, e continua attraverso civiltà antiche, da Edomiti, Nabatei, Romani e Bizantini ai musulmani.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;2shbf-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;2shbf-0-0&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;62ili&quot; data-offset-key=&quot;6ubt7-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;6ubt7-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;6ubt7-0-0&quot;&gt;Pernottamento in hotel&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;'),
(169, 17, 'es', 'Día libre en Aqaba.', NULL, '&lt;p&gt;Dia libre&lt;/p&gt;\r\n&lt;p&gt;Aqaba es una fusión de historia, naturaleza y vida urbana rodeada de pintorescas montañas y mar azul. Sumergiéndose en un entorno veraniego permanente, Aqaba lo invita a relajarse en sus playas, a divertirse con sus deportes acuáticos y a explorar los arrecifes de coral del Mar Rojo, hogar de cientos de diferentes tipos de corales y esponjas con su riqueza de peces. Colores brillantes y su museo arqueológico.&lt;/p&gt;\r\n&lt;p&gt;Alrededor de sus calles silenciosas y entre sus modernas instalaciones, Aqaba posee monumentos especiales con una rica historia que comienza en la Edad del Hierro y continúa a través de civilizaciones antiguas, desde edomitas, nabateos, romanos y bizantinos hasta musulmanes.&lt;/p&gt;\r\n&lt;p&gt;Pernocte en el hotel.&lt;/p&gt;'),
(170, 17, 'Ar', 'يوم في العقبة', NULL, '&lt;p style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;بعد الإفطار ، آخر صباح حر في العقبة: التسوق أو الاسترخاء.&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;الانتقال إلى عمان لقضاء الليلة في الفندق.&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;'),
(191, 18, 'en', 'FREE DAY IN AMMAN', NULL, '&lt;p&gt;&lt;strong&gt;Free day&lt;/strong&gt;<br>On this day, you can freely enjoy the countless resources that the city offers, including a walk in the city center, a visit to archaeological sites, a hot tea in Weibdeh or try the typical Rainbow Street shisha ... well Moreover.&lt;/p&gt;\r\n&lt;p&gt;Amman, formerly &lt;strong&gt;Philadeplhia&lt;/strong&gt;, is the largest and most populous city in the country.&lt;/p&gt;\r\n&lt;p&gt;Mainly divided into two parts: the western part, not only geographically, full of discos, pubs, shopping centers and the eastern part, which still retains important archaeological sites, such as &lt;strong&gt;The Citadel Roman amphitheater&lt;/strong&gt; ... &lt;strong&gt;typical Arabic &quot;suq&quot;.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Night at the hotel&lt;/strong&gt;&lt;/p&gt;'),
(192, 18, 'fr', 'Journe libre en Amman', NULL, '&lt;p&gt;&lt;strong&gt;Journée libre&lt;/strong&gt;<br>En ce jour, vous pouvez librement profiter des innombrables ressources que la ville offre, y compris une promenade dans le centre-ville, une visite de sites archéologiques, un thé chaud à Weibdeh ou essayez la chicha typique de Rainbow Street ... et bien plus encore.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Amman&lt;/strong&gt;, l&#039;ancienne &lt;strong&gt;Philadeplhia&lt;/strong&gt;, est la ville la plus grande et la plus peuplée du pays.&lt;/p&gt;\r\n&lt;p&gt;Principalement divisée en deux parties: la partie occidentale, non seulement géographiquement, regorgeant de discothèques, de pubs, de centres commerciaux et la partie orientale, qui conserve encore d’importants sites archéologiques, tels que &lt;strong&gt;La Citadel&lt;/strong&gt; l’amphithéâtre romain ... &lt;strong&gt;typique arabe &quot;suq&quot;.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Nuit à l&#039;hôtel&lt;/strong&gt;&lt;/p&gt;'),
(193, 18, 'it', 'Giornata libera ad Amman', NULL, '&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;dnnso&quot; data-offset-key=&quot;5fa40-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;5fa40-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;5fa40-0-0&quot;&gt;Giornata Libera &lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;dnnso&quot; data-offset-key=&quot;erk3k-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;erk3k-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;erk3k-0-0&quot;&gt;In questo giorno potrete godervi liberamente le innumerevoli risorse che offre la città, tra una passeggiata in Downtown, una visita ai siti archeologici, un thè caldo a Weibdeh o provare la tipica shisha a Rainbow Street ....e tanto altro ancora.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;erk3k-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;erk3k-0-0&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;dnnso&quot; data-offset-key=&quot;47nc8-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;47nc8-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;47nc8-0-0&quot;&gt;Pernottamento in hotel&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;47nc8-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;47nc8-0-0&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;dnnso&quot; data-offset-key=&quot;6iqa4-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;6iqa4-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;6iqa4-0-0&quot;&gt;Amman&lt;/span&gt;&lt;span data-offset-key=&quot;6iqa4-0-1&quot;&gt;, antica Philadeplhia, è la città più grande e popolosa del paese. Sostanzialmente divisa in due parti: la parte occidentale, non solo geograficamente, piena di locali notturni, pub, centri commerciali, e la parte orientale, la quale conserva ancora siti archeologici importantissimi, come La Cittadella, L&#039;Anfiteatro Romano...nonchè i tipici &quot;suq&quot; arabi.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;'),
(194, 18, 'es', 'Dìa libre en Amman', NULL, '&lt;p&gt;Dia libre<br>En este día, puede disfrutar libremente de los innumerables recursos que ofrece la ciudad, como un paseo por el centro, una visita a los sitios arqueológicos, un té caliente en Weibdeh o probar la típica shisha en Rainbow Street ... y mucho más.&lt;/p&gt;\r\n&lt;p&gt;Pernocte en el hotel.&lt;/p&gt;\r\n&lt;p&gt;Amman, la antigua Philadeplhia, es la ciudad más grande y más poblada del país. Substancialmente dividida en dos partes: la parte occidental, no solo geográficamente, llena de clubes nocturnos, pubs, centros comerciales y la parte oriental, que aún conserva importantes sitios arqueológicos, como La Cittadella, el Anfiteatro Romano ... Árabe típico &quot;suq&quot;.&lt;/p&gt;'),
(195, 18, 'Ar', 'يوم حر في عمان', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;يوم حر&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;في هذا اليوم ، يمكنك الاستمتاع بحرية بالأماكم التي لا تعد ولا تحصى التي تحتوي عليها المدينة ، بما في ذلك المشي في وسط المدينة ، زيارة المواقع الأثرية ، الشاي الساخن في اللويبدة أو تجربة الشيشة النموذجية في شارع الرينبو ... أكثر من ذلك.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;عمان ، سابقا فيلادلفيا ، هي أكبر مدينة وأكثرها اكتظاظا بالسكان في البلاد.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;تنقسم بشكل رئيسي إلى قسمين: الجزء الغربي ، ليس فقط جغرافيًا ، المليء بالمراقص والحانات ومراكز التسوق والجزء الشرقي ، والتي لا تزال تحتفظ بالمواقع الأثرية الهامة ، مثل المدرج الروماني البلد ... نموذجيًا العربية &quot;سوق&quot;.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;ليلة في الفندق&lt;/span&gt;&lt;/h3&gt;'),
(221, 19, 'en', 'JERUSALEM', NULL, '&lt;p&gt;&lt;strong&gt;Free day in Jerusalem.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;You can get lost in the narrow streets of the old city, heritage of Unesco, by going from Arabic to Christian, from Hebrew to Armenian without even realizing it.&lt;/p&gt;\r\n&lt;p&gt;It starts from &lt;strong&gt;Jaffa Gate&lt;/strong&gt;, to the west, where stones dating from 1538 were placed there by Ottoman Turks at the time of Suleyman the Magnificent.&lt;/p&gt;\r\n&lt;p&gt;The circumference of the city measures only 4 kilometers, so it is feasible. You will touch the eight ancient gates of Jerusalem, including the remains of the Roman gate below the present Damascus Gate and the gilded gate, closed in the seventh century awaiting the arrival of the Messiah.<br>&lt;strong&gt;Recommended stops:&lt;/strong&gt;<br>&lt;strong&gt;1. The Wailing Wall:&lt;/strong&gt; This is the holiest site of Judaism, but anyone can go there. This is the retaining wall built by Herod two thousand years ago during the renovation of the Second Temple in Jerusalem.<br>&lt;strong&gt;2. Haram el-Sharif:&lt;/strong&gt; or the Temple Mount<br>&lt;strong&gt;3. The biblical cuisine of the Eucalyptus Gastronomic Stop:&lt;/strong&gt; This restaurant combines Middle Eastern cuisine from the Bible era with international cuisine, using only local ingredients.<br>&lt;strong&gt;4. The Austrian Hospice Right in the center of the old town&lt;/strong&gt;, amidst the chaos of the Arab quarter, lies an oasis of paradise. Woodwork, red velvet, Art Nouveau chandeliers. This place, run by religious, houses a hotel and a restaurant.<br>&lt;strong&gt;5. Points of view To admire the panorama of Jerusalem:&lt;/strong&gt; from above, you must climb on one of the reliefs surrounding the city. The most beautiful views are: the bell tower of the Church of the Redeemer in the old town (you have to climb 750 steps!); the arch of the Hurva synagogue in the Jewish quarter; the roof of the Austrian hospice; the Erodeal Tower inside the City of David Museum; the hostel tower (just take the elevator).<br>&lt;strong&gt;6.Yad Vashem&lt;/strong&gt; - Holocaust Museum&lt;/p&gt;');
INSERT INTO `en33_tours_canned_days_contents` (`id`, `day_id`, `lang`, `title`, `place`, `description`) VALUES
(222, 19, 'fr', 'Jérusalem', NULL, '&lt;p&gt;&lt;strong&gt;Journée libre à Jérusalem.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Vous pouvez vous perdre dans les ruelles étroites de la vieille ville, patrimoine de l&#039;Unesco, en passant de l&#039;arabe au chrétien, de l&#039;hébreu à l&#039;arménien sans même vous en rendre compte. &lt;/p&gt;\r\n&lt;p&gt;Il commence à partir de &lt;strong&gt;la Porte de Jaffa&lt;/strong&gt;, à l&#039;ouest, où des pierres datant de 1538 y ont été placées par des Turcs ottomans à l&#039;époque de Suleyman le Magnifique.&lt;/p&gt;\r\n&lt;p&gt;La circonférence de la ville ne mesure que 4 kilomètres, il est donc réalisable. Vous toucherez les huit anciennes portes de Jérusalem, y compris les vestiges de la porte romaine située sous l&#039;actuelle porte de Damas et la porte dorée, fermée au VIIe siècle dans l&#039;attente de l&#039;arrivée du Messie.<br>&lt;strong&gt;Arrêts recommandés : &lt;/strong&gt;<br>&lt;strong&gt;1. Le mur des lamentations :&lt;/strong&gt; C&#039;est le site le plus sacré du judaïsme, mais tout le monde peut y aller. C&#039;est le mur de soutènement construit par Hérode il y a deux mille ans lors de la rénovation du Second Temple à Jérusalem.<br>&lt;strong&gt;2. Haram el-Sharif :&lt;/strong&gt; ou le mont du Temple<br>&lt;strong&gt;3. La cuisine biblique de l&#039;Eucalyptus Gastronomic Stop:&lt;/strong&gt; Ce restaurant combine la cuisine du Moyen-Orient de l&#039;époque de la Bible avec la cuisine internationale, en utilisant uniquement des ingrédients locaux.<br>&lt;strong&gt;4. L&#039;hospice autrichien En plein centre de la vieille ville,&lt;/strong&gt; au milieu du chaos du quartier arabe, se trouve une oasis de paradis. Boiserie, velours rouge, lustres Art Nouveau. Cet endroit, géré par des religieux, abrite un hôtel et un restaurant.<br>&lt;strong&gt;5. Points de vue Pour admirer le panorama de Jérusalem :&lt;/strong&gt; d&#039;en haut, vous devez grimper sur l&#039;un des reliefs entourant la ville. Les plus beaux points de vue sont: le clocher de l&#039;église du Rédempteur dans la vieille ville (il faut gravir 750 marches!); l&#039;arche de la synagogue Hurva dans le quartier juif; le toit de l&#039;hospice autrichien; la tour Erodeal à l&#039;intérieur du musée de la Cité de David; la tour de l&#039;auberge de jeunesse (prenez juste l&#039;ascenseur).<br>&lt;strong&gt;6.Yad Vashem -&lt;/strong&gt; Musée de l&#039;Holocauste&lt;/p&gt;'),
(223, 19, 'it', 'Gerusalemme', NULL, '&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;2m8pg&quot; data-offset-key=&quot;dflqh-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;dflqh-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;dflqh-0-0&quot;&gt;Giornata libera a Gerusalemme.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;dflqh-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;dflqh-0-0&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;2m8pg&quot; data-offset-key=&quot;5mhp9-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;5mhp9-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;5mhp9-0-0&quot;&gt;Potete perdervi tra i vicoli stretti della &lt;/span&gt;&lt;span data-offset-key=&quot;5mhp9-0-1&quot;&gt;Città Vecchia, Patrimonio dell’Unesco&lt;/span&gt;&lt;span data-offset-key=&quot;5mhp9-0-2&quot;&gt;, passando dal quartiere arabo a quello cristiano, dall’ebraico all’armeno senza neppure accorgervene. Si parte dalla &lt;/span&gt;&lt;span data-offset-key=&quot;5mhp9-0-3&quot;&gt;Porta di Giaffa&lt;/span&gt;&lt;span data-offset-key=&quot;5mhp9-0-4&quot;&gt;, a Ovest, dove si calpestano pietre risalenti al 1538 messe lì dai turchi ottomani ai tempi di Solimano il Magnifico. La circonferenza della città misura solamente &lt;/span&gt;&lt;span data-offset-key=&quot;5mhp9-0-5&quot;&gt;4 chilometri&lt;/span&gt;&lt;span data-offset-key=&quot;5mhp9-0-6&quot;&gt;, pertanto è un giro fattibile. Toccherete le &lt;/span&gt;&lt;span data-offset-key=&quot;5mhp9-0-7&quot;&gt;otto porte antiche di Gerusalemme&lt;/span&gt;&lt;span data-offset-key=&quot;5mhp9-0-8&quot;&gt;, compreso ciò che resta della porta Romana che si trova sotto all&#039;odierna &lt;/span&gt;&lt;span data-offset-key=&quot;5mhp9-0-9&quot;&gt;Porta di Damasco&lt;/span&gt;&lt;span data-offset-key=&quot;5mhp9-0-10&quot;&gt; e &lt;/span&gt;&lt;span data-offset-key=&quot;5mhp9-0-11&quot;&gt;Porta Dorata&lt;/span&gt;&lt;span data-offset-key=&quot;5mhp9-0-12&quot;&gt;, chiusa nel VII secolo in attesa dell’arrivo del Messia.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;2m8pg&quot; data-offset-key=&quot;313lf-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;313lf-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;313lf-0-0&quot;&gt;Tappe consigliate&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;2m8pg&quot; data-offset-key=&quot;8pbl5-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;8pbl5-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;8pbl5-0-0&quot;&gt;1. Il Muro del pianto&lt;/span&gt;&lt;span data-offset-key=&quot;8pbl5-0-1&quot;&gt; E’ &lt;/span&gt;&lt;span data-offset-key=&quot;8pbl5-0-2&quot;&gt;il sito più sacro al Giudaismo&lt;/span&gt;&lt;span data-offset-key=&quot;8pbl5-0-3&quot;&gt;, ma ci possono andare tutti. Si tratta del muro di contenimento fatto costruire da Erode duemila anni fa durante il rinnovamento del Secondo Tempio di &lt;/span&gt;&lt;span data-offset-key=&quot;8pbl5-0-4&quot;&gt;Gerusalemme&lt;/span&gt;&lt;span data-offset-key=&quot;8pbl5-0-5&quot;&gt;.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;2m8pg&quot; data-offset-key=&quot;61sp7-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;61sp7-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;61sp7-0-0&quot;&gt;3. Haram el-Sharif o Monte del Tempio&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;2m8pg&quot; data-offset-key=&quot;fmlgh-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;fmlgh-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;fmlgh-0-0&quot;&gt;4. La cucina biblica dell’Eucalyptus&lt;/span&gt;&lt;span data-offset-key=&quot;fmlgh-0-1&quot;&gt; T&lt;/span&gt;&lt;span data-offset-key=&quot;fmlgh-0-2&quot;&gt;appa gastronomica. &lt;/span&gt;&lt;span data-offset-key=&quot;fmlgh-0-3&quot;&gt;Questo ristorante combina la cucina mediorientale dei tempi della Bibbia con quella internazionale, impiegando solo ingredienti locali. &lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;2m8pg&quot; data-offset-key=&quot;58cjo-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;58cjo-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;58cjo-0-0&quot;&gt;5. L’Ospizio austriaco&lt;/span&gt;&lt;span data-offset-key=&quot;58cjo-0-1&quot;&gt; Proprio nel centro della &lt;/span&gt;&lt;span data-offset-key=&quot;58cjo-0-2&quot;&gt;Città Vecchia&lt;/span&gt;&lt;span data-offset-key=&quot;58cjo-0-3&quot;&gt;, in mezzo al caos del quartiere arabo, si trova &lt;/span&gt;&lt;span data-offset-key=&quot;58cjo-0-4&quot;&gt;un’oasi di paradiso&lt;/span&gt;&lt;span data-offset-key=&quot;58cjo-0-5&quot;&gt;. Boiserie, velluti rossi, lampadari liberty. Questo posto, gestito da religiosi, ospita un hotel e un ristorante.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;2m8pg&quot; data-offset-key=&quot;a4p7c-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;a4p7c-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;a4p7c-0-0&quot;&gt;6. Punti panoramici&lt;/span&gt;&lt;span data-offset-key=&quot;a4p7c-0-1&quot;&gt; Per ammirare il &lt;/span&gt;&lt;span data-offset-key=&quot;a4p7c-0-2&quot;&gt;panorama di Gerusalemme dall’alto&lt;/span&gt;&lt;span data-offset-key=&quot;a4p7c-0-3&quot;&gt; bisogna salire su uno dei rilievi circostanti alla città. I punti panoramici più belli sono: il campanile della &lt;/span&gt;&lt;span data-offset-key=&quot;a4p7c-0-4&quot;&gt;Chiesa del Redentore&lt;/span&gt;&lt;span data-offset-key=&quot;a4p7c-0-5&quot;&gt; nella Città Vecchia (bisogna salire 750 gradini!); l’arco della &lt;/span&gt;&lt;span data-offset-key=&quot;a4p7c-0-6&quot;&gt;Sinagoga di Hurva&lt;/span&gt;&lt;span data-offset-key=&quot;a4p7c-0-7&quot;&gt; nel quartiere ebraico; il tetto dell’&lt;/span&gt;&lt;span data-offset-key=&quot;a4p7c-0-8&quot;&gt;Ospizio austriaco&lt;/span&gt;&lt;span data-offset-key=&quot;a4p7c-0-9&quot;&gt;; la &lt;/span&gt;&lt;span data-offset-key=&quot;a4p7c-0-10&quot;&gt;torre di Erode&lt;/span&gt;&lt;span data-offset-key=&quot;a4p7c-0-11&quot;&gt;all’interno del museo nella Città di David; la torre dell’ostello della gioventù (basta prendere l’ascensore).&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;2m8pg&quot; data-offset-key=&quot;3td7l-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;3td7l-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;3td7l-0-0&quot;&gt;7 Yad Vashem – Museo dell’Olocausto&lt;/span&gt;&lt;span data-offset-key=&quot;3td7l-0-1&quot;&gt; &lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;'),
(224, 19, 'es', 'Jerusalén', NULL, '&lt;p&gt;Día libre en Jerusalén.&lt;/p&gt;\r\n&lt;p&gt;Puede perderse en los estrechos callejones del casco antiguo, patrimonio de la Unesco, pasando del árabe al cristiano, del hebreo al armenio sin siquiera darse cuenta. Comienza desde la Porta di Giaffa, hacia el oeste, donde los turcos otomanos colocan allí piedras que datan de 1538 en el momento de Suleiman el Magnífico. La circunferencia de la ciudad mide solo 4 kilómetros, por lo que es un paseo factible. Tocarás las ocho puertas antiguas de Jerusalén, incluyendo lo que queda de la puerta romana debajo de la actual Puerta de Damasco y la Puerta de Oro, cerrada en el siglo séptimo a la espera de la llegada del Mesías.<br>Paradas recomendadas<br>1. El Muro de las Lamentaciones Es el sitio más sagrado para el judaísmo, pero todos pueden ir allí. Este es el muro de contención construido por Herodes hace dos mil años durante la renovación del Segundo Templo en Jerusalén.<br>3. Haram el-Sharif o Monte del Templo<br>4. La cocina bíblica de la parada gastronómica del eucalipto. Este restaurante combina la cocina de Oriente Medio de los tiempos de la Biblia con la internacional, utilizando solo ingredientes locales.<br>5. El hospicio austriaco Justo en el centro de la Ciudad Vieja, en medio del caos del barrio árabe, hay un oasis de paraíso. Boiserie, terciopelos rojos, arañas de estilo Art Nouveau. Este lugar, dirigido por religiosos, alberga un hotel y un restaurante.<br>6. Puntos de vista Para admirar el panorama de Jerusalén desde arriba, debes subir a uno de los relieves que rodean la ciudad. Los puntos de vista más hermosos son: el campanario de la Iglesia del Redentor en la Ciudad Vieja (¡tienes que subir 750 escalones!); el arco de la sinagoga hurva en el barrio judío; el techo del hospicio austriaco; la torre Erodeal dentro del museo en la Ciudad de David; La torre del albergue juvenil (solo tomar el ascensor).<br>7 Yad Vashem - Museo del Holocausto&lt;/p&gt;'),
(225, 19, 'Ar', 'القدس', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;يوم حر في القدس.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;يمكنك أن تضيع في الشوارع الضيقة للمدينة القديمة ، تراث اليونسكو ، من خلال الذهاب من العربية إلى المسيحية ، من العبرية إلى الأرمينية دون حتى إدراك ذلك.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;يبدأ من بوابة يافا ، إلى الغرب ، حيث تم وضع الأحجار التي يرجع تاريخها إلى 1538 من قبل الأتراك العثمانيين في وقت سليمان القانوني.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;يبلغ قياس محيط المدينة 4 كيلومترات فقط ، لذا فمن الممكن. سوف تلمس البوابات القديمة الثمانية في القدس ، بما في ذلك بقايا البوابة الرومانية أسفل بوابة دمشق الحالية والبوابة المذهبة ، المغلقة في القرن السابع في انتظار وصول المسيح.&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;توقف الموصى بها:&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;1. حائط المبكى: هذا هو أقدس موقع لليهودية ، ولكن يمكن لأي شخص الذهاب إلى هناك. هذا هو الجدار الاستتباري الذي بناه هيرودس منذ ألفي عام أثناء ترميم الهيكل الثاني في القدس.&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;2. الحرم الشريف: أو الحرم القدسي الشريف&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;3. المطبخ التوراتي في مطعم Eucalyptus Gastronomic Stop: يجمع هذا المطعم بين مأكولات الشرق الأوسط من عصر الكتاب المقدس مع المأكولات العالمية ، وذلك باستخدام المكونات المحلية فقط.&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;4. النزل النمساوي يقع في وسط المدينة القديمة ، وسط فوضى الحي العربي ، وهو واحة من الجنة. أعمال خشبية ، مخمل أحمر ، ثريات Art Nouveau. هذا المكان ، الذي تديره دينية ، يضم فندق ومطعم.&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;5. وجهات النظر للإعجاب ببانوراما القدس: من فوق ، يجب عليك الصعود على أحد النقوش المحيطة بالمدينة. أجمل المناظر هي: برج جرس كنيسة الفادي في البلدة القديمة (عليك أن تصعد 750 خطوة!) ؛ قوس كنيس هورفا في الحي اليهودي. سقف المستشفى النمساوي ؛ برج Erodeal داخل متحف مدينة داود. برج النزل (فقط اصعد المصعد).&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;6. ياد فاشيم - متحف الهولوكوست&lt;/span&gt;&lt;/h3&gt;'),
(231, 20, 'en', 'AMMAN / JERASH / AJLUN / IRAQ AL AMIR', NULL, '&lt;p&gt;Departure for the visit of the magnificent &lt;strong&gt;Greco-Roman&lt;/strong&gt; city of &lt;strong&gt;Jerash&lt;/strong&gt;, whose paved alleys are full of history.&lt;/p&gt;\r\n&lt;p&gt;Continuation and discovery of the castle &lt;strong&gt;Ajlun&lt;/strong&gt; built by one of the generals of Saladin in the year 1184. Magnificent views of the Jordan Valley, the pine forest and olive groves nearby.&lt;/p&gt;\r\n&lt;p&gt;In the afternoon, we will visit the &lt;strong&gt;Iraq Palace al Amir,&lt;/strong&gt; rare Hellenistic monument of the Middle East which was the residence of Hyrcan in the early second century BC.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Accommodation: hotel.&lt;/strong&gt;<br>&lt;strong&gt;Meals included: morning, noon, evening.&lt;/strong&gt;&lt;/p&gt;'),
(232, 20, 'fr', 'Amman / Jerash / Ajlun / Iraq el Amir', NULL, '&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;color: #000000; font-family: verdana, geneva, sans-serif; font-size: 12pt;&quot;&gt;Départ pour la visite de la magnifique cité &lt;strong&gt;gréco-romaine&lt;/strong&gt; de &lt;strong&gt;Jerash,&lt;/strong&gt; dont les allées pavées sont empreintes d&#039;histoire.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;color: #000000; font-family: verdana, geneva, sans-serif; font-size: 12pt;&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;color: #000000; font-family: verdana, geneva, sans-serif; font-size: 12pt;&quot;&gt;Continuation et découverte du château d&#039;&lt;strong&gt;Ajlun&lt;/strong&gt; construit par l&#039;un des généraux de Saladin en l&#039;an 1184. Magnifique vue sur la vallée du Jourdain, la pinède et les oliveraies aux alentours. &lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;color: #000000; font-family: verdana, geneva, sans-serif; font-size: 12pt;&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;color: #000000; font-family: verdana, geneva, sans-serif; font-size: 12pt;&quot;&gt;Dans l&#039;après-midi, nous visiterons &lt;strong&gt;le Palais Iraq al Amir&lt;/strong&gt;, rare monument hellénistique du Proche-Orient qui fut la résidence d&#039;Hyrcan au début du IIe siècle avant J.-C.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;color: #000000; font-family: verdana, geneva, sans-serif; font-size: 12pt;&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;color: #000000; font-family: verdana, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;float: none; background-color: transparent; color: #000000; cursor: text; font-style: normal; font-variant: normal; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; display: inline !important;&quot;&gt;Hébergement : hôtel. &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;color: #000000; font-family: verdana, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;float: none; background-color: transparent; color: #000000; cursor: text; font-style: normal; font-variant: normal; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; display: inline !important;&quot;&gt;Repas inclus : matin, midi, soir.&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;'),
(233, 20, 'it', 'Amman / Jerash / Ajlun / Iraq el Amir', NULL, '&lt;p&gt;Partenza per la visita della magnifica città greco-romana di Jarash.&lt;/p&gt;\r\n&lt;p&gt;Continuazione e scoperta del castello di Ajlun, edificato da uno dei generali di Saladino nell&#039;anno 1184. Magnifiche vedute della Valle del Giordano, della pineta e degli uliveti nelle vicinanze. Nel pomeriggio visiteremo l&#039;antico palazzo di Iraq al Amir, raro monumento ellenistico del Medio Oriente che fu residenza di Hyrcan all&#039;inizio del II secolo aC.&lt;/p&gt;\r\n&lt;p&gt;<br>Alloggio: hotel.&lt;/p&gt;\r\n&lt;p&gt;Pasti inclusi: colazione, pranzo, cena.&lt;/p&gt;'),
(234, 20, 'es', 'Amman / Jerash / Ajlun / Iraq el Amir', NULL, '&lt;p&gt;Salida para la visita de la magnífica ciudad grecorromana de Jarash.&lt;/p&gt;\r\n&lt;p&gt;Continuación y descubrimiento del castillo de Ajlun, construido por uno de los generales de Saladin en el año 1184. Magníficas vistas del valle del Jordán, el bosque de pinos y los olivares cercanos. Por la tarde visitaremos el antiguo palacio de Irak en Amir, un raro monumento helenístico de Medio Oriente que fue la residencia de Hyrcan a principios del siglo II a.&lt;/p&gt;\r\n&lt;p&gt;<br>Alojamiento: hotel.&lt;/p&gt;\r\n&lt;p&gt;Comidas incluidas: desayuno, almuerzo, cena.&lt;/p&gt;'),
(235, 20, 'Ar', 'غمان / جرش / عجلون  / عراق الامير', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;رحيل لزيارة مدينة جرش الرومانية اليونانية الرائعة ، التي مليئة بالأزقة المرصوفة بالتاريخ.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;استمرار واكتشاف قلعة عجلون التي بناها أحد جنرالات صلاح الدين عام 1184. مناظر خلابة لوادي الأردن وغابة الصنوبر وبساتين الزيتون القريبة.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;في فترة ما بعد الظهر ، سنزور قصر الأمير في العراق ، وهو نصب تذكاري نادر في الشرق الأوسط كان مقر إقامة هيراكان في أوائل القرن الثاني قبل الميلاد.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;الإقامة: فندق.&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;وجبات الطعام ما يلي: الفطور ، الغداء ، العشاء.&lt;/span&gt;&lt;/h3&gt;'),
(236, 21, 'en', 'AMMAN / DESERT CASTLES / DEAD SEA / MONT NEBO / MADABA', NULL, '&lt;p&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif;&quot;&gt;This morning, it is the departure for the desert to the east of &lt;strong&gt;Amman&lt;/strong&gt; to discover the castles of the desert.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;span style=&quot;font-family: verdana, geneva, sans-serif;&quot;&gt;Remains of the early days of Islam, buildings dating from the Umayyad period or refuge of Lawrence of Arabia, each castle has its history ... Place to the splendor of the Rift Valley.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif;&quot;&gt;In Jordan, it manifests itself in a vast depression traversed in the north by the Jordan, giving birth to a rich agricultural region, to the south by the shores of the &lt;strong&gt;Dead Sea&lt;/strong&gt;, the lowest point of the globe at 408 meters below the level of the sea.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif;&quot;&gt;In the late afternoon we go to &lt;strong&gt;Mount Nebo&lt;/strong&gt; overlooking &lt;strong&gt;Madaba,&lt;/strong&gt; a small peaceful town not far from Amman. Moses, before dying there, would have contemplated from this summit a number of biblical sites such as Bethany, the oasis of Jericho, the shrine of Lot or &lt;strong&gt;Jerusalem&lt;/strong&gt;. Visit of the memorial of Moses and discovery of the splendid panorama on the valley.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif;&quot;&gt;Accommodation: hotel.&lt;/span&gt;&lt;/strong&gt;<br>&lt;strong&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif;&quot;&gt;Meals included: morning, noon, evening.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;'),
(237, 21, 'fr', 'Amman - châteaux du désert - mer Morte - Mont Nébo - Madaba', NULL, '&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;color: #000000; font-size: 12pt; font-family: verdana, geneva, sans-serif;&quot;&gt;Ce matin, c&#039;est le départ pour le désert à l&#039;est d&#039;&lt;strong&gt;Amman&lt;/strong&gt; pour découvrir les châteaux du désert. &lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;color: #000000; font-size: 12pt; font-family: verdana, geneva, sans-serif;&quot;&gt;Vestiges des premiers temps de l&#039;islam, constructions datant de l&#039;époque omeyyade ou refuge de Lawrence d&#039;Arabie, chaque château a son histoire... Place à la splendeur de la vallée du Rift. En Jordanie, elle se manifeste par une vaste dépression parcourue au nord par le Jourdain, donnant naissance à une riche région agricole, au sud par les rives de la mer Morte, point le plus bas du globe à 408 mètres en dessous du niveau de la mer. &lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;color: #000000; font-size: 12pt; font-family: verdana, geneva, sans-serif;&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;color: #000000; font-size: 12pt; font-family: verdana, geneva, sans-serif;&quot;&gt;En fin d&#039;après-midi nous nous rendons sur le &lt;strong&gt;Mont Nébo&lt;/strong&gt; qui surplombe &lt;strong&gt;Madaba&lt;/strong&gt;, petite bourgade paisible non loin d’Amman. Moïse, avant d’y mourir, aurait contemplé de ce sommet nombre de sites bibliques comme Béthanie, l’oasis de Jéricho, le sanctuaire de Loth ou encore &lt;strong&gt;Jérusalem&lt;/strong&gt;. Visite du mémorial de Moïse et découverte du splendide panorama sur la vallée.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;color: #000000; font-size: 12pt; font-family: verdana, geneva, sans-serif;&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;color: #000000; font-family: verdana, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;float: none; background-color: transparent; color: #000000; cursor: text; font-style: normal; font-variant: normal; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; display: inline !important;&quot;&gt;Hébergement : hôtel. &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;color: #000000; font-family: verdana, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;float: none; background-color: transparent; color: #000000; cursor: text; font-style: normal; font-variant: normal; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; display: inline !important;&quot;&gt;Repas inclus : matin, midi, soir.&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;'),
(238, 21, 'it', 'Amman - Castelli dei deserti - Mar Morto - Monte Nebo - Madaba', NULL, '&lt;p&gt;In questa mattinata, partiamo alla volta del deserto ad est di Amman per scoprire i castelli del deserto. Resti dei primi tempi dell&#039;Islam, edifici risalenti al periodo omayyade o rifugio di Lawrence d&#039;Arabia, ogni castello ha la sua storia ... Posto allo splendore della Rift Valley. Alla fine del pomeriggio andiamo al Monte Nebo, con vista su Madaba, una tranquilla cittadina poco distante da Amman. Mosè, prima di morire lì, avrebbe contemplato da questa vetta alcuni siti biblici come Betania, l&#039;oasi di Gerico, il santuario di Lot o Gerusalemme. Visita del memoriale di Mosè e scoperta dello splendido panorama sulla valle.&lt;/p&gt;\r\n&lt;p&gt;Alloggio: hotel.&lt;/p&gt;\r\n&lt;p&gt;Pasti inclusi: colazione, pranzo, cena&lt;/p&gt;'),
(239, 21, 'es', 'Amman - Castillos del desierto - Mar Muerto - Monte Nebo - Madaba', NULL, '&lt;p&gt;Esta mañana, salimos hacia el desierto al este de Amman para descubrir los castillos del desierto. Los restos de los primeros días del Islam, los edificios que datan del período omeya o refugio de Lawrence de Arabia, cada castillo tiene su propia historia ... Lugar del esplendor del Valle del Rift. Al final de la tarde, vamos al monte Nebo, con vistas a Madaba, una ciudad tranquila no muy lejos de Amman. Antes de que muriera allí, Moisés habría contemplado desde esta cima algunos sitios bíblicos como Betania, el oasis de Jericó, el santuario de Lot o Jerusalén. Visita el memorial de Moisés y descubre el espléndido panorama del valle.&lt;/p&gt;\r\n&lt;p&gt;Alojamiento: hotel.&lt;/p&gt;\r\n&lt;p&gt;Comidas incluidas: desayuno, almuerzo, cena.&lt;/p&gt;'),
(240, 21, 'Ar', 'عمان -القصور الصحراء - البحر الميت - جبل نيبو - مادبا', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;هذا الصباح ، هو الذهاب إلى شرق عمان لاكتشاف القصور الصحراوية.&lt;/strong&gt;&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;بقايا أيام الإسلام المبكرة ، المباني التي يرجع تاريخها إلى الفترة الأموية أو مأوى لورانس العرب ، كل قلعة لها تاريخها ... مكان لروعة الوادي المتصدع. في الأردن ، يتجلى ذلك في كساد شاسع يمر عبر الشمال من الأردن ، وينتج منطقة زراعية غنية ، إلى الجنوب على ضفاف البحر الميت ، أدنى نقطة في العالم على ارتفاع 408 أمتار تحت مستوى سطح البحر. الأربعاء&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;ثم بعد ذلك  نذهب إلى جبل نيبو المطل على مادبا ، وهي بلدة هادئة صغيرة ليست بعيدة عن عمان. قبل موته  كان النبي موسى يفكر في هذه القمة في عدد من المواقع التوراتية مثل بيت عنيا ، واحة أريحا ، مزار لوط أو القدس. زيارة النصب التذكاري لموسى واكتشاف بانوراما رائعة على الوادي.&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;الإقامة: فندق.&lt;/strong&gt;&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;وجبات الطعام ما يلي: الفطور ، الغداء ، العشاء.&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;'),
(241, 22, 'en', 'MADABA / KERAK / LITTLE PETRA', NULL, '&lt;p&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif;&quot;&gt;This morning we discover &lt;strong&gt;Madaba&lt;/strong&gt; and its &lt;strong&gt;church Saint-Georges,&lt;/strong&gt; famous for its mosaic which represents the oldest cartographic representation that came to us from the Holy Land and in particular from &lt;strong&gt;Jerusalem&lt;/strong&gt;. It dates from the end of the 6th century.&lt;/span&gt;<br>&lt;span style=&quot;font-family: verdana, geneva, sans-serif;&quot;&gt;We then take the road of the Kings offering magnificent views of vertiginous canyons. We stop for a few moments to observe the &lt;strong&gt;Wadi Mujib,&lt;/strong&gt; the river that takes the deepest canyon in Jordan.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif;&quot;&gt;En route, visit the cross fortress of &lt;strong&gt;Kerak,&lt;/strong&gt; place of great battles between the Moors, led by Saladin, and the cross of Renaud de Chatillon. The castle remains in a remarkable state of preservation! Then it is the arrival at the fantastic site of Little Petra (8 km north of Petra) and the exploration of Sîq el Bared and Beidha (Neolithic village, 6500 years before our era). Installation at the hotel in Petra &lt;strong&gt;(Wadi Musa)&lt;/strong&gt; for three nights.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif;&quot;&gt;Accommodation: hotel.&lt;/span&gt;&lt;/strong&gt;<br>&lt;strong&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif;&quot;&gt;Meals included: morning, noon, evening.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;'),
(242, 22, 'fr', 'Madaba - Kérak - Little Pétra', NULL, '&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;color: #000000; font-size: 12pt; font-family: verdana, geneva, sans-serif;&quot;&gt;Ce matin nous découvrons &lt;strong&gt;Madaba et son église Saint-Georges&lt;/strong&gt;, célèbre pour sa mosaïque qui représente la plus ancienne représentation cartographique qui nous soit parvenue de la Terre sainte et en particulier de &lt;strong&gt;Jérusalem&lt;/strong&gt;. Elle date de la fin du VIe siècle.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;color: #000000; font-size: 12pt; font-family: verdana, geneva, sans-serif;&quot;&gt; Nous empruntons ensuite la route des Rois offrant de magnifiques points de vue sur des canyons vertigineux. Nous nous arrêtons quelques instants pour observer le &lt;strong&gt;Wadi Mujib&lt;/strong&gt;, la rivière qui emprunte le plus profond canyon de Jordanie.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;color: #000000; font-size: 12pt; font-family: verdana, geneva, sans-serif;&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;color: #000000; font-size: 12pt; font-family: verdana, geneva, sans-serif;&quot;&gt;En route, visite de la forteresse croisée de &lt;strong&gt;Kérak,&lt;/strong&gt; lieu de grandes batailles entre les maures, menés par Saladin, et les croisés de Renaud de Châtillon. Le château reste dans un état de conservation remarquable ! Puis c’est l’arrivée au fantastique site de Little Petra (8 km au nord de &lt;strong&gt;Pétra&lt;/strong&gt;) et l’exploration du &lt;strong&gt;Sîq el Bared&lt;/strong&gt; et de Beidha (village néolithique, 6500 ans avant notre ère). Installation à l’hôtel à Pétra (Wadi Moussa) pour trois nuits.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;color: #000000; font-size: 12pt; font-family: verdana, geneva, sans-serif;&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;color: #000000; font-family: verdana, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;float: none; background-color: transparent; color: #000000; cursor: text; font-style: normal; font-variant: normal; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; display: inline !important;&quot;&gt;Hébergement : hôtel. &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div class=&quot;travel__step__subtitle&quot; style=&quot;background-color: transparent; box-sizing: border-box; color: #21201f; font-family: Cervo Neue,Arial Narrow,sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: 500; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; margin: 0px;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;color: #000000; font-family: verdana, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;float: none; background-color: transparent; color: #000000; cursor: text; font-style: normal; font-variant: normal; letter-spacing: normal; orphans: 2; text-align: left; text-decoration: none; text-indent: 0px; text-transform: none; -webkit-text-stroke-width: 0px; white-space: normal; word-spacing: 0px; display: inline !important;&quot;&gt;Repas inclus : matin, midi, soir.&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;'),
(243, 22, 'it', 'Madaba - Kerak - Little Petra', NULL, '&lt;p&gt;Stamattina scopriamo Madaba e la Chiesa di San Giorgio, famosa per il mosaico pavimentale con la rappresentazione più antica della Terra Santa. Risale alla fine del VI secolo.<br>Prendiamo quindi la strada dei Re offrendo magnifiche vedute di canyon vertiginosi. Ci fermiamo per qualche istante ad osservare il Wadi Mujib, il fiume che porta nel canyon più profondo della Giordania. Durante il tragitto, visita della fortezza di Karak, luogo di grandi battaglie tra i musulmani, guidati da Saladino, ed i crociati di Rinaldo di Chatillon. Il castello rimane in un notevole stato di conservazione! In seguito ci dirigiamo verso il fantastico sito di Little Petra (8 km a nord di Petra) e all&#039;esplorazione di Sîq el Bared e Beidha (villaggio neolitico, 6500 anni prima della nostra era). Sistemazione in hotel a Petra (Wadi Musa)&lt;/p&gt;\r\n&lt;p&gt;Alloggio: hotel. Pasti inclusi: colazione, cena&lt;/p&gt;'),
(244, 22, 'es', 'Madaba - Kerak - Pequeño Petra', NULL, '&lt;p&gt;Esta mañana descubrimos Madaba y la Iglesia de San Giorgio, famosa por el mosaico del suelo con la representación más antigua de Tierra Santa. Se remonta a finales del siglo VI.<br>Luego tomamos el camino de los reyes que ofrecen magníficas vistas de cañones vertiginosos. Nos detenemos por unos momentos para observar el Wadi Mujib, el río que conduce al cañón más profundo del Jordán. En el camino, visite la fortaleza Karak, lugar de grandes batallas entre los musulmanes, liderada por Saladin, y los cruzados de Rinaldo di Chatillon. El castillo permanece en un notable estado de conservación! Luego nos dirigimos hacia el sitio fantástico de Little Petra (8 km al norte de Petra) y la exploración de Sîq el Bared y Beidha (aldea neolítica, 6500 años antes de nuestra era). Alojamiento en hotel en Petra (Wadi Musa)&lt;/p&gt;\r\n&lt;p&gt;Alojamiento: hotel. Comidas incluidas: desayuno, cena.&lt;/p&gt;'),
(245, 22, 'Ar', 'مادبا - الكرك - البتراء الصغيرة', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;نكتشف هذا الصباح مادابا وكنيستها سانت جورج التي تشتهر بفسيفساءها التي تمثل أقدم تمثيل لرسم الخرائط جاء إلينا من الأرض المقدسة وخاصة من القدس. يعود تاريخه إلى نهاية القرن السادس.&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;ثم نأخذ طريق الملوك حيث نعرض مناظر رائعة من الأخاديد العميقة. نتوقف لبضع لحظات لمراقبة وادي مجيب ، النهر الذي يأخذ أعمق كانيون في الأردن.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;في الطريق ، قم بزيارة حصن الكرك ، مكان المعارك العظيمة بين المغاربة ، بقيادة صلاح الدين ، وصليب رينو دي شاتيلون. القلعة لا تزال في حالة رائعة من الحفاظ عليها! ثم إنه الوصول إلى موقع البتراء الصغيرة الرائع (8 كيلومترات شمال البتراء) واستكشاف Síq el  ، قبل 6500 سنة من عصرنا). الإقامة في الفندق في البتراء ).&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;الإقامة: فندق.&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;وجبات الطعام ما يلي: الفطور ، الغداء ، العشاء.&lt;/span&gt;&lt;/h3&gt;'),
(246, 23, 'en', 'DEAD SEA / MADABA / MONT NEBO / KERAK / DANA', NULL, '&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Departure to the north to visit &lt;strong&gt;Madaba&lt;/strong&gt;, the &quot;city of mosaics&quot;, the most famous of which is a 6th century mosaic map depicting Jerusalem. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Then visit &lt;strong&gt;Mount Nebo&lt;/strong&gt; which offers a spectacular view of the Holy Land. Here you will find the memorial of Moses, and the place from which he discovered the promised land. After the visit, crossing&lt;strong&gt; the valley of Mojeb (wadi almojeb)&lt;/strong&gt; between Madaba and &lt;strong&gt;Kerak. &lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Visit of Kerak Castle, built by the Crusaders in the 12th century. We will arrive in the evening with the sunset on the mountain of &lt;strong&gt;Dana.&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Accommodation: hotel&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Meals included: Morning, evening&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;');
INSERT INTO `en33_tours_canned_days_contents` (`id`, `day_id`, `lang`, `title`, `place`, `description`) VALUES
(247, 23, 'fr', 'MER MORTE / MADABA / MONT NEBO / KERAK / DANA', NULL, '&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;text-align: left; text-transform: none; text-indent: 0px; letter-spacing: 0.7px; font-style: normal; font-variant: normal; text-decoration: none; word-spacing: 0px; white-space: normal; orphans: 2; float: none; -webkit-text-stroke-width: 0px; background-color: transparent; display: inline !important;&quot;&gt;Départ vers le nord pour visiter &lt;strong&gt;Madaba,&lt;/strong&gt; la &lt;strong&gt;« ville des mosaïques »&lt;/strong&gt; dont la plus célèbre est une carte mosaïque du 6ème siècle, représentant Jérusalem. Puis visite du Mont Nébo qui offre une vue spectaculaire sur la Terre Sainte. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;text-align: left; text-transform: none; text-indent: 0px; letter-spacing: 0.7px; font-style: normal; font-variant: normal; text-decoration: none; word-spacing: 0px; white-space: normal; orphans: 2; float: none; -webkit-text-stroke-width: 0px; background-color: transparent; display: inline !important;&quot;&gt;Ici, vous trouverez le mémorial de Moïse, et l&#039;endroit duquel il a découvert la terre promise. Après la visite, traversée de &lt;strong&gt;la vallée du Mojeb (wadi almojeb)&lt;/strong&gt; entre Madaba et Kérak. Visite du château de &lt;strong&gt;Kérak&lt;/strong&gt;, construit par les Croisés au 12ème siècle. Nous arriverons le soir avec le coucher du soleil sur la montagne de &lt;strong&gt;Dana.&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;text-align: left; text-transform: none; text-indent: 0px; letter-spacing: 0.7px; font-style: normal; font-variant: normal; text-decoration: none; word-spacing: 0px; white-space: normal; orphans: 2; float: none; -webkit-text-stroke-width: 0px; background-color: transparent; display: inline !important;&quot;&gt;Hebergement : hotel &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family: verdana, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;text-align: left; text-transform: none; text-indent: 0px; letter-spacing: 0.7px; font-style: normal; font-variant: normal; text-decoration: none; word-spacing: 0px; white-space: normal; orphans: 2; float: none; -webkit-text-stroke-width: 0px; background-color: transparent; display: inline !important;&quot;&gt;Repas inclu : Matin , soir&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;'),
(248, 23, 'it', 'MAR MORTO / MADABA / NEBO MOUNT / KERAK / DANA', NULL, '&lt;p&gt;Partenza verso nord per visitare Madaba, la &quot;città dei mosaici&quot;, il più famoso dei quali è una mappa mosaica del VI secolo raffigurante Gerusalemme. Quindi visitare il Monte Nebo che offre una vista spettacolare della Terra Santa. Qui troverai il memoriale di Mosè e il luogo da cui ha scoperto la terra promessa. Dopo la visita, attraversando la valle del Moujib (Wadi Almoujib) tra Madaba e Alkarak. Visita del castello di Karak, costruito dai crociati nel 12 ° secolo. Tramonto sulla montagna di Dana.&lt;/p&gt;\r\n&lt;p&gt;Sistemazione: hotel, pasti inclusi: colazione, cena&lt;/p&gt;'),
(249, 23, 'es', 'MAR MUERTO / MADABA / NEBO MOUNT / KARAK / DANA', NULL, '&lt;p&gt;Salida hacia el norte para visitar Madaba, la &quot;ciudad de los mosaicos&quot;, la más famosa de las cuales es un mapa de mosaico del siglo sexto que representa a Jerusalén. Luego visite el Monte Nebo, que ofrece una vista espectacular de la Tierra Santa. Aquí encontrará el memorial de Moisés y el lugar desde el cual descubrió la tierra prometida. Después de la visita, cruzamos el valle de Moujib (Wadi Almoujib) entre Madaba y Alkarak. Visita el castillo de Karak, construido por los cruzados en el siglo XII. Atardecer en la montaña dana.&lt;/p&gt;\r\n&lt;p&gt;Alojamiento: hotel, comidas incluidas, desayuno, cena.&lt;/p&gt;'),
(250, 23, 'Ar', 'البحرالميت  - مادابا - جبل نيبو - كرك  -ضانا', NULL, ''),
(251, 24, 'en', 'DANA / SHOWBAK / Little PETRA / PETRA', NULL, '&lt;p&gt;Visit the traditional village of &lt;strong&gt;Dana&lt;/strong&gt;, the craft center and the museum of the nature reserve. Visit of the castle of &lt;strong&gt;Showbak.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Remains isolated from the ancient glory of the Crusaders, the castle of Showbak is located at 30km south of Dana then road to Petit Pétra (a miniature replica of the &lt;strong&gt;&quot;City of Roses of Petra&quot;)&lt;/strong&gt;&lt;/p&gt;'),
(252, 24, 'fr', 'DANA / SHOWBAK / PETIT PETRA / PETRA', NULL, '&lt;p&gt;&lt;span style=&quot;text-align: left; color: #000000; text-transform: none; text-indent: 0px; letter-spacing: 0.7px; font-family: Arial,Verdana,Helvetica,sans-serif; font-size: 12pt; font-style: normal; font-variant: normal; font-weight: 400; text-decoration: none; word-spacing: 0px; display: inline !important; white-space: normal; orphans: 2; float: none; -webkit-text-stroke-width: 0px; background-color: transparent;&quot;&gt;Visite du village traditionnel de&lt;strong&gt; Dana&lt;/strong&gt;, du centre artisanal et du musée de la réserve naturelle. Visite du château de &lt;strong&gt;Showbak. &lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span style=&quot;text-align: left; color: #000000; text-transform: none; text-indent: 0px; letter-spacing: 0.7px; font-family: Arial,Verdana,Helvetica,sans-serif; font-size: 12pt; font-style: normal; font-variant: normal; font-weight: 400; text-decoration: none; word-spacing: 0px; display: inline !important; white-space: normal; orphans: 2; float: none; -webkit-text-stroke-width: 0px; background-color: transparent;&quot;&gt;Vestige isolé de l&#039;ancienne gloire des Croisés, le château de Showbak se trouve à moins 30km au sud de &lt;strong&gt;Dana&lt;/strong&gt; puis route vers &lt;strong&gt;Petit Pétra&lt;/strong&gt; (une réplique en miniature de la &lt;strong&gt;«Cité des Roses de Pétra »)&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;'),
(253, 24, 'it', 'DANA / SHOWBAK / PICCOLO PETRA / PETRA', NULL, '&lt;p&gt;Visita del tradizionale villaggio di Dana, il centro artigianale e il museo della riserva naturale. Visita del castello di Showbak. Resta isolata dall&#039;antica gloria dei crociati, il castello di Showbak si trova a 30 km a sud di Dana, quindi strada verso Piccola Petra &lt;/p&gt;'),
(254, 24, 'es', 'DANA / SHOWBAK / PEQUEÑA PETRA / PETRA', NULL, '&lt;p&gt;Visite el pueblo tradicional de Dana, el centro de artesanía y el museo de la reserva natural. Visita al castillo de Showbak. Permanece aislado de la antigua gloria de los cruzados. El castillo de Showbak se encuentra a 30 km al sur de Dana, luego el camino a Piccola Petra.&lt;/p&gt;'),
(255, 24, 'Ar', 'دانا / شوبك / بترا صغيرة  / بترا', NULL, ''),
(306, 25, 'en', 'ALLENBY BRIDGE / MASADA / BETHLEHEM / JERUSALEM', NULL, '&lt;p&gt;visit &lt;strong&gt;Capernaum&lt;/strong&gt;, the &lt;strong&gt;Mount of Beatitudes&lt;/strong&gt; and &lt;strong&gt;Tabgha&lt;/strong&gt;, the fundamental tour of the &lt;strong&gt;Sea of Galilee.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Continuation to &lt;strong&gt;Haifa,&lt;/strong&gt; visit of &lt;strong&gt;Mt. Carmel,&lt;/strong&gt; Stella Mares, stop at the beautiful view of &lt;strong&gt;Bahaai Gardens.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Road to &lt;strong&gt;Tel Aviv.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;City tour in Tel Aviv, visit the ancient city of &lt;strong&gt;Jaffa&lt;/strong&gt; and its &lt;strong&gt;Old Port, St. Peter House.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Road to &lt;strong&gt;Jerusalem&lt;/strong&gt; and installation at your hotel.&lt;/p&gt;'),
(307, 25, 'fr', 'Pont La Mer Morte - Allenby - Masada - Bethléem - Jérusalem', NULL, '&lt;p&gt;&lt;span&gt;visitez &lt;strong&gt;Capernaum&lt;/strong&gt;, &lt;strong&gt;le Mont des Béatitudes&lt;/strong&gt; et&lt;strong&gt; Tabgha&lt;/strong&gt;, le tour fondamental de la &lt;strong&gt;Mer de Galilée. &lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;Continuation à &lt;strong&gt;Haïfa,&lt;/strong&gt; visite du &lt;strong&gt;Mont. Carmel&lt;/strong&gt;, Stella Mares, arrêt au superbe point de vue des&lt;strong&gt; Jardins Bahaai. &lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;Route pour &lt;strong&gt;Tel Aviv. &lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;Visite de la ville à Tel Aviv, visite de l’ancienne ville de &lt;strong&gt;Jaffa&lt;/strong&gt; et de son &lt;strong&gt;Vieux-Port&lt;/strong&gt;,&lt;strong&gt; St. Peter House. &lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;Route pour &lt;strong&gt;Jérusalem&lt;/strong&gt; et installation à votre hôtel.&lt;/span&gt;&lt;/p&gt;'),
(308, 25, 'it', 'Ponte del Mar Morto - Allenby - Masada - Betlemme - Gerusalemme', NULL, '&lt;p&gt;Visita di Cafarnao, il Monte delle Beatitudini e Tabgha, il tour fondamentale del Mare di Galilea.&lt;/p&gt;\r\n&lt;p&gt;Continuazione verso Haifa, visita del Monte Carmel, Stella Maris, con fermata alla splendida vista dei Giardini Bahaai.&lt;/p&gt;\r\n&lt;p&gt;Strada per Tel Aviv.&lt;/p&gt;\r\n&lt;p&gt;Visita della città a Tel Aviv, visitiamo l&#039;antica città di Giaffa e il suo Porto Vecchio, la Casa di San Pietro.&lt;/p&gt;\r\n&lt;p&gt;Strada per Gerusalemme e sistemazione in hotel.&lt;/p&gt;'),
(309, 25, 'es', 'Puente del Mar Muerto - Allenby - Masada - Belén - Jerusalén', NULL, '&lt;p&gt;Visita a Capernaum, el Monte de las Bienaventuranzas y Tabgha, el recorrido fundamental del Mar de Galilea.&lt;/p&gt;\r\n&lt;p&gt;Continuación a Haifa, visita del Monte Carmelo, Stella Maris, con una parada en la espléndida vista de los Jardines Bahaai.&lt;/p&gt;\r\n&lt;p&gt;Camino a tel aviv.&lt;/p&gt;\r\n&lt;p&gt;Visite la ciudad de Tel Aviv, visite la antigua ciudad de Jaffa y su antiguo puerto, la Casa de San Pedro.&lt;/p&gt;\r\n&lt;p&gt;Camino a Jerusalén y alojamiento en hotel.&lt;/p&gt;'),
(310, 25, 'Ar', 'جسر الملك حسين - مسعدة - بيت لحم - القدس', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;يارة كفرناحوم وجبل التطويبات والطابغة ، جولة أساسية في بحر الجليل.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;الاستمرار إلى حيفا ، زيارة جبل. كارميل ، ستيلا ماريس ، يتوقف عند منظر جميل من حدائق البهائي.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;الطريق الى تل ابيب.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;جولة في المدينة في تل أبيب ، وزيارة مدينة يافا القديمة وميناءها القديم ، وسانت بيتر هاوس.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;الطريق إلى القدس والإقامة في فندقك.&lt;/span&gt;&lt;/h3&gt;'),
(311, 26, 'en', 'SHOBAK / WADI GHWEIRE / PETRA', NULL, '&lt;p&gt;After breakfast, visit the Shobak castle then we continue our road to &lt;strong&gt;Ghuweir canyon!&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Hike in this natural setting, between the hanging gardens &lt;strong&gt;accompanied by your local guide.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Picnic lunch Then after the hike, transfer to &lt;strong&gt;Petra&lt;/strong&gt; via the &lt;strong&gt;Wadi Araba desert.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;5h hike&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Dinner and overnight at the hotel.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Full board&lt;/strong&gt;&lt;/p&gt;'),
(312, 26, 'fr', 'Shobak - Wadi Ghweire - Pétra', NULL, '&lt;table width=&quot;5&quot; height=&quot;5&quot;&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td style=&quot;width: 0px;&quot;&gt;&lt;/td&gt;\r\n&lt;td style=&quot;width: 0px;&quot;&gt;&lt;/td&gt;\r\n&lt;td style=&quot;width: 0px;&quot;&gt;&lt;/td&gt;\r\n&lt;td style=&quot;width: 0px;&quot;&gt;&lt;/td&gt;\r\n&lt;td style=&quot;width: 0px;&quot;&gt;&lt;/td&gt;\r\n&lt;td style=&quot;width: 0px;&quot;&gt;&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;\r\n&lt;p&gt;&lt;span&gt;Après le petit déjeuner,passage par le chateau de &lt;strong&gt;Shobak&lt;/strong&gt; puis en route pour &lt;strong&gt;le canyon du Ghuweir!&lt;/strong&gt; &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;&lt;strong&gt;Randonnée&lt;/strong&gt; dans cet écrin de nature, entre les jardins suspendus&lt;strong&gt; accompagné de votre guide local&lt;/strong&gt;. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;Pique nique le midi Puis après la randonnée, transfert à&lt;strong&gt; Pétra&lt;/strong&gt; en passant par le désert du &lt;strong&gt;Wadi Araba.&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Randonnée 5h&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;&lt;strong&gt; Dîner et nuit à l&#039;hôtel.&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt; &lt;strong&gt;Pension complete &lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;'),
(313, 26, 'it', 'Shobak - Wadi Ghweire - Petra', NULL, '&lt;p&gt;Dopo colazione, visita del castello di Shoubak e guida fino al canyon di Wadi Ghuweir! Fai un&#039;escursione in questo ambiente naturale, tra i giardini pensili accompagnati dalla tua guida locale. Escursione 5h&lt;/p&gt;\r\n&lt;p&gt;Pranzo al sacco&lt;/p&gt;\r\n&lt;p&gt;Al termine, trasferimento a Petra attraverso il deserto di Wadi Araba.&lt;/p&gt;\r\n&lt;p&gt;Cena e pernottamento in hotel. &lt;/p&gt;'),
(314, 26, 'es', 'Shobak - Wadi Ghweire - Petra', NULL, '&lt;p&gt;Después del desayuno, visite el castillo de Shoubak y conduzca hasta el cañón Wadi Ghuweir. Realice una excursión en este entorno natural, entre los jardines colgantes acompañados por su guía local. Excursión 5h&lt;/p&gt;\r\n&lt;p&gt;Almuerzo para llevar&lt;/p&gt;\r\n&lt;p&gt;Al final, traslado a Petra a través del desierto de Wadi Araba.&lt;/p&gt;\r\n&lt;p&gt;Cena y alojamiento en el hotel.&lt;/p&gt;'),
(315, 26, 'Ar', 'الشوبك - وادي غوير - البتراء', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;بعد وجبة الإفطار ، نقوم بزيارة قلعة الشوبك وثم وادي غوير&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;تنزه في هذا المكان الطبيعي ، بين الحدائق المعلقة مصحوبة بمرشدك المحلي.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;غداء ثم بعد التنزه ، الانتقال إلى البتراء عبر صحراء وادي عربة.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;العشاء والمبيت في الفندق.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;إقامة كاملة&lt;/span&gt;&lt;/h3&gt;'),
(316, 27, 'en', 'MA&#039;IN HOT SPRINGS', NULL, '&lt;p&gt;Spend unforgettable moments with your family at the warm waterfall at the &lt;strong&gt;&quot;family pool&quot;,&lt;/strong&gt; or luxuriate in the Roman baths inside.<br>The hot springs of &lt;strong&gt;Hammamat Ma&#039;in&lt;/strong&gt; are a must in Jordan, not only for their mineral wealth, but also for the beautiful natural setting.&lt;/p&gt;\r\n&lt;p&gt;Enjoy the services of your hotel (pool, massage, ride) one last morning before leaving for &lt;strong&gt;Wadi Al Mujib.&lt;/strong&gt;<br>Do not forget your camera to take a souvenir&lt;/p&gt;'),
(317, 27, 'fr', 'Ma&#039;in Sources  d&#039;Eau Chaudes', NULL, '&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;986gu&quot; data-offset-key=&quot;aldha-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;aldha-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;aldha-0-0&quot;&gt;Passez des moments inoubliables avec votre famille à la cascade chaude à la &lt;strong&gt;&quot;piscine familiale&quot;&lt;/strong&gt;, ou prélassez-vous dans les thermes romains à l&#039;intérieur.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;986gu&quot; data-offset-key=&quot;28smq-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;28smq-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;28smq-0-0&quot;&gt;Les sources chaudes d’&lt;strong&gt;Hammamat Ma&#039;in&lt;/strong&gt; sont un incontournable de la Jordanie, non seulement pour leur richesse minérale, mais aussi pour le magnifique cadre naturel.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;28smq-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;28smq-0-0&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;986gu&quot; data-offset-key=&quot;5136p-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;5136p-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;5136p-0-0&quot;&gt;Profitez des services de votre hôtel (piscine, massage, balade) une dernière matinée avant de partir pour &lt;strong&gt;Wadi Al Mujib. &lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;5136p-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;5136p-0-0&quot;&gt;N&#039;oubliez pas votre appareil photo pour prendre un souvenir &lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;'),
(318, 27, 'it', 'Ma&#039;in fonti di acqua calda', NULL, '&lt;p&gt;Trascorri momenti indimenticabili con la tua famiglia nella calda cascata della &quot;piscina per famiglie&quot; o goditi i bagni romani all&#039;interno.<br>Le sorgenti termali di Hammamat Ma&#039;in sono un must in Giordania, non solo per la loro ricchezza minerale, ma anche per la splendida cornice naturale.<br>Goditi i servizi del tuo hotel (piscina, massaggi, corsa) l&#039;ultima mattina prima di partire per Wadi Al Mujib.<br><br>&lt;/p&gt;'),
(319, 27, 'es', 'Fuentes de agua caliente', NULL, '&lt;p&gt;Pase momentos inolvidables con su familia en la cálida cascada de la &quot;piscina familiar&quot; o disfrute de los baños romanos en el interior.<br>Las aguas termales de Hammamat Ma&#039;in son una necesidad en Jordania, no solo por su riqueza mineral, sino también por el bello entorno natural.<br>Disfrute de los servicios de su hotel (piscina, masajes, carreras) la última mañana antes de partir hacia Wadi Al Mujib.&lt;/p&gt;'),
(321, 28, 'en', 'DEAD SEA / WADI AL MUJIB', NULL, '&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;b0589&quot; data-offset-key=&quot;e1mmn-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;e1mmn-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;e1mmn-0-0&quot;&gt;Transfer to the heart of &lt;strong&gt;Wadi-Mujib&lt;/strong&gt;, the deepest &lt;strong&gt;canyon&lt;/strong&gt; in Jordan that is part of the Rift Range. &lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;e1mmn-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;e1mmn-0-0&quot;&gt;Exploration and aquatic walk. Discovery of its waterfall and its natural pools. Walk and swim in the natural pools dug in &quot;pot&quot;.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;b0589&quot; data-offset-key=&quot;f24br-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;f24br-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;f24br-0-0&quot;&gt;We continue our exploration to the waters of the famous dead sea with the highest salt rate in the world.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;f24br-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;f24br-0-0&quot;&gt;Feel free to experience the &lt;strong&gt;&quot;bathing&quot;&lt;/strong&gt; in this sea where you can only float! &lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;'),
(322, 28, 'fr', 'La Mer Morte - Wadi Mujib', NULL, '&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;b0589&quot; data-offset-key=&quot;ntri-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;ntri-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;ntri-0-0&quot;&gt;Transfert au coeur du &lt;/span&gt;&lt;strong&gt;Wadi-Mujib&lt;/strong&gt;&lt;span data-offset-key=&quot;ntri-0-2&quot;&gt;, le plus profond canyon de Jordanie qui fait partie de la chaîne du Rift. Exploration et marche aquatique. Découverte de sa cascade et de ses &lt;strong&gt;bassins naturelles. &lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;ntri-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;ntri-0-2&quot;&gt;Marche et baignade dans les piscines naturelles creusées en &quot;marmite&quot;.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;ntri-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;ntri-0-2&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;b0589&quot; data-offset-key=&quot;7higv-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;7higv-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;7higv-0-0&quot;&gt;Nous poursuivons notre exploration jusqu&#039;aux eaux de la fameuse mer morte au taux de sel le plus élevé du monde. N&#039;hésitez pas à vivre l&#039;expérience de la &lt;strong&gt;«baignade »&lt;/strong&gt; dans cette mer où l&#039;on ne peut que flotter ! &lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;'),
(323, 28, 'it', 'Il Mar Morto - Wadi Mujib', NULL, '&lt;p&gt;Trasferimento nel cuore di Wadi-Mujib, il canyon più profondo in Giordania che fa parte della Rift Valley. Scoperta della sua cascata e delle sue piscine naturali. Cammina e nuota nelle piscine naturali scavate nella &quot;pentola&quot;.<br>Continuiamo la nostra esplorazione verso le acque salate del famoso Mar Morto. Sentiti libero di provare il &quot;bagno&quot; in questo mare dove puoi solo galleggiare!&lt;/p&gt;'),
(324, 28, 'es', 'El Mar Muerto - Wadi Mujib', NULL, '&lt;p&gt;Trasládese al corazón de Wadi-Mujib, el cañón más profundo de Jordania que forma parte del Valle del Rift. Descubrimiento de su cascada y de sus piscinas naturales. Camina y nada en las piscinas naturales excavadas en la &quot;olla&quot;.<br>Continuamos nuestra exploración de las aguas saladas del famoso Mar Muerto. ¡Siéntete libre de probar el &quot;baño&quot; en este mar donde solo puedes flotar!&lt;/p&gt;'),
(325, 28, 'Ar', 'البحر الميت - وادي الموجب', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;الانتقال إلى قلب وادي الموجب ، أعمق وادي في الأردن والذي هو جزء من سلسلة جبال ريفت. الاستكشاف والمشي المائي. اكتشاف شلاله ومسابحه الطبيعية.&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;المشي والسباحة في حمامات طبيعية &quot;.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;نواصل استكشافنا لمياه البحر الميت الشهير مع أعلى معدل ملوحة في العالم. لا تتردد في تجربة &quot;الاستحمام&quot; في هذا البحر حيث يمكنك فقط أن تطفو!&lt;/span&gt;&lt;/h3&gt;'),
(341, 29, 'en', 'CULTURAL SPLENDOR IN NORTHERN JORDAN', NULL, '&lt;p&gt;You will have breakfast before taking the road to reach the ancient city of &lt;strong&gt;Umm Qays&lt;/strong&gt;, called &quot;Gadara&quot;. This ancient city is one of the ten cities of the Decapolis.<br>Upon arrival in &lt;strong&gt;&quot;Gadara&quot;,&lt;/strong&gt; you will enjoy beautiful panoramic views of&lt;strong&gt; the Sea of Galilee.&lt;/strong&gt; &quot;Gadara&quot; is the site where Jesus performed the famous miracle of the pigs: Jesus saved a man possessed by demons by transferring them into a herd of swine that plunged into the Sea of Galilee and drowned.&lt;/p&gt;\r\n&lt;p&gt;You will take the road back to Amman and stop at &lt;strong&gt;Pella,&lt;/strong&gt; one of the ten cities of the Decapolis, before continuing on to Amman.<br>When you arrive in &lt;strong&gt;Amman&lt;/strong&gt;, you will go to your hotel to have a good dinner and spend the night there.&lt;/p&gt;'),
(342, 29, 'fr', 'Splendeurs culturelles dans le Nord de la Jordanie', NULL, '&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;cpsv8&quot; data-offset-key=&quot;da880-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;da880-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;da880-0-0&quot;&gt;Vous prendrez votre petit déjeuner avant de prendre la route pour rejoindre la cité antique de&lt;strong&gt; Umm Qays&lt;/strong&gt;, dénommée « Gadara ». Cette cité antique est l&#039;une des dix villes de la Décapole. &lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;cpsv8&quot; data-offset-key=&quot;2jnc7-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;2jnc7-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;2jnc7-0-0&quot;&gt;A votre arrivée à &lt;strong&gt;« Gadara »,&lt;/strong&gt; vous profiterez de superbes vues panoramiques sur la Mer de Galilée. « Gadara » correspond au site où Jésus accomplit le fameux miracle des cochons : Jésus sauva un homme possédé par des démons en transférant ces derniers dans un troupeau de pourceaux qui plongèrent dans la &lt;strong&gt;mer de Galilée&lt;/strong&gt; et se noyèrent.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;2jnc7-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;2jnc7-0-0&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;cpsv8&quot; data-offset-key=&quot;cmmps-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;cmmps-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;cmmps-0-0&quot;&gt;Vous prendrez la route de retour vers&lt;strong&gt; Amman&lt;/strong&gt; et ferez une halte à&lt;strong&gt; Pella&lt;/strong&gt;, une des dix cités de la Décapoles, avant de poursuivre votre route vers Amman.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;cpsv8&quot; data-offset-key=&quot;73cbj-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;73cbj-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;73cbj-0-0&quot;&gt;A votre arrivée à &lt;strong&gt;Amman&lt;/strong&gt;, vous rejoindrez votre hôtel pour y prendre un bon dîner et y passer la nuit.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;'),
(343, 29, 'it', 'Splendore culturale nel nord della Giordania', NULL, '&lt;p&gt;Dopo la prima colazione, raggiungiamo l&#039;antica città di Umm Qays, chiamata &quot;Gadara&quot;. Questa antica città è una delle antiche dieci città che ormavano la Decapoli.<br>All&#039;arrivo a &quot;Gadara&quot;, godrai di splendide viste panoramiche sul Mare di Galilea. &quot;Gadara&quot; è il luogo in cui Gesù compì il famoso miracolo dei maiali: Gesù salvò un uomo posseduto dai demoni trasferendoli in un branco di porci, quest&#039;ultimi, impazziti completamente, si gettarono nel mare di Galilea ed affogarono..<br>Prendiamo poi la strada per Amman e ci fermiamo a Pella, un&#039;altra città della Decapoli, prima di giungere ad Amman.&lt;/p&gt;\r\n&lt;p&gt;<br>Pasti inclusi: colazione, cena&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Sistemazione: hotel&lt;/p&gt;'),
(344, 29, 'es', 'Esplendor cultural en el norte de Jordania', NULL, '&lt;p&gt;Después del desayuno, llegamos a la antigua ciudad de Umm Qays, llamada &quot;Gadara&quot;. Esta antigua ciudad es una de las diez antiguas ciudades que amarraron la Decápolis.<br>Al llegar a &quot;Gadara&quot;, disfrutará de hermosas vistas panorámicas del Mar de Galilea. &quot;Gadara&quot; es el lugar donde Jesús realizó el famoso milagro de los cerdos: Jesús salvó a un hombre poseído por demonios y los transfirió a una manada de cerdos, este último, completamente loco, se arrojaron al mar de Galilea y se ahogaron.<br>Luego tomamos el camino a Amman y paramos en Pella, otra ciudad de Decápolis, antes de llegar a Amman.&lt;/p&gt;\r\n&lt;p&gt;<br>Comidas incluidas: desayuno, cena.&lt;/p&gt;\r\n&lt;p&gt;&lt;/p&gt;\r\n&lt;p&gt;Alojamiento: hotel&lt;/p&gt;'),
(345, 29, 'Ar', 'روائع ثقافية في شمال الأردن', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;ستحصل على وجبة الإفطار قبل أن تسلك الطريق للوصول إلى مدينة أم قيس القديمة ، المسماة &quot;غادارا&quot;. هذه المدينة القديمة هي واحدة  من عشر مدن في Decapolis.&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;عند الوصول إلى &quot;Gadara&quot; ، ستتمتع بمناظر بانورامية جميلة على بحر الجليل. &quot;غادارا&quot; هو الموقع الذي أدّى فيه يسوع المعجزة الشهيرة للخنازير: أنقذ يسوع رجلاً امتلكه الشياطين بنقله إلى قطيع من الخنازير سقط في بحر الجليل وغرق.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;سوف تأخذ الطريق إلى عمان وتوقف في بيلا ، واحدة من عشر مدن في مدينة دي نابولي ، قبل أن تستمر في عمان.&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;عند وصولك إلى عمان ، ستذهب إلى فندقك لتتناول عشاءًا جيدًا وتقضي الليلة هناك.&lt;/span&gt;&lt;/h3&gt;'),
(701, 30, 'en', 'WALK IN THE ANCIENT CANYON - WADI GHWEIRE AND WADI FINAN', NULL, '&lt;p&gt;Transfer by car to &lt;strong&gt;Wadi Finan&lt;/strong&gt; and &lt;strong&gt;Wadi Gweire&lt;/strong&gt; where we start a walk in the ancient canyon of Finan.<br>We reach a beautiful valley dotted with wild oases lined with laurels -roses. Then we go on a copper mining site before reaching the Gweire canyon with refreshing sources of fresh water then&lt;strong&gt; Al Mansourah&lt;/strong&gt; before a short transfer to &lt;strong&gt;Petra.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Hiking time: 5.5 hours&lt;/strong&gt;<br>&lt;strong&gt;Accompanying a local guide&lt;/strong&gt;&lt;/p&gt;'),
(702, 30, 'fr', 'Marche dans l&#039;Antique Canyon', NULL, '&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;e7kc9&quot; data-offset-key=&quot;1lj2s-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;1lj2s-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;1lj2s-0-0&quot;&gt;Transfert en véhicule pour le &lt;/span&gt;&lt;strong&gt;Wadi Finan&lt;/strong&gt;&lt;span data-offset-key=&quot;1lj2s-0-2&quot;&gt; et le &lt;/span&gt;&lt;strong&gt;Wadi Gweire&lt;/strong&gt;&lt;span data-offset-key=&quot;1lj2s-0-4&quot;&gt; où nous entamons une marche dans l&#039;antique canyon de Finan. &lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;e7kc9&quot; data-offset-key=&quot;cgn36-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;cgn36-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;cgn36-0-0&quot;&gt;Nous accédons à une superbe vallée parsemée d&#039;oasis sauvages bordées de lauriers -roses. Puis nous passons sur un site d&#039;exploitation minière de cuivre avant de rejoindre le canyon de Gweire aux rafraîchissantes sources d&#039;eau douce puis&lt;/span&gt;&lt;span data-offset-key=&quot;cgn36-0-1&quot;&gt; Al &lt;strong&gt;Mansourah&lt;/strong&gt;&lt;/span&gt;&lt;span data-offset-key=&quot;cgn36-0-2&quot;&gt; avant un court transfert pour Pétra.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;cgn36-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;cgn36-0-2&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;e7kc9&quot; data-offset-key=&quot;e5pbg-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;e5pbg-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;strong&gt;Randonnée: 5,5 heures &lt;/strong&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;e7kc9&quot; data-offset-key=&quot;3jdkc-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;3jdkc-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;strong&gt;Accompagnemet d&#039;un guide locale&lt;/strong&gt;&lt;span data-offset-key=&quot;3jdkc-0-1&quot;&gt; &lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;'),
(703, 30, 'it', 'Cammina nel canyon antico', NULL, '&lt;p&gt;Trasferimento in auto a Wadi Finan e Wadi Gweire dove iniziamo una passeggiata nell&#039;antico canyon di Finan.<br>Raggiungiamo una bellissima valle punteggiata da oasi selvagge fiancheggiate da allori -rose. Poi andiamo in un sito minerario di rame prima di raggiungere il canyon del Gweire con fonti rinfrescanti di acqua dolce poi Al Mansourah prima di un breve trasferimento a Petra.&lt;/p&gt;\r\n&lt;p&gt;Tempo di percorrenza: 5,5 ore<br>Accompagnare una guida locale&lt;/p&gt;'),
(704, 30, 'es', 'Caminar en el antiguo cañón', NULL, '&lt;p&gt;Traslado en automóvil a Wadi Finan y Wadi Gweire, donde comenzamos a caminar en el antiguo cañón de Finan.<br>Llegamos a un hermoso valle salpicado de oasis salvajes flanqueados por laureles. Luego, vamos a un sitio de minería de cobre antes de llegar al cañón de Gweire con fuentes refrescantes de agua dulce, luego de Al Mansourah antes de un corto traslado a Petra.&lt;/p&gt;\r\n&lt;p&gt;Tiempo de viaje: 5,5 horas.<br>Acompañar a un guía local.&lt;/p&gt;'),
(705, 30, 'Ar', 'المشي في الوادي القديم', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;نقل بالسيارة إلى وادي الفنان ووادي الجوير حيث نبدأ نزهة في الوادي القديم في فينان.<br>نصل إلى وادي غوير الجميل مزروع بالواحات البرية المبطنة . ثم نذهب في موقع تعدين النحاس قبل الوصول إلى الوادي  مع مصادر منعشة من المياه العذبة ثم المنصورة قبل الانتقال إلى البتراء.&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;وقت المشي: 5.5 ساعة<br>يرافق دليل محلي&lt;/h3&gt;'),
(706, 31, 'en', 'WATER HIKING IN WADI IBN HAMMAD', NULL, '&lt;p&gt;Beautiful aquatic hike in the waters of &lt;strong&gt;Wadi Ibn Hamad.&lt;/strong&gt; It is a day under the sign of water between lush valleys, waterfalls and hot springs lined with wild palm groves.<br>We continue our pushes to &lt;strong&gt;Wadi-Finan&lt;/strong&gt; where we set up our bivouac.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Hiking time: 4.5 hours&lt;/strong&gt;<br>&lt;strong&gt;Accompanying a local guide&lt;/strong&gt;<br>&lt;strong&gt;Type of accommodation in bivouac&lt;/strong&gt;&lt;/p&gt;'),
(707, 31, 'fr', 'Rando-aquatique à Wadi Ibn Hammad', NULL, '&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;b9os2&quot; data-offset-key=&quot;71v0n-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;71v0n-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;71v0n-0-0&quot;&gt;Belle rando-aquatique dans les eaux du &lt;strong&gt;Wadi Ibn Hamad&lt;/strong&gt;. C&#039;est une journée placée sous le signe de l&#039;eau entre vallées luxuriantes, cascades et sources chaudes bordées de palmeraies sauvages. &lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;71v0n-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;71v0n-0-0&quot;&gt;Nous poursuivons notre poussons jusqu&#039;à &lt;strong&gt;Wadi-Finan&lt;/strong&gt; où nous installons notre bivouac.&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;71v0n-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;71v0n-0-0&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;b9os2&quot; data-offset-key=&quot;cu4qn-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;cu4qn-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;strong&gt;Randonnée: 4,5 heures&lt;/strong&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;b9os2&quot; data-offset-key=&quot;29gg3-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;29gg3-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;strong&gt;Accompagnemet d&#039;un guide locale &lt;/strong&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;29gg3-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;strong&gt;Type d&#039;hébergement en bivouac&lt;/strong&gt;&lt;span data-offset-key=&quot;29gg3-0-3&quot;&gt; &lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;'),
(708, 31, 'it', 'Escursioni in acqua a Wadi Ibn Hammad', NULL, '&lt;p&gt;Bella escursione acquatica nelle acque del Wadi Ibn Hamad. È un giorno sotto il segno dell&#039;acqua tra valli lussureggianti, cascate e sorgenti termali fiancheggiate da palmeti selvaggi. Continuiamo le nostre spinte verso il Wadi-Finan dove istituiamo il nostro bivacco.&lt;/p&gt;\r\n&lt;p&gt;Tempo di percorrenza: 4,5 ore<br>Accompagnamento di una guida locale Tipo di alloggio in bivacco&lt;/p&gt;'),
(709, 31, 'es', 'Senderismo acuático en Wadi Ibn Hammad', NULL, '&lt;p&gt;Hermosa excursión de agua en las aguas de Wadi Ibn Hamad. Es un día bajo el signo del agua entre exuberantes valles, cascadas y fuentes termales bordeadas de palmerales silvestres. Continuamos nuestros esfuerzos hacia el Wadi-Finan, donde instalamos nuestro bivouac.&lt;/p&gt;\r\n&lt;p&gt;Tiempo de viaje: 4,5 horas.<br>Acompañamiento de un guía local. Tipo de alojamiento en bivouac.&lt;/p&gt;'),
(710, 31, 'Ar', 'المشي في الوادي المائي / وادي ابن حماد', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;ارتفاع جميل في المياه في وادي ابن حمد. إنه يوم تحت علامة الماء بين الوديان الخصبة والشلالات والينابيع الساخنة التي تصطف بساتين النخيل البرية.&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;نواصل دفعاتنا إلى وادي الفنجان حيث أقمنا إقامة لدينا.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;وقت المشي: 4.5 ساعة&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;يرافق دليل محلي&lt;/span&gt;<br>&lt;span style=&quot;font-size: 14pt;&quot;&gt;نوع الإقامة في bivouac&lt;/span&gt;&lt;/h3&gt;'),
(711, 32, 'en', 'KINGS ROAD / AMMAN / MADABA / MONT NEBO / DANA', NULL, '&lt;p&gt;Breakfast at the hotel Departure for the visit of &lt;strong&gt;Madaba.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;It is one of the most memorable sites in the Holy Land. Called &quot;the city of mosaic&quot;, Madaba offers many sites to explore.<br>The most remarkable discovery is a map of Jerusalem, and other holy cities, in Byzantine mosaic dating from the sixth century, inside &lt;strong&gt;the church of Saint George.&lt;/strong&gt; Then transfer to &lt;strong&gt;Mount Nebo&lt;/strong&gt; from which Moses saw the Holy Land of Canaan, and presumed burial place of Moses.<br>Finally transfer to &lt;strong&gt;Dana.&lt;/strong&gt; Free walk around the old village of &lt;strong&gt;Dana&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;<br>&lt;strong&gt;Night at the hotel&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Departure at 8 am the driver picks you up at the reception.&lt;/strong&gt;&lt;/p&gt;'),
(712, 32, 'fr', 'La Route de Roi - Amman- Madaba - Monte Nebo - Dana', NULL, '&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;3vu9k&quot; data-offset-key=&quot;7a02u-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;7a02u-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;7a02u-0-0&quot;&gt;Petit déjeuner a l’hôtel Départ pour la visite de &lt;strong&gt;Madaba.&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;7a02u-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;7a02u-0-0&quot;&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;3vu9k&quot; data-offset-key=&quot;27rsn-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;27rsn-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;27rsn-0-0&quot;&gt;C&#039;est l’un des sites les plus mémorables de la Terre Sainte. Appelée &lt;/span&gt;&lt;span data-offset-key=&quot;27rsn-0-1&quot;&gt;« la ville de la mosaïque »&lt;/span&gt;&lt;span data-offset-key=&quot;27rsn-0-2&quot;&gt;, &lt;/span&gt;&lt;span data-offset-key=&quot;27rsn-0-3&quot;&gt;Madaba&lt;/span&gt;&lt;span data-offset-key=&quot;27rsn-0-4&quot;&gt; offre de nombreux sites à explorer.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;3vu9k&quot; data-offset-key=&quot;3d8iq-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;3d8iq-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;3d8iq-0-0&quot;&gt;La plus remarquable découverte est une carte de Jérusalem, et des autres villes saintes, en mosaïque byzantine datant du VIème siècle, à l’intérieur de &lt;strong&gt;l’église Saint Georges.&lt;/strong&gt; Ensuite transfert vers &lt;/span&gt;&lt;span data-offset-key=&quot;3d8iq-0-1&quot;&gt;le &lt;strong&gt;Mont Nébo&lt;/strong&gt;&lt;/span&gt;&lt;span data-offset-key=&quot;3d8iq-0-2&quot;&gt; depuis lequel Moïse aperçut la Terre Sainte de Canaan, et présumé lieu de sépulture de Moïse.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;3vu9k&quot; data-offset-key=&quot;1lcev-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;1lcev-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;1lcev-0-0&quot;&gt;Enfin transfert à &lt;/span&gt;&lt;strong&gt;Dana&lt;/strong&gt;&lt;span data-offset-key=&quot;1lcev-0-2&quot;&gt;. Promenade libre autour du vieux village de &lt;strong&gt;Dana&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;div data-offset-key=&quot;1lcev-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;1lcev-0-2&quot;&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;3vu9k&quot; data-offset-key=&quot;aksds-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;aksds-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;strong&gt;Nuit à l’hôtel&lt;/strong&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;vSx3NFuqXENTAm-7MW8Bh&quot; data-block=&quot;true&quot; data-editor=&quot;3vu9k&quot; data-offset-key=&quot;4lg54-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;4lg54-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;strong&gt;Départ a 8h le chauffeur vous récupère a la réception.&lt;/strong&gt;&lt;/div&gt;\r\n&lt;/div&gt;'),
(713, 32, 'it', 'King Road - Amman-Madaba - Mount Nebo - Dana', NULL, '&lt;p&gt;Colazione in hotel Partenza per la visita di Madaba.&lt;/p&gt;\r\n&lt;p&gt;È uno dei siti più memorabili in Terra Santa. Chiamata &quot;la città del mosaico&quot;, Madaba offre molti siti da esplorare.<br>La scoperta più notevole è una mappa di Gerusalemme e altre città sante, in mosaico bizantino del VI secolo, all&#039;interno della chiesa di San Giorgio. Quindi trasferimento al Monte Nebo da cui Mosè vide la Terra Santa di Canaan e presunto luogo di sepoltura di Mosè.<br>Finalmente trasferimento a Dana. Passeggiata libera attorno al vecchio villaggio di Dana<br>Notte in albergo&lt;/p&gt;\r\n&lt;p&gt;Partenza alle 8 del mattino l&#039;autista vi preleva alla reception.&lt;/p&gt;'),
(714, 32, 'es', 'El camino del rey - Amman - Madaba - Monte Nebo - Dana', NULL, '&lt;p&gt;Petit déjeuner à l&#039;hôtel. Départ pour la visite de Madaba.&lt;/p&gt;\r\n&lt;p&gt;C&#039;est l&#039;un des sites les plus mémorables de Terre Sainte. Appelée &quot;la ville des mosaïques&quot;, Madaba propose de nombreux sites à explorer.<br>La découverte la plus remarquable est une carte de Jérusalem et d&#039;autres villes saintes, en mosaïque byzantine du VIe siècle, à l&#039;intérieur de l&#039;église de San Giorgio. Puis transfert au mont Nebo d&#039;où Moïse a vu la Terre Sainte de Canaan et le lieu de sépulture de Moïse.<br>Enfin transfert à Dana. Promenade libre dans le vieux village de Dana<br>Nuit à l&#039;hôtel&lt;/p&gt;\r\n&lt;p&gt;Départ à 8 heures, le chauffeur vient vous chercher à la réception.&lt;/p&gt;'),
(715, 32, 'Ar', 'الطريق الملوكي - عمان - مادبا - جبل نيبو - -ضانا', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;strong&gt;الإفطار في الفندق,ثم المغادرة لزيارة مادبا.&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;strong&gt;إنها واحدة من أكثر المواقع التي لا تنسى في الأرض المقدسة. يُطلق على مدينة مادبا اسم &quot;مدينة الفسيفساء&quot; ، ويقدم العديد من المواقع لاستكشافها.&lt;/strong&gt;<br>&lt;strong&gt;أهم اكتشاف هو خريطة للقدس ، وغيرها من المدن المقدسة ، في الفسيفساء البيزنطية التي يرجع تاريخها إلى القرن السادس ، داخل كنيسة القديس جورج.&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;strong&gt; ثم نقل إلى جبل نيبو حيث رأى موسى الأرض المقدسة كنعان ، ومكان دفن موسى المفترض.&lt;/strong&gt;<br>&lt;strong&gt;أخيرا نقل إلى دانا. تجول في جميع أنحاء قرية دانا القديمة&lt;/strong&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;strong&gt;ليلة في الفندق&lt;/strong&gt;<br><br>&lt;/h3&gt;'),
(721, 33, 'en', 'ARRIVAL AT AMMAN / THE DEAD SEA', NULL, '&lt;p&gt;Upon your arrival at &lt;strong&gt;Queen Alia International Airport&lt;/strong&gt;, our representative will assist you in your visa.&lt;/p&gt;\r\n&lt;p&gt;Reception of our driver and transfer to your hotel, located on the shores of &lt;strong&gt;the Dead Sea&lt;/strong&gt;, where you can enjoy moments of relaxation.&lt;/p&gt;\r\n&lt;p&gt;Free day of relaxation between swimming pool, bath in the Dead Sea and its mud, rich in mineral salts for a concentration of well-being and relaxation. Possibility of massages, spa treatments, saunas inside the hotel. The Dead Sea, basically a salt water lake, reaches a surface altitude of -430 m. Divided between the Israeli and the Jordanian, it is ideal for those who want to dedicate themselves to the health and well-being of the skin.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Overnight in a luxury hotel.&lt;/strong&gt;&lt;/p&gt;'),
(722, 33, 'fr', 'Arrivée à Amman - Mer Morte', NULL, '&lt;p&gt;À votre arrivée à &lt;strong&gt;l&#039;aéroport international Queen Alia&lt;/strong&gt;, notre représentant vous aidera avec vos documents.&lt;/p&gt;\r\n&lt;p&gt;Accueil de notre chauffeur et transfert à votre hôtel, situé sur les rives de la &lt;strong&gt;mer Morte&lt;/strong&gt;, où vous pourrez profiter de moments de détente.&lt;/p&gt;\r\n&lt;p&gt;Journée libre de détente entre piscine, bain dans la mer Morte et sa boue, riche en sels minéraux pour une concentration de bien-être et de détente.&lt;/p&gt;\r\n&lt;p&gt;Possibilité de massages, traitements de spa, saunas à l&#039;intérieur de l&#039;hôtel.&lt;/p&gt;\r\n&lt;p&gt;La mer Morte, un lac d&#039;eau salée, atteint une altitude de surface de -430 m. Divisé entre l&#039;Israélien et le Jordanien, il est idéal pour ceux qui veulent se consacrer à la santé et au bien-être de la peau.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Nuit dans un hôtel de luxe.&lt;/strong&gt;&lt;/p&gt;');
INSERT INTO `en33_tours_canned_days_contents` (`id`, `day_id`, `lang`, `title`, `place`, `description`) VALUES
(723, 33, 'it', 'Arrivo ad Amman - Mar Morto', NULL, '&lt;p&gt;Al vostro arrivo in aeroporto &lt;strong&gt;Queen Alia International&lt;/strong&gt; un nostro rappresentante incaricato vi assisterà nelle pratiche burocratiche.&lt;/p&gt;\r\n&lt;p&gt;Accoglienza del nostro &lt;strong&gt;l&#039;autista&lt;/strong&gt; e trasferta verso il vostro hotel, posto sulle rive del Mar Morto, nel quale potrete godervi momenti di relax. Giornata libera all&#039;insegna del relax tra piscina, bagno nel Mar Morto ed i suoi fanghi, ricchissimi di sali oligominerali per una concentrazione di benessere e relax. Possibilità di usufruire di massaggi,trattamenti spa, saune all&#039;interno dell` hotel. Il Mar Morto, fondamentalmente un lago di acqua salata, raggiunge un&#039;altitudine di superficie di -430 m. Diviso tra parte israeliana e giordana, è l&#039;ideale per chi desidera dedicarsi alla salute ed al benessere della pelle.&lt;/p&gt;\r\n&lt;p&gt;Pernottamento in un lussuoso Hotel.&lt;/p&gt;'),
(724, 33, 'es', 'Arrivo ad Amman - Mar Morto', NULL, '&lt;p&gt;A su llegada al Aeropuerto Internacional Queen Alia, nuestro representante lo ayudará con el papeleo.&lt;/p&gt;\r\n&lt;p&gt;Recepción de nuestro conductor y traslado a su hotel, ubicado a orillas del Mar Muerto, donde podrá disfrutar de momentos de relajación. Día libre de relajación entre la piscina, el baño en el Mar Muerto y su barro, rico en sales minerales para una concentración de bienestar y relajación. Posibilidad de masajes, tratamientos de spa, saunas dentro del hotel. El Mar Muerto, básicamente un lago de agua salada, alcanza una altitud de superficie de -430 m. Dividido entre el israelí y el jordano, es ideal para aquellos que desean dedicarse a la salud y el bienestar de la piel.&lt;/p&gt;\r\n&lt;p&gt;Pasaremos la noche en un hotel de lujo.&lt;/p&gt;'),
(725, 33, 'Ar', 'الوصول إلى عمان  - البحر الميت', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;لدى وصولك إلى مطار الملكة علياء الدولي ، سيساعدك مندوبنا في مستنداتك.&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;نرحب بك سائقنا ونقله إلى فندقك ، الذي يقع على شواطئ البحر الميت ، حيث يمكنك الاستمتاع بلحظات من الاسترخاء.&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;يوم حر للاسترخاء بين المسبح وحوض الاستحمام في البحر الميت وطينه ، غني بالأملاح المعدنية لتركيز الرفاهية والاسترخاء.&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;إمكانية التدليك وعلاجات السبا وحمامات البخار داخل الفندق.&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;البحر الميت ، بحيرة المياه المالحة ، تصل إلى ارتفاع سطح -430 م. ينقسم بين الإسرائيليين والأردنيين ، فهو مثالي لأولئك الذين يرغبون في تكريس أنفسهم لصحة ورفاه البشرة.&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;ليلة في فندق فخم.&lt;/h3&gt;'),
(726, 34, 'en', 'DEAD SEA / AQABA', NULL, '&lt;p&gt;We leave for &lt;strong&gt;Aqaba&lt;/strong&gt; for a Free Day on &lt;strong&gt;the Red Sea.&lt;/strong&gt;<br>Aqaba is a fusion of history, nature and city life surrounded by picturesque mountains and blue sea.&lt;/p&gt;\r\n&lt;p&gt;Immersing yourself in a permanently summer setting.<br>Aqaba invites you to relax on its beaches, have fun with its water sports and explore the coral reefs of the Red Sea, home to hundreds of divers. You will discover all kinds of corals and sponges, brightly colored fish. Around its silent streets and among its modern facilities, Aqaba holds special monuments with a rich history that begins in the Iron Age, and continues through ancient civilizations, from Edomites, Nabateans, Romans and Byzantines to Muslims.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Overnight at Hotel&lt;/strong&gt;&lt;/p&gt;'),
(727, 34, 'fr', 'La Mer Morte - Aqaba', NULL, '&lt;p&gt;Nous partons pour &lt;strong&gt;Aqaba&lt;/strong&gt; pour une journée libre sur &lt;strong&gt;la mer Rouge.&lt;/strong&gt;<br>Aqaba est une fusion de l&#039;histoire, de la nature et de la vie urbaine entourée de montagnes pittoresques et d&#039;une mer bleue.&lt;/p&gt;\r\n&lt;p&gt;Plongez-vous dans un cadre d&#039;été permanent.<br>&lt;strong&gt;Aqaba&lt;/strong&gt; vous invite à vous détendre sur ses plages, à vous amuser avec ses sports nautiques et à explorer les récifs coralliens de la mer Rouge, qui abritent des centaines de plongeurs. Vous découvrirez toutes sortes de coraux et d&#039;éponges, des poissons aux couleurs vives.&lt;/p&gt;\r\n&lt;p&gt;Autour de ses rues silencieuses et de ses installations modernes, Aqaba abrite des monuments à la riche histoire qui commence à l’âge du fer et se poursuit à travers les civilisations anciennes, des Edomites aux Nabatéens, en passant par les Romains et les Byzantins.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Nuit à l&#039;hôtel&lt;/strong&gt;&lt;/p&gt;'),
(728, 34, 'it', 'Mar Morto - Aqaba', NULL, '&lt;p&gt;Si parte per &lt;strong&gt;Aqaba&lt;/strong&gt; per una &lt;span style=&quot;text-decoration: underline;&quot;&gt;Giornata Liber&lt;/span&gt;a sul &lt;strong&gt;Mar Rosso.&lt;/strong&gt; <br>Aqaba è una fusione di storia, natura e vita cittadina circondata da pittoresche montagne e mare blu.&lt;/p&gt;\r\n&lt;p&gt;Immergendosi in una cornice permanentemente estiva. <br> Aqaba vi invita a rilassarvi sulle sue spiagge, a divertirvi con i suoi sport acquatici e ad esplorare le barriere coralline del Mar Rosso, sede di centinaia di diver. Scoprirete tutti i tipi di coralli e spugne, pesci dai colori brillanti. Intorno alle sue strade silenziose e tra le sue strutture moderne, Aqaba detiene monumenti speciali con una ricca storia che inizia nell&#039;età del ferro, e continua attraverso civiltà antiche, da Edomiti, Nabatei, Romani e Bizantini ai musulmani.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Pernottamento in hotel &lt;/strong&gt;&lt;/p&gt;'),
(729, 34, 'es', 'Mar Morto - Aqaba', NULL, '&lt;p&gt;Salimos para Aqaba para un día libre en el Mar Rojo.<br>Aqaba es una fusión de historia, naturaleza y vida urbana rodeada de pintorescas montañas y mar azul.&lt;/p&gt;\r\n&lt;p&gt;Sumérgete en un entorno de verano permanente.<br>Aqaba lo invita a relajarse en sus playas, divertirse con sus deportes acuáticos y explorar los arrecifes de coral del Mar Rojo, hogar de cientos de buceadores. Usted descubrirá todo tipo de corales y esponjas, peces de colores brillantes. Alrededor de sus calles silenciosas y entre sus modernas instalaciones, Aqaba posee monumentos especiales con una rica historia que comienza en la Edad del Hierro y continúa a través de civilizaciones antiguas, desde edomitas, nabateos, romanos y bizantinos hasta musulmanes.&lt;/p&gt;\r\n&lt;p&gt;Pernocte en el hotel.&lt;/p&gt;'),
(730, 34, 'Ar', 'البحر الميت- العقبة', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 14pt;&quot;&gt;نترك العقبة لذهاب إلى يوم حر على البحر الأحمر.&lt;/span&gt;<br>&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 14pt;&quot;&gt;العقبة هي مزيج من التاريخ والطبيعة والحياة الحضرية تحيط بها الجبال الخلابة والبحر الأزرق.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 14pt;&quot;&gt;اغمر نفسك في بيئة صيفية دائمة.&lt;/span&gt;<br>&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 14pt;&quot;&gt;تدعوكم العقبة للاسترخاء على شواطئها ، والاستمتاع بالرياضات المائية واستكشاف الشعب المرجانية في البحر الأحمر ، التي تضم مئات الغواصين. سوف تكتشف جميع أنواع الشعاب والإسفنج والأسماك بألوان زاهية.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 14pt;&quot;&gt;حول شوارعها الصامتة والمرافق الحديثة ، العقبة هي موطن للآثار ذات التاريخ الغني الذي يبدأ في العصر الحديدي ويستمر من خلال الحضارات القديمة ، من الأدوميين إلى الأنباط ، من خلال الرومان والبيزنطيين.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 14pt;&quot;&gt;ليلة في الفندق&lt;/span&gt;&lt;/h3&gt;'),
(741, 35, 'en', 'AQABA / WADI RUM', NULL, '&lt;p&gt;Breakfast at the hotel.&lt;/p&gt;\r\n&lt;p&gt;We leave for &lt;strong&gt;Wadi Rum.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Wadi Rum puts life in perspective. &quot;The glory of Rum will not allow a man to get lost in feverish regrets,&quot; said TE Lawrence (of Arabia), whose descriptions have made the place immortal for many of us. &quot;Vast, resonant and divine&quot;. With these words T.E. Lawrence describes Wadi Rum, the largest and most magnificent desert in Jordan, with its fabulous, timeless and immaculate landscapes. A labyrinth of monolithic rock formations rises in a desert territory at an altitude of 1,750 meters, creating a natural challenge for the most experienced mountaineers. Also known as the &quot;Valley of the Moon&quot;, Prince Faisal Bin Hussein and T.E. Lawrence established his headquarters during the Arab uprising against the Ottomans.&lt;/p&gt;\r\n&lt;p&gt;For this day, we propose to take a 4x4 jeep tour through the dunes and arches of the desert.&lt;/p&gt;\r\n&lt;p&gt;We will visit &lt;strong&gt;Sand Dunes - Al Ameleh Listings - Lawrence Canyon - Siq Um Al Tawaqi - Lawrence House - Canyon Barrah.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;After the picnic, possibility of hiking in the desert by following the directions of our choice or enjoy a&lt;strong&gt; Bedouin guide named by us.&lt;/strong&gt;&lt;/p&gt;'),
(742, 35, 'fr', 'AQABA - WADI RUM', NULL, '&lt;p&gt;Petit déjeuner à l&#039;hôtel.&lt;/p&gt;\r\n&lt;p&gt;Nous partons pour &lt;strong&gt;le Wadi Rum.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Wadi Rum met la vie en perspective. &quot;La gloire de Rum ne permettra pas à un homme de se perdre dans des regrets fébriles&quot;, a déclaré TE Lawrence (d&#039;Arabie), dont les descriptions ont rendu l&#039;endroit immortel pour beaucoup d&#039;entre nous. &quot;Vaste, résonnant et divin&quot;. Avec ces mots T.E. Lawrence décrit Wadi Rum, le désert le plus vaste et le plus magnifique de Jordanie, avec ses paysages fabuleux, intemporels et immaculés. Un labyrinthe de formations rocheuses monolithiques s&#039;élève dans un territoire désertique à une altitude de 1 750 mètres, créant un défi naturel pour les alpinistes les plus expérimentés. Aussi connu sous le nom de &quot;Vallée de la Lune&quot;, le prince Faisal Bin Hussein et T.E. Lawrence établit son quartier général pendant la révolte arabe contre les Ottomans.&lt;/p&gt;\r\n&lt;p&gt;Pour cette journée, nous proposons de faire un tour en 4x4 en jeep à travers les dunes et les arches du désert.&lt;/p&gt;\r\n&lt;p&gt;Nous visiterons Sand Dunes - &lt;strong&gt;Inscriptions Al Ameleh&lt;/strong&gt; - &lt;strong&gt;Canyon Lawrence&lt;/strong&gt; - &lt;strong&gt;Siq Um Al Tawaqi&lt;/strong&gt; - &lt;strong&gt;Maison Lawrence&lt;/strong&gt; -&lt;strong&gt; Canyon Barrah.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Après le pique-nique, possibilité de faire une randonnée dans le désert en suivant les indications de notre choix ou de profiter d&#039;un guide bédouin nommé par nous.&lt;/p&gt;\r\n&lt;p&gt;Dîner et nuit dans un magnifique camp bédouin.&lt;/p&gt;'),
(743, 35, 'it', 'AQABA - WADI RUM', NULL, '&lt;p&gt;Prima colazione in Albergo.&lt;/p&gt;\r\n&lt;p&gt;Si parte per&lt;strong&gt; Wadi Rum&lt;/strong&gt;.&lt;/p&gt;\r\n&lt;p&gt;Wadi Rum mette la vita in prospettiva. &quot;La gloria di Rum non permetterebbe a un uomo di sprecare se stesso in rimpianti febbrili&quot;, ha dichiarato TE Lawrence (di Arabia), le cui descrizioni hanno reso immortale il posto per così tanti di noi. “Vasto, echeggiante e divino”. Con queste parole T.E. Lawrence descriveva il Wadi Rum, il più esteso e stupefacente deserto della Giordania, con i suoi paesaggi favolosi, senza tempo e incontaminati. Un dedalo di formazioni rocciose monolitiche si innalza in un territorio desertico fino ad altezze di 1750 metri, creando una sfida naturale anche per gli scalatori più esperti. Noto anche come “Valle della Luna”, in questo luogo il Principe Faisal Bin Hussein e T.E. Lawrence insediarono il loro quartier generale durante la Rivolta Araba contro gli Ottomani. <br> <br>per questa giornata vi proponiamo infatti di fare un &lt;strong&gt;jeep tour 4x4&lt;/strong&gt; attraverso le dune e gli archi del deserto. Visiteremo Sand Dunes - &lt;span style=&quot;text-decoration: underline;&quot;&gt;Al Ameleh Inscriptions - Lawrence&#039;s Canyon - Siq Um Al Tawaqi - Lawrence&#039;s House - Barrah Canyon.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;Dopo il &lt;strong&gt;pranzo al sacco&lt;/strong&gt; possibilità di trekking nel deserto attraverso le direzioni da noi consigliate od in alternativa usufruire di una guida beduina da noi incaricata.&lt;/p&gt;\r\n&lt;p&gt;Cena e pernottamento in un magnifico campeggio beduino.<br><br>&lt;/p&gt;'),
(744, 35, 'es', 'AQABA - WADI RUM', NULL, '&lt;p&gt;Desayuno en el hotel.&lt;/p&gt;\r\n&lt;p&gt;Salimos para Wadi Rum.&lt;/p&gt;\r\n&lt;p&gt;Wadi Rum pone la vida en perspectiva. &quot;La gloria de Ron no permitiría que un hombre se desperdicie en lamentos febriles&quot;, dijo TE Lawrence (de Arabia), cuyas descripciones han hecho que el lugar sea inmortal para muchos de nosotros. &quot;Vasta, resonante y divina&quot;. Con estas palabras T.E. Lawrence describió Wadi Rum, el desierto más extenso e impresionante de Jordania, con sus paisajes fabulosos, atemporales y prístinos. Un laberinto de formaciones rocosas monolíticas se eleva en un territorio desértico hasta alturas de 1750 metros, creando un desafío natural incluso para los escaladores más experimentados. También conocido como &quot;Valle de la Luna&quot;, en este lugar el Príncipe Faisal Bin Hussein y T.E. Lawrence estableció su cuartel general durante la revuelta árabe contra los otomanos.&lt;/p&gt;\r\n&lt;p&gt;Para este día nos proponemos realizar un recorrido en jeep 4x4 por las dunas y arcos del desierto. Visitaremos las dunas de arena - Al Ameleh Inscripciones - Cañón de Lawrence - Siq Um Al Tawaqi - Casa de Lawrence - Cañón de Barrah.&lt;/p&gt;\r\n&lt;p&gt;Después del almuerzo para llevar, puede hacer trekking en el desierto siguiendo las instrucciones recomendadas por nosotros o, alternativamente, aprovechar un guía beduino designado por nosotros.&lt;/p&gt;\r\n&lt;p&gt;Cena y alojamiento en un magnífico campamento beduino.&lt;/p&gt;'),
(745, 35, 'Ar', 'العقبة - وادي رم', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 14pt;&quot;&gt;الإفطار في الفندق.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 14pt;&quot;&gt;نترك لوادي رم.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 14pt;&quot;&gt;يضع وادي رم الحياة في المنظور.  لورنس العرب الذي جعلت أوصافه المكان خالدا بالنسبة للكثيرين منا: &quot;إن مجد رم لن يسمح للرجل بالضياع في أسفه المحموم&quot;. &quot;واسعة ، رنانة وإلهية&quot;. بهذه الكلمات ، تصف تي. لورانس وادي رم ، أكبر وأروع صحراء في الأردن ، بمناظرها الخرافية والذهبية الخالدة. ترتفع متاهة من التكوينات الصخرية المتجانسة في منطقة صحراوية على ارتفاع 1750 متراً ، الأمر الذي يخلق تحدياً طبيعياً لأكثر متسلقي الجبال خبرة. المعروف أيضا باسم &quot;وادي القمر&quot; ، أنشأ الأمير فيصل بن حسين وتورانس لورانس مقره خلال الانتفاضة العربية ضد العثمانيين.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 14pt;&quot;&gt;لهذا اليوم ، نقترح أن تأخذ جولة جيب من خلال الكثبان الرملية والأقواس في الصحراء.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 14pt;&quot;&gt;سنقوم بزيارة الكثبان الرملية - قوائم العميلة - لورانس كانيون - سيك أم الطواقي - منزل لورانس - كانيون بارا.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 14pt;&quot;&gt;بعد نزهة ، إمكانية المشي في الصحراء باتباع التوجيهات من اختيارنا أو التمتع بدليل بدوي يدعى لنا.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 14pt;&quot;&gt;العشاء والمبيت في مخيم بدوي جميل.&lt;/span&gt;&lt;/h3&gt;'),
(756, 36, 'en', 'WADI RUM / PETRA', NULL, '&lt;p&gt;8.00 am Transfer to Petra.<br>At 10:00 am meeting with the Official Guide to the Visitor Center in Petra.&lt;/p&gt;\r\n&lt;p&gt;We head towards the archaeological site where together with your official guide we will take you to the Nabataean site; walk through the Siq, a famous canyon that leads directly to Khazné, one of the jewels of the Nabataean city, &lt;strong&gt;Theaters and the Royal Tombs.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;We stop for a lunch at the &lt;strong&gt;Al-Basin restaurant,&lt;/strong&gt; located inside the Nabatean city.&lt;/p&gt;\r\n&lt;p&gt;After lunch, we continue autonomously our journey towards the monastry.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Dinner and overnight in hotel in Petra.&lt;/strong&gt;&lt;/p&gt;'),
(757, 36, 'fr', 'WADI RUM - PETRA', NULL, '&lt;p&gt;8h00 Transfert à&lt;strong&gt; Petra.&lt;/strong&gt;<br>À 10 heures, rencontre avec le guide officiel du centre d&#039;accueil à Petra.&lt;/p&gt;\r\n&lt;p&gt;Nous nous dirigeons vers le site archéologique où, avec votre guide officiel, nous vous conduirons au site nabatéen; parcourez &lt;strong&gt;le Siq,&lt;/strong&gt; célèbre canyon qui mène directement à &lt;strong&gt;Khazné,&lt;/strong&gt; l&#039;un des joyaux de la ville nabatéenne, en passant par  les théâtres et les tombeaux royaux. &lt;/p&gt;\r\n&lt;p&gt;Nous nous arrêtons pour un déjeuner au restaurant Al-Basin, situé dans la&lt;strong&gt; ville nabatéenne.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Après le déjeuner, nous continuons de manière autonome notre voyage.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Dîner et nuit à l&#039;hôtel à Petra.&lt;/strong&gt;&lt;/p&gt;'),
(758, 36, 'it', 'WADI RUM - PETRA', NULL, '&lt;p&gt;Ore 8:00 Trasferimento &lt;strong&gt;Verso Petra.&lt;/strong&gt;<br>Alle ore 10:00 &lt;strong&gt;incontro con la Guida Ufficiale&lt;/strong&gt; al &lt;strong&gt;Visitor Center&lt;/strong&gt; di Petra.&lt;/p&gt;\r\n&lt;p&gt;Ci dirigiamo verso il sito archeologico dove insieme alla tua &lt;strong&gt;guida ufficiale&lt;/strong&gt; ti accompagneremo verso il sito nabateo; camminata attraverso il &lt;strong&gt;Siq&lt;/strong&gt;, famoso &lt;span style=&quot;text-decoration: underline;&quot;&gt;canyon&lt;/span&gt; che conduce direttamente a&lt;strong&gt; Khazné&lt;/strong&gt;, uno dei gioielli della citta nabatea, procedendo per La &lt;span style=&quot;text-decoration: underline;&quot;&gt;Strada delle Facciate&lt;/span&gt;, i T&lt;strong&gt;eatri, Le Tombe Reali, Il Cardo, Il Castello della Figlia del Faraone&lt;/strong&gt;.&lt;/p&gt;\r\n&lt;p&gt;Ci fermiamo per un pranzo al ristorante &lt;strong&gt;Al- Basin,&lt;/strong&gt; situato all&#039;interno della citta nabatea.&lt;/p&gt;\r\n&lt;p&gt;Dopo il pranzo, Continuiamo in autonomia il nostro cammino verso Il &lt;strong&gt;Monastero&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Cena e Pernottamento in hotel a Petra.&lt;/p&gt;'),
(759, 36, 'es', 'WADI RUM - PETRA', NULL, '&lt;p&gt;8.00 am Traslado a Petra.<br>A las 10:00 am encuentro con la Guía Oficial del Centro de Visitantes en Petra.&lt;/p&gt;\r\n&lt;p&gt;Nos dirigimos hacia el sitio arqueológico donde, junto con su guía oficial, lo llevaremos al sitio nabateo; Camine por el Siq, un famoso cañón que conduce directamente a Khazné, una de las joyas de la ciudad nabatea, y continúa por la Strada delle Facte, los teatros, las tumbas reales, Il Cardo, el Castello della Figlia de Faraone.&lt;/p&gt;\r\n&lt;p&gt;Paramos a almorzar en el restaurante Al-Basin, ubicado dentro de la ciudad nabatea.&lt;/p&gt;\r\n&lt;p&gt;Después del almuerzo, continuamos de forma autónoma nuestro viaje hacia Il Monastero.&lt;/p&gt;\r\n&lt;p&gt;Cena y alojamiento en hotel en Petra.&lt;/p&gt;'),
(760, 36, 'Ar', 'WADI RUM - PETRA', NULL, ''),
(776, 37, 'en', 'PETRA / WADI SABRA', NULL, '&lt;p&gt;&lt;strong&gt;Meeting with your Bedouin guide at 9:00&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;This day is dedicated to the city of Nabataeans.&lt;/p&gt;\r\n&lt;p&gt;The city of roses was an important place for commercial myrrh, incense, cinnamon, precious stones, the best fabrics and now houses more than 700 rock-cut monuments. After exploring this world, we leave for Wadi Sabra.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Trekking of about 7 hours.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Night in a camp.&lt;/strong&gt;&lt;/p&gt;'),
(777, 37, 'fr', 'PETRA - WADI SABRA', NULL, '&lt;p&gt;&lt;strong&gt;Rencontre avec votre guide bédouin à 9h00&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Cette journée est dédiée à la ville des Nabatéens.&lt;/p&gt;\r\n&lt;p&gt;La ville des roses était un lieu important pour la myrrhe commerciale, l&#039;encens, la cannelle, les pierres précieuses, les meilleurs tissus et abrite aujourd&#039;hui plus de 700 monuments taillés dans le roc. Après avoir exploré ce monde, nous partons pour Wadi Sabra.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Trekking d&#039;environ 7 heures.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Nuit dans un campement. &lt;/strong&gt;&lt;/p&gt;'),
(778, 37, 'it', 'PETRA - WADI SABRA Trekking', NULL, '&lt;p&gt;Incontro con la vostra &lt;strong&gt;guida beduina&lt;/strong&gt; alle ore 9:00.&lt;/p&gt;\r\n&lt;p&gt;Questa giornata è dedicata alla città dei Nabatea. La città delle rosa era un posto importante per commerciale mirra, incenso, cannella, pietre preziose, i migliori tessuti e ora ospita oltre 700 monumenti, scolpiti nella roccia. Dopo aver esplorato questo mondo, partiamo per &lt;strong&gt;Wadi Sabra&lt;/strong&gt;.&lt;/p&gt;\r\n&lt;p&gt;Trekking di circa 7 ore.&lt;/p&gt;\r\n&lt;p&gt;Pernottamento in campo tendato.&lt;/p&gt;'),
(779, 37, 'es', 'PETRA - WADI SABRA', NULL, '&lt;p&gt;Reunión con su guía beduino a las 9:00 am&lt;/p&gt;\r\n&lt;p&gt;Este día está dedicado a la ciudad de los nabateos. La ciudad de las rosas era un lugar importante para mirra comercial, incienso, canela, piedras preciosas, las mejores telas y ahora alberga más de 700 monumentos, tallados en la roca. Después de explorar este mundo, partimos hacia Wadi Sabra.&lt;/p&gt;\r\n&lt;p&gt;Trekking de unas 7 horas.&lt;/p&gt;\r\n&lt;p&gt;Pernocte en campamento de tiendas de campaña.&lt;/p&gt;'),
(780, 37, 'Ar', 'PETRA - WADI SABRA', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;لقاء مع دليلك البدوي في الساعة 9:00&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;هذا اليوم مخصص لمدينة الأنباط.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;كانت مدينة الورود مكاناً مهماً للمر التجارية ، والبخور ، والقرفة ، والأحجار الكريمة ، وأفضل الأقمشة ، وتضم الآن أكثر من 700 قطعة أثرية من الصخور. بعد استكشاف هذا العالم ، نغادر إلى وادي صبرا.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;المدة الزمنية للمشي  حوالي 7 ساعات.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;ليلة في مخيم.&lt;/span&gt;&lt;/h3&gt;'),
(786, 38, 'en', 'WADI AL SAIF / GHARANDAL / GSAIB SOURCE', NULL, '&lt;p&gt;This day is dedicated to the city of the Nabataeans.&lt;/p&gt;\r\n&lt;p&gt;The city of roses was an important place to trade myrrh, incense, cinnamon, precious stones, the best fabrics and now houses over 700 monuments, carved into the rock.&lt;/p&gt;\r\n&lt;p&gt;After exploring this world, we leave for &lt;strong&gt;Wadi Sabra. &lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Walking for about 7 hours. Overnight in a tented camp&lt;/strong&gt;&lt;/p&gt;'),
(787, 38, 'fr', 'Wadi Al Saif – Gharandal – Gsaib sources', NULL, '&lt;p&gt;Cette journée est dédiée à&lt;strong&gt; la ville des Nabatéens.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;La ville des roses était un lieu important pour le commerce de la myrrhe, de l&#039;encens, de la cannelle, des pierres précieuses, des meilleurs tissus et abrite aujourd&#039;hui plus de 700 monuments taillés dans le roc.&lt;/p&gt;\r\n&lt;p&gt;Après avoir exploré ce monde, nous partons pour &lt;strong&gt;Wadi Sabra.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Marcher pendant environ 7 heures. &lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Nuit dans un camp de tentes&lt;/strong&gt;&lt;/p&gt;'),
(788, 38, 'it', 'Wadi Al Saif – Gharandal – Gsaib sources', NULL, '&lt;p&gt;Questa giornata è dedicata alla città dei Nabatei.&lt;/p&gt;\r\n&lt;p&gt;La città delle rose era un posto importante per commerciare mirra, incenso, cannella, pietre preziose, i migliori tessuti e ora ospita oltre 700 monumenti, scolpiti nella roccia.&lt;/p&gt;\r\n&lt;p&gt;Dopo aver esplorato questo mondo, partiamo per Wadi Sabra. Camminando per circa 7 ore. Pernottamento in un campo tendato&lt;/p&gt;'),
(789, 38, 'es', 'Wadi Al Saif – Gharandal – Gsaib sources', NULL, '&lt;p&gt;Este día está dedicado a la ciudad de los nabateos.&lt;/p&gt;\r\n&lt;p&gt;La ciudad de las rosas era un lugar importante para el comercio de mirra, incienso, canela, piedras preciosas, las mejores telas y ahora alberga más de 700 monumentos tallados en la roca.&lt;/p&gt;\r\n&lt;p&gt;Después de explorar este mundo, partimos hacia Wadi Sabra. Caminando por unas 7 horas. Pernocte en un campamento de tiendas de campaña.&lt;/p&gt;'),
(790, 38, 'Ar', 'وادي سيف – غرندل– منابع غصيب', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;هذا اليوم مخصص لمدينة الأنباط.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;كانت مدينة الورود مكانًا مهمًا لتجارة المر ، والبخور ، والقرفة ، والأحجار الكريمة ، وأفضل الأقمشة ، واليوم تضم أكثر من 700 نصب تذكاري محفور في الصخر.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;بعد استكشاف هذا العالم ، نغادر إلى وادي صبرا.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;المشي لمدة 7 ساعات.&lt;/span&gt;&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;ليلة في مخيم خيمة&lt;/span&gt;&lt;/h3&gt;'),
(801, 39, 'en', 'GSAIB SOURCES  /  WADI MLAUNE /  REGANA DUNES', NULL, '&lt;p&gt;Today we are walking in the direction of the dunes Regana through the valley of 1001 colors, Wadi Mlauan.&lt;/p&gt;\r\n&lt;p&gt;Wadi Mlauan is a world apart with a unique geology in which colors change in many varieties depending on the nature of the terrain.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Trekking of about 6.5 hours (17 km).&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Overnight in tented camp.&lt;/strong&gt;&lt;/p&gt;'),
(802, 39, 'fr', 'Gsaib sourses – Wadi Mlauan – Regana Dunes', NULL, '&lt;p&gt;Aujourd&#039;hui, nous marchons en direction &lt;strong&gt;des dunes de Regana&lt;/strong&gt; à travers la vallée aux 1001 couleurs, &lt;strong&gt;le Wadi Mlauan.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Wadi Mlauan est un monde à part avec une géologie unique dans laquelle les couleurs changent dans de nombreuses variétés en fonction de la nature du terrain.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Trekking d&#039;environ 6,5 heures (17 km).&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Nuit dans un camp de tentes.&lt;/strong&gt;&lt;/p&gt;'),
(803, 39, 'it', 'Gsaib sourses – Wadi Mlauan – Regana Dunes', NULL, '&lt;p&gt;Oggi stiamo camminando nella direzione delle dune Regana attraverso la valle dei 1001 colori, &lt;strong&gt;Wadi Mlauan&lt;/strong&gt;.&lt;/p&gt;\r\n&lt;p&gt;Wadi Mlauan è un mondo a parte con una geologia unica in cui i colori cambiano in molte varietà a seconda della natura del terreno.&lt;/p&gt;\r\n&lt;p&gt;Trekking di circa &lt;strong&gt;6,5 ore (17 km)&lt;/strong&gt;.&lt;/p&gt;\r\n&lt;p&gt;Pernottamento in campo tendato.&lt;/p&gt;'),
(804, 39, 'es', 'Gsaib sourses – Wadi Mlauan – Regana Dunes', NULL, '&lt;p&gt;Hoy caminamos en dirección a las dunas de Regana a través del valle de 1001 colores, Wadi Mlauan.&lt;/p&gt;\r\n&lt;p&gt;Wadi Mlauan es un mundo aparte con una geología única en la que los colores cambian en muchas variedades según la naturaleza del terreno.&lt;/p&gt;\r\n&lt;p&gt;Senderismo de unas 6,5 horas (17 km).&lt;/p&gt;\r\n&lt;p&gt;Pernocte en campamento de tiendas de campaña.&lt;/p&gt;'),
(805, 39, 'Ar', 'منابع غصيب– وادي ملون – كتبان ريجانا', NULL, '&lt;h3 style=&quot;text-align: right;&quot;&gt;اليوم ، نسير نحو كثبان ريجانا الرملية عبر وادي الألوان 1001 لون تقريبا، وادي ملوان.&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;وادي ملوان هو عالم منفصل مع جيولوجية فريدة تتغير فيها الألوان في العديد من الأصناف اعتمادًا على طبيعة التضاريس.&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;الرحلات حوالي 6.5 ساعة (17 كم).&lt;/h3&gt;\r\n&lt;h3 style=&quot;text-align: right;&quot;&gt;ليلة في مخيم خيمة.&lt;/h3&gt;'),
(1711, 40, 'en', 'FIRST DAY AT WADI RUM', 'Wadi Rum', ''),
(1712, 40, 'fr', 'Premier Jour à Wadi Rum', '', '<p><span data-offset-key=\"dsfus-0-0\">Après le petit déjeuner, vous repartirez en direction du Sud vers le<strong> Wadi Rum</strong>, appelé \"Vallée de la Lune\". Rendez-vous pour un </span><strong>déjeuner traditionnel</strong><span data-offset-key=\"dsfus-0-2\"> sous une tente bédouin. Puis, <strong>départ en 4x4</strong> pour découvrir le </span><span data-offset-key=\"dsfus-0-3\">paysage désertique le plus vaste et le plus majestueux de la Jordanie !</span><span data-offset-key=\"dsfus-0-4\"> \"Vaste, retentissant, divin\" sont les mots utilisés par Lawrence d\'Arabie pour décrire les lieux.</span></p>\r\n<p><span data-offset-key=\"dsfus-0-4\">Collines de grès rouge, plaine sablonneuse, étranges formations rocheuses aux teintes ocres, et coucher de soleil inoubliable. </span></p>\r\n<p><span data-offset-key=\"dsfus-0-4\">Vous passerez la nuit dans un </span><span data-offset-key=\"dsfus-0-5\">camp bédouin</span><span data-offset-key=\"dsfus-0-6\"> sous une tente traditionnelle. </span></p>\r\n<p><strong>Au programme : soirée bédouine et dîner typique. </strong></p>'),
(1713, 40, 'it', 'PRIMA GIORNATA A WADI RUM', '', ''),
(1714, 40, 'es', 'FIRST DAY AT WADI RUM', '', ''),
(1715, 40, 'Ar', 'FIRST DAY AT WADI RUM', '', ''),
(1716, 41, 'en', 'SECOND DAY AT WADI RUM', NULL, '&lt;p&gt;For these two days of walking in the desert, the sublime will continue to operate to drive you north towards the Bedouin camp of Djebel Khazali and through two beautiful massifs:&lt;strong&gt; Um Muqur and Um Sabatah.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;A beautiful night under a Bedouin tent in perspective and what&#039;s more beautiful than sleeping in this world of multi-colored sands and rocky peaks chocolate or ocher.&lt;/p&gt;\r\n&lt;p&gt;The beauty of this desert that had so fascinated &lt;strong&gt;Lawrence of Arabia&lt;/strong&gt; has no equal.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Night under tent.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Type of camping accommodation&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Hiking: 5 hours&lt;/strong&gt;&lt;/p&gt;'),
(1717, 41, 'fr', 'Deuxième journée à Wadi Rum', NULL, '&lt;p&gt;&lt;span&gt;Pour ces deux journée de marche dans le désert, le sublime va continuer à opérer pour vous conduire vers le nord en direction du &lt;strong&gt;campement Bédouin&lt;/strong&gt; du &lt;strong&gt;Djebel Khazali&lt;/strong&gt; et en passant par deux magnifiques massifs : &lt;strong&gt;Um Muqur&lt;/strong&gt; et &lt;strong&gt;Um Sabatah&lt;/strong&gt;.&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;Une belle nuit sous une tente bédouine en perspective et quoi de plus beau que de dormir dans ce monde de sables multi-couleurs et de pitons rocheux couleur chocolat ou ocres. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;La beauté de ce désert qui avait tant fasciné Lawrence d&#039;Arabie n&#039;a pas d&#039;égal. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Nuit sous tente. &lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Type d´hébergement en camping &lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Randonnée : 5 heures &lt;/strong&gt;&lt;/p&gt;'),
(1718, 41, 'it', 'SECOND DAY AT WADI RUM', NULL, ''),
(1719, 41, 'es', 'SECOND DAY AT WADI RUM', NULL, ''),
(1720, 41, 'Ar', 'SECOND DAY AT WADI RUM', NULL, ''),
(1721, 42, 'en', 'END OF YOUR PROGRAM', NULL, ''),
(1722, 42, 'fr', 'Fin de votre séjour', NULL, '&lt;p&gt;&lt;span&gt;Après le petit déjeuner,selons vos horaires de vol &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;transfert à l&#039;aéroport pour le départ. &lt;/strong&gt;&lt;/p&gt;'),
(1723, 42, 'it', 'END OF YOUR PROGRAM', NULL, ''),
(1724, 42, 'es', 'END OF YOUR PROGRAM', NULL, ''),
(1725, 42, 'Ar', 'END OF YOUR PROGRAM', NULL, ''),
(1906, 43, 'en', 'ARRIVAL TO MUSCAT', NULL, ''),
(1907, 43, 'fr', 'Arrivée à Mascate', NULL, '&lt;p&gt;Assistance à l&#039;aéroport de Mascate et transfert à l&#039;hôtel, temps libre. 15h30, départ avec notre guide pour la visite de la ville: le musée &lt;strong&gt;Bait al Zubair,&lt;/strong&gt; Al Alam Palace, forts portugais Mirani &amp;amp; Jalali. et &lt;strong&gt;le souk de Muttrah,&lt;/strong&gt; et un peu temps pour le shopping. &lt;strong&gt;Dîner&lt;/strong&gt; dans un restaurant local. &lt;strong&gt;Nuit à l&#039;hôtel.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;NB :&lt;/strong&gt;&lt;span&gt; &lt;/span&gt;Oman Air et Turkish Airlines sont deux compagnies aériennes qui permettent de mixer et combiner les deux pays au départ de Paris.&lt;/p&gt;'),
(1908, 43, 'it', 'Arrival To Mascat', NULL, ''),
(1909, 43, 'es', 'Arrival To Mascat', NULL, ''),
(1910, 43, 'Ar', 'Arrival To Mascat', NULL, ''),
(1916, 44, 'en', 'MUSCAT / NAKHAL / AL HAMRA', NULL, ''),
(1917, 44, 'fr', 'Mascate / Nakhal / Al Hamra', NULL, '&lt;p&gt;08h00. Départ. Visite de la &lt;strong&gt;Grande Mosquée du Sultan Qaboos.&lt;/strong&gt; Après la visite, nous commençons un voyage passionnant en  &lt;strong&gt;4X4&lt;/strong&gt; à travers les magnifiques &lt;strong&gt;montagnes du Hajjar.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Nakhl: visite du fort. Après le déjeuner, nous roulons à travers le &lt;strong&gt;Wadi Bani Awf&lt;/strong&gt; traversant les montagnes du Hajjar. Nous descendons vers&lt;strong&gt; Al Hamra,&lt;/strong&gt; une ville vieille de 400 ans dans la région Ad &lt;strong&gt;Dakhiliyah. &lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;Certaines des plus anciennes maisons conservées à Oman peuvent être trouvés dans Al Hamra, une ville construite sur une dalle de roche inclinée. Beaucoup de maisons ont deux étages, avec des plafonds en poutres de palmiers et de frondes surmontées de boue et de paille. &lt;strong&gt;Dîner et nuit à l&#039;hôte&lt;/strong&gt;l.&lt;/p&gt;'),
(1918, 44, 'it', 'MUSCAT / NAKHAL / AL HAMRA', NULL, ''),
(1919, 44, 'es', 'MUSCAT / NAKHAL / AL HAMRA', NULL, ''),
(1920, 44, 'Ar', 'MUSCAT / NAKHAL / AL HAMRA', NULL, ''),
(1921, 45, 'en', 'NIZWA / WAHIBA SANDS', NULL, ''),
(1922, 45, 'fr', 'Nizwa / Wahiba Sands', NULL, '&lt;p&gt;&lt;span&gt;&lt;strong&gt;08h00&lt;/strong&gt;. Après le petit déjeuner, départ de l&#039;hôtel pour &lt;strong&gt;Nizwa&lt;/strong&gt;, visite du &lt;strong&gt;Fort&lt;/strong&gt;, du S&lt;strong&gt;ouk traditionne&lt;/strong&gt;l et des &lt;strong&gt;Falaj de Daris&lt;/strong&gt; (site du patrimoine du monde). &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;Après la visite, nous continuons vers &lt;strong&gt;les grotes d&#039;Al Hoota,&lt;/strong&gt; appareils photo et caméras vidéo non autorisés à l&#039;intérieur de la grotte. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;&lt;strong&gt;Déjeuner dans un restaurant local&lt;/strong&gt;. Après le déjeuner, nous continuons vers &lt;strong&gt;le désert des Wahiba.&lt;/strong&gt; Arrivée au camp où vous pouvez profiter des dunes et du coucher de soleil. &lt;strong&gt;Dîner et nuit au camp.&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;'),
(1923, 45, 'it', 'Nizwa / Wahiba Sands', NULL, ''),
(1924, 45, 'es', 'Nizwa / Wahiba Sands', NULL, ''),
(1925, 45, 'Ar', 'Nizwa / Wahiba Sands', NULL, ''),
(1926, 46, 'en', 'WAHIBA SANDS / WADI BANI KHALID / SUR', NULL, ''),
(1927, 46, 'fr', 'Wahiba Sands / Wadi Bani Khalid / Sur', NULL, '&lt;p&gt;&lt;span&gt;&lt;strong&gt;08h30&lt;/strong&gt;. Après le petit déjeuner, nous quittons le camp pour une expérience incroyable, conduite en profondeur dans le &lt;strong&gt;désert de Wahiba.&lt;/strong&gt; Montée des plus hautes dunes, avec nos chauffeurs expérimentés. Après cela, nous quittons le désert pour aller à &lt;strong&gt;Wadi Bani Khalid. &lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;Ici vous pouvez nager dans les eaux cristallines ou partir dans une courte randonnée jusqu&#039;à la grotte. (Chaussures techniques nécessaires). &lt;strong&gt;Déjeuner au petit restaurant,&lt;/strong&gt; avec une vue magnifique sur le Wadi. Après le déjeuner, nous continuons notre voyage vers Sur. Visite de l&#039;atelier de dhows traditionnels et de l&#039;ancien &lt;strong&gt;quartier d&#039;Al Ayjah.&lt;/strong&gt; &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Dîner et nuit à l&#039;hôtel.&lt;/strong&gt;&lt;/p&gt;'),
(1928, 46, 'it', 'Wahiba Sands / Wadi Bani Khalid / Sur', NULL, ''),
(1929, 46, 'es', 'Wahiba Sands / Wadi Bani Khalid / Sur', NULL, ''),
(1930, 46, 'Ar', 'Wahiba Sands / Wadi Bani Khalid / Sur', NULL, ''),
(1931, 47, 'en', 'SUR / WADI SHAB / WADI TIWI / MASCATE', NULL, ''),
(1932, 47, 'fr', 'Sur / Wadi Shab / Wadi Tiwi / Mascate', NULL, '&lt;p&gt;&lt;span&gt;Nous remontons vers &lt;strong&gt;le Wadi Shab.&lt;/strong&gt; Déjeuner à Wadi Shab Resort, où vous pourrez également nager dans la magnifique eau bleue de &lt;strong&gt;la mer d&#039;Arabie&lt;/strong&gt;, photo-stop à l&#039;ancienne &lt;strong&gt;ville de Qalhat&lt;/strong&gt; (patrimoine mondial de l&#039;UNESCO). Sur le chemin du retour, nous nous arrêterons au &lt;strong&gt;gouffre de Bimah.&lt;/strong&gt; Il est situé dans &lt;strong&gt;le Hawiyat Najm parc&lt;/strong&gt; clôturé et équipé de toilettes. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;&lt;strong&gt;Arrivée à l&#039;hôtel et dîner dans un restaurant local. &lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;'),
(1933, 47, 'it', 'Sur / Wadi Shab / Wadi Tiwi / Mascate', NULL, ''),
(1934, 47, 'es', 'Sur / Wadi Shab / Wadi Tiwi / Mascate', NULL, ''),
(1935, 47, 'Ar', 'Sur / Wadi Shab / Wadi Tiwi / Mascate', NULL, ''),
(1936, 48, 'en', 'MASCATE / AMMAN (JORDANIE) / CHATEAUX DU DESERT / AMMAN', NULL, ''),
(1937, 48, 'fr', 'Mascate / Amman (Jordanie) / Châteaux du Désert /  Amman', NULL, '&lt;p&gt;Transfert à l&#039;aéroport et vol pour&lt;strong&gt; Amman&lt;/strong&gt; en &lt;strong&gt;Jordanie&lt;/strong&gt; le matin tôt.&lt;/p&gt;\r\n&lt;p&gt;Arrivée, accueil puis transfert vers l&#039;hôtle pour déposer les bagages. Départ pour les châteaux du désert de Jordanie: &lt;strong&gt;Qasr al Amra,&lt;/strong&gt; l&#039;un des monuments les mieux conservés, est un site du &lt;strong&gt;patrimoine mondial de l&#039;UNESCO.&lt;/strong&gt; Ses murs intérieurs et ses plafonds sont couverts de fresques animées, et deux des chambres sont pavées de mosaïques colorées.&lt;/p&gt;\r\n&lt;p&gt;Le&lt;strong&gt; fort d&#039;Al Azraq&lt;/strong&gt; en basalte noir, utilisé en continu depuis l&#039;époque romaine, a été le siège de&lt;strong&gt; Lawrence d&#039;Arabie&lt;/strong&gt; pendant les révoltes arabes.&lt;/p&gt;\r\n&lt;p&gt;L&#039;après-midi, nous revenons à Amman, une ville de plus de 19 collines ou «&lt;strong&gt;djebels».&lt;/strong&gt; Amman est la capitale du Royaume hachémite de Jordanie. Connu comme Rabbath-Ammon au cours de l&#039;âge de fer et plus tard comme Philadelphie, la ville antique faisait autrefois partie de la Décapole. Visite de la Citadelle et le temple d&#039;Hercule, le Palais des Omeyyades, l&#039;église byzantine et le musée ainsi que&lt;strong&gt; le Théâtre romain&lt;/strong&gt;. Promenade dans le Suk en centre ville puis&lt;strong&gt; dîner dans un restaurant typique jordanien.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;NB :&lt;/strong&gt;&lt;span&gt; &lt;/span&gt;Les vols d&#039;Oman Air et de Turkish Airlines permettent de combiner les deux pays. Les vols ne sont pas compris dans le prix et vous devez les réserver par vous-mêmes avant votre arrivée. Faites attention à bien calculer les jours pour les réservations des vols selon l&#039;itinéraire donné.&lt;/p&gt;'),
(1938, 48, 'it', 'Mascate / Amman (Jordanie) / Châteaux du Désert /  Amman', NULL, ''),
(1939, 48, 'es', 'Mascate / Amman (Jordanie) / Châteaux du Désert /  Amman', NULL, ''),
(1940, 48, 'Ar', 'Mascate / Amman (Jordanie) / Châteaux du Désert /  Amman', NULL, ''),
(1941, 49, 'en', 'AMMAN / JERASH / UM QAIS / DEAD SEA', NULL, ''),
(1942, 49, 'fr', 'Amman / Jerash / Umm Qais / Mer Morte', NULL, '&lt;p&gt;Aujourd&#039;hui, nous explorons &lt;strong&gt;Jérash,&lt;/strong&gt; l&#039;ancienne &lt;strong&gt;Gerasa.&lt;/strong&gt; Jérash révèle un bel exemple de l&#039;urbanisme romain provincial formel que l&#039;on trouve dans tout le Moyen-Orient, comprenant pavées, colonnades, rues, temples, théâtres, bains, des tours et des portes.&lt;/p&gt;\r\n&lt;p&gt;Ensuite départ pour &lt;strong&gt;Umm Qais&lt;/strong&gt;, l&#039;ancienne &lt;strong&gt;Gadara&lt;/strong&gt;, d&#039;où nous aurons une vue magnifique sur la mer de Galilée et le Golan. La cité avait été autrefois le foyer de plusieurs poètes et philosophes, y compris un des fondateurs d&#039;une école de rhétorique à Rome, et était appelée « nouvelle Athènes&quot; par un poète.&lt;/p&gt;\r\n&lt;p&gt;Sur le chemin du retour par &lt;strong&gt;la vallée du Jourdain,&lt;/strong&gt; nous passons par &lt;strong&gt;Pella,&lt;/strong&gt; un des plus anciens sites culturels de la Jordanie.&lt;/p&gt;\r\n&lt;p&gt;Dans la soirée, nous arriverons à la&lt;strong&gt; Mer Morte&lt;/strong&gt;&lt;/p&gt;'),
(1943, 49, 'it', 'Amman / Jerash / Umm Qais / Mer Morte', NULL, ''),
(1944, 49, 'es', 'Amman / Jerash / Umm Qais / Mer Morte', NULL, ''),
(1945, 49, 'Ar', 'Amman / Jerash / Umm Qais / Mer Morte', NULL, ''),
(1946, 50, 'en', 'DEAD SEA ( WITH BETHANY OPTION)', NULL, ''),
(1947, 50, 'fr', 'Mer Morte (avec option Bethany)', NULL, '&lt;p&gt;Ici, vous serez à l&#039;endroit le plus bas sur terre avec plus de 400m en dessous du niveau de la mer. Détendez-vous et flottez sans effort dans l&#039;eau chaude, apaisante et très salée tout en profitant des &lt;strong&gt;minéraux&lt;/strong&gt; de cette eau ainsi que des rayons de &lt;strong&gt;soleil jordanien&lt;/strong&gt;. Badijonez vous de la boue noire saine pour donner de la douceur à votre peau.&lt;/p&gt;\r\n&lt;p&gt;Une excursion sur le site de l&#039;établissement de&lt;strong&gt; Jean-Baptiste&lt;/strong&gt; à &lt;strong&gt;Béthanie,&lt;/strong&gt; où Jésus a été baptisé, &lt;strong&gt;en option.&lt;/strong&gt;&lt;/p&gt;'),
(1948, 50, 'it', 'Dead Sea (with Bethany option).', NULL, ''),
(1949, 50, 'es', 'Dead Sea (with Bethany option).', NULL, ''),
(1950, 50, 'Ar', 'Dead Sea (with Bethany option).', NULL, ''),
(1951, 51, 'en', 'DEAD SEA / MONT NEBO / MADABA / KERAK / PETRA', NULL, ''),
(1952, 51, 'fr', 'Mer Morte / Mont Nebo / Madaba / Kérak / Petra', NULL, '&lt;p&gt;De la &lt;strong&gt;Mer Morte&lt;/strong&gt; la route serpente jusqu&#039;au Mont Nebo, l&#039;un des lieux saints les plus vénérés de Jordanie et l&#039;endroit où Moïse a été enterré.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Madaba&lt;/strong&gt; est plus connue pour ses mosaïques byzantines et omeyyades spectaculaires et abrite la célèbre Carte de Jérusalem en mosaïques. La Mosaïque couvre le plancher de&lt;strong&gt; l&#039;église grecque orthodoxe de Saint-Georges,&lt;/strong&gt; qui a été construite en 1896, sur les restes d&#039;une église byzantine beaucoup plus ancienne, 6ème S. Le panneau de mosaïque entourant la carte était à l&#039;origine d&#039;environ 15,6 X 6m, 94 m², seulement environ un quart est conservé.&lt;/p&gt;\r\n&lt;p&gt;Pour &lt;strong&gt;Kérak,&lt;/strong&gt; nous allons suivre &lt;strong&gt;la route des Rois,&lt;/strong&gt; en passant par&lt;strong&gt; le Wadi Mujib, «Grand Canyon»&lt;/strong&gt; de Jordanie avec ses vues spectaculaires. Kérak, l&#039;ancienne forteresse des croisée, se trouve à 900m au dessus du niveau de la mer. Exploration de son labyrinthe sans fin de voûtes et de couloirs. Le château que nous voyons aujourd&#039;hui date du 12ème siècle.&lt;/p&gt;\r\n&lt;p&gt;Peu de temps avant d&#039;arriver à &lt;strong&gt;Wadi Musa,&lt;/strong&gt; nous nous arrêterons à Little Petra pour voir l&#039;une des très rares peintures Nabatéenne conservée à nos jours.&lt;/p&gt;'),
(1953, 51, 'it', 'Mer Morte / Mont Nebo / Madaba / Kérak / Petra', NULL, ''),
(1954, 51, 'es', 'Mer Morte / Mont Nebo / Madaba / Kérak / Petra', NULL, ''),
(1955, 51, 'Ar', 'Mer Morte / Mont Nebo / Madaba / Kérak / Petra', NULL, ''),
(1956, 52, 'en', 'PETRA', NULL, ''),
(1957, 52, 'fr', 'Petra', NULL, '&lt;p&gt;Journée consacrée à la cité rose et rouge de &lt;strong&gt;Petra.&lt;/strong&gt; Petra fait du &lt;strong&gt;patrimoine mondial de l&#039;UNESCO&lt;/strong&gt; et elle est l&#039;une des sept merveilles du monde. Caché au milieu des plis des collines spectaculaires, ce site unique a été oublié du monde jusqu&#039;à ce qu&#039;il fut redécouvert en 1812 par l&#039;explorateur suisse Johann Ludwig Burckhardt. On a beaucoup écrit à propos de Petra, rien ne vous prépare vraiment pour ce lieu étonnant. Il faut vraiment le voir pour le croire !!! Traversée de &lt;strong&gt;siqs&lt;/strong&gt; &lt;strong&gt;(Gorges étroites)&lt;/strong&gt; et canyons et exploration de centaines, de grottes, de tombeaux, de temples de tous les styles et de toutes les dimensions sculptés dans&lt;strong&gt; le grès coloré des montagnes&lt;/strong&gt;. De certains endroits, vous aurez une vue imprenable sur cette immense ville antique.&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Alternative:&lt;/strong&gt; Si vous préférez ne pas monter au Deir, vous pouvez rester dans la ville basse pour visiter l&#039;église byzantine avec ses mosaïques ou bien prendre une tasse de thé à l&#039;ombre. Il y a aussi deux excellents musées;&lt;strong&gt; le Musée archéologique de Petra&lt;/strong&gt; et &lt;strong&gt;le Musée nabatéens de Petra.&lt;/strong&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Fin de journée avec un dîner jordanien à l&#039;hôtel.&lt;/strong&gt;&lt;/p&gt;'),
(1958, 52, 'it', 'Petra.', NULL, ''),
(1959, 52, 'es', 'Petra.', NULL, ''),
(1960, 52, 'Ar', 'Petra.', NULL, ''),
(1961, 53, 'en', 'PETRA / WADI RUM', NULL, ''),
(1962, 53, 'fr', 'Petra / Wadi Rum', NULL, '&lt;p&gt;&lt;span&gt;Après le petit déjeuner, nous nous dirigerons vers le &lt;strong&gt;Wadi Rum.&lt;/strong&gt; La météo et le vent ont sculpté les pitons recheux en imposants grattes ciel de toutes couleurs,  des vues à couper le souffle et des paysages sans fin.  Un tour en jeep ou un tours à dos de chameau pour mieux apprécier ce désert. Après&lt;strong&gt; le coucher du soleil,&lt;/strong&gt; vous pouvez apprendre davantage sur&lt;strong&gt; la vie bédouine&lt;/strong&gt; avec la préparation du repas dans le désert. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;strong&gt;Nuit sous un ciel étoilé ou dans une tente bédouine.&lt;/strong&gt;&lt;/p&gt;'),
(1963, 53, 'it', 'Petra / Wadi Rum', NULL, '&lt;div class=&quot;style_block__21TUn&quot; data-block=&quot;true&quot; data-editor=&quot;7j6lm&quot; data-offset-key=&quot;5d0ea-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;5d0ea-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;span data-offset-key=&quot;5d0ea-0-0&quot;&gt;Dopo colazione, avverà il trasferimento verso il deserto di &lt;/span&gt;&lt;span data-offset-key=&quot;5d0ea-0-1&quot;&gt;Wadi rum&lt;/span&gt;&lt;span data-offset-key=&quot;5d0ea-0-2&quot;&gt;, il più esteso e stupefacente deserto della Giordania, con i suoi paesaggi favolosi, senza tempo e incontaminati. Giornata di escursioni, tra passeggiate autonome e j&lt;/span&gt;&lt;span data-offset-key=&quot;5d0ea-0-3&quot;&gt;eep tour 4x4 ( tre ore )&lt;/span&gt;&lt;span data-offset-key=&quot;5d0ea-0-4&quot;&gt; la meravigliosa sabbia rossa del deserto.&lt;/span&gt;&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;style_block__21TUn&quot; data-block=&quot;true&quot; data-editor=&quot;7j6lm&quot; data-offset-key=&quot;l43g-0-0&quot;&gt;\r\n&lt;div data-offset-key=&quot;l43g-0-0&quot; class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot;&gt;&lt;strong&gt;Pernottamento e cena tipica in un magnifico camping in Wadi Rum.&lt;/strong&gt;&lt;/div&gt;\r\n&lt;/div&gt;'),
(1964, 53, 'es', 'Petra / Wadi Rum', NULL, ''),
(1965, 53, 'Ar', 'Petra / Wadi Rum', NULL, ''),
(1966, 54, 'en', 'WADI RUM / AQABA', '', ''),
(1967, 54, 'fr', 'Wadi Rum / Aqaba', '', '<p><span><strong>Petit-déjeuner</strong> dans la <strong>tente bédouine</strong> comme<strong> Lawrence d\'Arabie.</strong> Après les dernièrs moments  dans ce beau paysage nous vous conduisons à Aqaba, seul débouché de la Jordanie sur la mer. </span></p>\r\n<p><span>Vous pouvez profiter d\'une journée libre à la <strong>piscine</strong>, <strong>shopping</strong> ou faire une balade en bateau à fond de verre à la découverte de <strong>la Mer Rouge.</strong></span></p>'),
(1968, 54, 'it', 'Wadi Rum / Aqaba', '', ''),
(1969, 54, 'es', 'Wadi Rum / Aqaba', '', ''),
(1970, 54, 'Ar', 'Wadi Rum / Aqaba', '', ''),
(1971, 55, 'en', 'AQABA / UM ARRASSAS / AMMAN', NULL, '');
INSERT INTO `en33_tours_canned_days_contents` (`id`, `day_id`, `lang`, `title`, `place`, `description`) VALUES
(1972, 55, 'fr', 'Aqaba / Umm Arrassas / Amman', NULL, '&lt;p&gt;&lt;span&gt;Après le petit déjeuner, nous partons à &lt;strong&gt;Amman&lt;/strong&gt; par la route du désert. Sur notre chemin, nous nous arrêtons pour la visite &lt;strong&gt;d&#039;Umm Arrassas,&lt;/strong&gt; un important site archéologique qui a été déclaré&lt;strong&gt; site du patrimoine mondial en 2004&lt;/strong&gt;. Ses structures datent du 3 au 9ème siècle et la plupart n&#039;ont pas encore été fouillés. &lt;/span&gt;&lt;/p&gt;\r\n&lt;p&gt;&lt;span&gt;Le site est surtout connu pour ses magnifiques &lt;strong&gt;mosaïques byzantines,&lt;/strong&gt; qui ont été découverte dans deux &lt;strong&gt;églises&lt;/strong&gt; différentes datant du 6ème et 8ème siècles. La plus grande mosaïque représente 15 grandes villes telles qu&#039;elles étaient au &lt;strong&gt;8ème siècle,&lt;/strong&gt; chacune d&#039;elles est indiquée en &lt;strong&gt;grec.&lt;/strong&gt; Celles du côté nord sont en Palestine et celles de gauche sont en Jordanie.&lt;/span&gt;&lt;/p&gt;'),
(1973, 55, 'it', 'Aqaba / Umm Arrassas / Amman', NULL, ''),
(1974, 55, 'es', 'Aqaba / Umm Arrassas / Amman', NULL, ''),
(1975, 55, 'Ar', 'Aqaba / Umm Arrassas / Amman', NULL, ''),
